import React, { useState, useEffect } from 'react';
import { sprintf, __ } from '@wordpress/i18n';
import { debug, nonce } from '@jupiterx/control-panel';
import Spinner from '../../../components/spinner';
import { Button } from 'react-bootstrap';
import Alert from '../../../components/alert';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faRedoAlt, faTrashAlt } from '@fortawesome/free-solid-svg-icons';
import './style.scss';

const Logs = () => {
	const [ loading, setLoading ] = useState( true );
	const [ logs, setLogs ] = useState( '' );
	const [ info, setInfo ] = useState( {} );

	useEffect( () => {
		getLogs();
	}, [] );

	const getLogs = () => {
		wp.ajax.post( {
			action: 'jupiterx_cp_get_logs',
			nonce,
			beforeSend: setLoading( true ),
		} )
			.always( ( data ) => {
				setLoading( false );
				setLogs( data[ 0 ] );

				if ( typeof data[ 1 ] !== 'undefined' ) {
					setInfo( data[ 1 ] );
				}
			} );
	};

	const deleteLogs = () => {
		wp.ajax.post( {
			action: 'jupiterx_cp_delete_logs',
			nonce,
			beforeSend: setLoading( true ),
		} )
			.always( ( data ) => {
				setLoading( false );
				setLogs( data[ 0 ] );

				if ( typeof data[ 1 ] !== 'undefined' ) {
					setInfo( data[ 1 ] );
				}

				getLogs();
			} );
	};

	return (
		! debug.enabled ? ( <p dangerouslySetInnerHTML={ {
			__html: sprintf(
				// translators: %s Link to help
				__( 'To start logging and viewing the logs, you need to enable Debug Log as explained in this <a href="%s" target="_blank">article</a>.', 'jupiterx-core' ),
				'https://themes.artbees.net/?p=93819',
			),
		} } /> ) : (
			<>
				<div className="d-flex align-items-center justify-content-between mb-3">
					<div>
						<span>{ __( 'You are viewing recent debug logs (max last 10,000 lines) of your site.', 'jupiterx-core' ) + ' ' }</span>
						{ info.filePath ? (
							<span dangerouslySetInnerHTML={ {
								__html: sprintf(
									// translators: %s Link to help
									__( 'The log file is located in <code>%1$s</code> and size is <code>%2$s</code>.', 'jupiterx-core' ),
									info.filePath,
									info.fileSize
								),
							} } />
						) : ( '' ) }
					</div>
					<div className="jx-cp-logs-actions ms-2">
						<Button
							variant="outline-primary"
							size="sm"
							disabled={ loading }
							onClick={ getLogs }
						>
							<FontAwesomeIcon
								icon={ faRedoAlt }
							/>
							{ ' ' }
							<span>{ __( 'Refresh Logs', 'jupiterx-core' ) }</span>
						</Button>
						<Button
							className="ms-2"
							variant="outline-primary"
							size="sm"
							disabled={ loading }
							onClick={ deleteLogs }
						>
							<FontAwesomeIcon
								icon={ faTrashAlt }
							/>
							{ ' ' }
							<span>{ __( 'Clear Logs', 'jupiterx-core' ) }</span>
						</Button>
					</div>
				</div>
				<Alert variant="warning">
					{ __( 'Please be cautious about sharing sensitive logs. It may contain your purchase code and email so better to share it in a private message.', 'jupiterx-core' ) }
				</Alert>
				<div className="jx-cp-logs-messages p-4 mb-2">{ loading ? <Spinner /> : (
					<div dangerouslySetInnerHTML={ {
						__html: logs,
					} } />
				) }</div>
				<p dangerouslySetInnerHTML={ {
					__html: sprintf(
						// translators: %s Link to help
						__( "If you don't need to log the errors, it's recommended to disable Debug Log as explained in this <a href='%s' target='_blank'>article</a>.", 'jupiterx-core' ),
						'https://themes.artbees.net/?p=93819',
					),
				} } />
			</>
		)
	);
};

export default Logs;
