import React, { useReducer, useEffect, useContext } from 'react';
import { Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import $ from 'jquery';
import { adminAjaxURL, nonce } from '@jupiterx/control-panel';
import { TemplatesContext } from '../../../../store/templates';
import { initialState, actions, reducer } from './reducer';
import Dialog from '../../../../components/dialog';
import Steps from './steps';
import './style.scss';
import { SettingsContext } from '../../../../store/settings';

const getEventSourceURL = ( { media, id, title, mode, demo } ) => {
	const url = new URL( adminAjaxURL );

	url.searchParams.append( 'action', 'jupiterx_core_cp_import_template_content' );
	url.searchParams.append( 'import_media', media );
	url.searchParams.append( 'template_id', id );
	url.searchParams.append( 'template_name', title );
	url.searchParams.append( 'template_demo', demo );
	url.searchParams.append( 'partial_import', mode === 'partial' );
	url.searchParams.append( 'nonce', nonce );

	return url.href;
};

const runImport = ( method, config, dispatch, handleSetSimplicityMode, simplicity, options, setOptions ) => {
	const { mode, media, id, title, demo } = config;

	const errorMessage = ( message ) => {
		dispatch( {
			type: actions.ERROR,
			payload: message || __( 'An error occurred while importing the template, please try again.', 'jupiterx-core' ),
		} );
	};

	// Use EventSource for template content.
	if ( method === 'theme_content' ) {
		const event = new window.EventSource( getEventSourceURL( config ) );

		event.addEventListener( 'message', ( res ) => {
			const data = JSON.parse( res.data );

			if ( ! data.error && data.status ) {
				dispatch( {
					type: actions.NEXT_QUERY,
					payload: data.message,
				} );
			} else {
				errorMessage( data.message );
			}

			event.close();
		} );
		return;
	}

	$.ajax( {
		type: 'POST',
		url: _wpUtilSettings.ajax.url,
		timeout: 0,
		data: {
			action: 'jupiterx_core_cp_import_template',
			type: method,
			import_media: media,
			template_id: id,
			template_name: title,
			template_demo: demo,
			partial_import: mode === 'partial',
			nonce,
		},
		error() {
			errorMessage();
		},
	} ).done( ( data ) => {
		const { status, message } = data;

		if ( ! status && ! message ) {
			errorMessage();
			return;
		}

		if ( ! status ) {
			errorMessage( message );
			return;
		}

		if ( method === 'install_plugins' ) {
			$.ajax( {
				type: 'POST',
				url: data.url,
				data: data.install,
				success: () => {
					dispatch( {
						type: actions.NEXT_QUERY,
						payload: message,
					} );
				},
			} );

			return;
		}

		dispatch( {
			type: actions.NEXT_QUERY,
			payload: message,
		} );

		if ( method === 'finalize' && ( simplicity === '1' || simplicity === true ) ) {
			options.disable_theme_default_settings = '0';
			setOptions( options );
			handleSetSimplicityMode( '0' );
		}
	} );
};

const ImportDialog = ( { show, onHide, templateImport = {}, handleSetSimplicityMode, simplicity } ) => {
	const [ {
		isCompleted,
		isLoading,
		config,
		progress,
		query,
		steps,
		error,
	}, dispatch ] = useReducer( reducer, initialState );

	const { setTemplateInstalled, hasTemplateInstalled } = useContext( TemplatesContext );
	const { options, setOptions } = useContext( SettingsContext );

	useEffect( () => {
		dispatch( {
			type: actions.CONFIG,
			payload: templateImport,
		} );
	}, [ templateImport ] );

	useEffect( () => {
		if ( ! query.length ) {
			return;
		}

		const [ method ] = query;
		// Run import.
		runImport( method, config, dispatch, handleSetSimplicityMode, simplicity, options, setOptions );
	}, [ query, config ] );

	const handleClose = () => {
		onHide();

		if ( isCompleted && config.mode === 'full' && config.id && config.title ) {
			setTemplateInstalled( { ...config } );
			$( '#dashboard-welcome-box-check-list-readymade' ).find( 'svg' ).attr( 'class', 'box-check-box-icon' ).find( 'path' ).remove();
		}

		setTimeout( () => {
			dispatch( { type: actions.RESET } );
		}, 200 );
	};

	const handleSubmit = ( event ) => {
		event.preventDefault();

		// Save form data.
		const { target: { elements } } = event;
		dispatch( {
			type: actions.CONFIG,
			payload: {
				media: elements.media.checked,
				mode: elements.mode.value,
			},
		} );
	};

	const handleConfirm = () => {
		dispatch( { type: actions.INITIALIZE } );
	};

	// Error handling.
	if ( error ) {
		return (
			<Dialog
				title={ __( 'Something went wrong!', 'jupiterx-core' ) }
				variant="error"
				show={ show }
				onHide={ handleClose }
			>
				{ error }
			</Dialog>
		);
	}

	// On install success.
	if ( isCompleted ) {
		return (
			<Dialog
				title={ __( 'All Done!', 'jupiterx-core' ) }
				variant="success"
				show={ show }
				onHide={ handleClose }
			>
				{ __( 'The template is successfully imported.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	// On installation process.
	if ( isLoading ) {
		return (
			<Dialog
				title={ __( 'Importing is in progress...', 'jupiterx-core' ) }
				variant="progress"
				show={ show }
				isLoading={ isLoading }
				progressNow={ progress }
			>
				<Steps steps={ steps } />
			</Dialog>
		);
	}

	// Show confirmation dialog.
	if ( config.mode ) {
		return (
			<Dialog
				variant="warning"
				show={ show }
				onHide={ handleClose }
				onOk={ handleConfirm }
				title={ __( 'Important Notice', 'jupiterx-core' ) }
				okText={ __( 'Yes', 'jupiterx-core' ) }
				showCancel={ true }
			>
				{ config.mode === 'full' && __( 'All of your current content, settings, widgets, etc. will be removed and the new content will be imported.', 'jupiterx-core' ) }
				{ ' ' }
				{ __( 'Are you sure you want to continue?', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	return (
		<Dialog
			title={ __( 'Choose how you want to import this template', 'jupiterx-core' ) }
			variant=""
			show={ show }
			onHide={ handleClose }
			onSubmit={ handleSubmit }
			submitText={ __( 'Import', 'jupiterx-core' ) }
		>
			<Form.Group controlId="mode">
				<Form.Check
					defaultChecked={ ! hasTemplateInstalled }
					id="mode-full"
					className="font-weight-bold"
					type="radio"
					name="mode"
					value="full"
					label={ __(	'Full Import', 'jupiterx-core' ) }
				/>
				<p className="ps-4 text-secondary mb-2">{ __( 'Your current content, settings, widgets, etc. will be removed and the database will be reset. New page contents and settings will be imported.', 'jupiterx-core' ) }</p>
				<Form.Check
					defaultChecked={ hasTemplateInstalled }
					id="mode-partial"
					className="font-weight-bold"
					type="radio"
					name="mode"
					value="partial"
					label={ __(	'Content Import', 'jupiterx-core' ) }
				/>
				<p className="ps-4 text-secondary">{ __( 'Keep your current content, settings, widgets, etc. Only the new page contents will be imported.', 'jupiterx-core' ) }</p>
			</Form.Group>
			<hr />
			<Form.Group controlId="media" className="m-0">
				<Form.Check
					defaultChecked={ true }
					type="checkbox"
					name="media"
					label={ __(	'Include media (copyrighted).', 'jupiterx-core' ) }
				/>
				<Form.Text muted>
					{ __( 'Notice: While importing the media, SVG support will be enabled if it was disabled before.', 'jupiterx-core' ) }
				</Form.Text>
			</Form.Group>
		</Dialog>
	);
};

export default ImportDialog;
