import React, { useState, useEffect, useContext, useCallback } from 'react';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import { Card, Dropdown, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
	faCalendarAlt,
	faCircle,
	faEdit,
	faEllipsisV,
	faSignOutAlt,
	faSitemap,
	faTrashAlt,
	faUserAlt,
} from '@fortawesome/free-solid-svg-icons';
import Dialog from '../../../components/dialog';
import Condition from './../../../components/conditions';
import MetaEditor from './meta-modal';
import ItemIframe from './item-iframe';
import Tooltip from '../../../components/tooltip';
import { LayoutBuilderContext } from '../index';
import './style.scss';

const Item = ( props ) => {
	const [ stringConditions, setStringConditions ] = useState( props.conditionsString );
	const [ hasCondition, setHasCondition ] = useState( true );
	const [ showCondition, setShowCondition ] = useState( false );
	const defaultOptions = useContext( LayoutBuilderContext );
	const [ showMetaDialog, setShowMetaDialog ] = useState( false );

	useEffect( () => {
		if ( _.isEmpty( stringConditions ) || stringConditions.includes( 'No Instance' ) ) {
			setHasCondition( false );
		}
	}, [ stringConditions ] );

	const getConditions = ( postId ) => {
		wp.ajax.post( {
			action: 'jupiterx_conditional_manager',
			sub_action: 'load_post_conditions_string',
			post: postId,
			nonce,
		} )
			.done( ( data ) => {
				if ( ! _.isEmpty( data.string ) ) {
					setHasCondition( true );
				}

				if ( _.isEmpty( data.string ) ) {
					data.string = 'No Instance';
				}

				setStringConditions( data.string );

				const array = [ { id: props.post, post_title: props.title, conditions: data.array, condition_string: data.string } ];
				props.expandAllConditions( array );
			} )
			.fail( () => {
				setStringConditions( __( 'No Instance', 'jupiterx-core' ) );
				setHasCondition( false );
			} );
	};

	const layoutExport = ( postId ) => {
		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'export',
			post: postId,
			nonce,
		} )
			.done( ( data ) => {
				const fileName = data.title;
				const link = document.createElement( 'a' );
				link.href = 'data:text/json;charset=utf-8,' + encodeURIComponent( JSON.stringify( data ) );
				link.download = fileName + '.json';
				document.body.appendChild( link );
				link.click();
				document.body.removeChild( link );
			} )
			.fail( () => {
			} );
	};

	const onWindowsResize = useCallback( () => {
		if ( document.querySelectorAll( '#jupiterx-condition-form-inner-wrapper' ).length < 1 ) {
			return;
		}

		let subtract = 250;

		if ( window.innerHeight > 1100 ) {
			subtract = subtract + 50;
		}

		if ( window.innerHeight > 1200 ) {
			subtract = subtract + 15;
		}

		const height = parseInt( window.innerHeight ) - subtract;
		document.querySelector( '#jupiterx-condition-form-inner-wrapper' ).style.maxHeight = height + 'px';
	} );

	const fiXContainerHeighOnResize = () => {
		onWindowsResize();
		window.addEventListener( 'resize', onWindowsResize );
	};

	return (
		<>
			<Card className={ 'layout-builder-templates-item ' + props.className } >
				<Card.Header className="item-header clearfix">
					<div className="card-header-left-side">
						<FontAwesomeIcon
							className={ `icon-circle ${ hasCondition ? 'icon-circle-green' : 'icon-circle-grey' }` }
							icon={ faCircle }
						/>
						<span className={ `layout-builder-title ${ 'title-' + props.post } ` }>{ props.title }</span>
					</div>
					<div className="card-header-right-side">
						<Button
							className="float-end layout-builder-edit"
							variant="outline-primary"
							onClick={ () => window.open( props.editUrl, '_blank' ) }
						>
							<FontAwesomeIcon icon={ faEdit } ></FontAwesomeIcon>
							{ __( 'Edit', 'jupiterx-core' ) }
						</Button>
						<Dropdown className="dropdown float-end">
							<Dropdown.Toggle variant="link">
								<FontAwesomeIcon className="text-muted" icon={ faEllipsisV } />
							</Dropdown.Toggle>

							<Dropdown.Menu
								// Style has to be inline in this case.
								style={ { margin: '17px 0 0 0' } }
							>
								<Dropdown.Item onClick={ props.editTitle }>
									<FontAwesomeIcon icon={ faEdit } />
									<span>{ __( 'Rename', 'jupiterx-core' ) }</span>
								</Dropdown.Item>
								<Dropdown.Item onClick={ () => layoutExport( props.post ) } >
									<FontAwesomeIcon icon={ faSignOutAlt } className="fa-rotate-180" />
									<span>{ __( 'Export', 'jupiterx-core' ) }</span>
								</Dropdown.Item >
								<Dropdown.Item onClick={ () => props.remove( props.post ) } >
									<FontAwesomeIcon className="text-danger" icon={ faTrashAlt } />
									<span className="text-danger">{ __( 'Delete', 'jupiterx-core' ) }</span>
								</Dropdown.Item>
							</Dropdown.Menu>
						</Dropdown>
					</div>
				</Card.Header>
				<Card.Body id="layout-builder-item-body" className="item-body">
					{ props.previewUrl && <ItemIframe previewUrl={ props.previewUrl } /> }
				</Card.Body>
				<Card.Footer className="item-footer">
					<div className="layout-builder-conditions">
						<div className="layout-builder-sitemap">
							<FontAwesomeIcon icon={ faSitemap } />
							<div className="condition-text"> <b> { __( 'Display in', 'jupiterx-core' ) } </b>
								{ stringConditions }
							</div>
							<span className="condition-edit" // eslint-disable-line
								onClick={ () => {
									setShowCondition( true );
									fiXContainerHeighOnResize();
								} }
							>
								{ __( 'Edit Conditions', 'jupiterx-core' ) }
							</span>
							{
								! props.simplicityMode && [ 'header', 'footer' ].includes( props.section ) &&
								<>
									<span className="items-divider"></span>
									<span className="meta-edit" // eslint-disable-line
										onClick={ () => setShowMetaDialog( true ) }
									>
										{ __( 'Post Meta Conditions', 'jupiterx-core' ) }
									</span>
								</>
							}
						</div>
					</div>
					<div className="layout-builder-info">
						<Tooltip overlay={ props.date }>
							<span className="layout-builder-date">
								<FontAwesomeIcon icon={ faCalendarAlt } className="far" />
								<span>{ props.date }</span>
							</span>
						</Tooltip>
						<Tooltip overlay={ props.author }>
							<span className="layout-builder-author">
								<FontAwesomeIcon icon={ faUserAlt } />
								<span> { props.author } </span>
							</span>
						</Tooltip>
					</div>
				</Card.Footer>
			</Card>
			<Dialog
				show={ showCondition }
				className="jupiterx-layout-builder-conditions-dialog"
				title={ __( 'Edit Conditions', 'jupiterx-core' ) }
				onHide={ () => {
					setShowCondition( false );
					window.removeEventListener( 'resize', onWindowsResize );
				} }
				footer={ false }
			>
				<div
					className="condition-content"
					id="jupiterx-layout-builder-condition-content"
				>
					<Condition
						title={ props.title }
						post={ props.post }
						place="layout-builder"
						type={ props.section }
						typeTitle={ props.sectionTitle }
						allConditions={ props.allConditions }
						defaultOptions={ defaultOptions }
						setSize={ onWindowsResize }
						extra={ () => {
							setShowCondition( false );
							getConditions( props.post );
							props.resort( props.post );
						} }
					/>
				</div>
			</Dialog>
			<Dialog
				show={ showMetaDialog }
				className="jupiterx-layout-builder-meta-edit-dialog"
				title={ __( 'Post Meta Conditions', 'jupiterx-core' ) }
				onHide={ () => {
					setShowMetaDialog( false );
				} }
				footer={ false }
			>
				<MetaEditor
					identify={ props.post }
					type={ props.section }
					typeTitle={ props.sectionTitle }
					title={ props.title }
					hide={ () => setShowMetaDialog( false ) }
				/>
			</Dialog>
		</>
	);
};

export default Item;
