import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { Button, Form, Spinner } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAngleLeft } from '@fortawesome/free-solid-svg-icons';
import IconHandler from './icon-handler';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';

const Post = ( props ) => {
	const { register, handleSubmit } = useForm();
	const [ submit, setSubmit ] = useState( 'creating' );

	const onSubmit = ( post ) => {
		if ( ! post.icon_set_content ) {
			post.icon_set_content = document.getElementById( 'icon_set_content' ).value;
		}

		setSubmit( 'saving' );

		wp.ajax.post( {
			action: 'jupiterx_custom_icons',
			sub_action: 'save_post',
			post,
			nonce,
		} )
			.done( () => {
				setSubmit( 'creating' );
				props.afterSubmit();
			} )
			.fail( ( data ) => {
				setSubmit( 'creating' );
				document.getElementsByClassName( 'show-error-result' )[ 0 ].innerHTML = data;
			} );
	};

	const getSubmitButton = () => {
		if ( 'creating' === submit ) {
			return <button
				variant="primary"  // eslint-disable-line
				className="mt-2 new-custom-icons-submit"
				type="submit"
				onClick={ handleSubmit }>
				{ props.mode === 'edit' ? __( 'Update', 'jupiterx-core' ) : __( 'Create', 'jupiterx-core' ) }
			</button>;
		}

		if ( 'saving' === submit ) {
			return <button
				variant="primary"  // eslint-disable-line
				className="mt-2 new-custom-icons-submit saving-mode">
				<Spinner as="span"
					animation="border"
					size="sm"
					role="status"
					aria-hidden="true"
					className="me-2" />
				<span>{ __( 'Saving', 'jupiterx-core' ) }</span>
			</button>;
		}
	};

	return (
		<div className="custom-icons-add-new">
			<div className="header-wrapper">
				<span className="header">
					{
						'new' === props.mode
							? __( 'Add New Icon Set', 'jupiterx-core' )
							: __( 'Edit Icon Set', 'jupiterx-core' )
					}
				</span>
				{
					<Button
						variant="secondary"
						className="px-4 post-back-button"
						onClick={ props.backButton }
					>
						<FontAwesomeIcon icon={ faAngleLeft } className="me-2" />
						{ __( 'Back', 'jupiterx-core' ) }
					</Button>
				}
			</div>
			<Form onSubmit={ handleSubmit( onSubmit ) } className="add-edit-icons" id="addEditIcon">
				<Form.Group className="jx-icon-set-name">
					<Form.Label>
						{ __( '1. What is the name of this icon set?', 'jupiterx-core' ) }
					</Form.Label>
					<Form.Control
						type="text"
						id="custom_title"
						defaultValue={ props.post.post_title }
						name="custom_icons_post_title"
						className="w-25"
						placeholder={ __( 'Enter a name', 'jupiterx-core' ) }
						{ ...register( 'custom_icons_post_title' ) }
					/>
				</Form.Group>
				<hr />
				<Form.Group className="jx-icon-set-file">
					<Form.Label>
						{ __( '2. Icons', 'jupiterx-core' ) }
					</Form.Label>
					<IconHandler
						previousData={ props.post && JSON.parse( props.post.post_content ) }
						formRef={ register }
						defaultValues={ props.post?.post_content ? JSON.parse( props.post.post_content ) : null }
					/>
				</Form.Group>
				<Form.Control
					size="sm"
					className="d-none"
					type="text"
					defaultValue={ props.post.ID }
					name="custom_icons_submit_mode"
					id="custom_icons_submit_mode"
					{ ...register( 'custom_icons_submit_mode' ) }
					onChange={ handleSubmit }
				/>
				<hr />
				<div className="submit-area">
					{ getSubmitButton() }
					<Button
						variant="outline-danger"
						className="float-end mt-2 remove-btn"
						onClick={ props.removeBtn }
					>
						{ __( 'Remove', 'jupiterx-core' ) }
					</Button>
					<p className="show-error-result"></p>
				</div>
			</Form>
		</div>
	);
};

export default Post;
