import React from 'react';

const SingleTemplatePreview = ( props ) => {
	const manageOnClick = () => {
		props.onSingeLayoutClick( {
			thumbnail: props.data.thumbnail,
			template_id: props.data.id,
			status: 'selected',
		}, false );
	};

	return (
		<>
			<div
				className="single-template-preview-wrap"
				role="button"
				tabIndex={ 0 }
				onClick={ manageOnClick }
				onKeyDown={ ( e ) => {
					if ( e.key === 'Enter' || e.key === 'Spacebar' || e.key === ' ' ) {
						manageOnClick();
					}
				} }
			>
				<img
					src={ props.data.thumbnail }
					className="mx-auto d-block"
					alt={ props.data.title }
					data-id={ props.data.id }
					data-url={ props.data.url }
					title={ props.data.title }
					aria-hidden={ true }
				/>
			</div>
		</>
	);
};

export default SingleTemplatePreview;
