import React, { useState } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import Post from './post';
import ListTable from './list-table';
import Dialog from '../../components/dialog';
import './style.scss';
const $ = jQuery;

const CustomSnippets = () => {
	const [ active, setActive ] = useState( 'list' );
	const [ postObject, setPostObject ] = useState( null );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ postToDelete, setPostToDelete ] = useState( 0 );

	const removePostButton = ( post ) => {
		setPostToDelete( post );
		setShowDialog( true );
	};

	const remove = ( post ) => {
		if ( 0 === post ) {
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_snippets',
			sub_action: 'remove_post',
			nonce,
			post_id: post.ID,
		} )
			.done( () => {
				setActive( 'list' );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
				setActive( 'list' );
			} );
	};

	$( '#navigation-custom-snippets' ).on( 'click', function() {
		setActive( 'list' );
	} );

	const listTableCreateNew = () => {
		setActive( 'new' );
	};

	const listTableEditPost = ( post ) => {
		setPostObject( post );
		setActive( 'edit' );
	};

	return (
		<div className="pt-3 custom-snippet-wrapper" >
			{
				'list' === active &&
				<div>
					<ListTable
						active={ active }
						createNew={ listTableCreateNew }
						edit={ listTableEditPost }
						newButton={ () => {
							setPostObject( null );
							setActive( 'new' );
						} }
						remove={ ( post ) => remove( post ) }
						refresh
					/>
				</div>
			}
			{
				'new' === active &&
				<div>
					<Post
						mode={ 'new' }
						post={ 0 }
						removeBtn={ () => setActive( 'list' ) }
						afterSubmit={ () => setActive( 'list' ) }
						backButton={ () => setActive( 'list' ) }
					/>
				</div>
			}
			{
				'edit' === active &&
				<div>
					<Post
						mode={ 'edit' }
						post={ postObject }
						removeBtn={ () => removePostButton( postObject ) }
						afterSubmit={ () => setActive( 'list' ) }
						backButton={ () => setActive( 'list' ) }
					/>
				</div>
			}
			{
				showDialog &&
				<Dialog
					className="jupiterx-custom-snippet-delete-confirm"
					show
					variant="warning"
					title={ __( 'Remove the custom snippet', 'jupiterx-core' ) }
					onCancel={ () => setShowDialog( false ) }
					onOk={ () => {
						remove( postToDelete );
						setShowDialog( false );
					} }
					closeButton={ false }
					okText={ __( 'Remove', 'jupiterx-core' ) }
					cancelText={ __( 'Discard', 'jupiterx-core' ) }
				>
					{ __( 'Are you sure you want to delete this snippet? This action can’t be undone.', 'jupiterx-core' ) }
				</Dialog>
			}
		</div>
	);
};

export default CustomSnippets;
