import React, { useCallback, useState, useEffect, useRef } from 'react';
import AsyncSelect from 'react-select/async';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTimes } from '@fortawesome/free-solid-svg-icons';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';

const CustomAsyncSelect = ( props ) => {
	const loadDefaultFromContext = () => {
		let posts;
		const global = [ 'header', 'footer', 'page-title-bar' ],
			singles = [ 'single', 'product' ],
			mode = props.type;

		if ( 'wpml' === props.inputField.conditionB ) {
			if ( '_language' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.wpml_languages;
			}
		}

		if ( 'layout-builder' === props.place && global.includes( props.type ) ) {
			if ( 'single_page' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.page;
			}

			if ( 'single_post' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.post;
			}

			if ( 'single_portfolio' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.portfolio;
			}

			if ( 'single_product' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.product;
			}
		}

		if ( 'layout-builder' === props.place && singles.includes( props.type ) ) {
			if ( 'single_page' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.page;
			}

			if ( 'single_post' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.post;
			}

			if ( 'single_portfolio' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.portfolio;
			}
		}

		if ( 'layout-builder' === props.place && 'product' === mode ) {
			if ( 'single_product' === props.inputField.conditionC ) {
				posts = props.defaultOptions.defaults4thParameter.product;
			}
		}

		if ( _.isEmpty( posts ) ) {
			return [ { value: 'all', label: __( 'All', 'jupiterx-core' ) } ];
		}

		return posts;
	};

	const [ menuView, setMenuView ] = useState( false ),
		[ loadedDefaults ] = useState( loadDefaultFromContext() ),
		rowId = props.index,
		$ = jQuery;

	const setWidth = () => {
		setTimeout( () => {
			const dropdownParent = $( `.conditions-row-${ props.index }` ).find( 'div[class*="-menu"]' ),
				width = dropdownParent.width(),
				dropdown = dropdownParent.children().first();

			dropdown.animate( { width: `${ width }px` }, 'fast' );
			dropdownParent.show();
		}, 50 );
	};

	const triggerTextMode = ( e ) => {
		$( e.target )
			.parents( '.basic-single' )
			.find( '.jupiterx-layout-builder-condition-last-parameter-selected-item' )
			.html( `<span>${ __( 'Search...', 'jupiterx-core' ) }</span>` );
	};

	const clear = ( e, index ) => {
		const fields = props.inputFields;
		fields[ index ].conditionD = [ 'all', __( 'All', 'jupiterx-core' ) ];

		props.setInputFields( fields );

		triggerTextMode( e );
	};

	const filterOptions = useCallback( ( input, callback ) => {
		const matchingOptions = loadedDefaults.filter( ( option ) =>
			option.label.toLowerCase().includes( input.toLowerCase() )
		);

		if ( matchingOptions.length > 0 ) {
			callback( matchingOptions );
			return;
		}

		if ( input.length < 2 ) {
			callback( [ { value: 'all', label: __( 'All', 'jupiterx-core' ) } ] );
			return;
		}

		return new Promise( () => {
			wp.ajax.post( {
				action: 'jupiterx_conditional_manager',
				sub_action: 'retrieve_select_options',
				type: props.inputField.conditionB,
				sub: props.inputField.conditionC,
				value: input,
				nonce,
			} )
				.always( ( response ) => {
					response.unshift( { value: 'all', label: __( 'All', 'jupiterx-core' ) } );
					callback( response );
				} );
		} );
	}, [ props.inputField.conditionB, props.inputField.conditionC ] );

	const clearProcess = ( index ) => {
		return (
			<span // eslint-disable-line
				className="clearer-indicator"
				onClick={ ( e ) => {
					clear( e, index );
				} }
			>
				<FontAwesomeIcon icon={ faTimes } />
			</span>
		);
	};

	const isMounted = useRef( false );

	useEffect( () => {
		isMounted.current = true;
		return () => {
			isMounted.current = false;
		};
	}, [] );

	const convertTextToLink = ( selectedValue ) => {
		const timeoutId = setTimeout( () => {
			if ( ! isMounted.current ) {
				return;
			}

			// Handle cleared selection or unexpected shapes
			if ( ! selectedValue || ! selectedValue.value ) {
				return;
			}

			if ( 'all' === selectedValue.value ) {
				return;
			}

			const placeHolder = $( `.conditions-row-${ rowId }` ).find( 'div[class*="singleValue"]' );
			placeHolder.find( 'a' ).attr( 'href', selectedValue.link );
			setMenuView( false );

			return () => clearTimeout( timeoutId );
		}, 500 );
	};

	const setDefaultOption = () => {
		if ( _.isEmpty( props.inputField.conditionD[ 2 ] ) ) {
			return props.inputField.conditionD ? { value: props.inputField.conditionD[ 0 ], label: props.inputField.conditionD[ 1 ] } : '';
		}
	};

	const customizeOptionsLabel = ( { label, value, link, flag_url: flagURL } ) => {
		if ( 'all' === value ) {
			return (
				<>
					{ label }
				</>
			);
		}

		return (
			<>
				<div className="jupiterx-layout-builder-condition-last-parameter-dropdown-items">
					{ flagURL && <img src={ flagURL } alt={ label } /> }
					<span>
						{ label }
					</span>
					<a
						href={ link }
						target="_blank"
					>
						<span className="dashicons dashicons-external"></span>
					</a>
				</div>
				<div className="jupiterx-layout-builder-condition-last-parameter-selected-item">
					<a href={ link } target="_blank">
						<span>{ label }</span>
					</a>
				</div>
			</>
		);
	};

	const handleOnChange = ( selectedOption ) => {
		convertTextToLink( selectedOption );
		props.handleInputChange( props.index, selectedOption );
	};

	const setEditAble = () => {
		const placeHolder = $( `.conditions-row-${ rowId }` ).find( 'div[class*="singleValue"]' );
		placeHolder
			.attr( 'contentEditable', 'true' );
	};

	return (
		<AsyncSelect
			defaultOptions={ loadedDefaults }
			defaultValue={ setDefaultOption() }
			placeholder={ __( 'Type to search', 'jupiterx-core' ) }
			className={ `basic-single conditions-row-${ rowId }` }
			id="conditionD"
			isClearable={ true }
			components={
				{
					DropdownIndicator: () => null,
					IndicatorSeparator: () => null,
					ClearIndicator: () => clearProcess( props.index ),
				}
			}
			onChange={ handleOnChange }
			onFocus={ () => {
				setMenuView( true );
				setWidth();
				setEditAble();
			} }
			onBlur={ () => {
				setMenuView( false );
			} }
			cacheOptions
			blurInputOnSelect={ true }
			loadOptions={ _.throttle( filterOptions, 1500, { leading: false, trailing: true } ) }
			formatOptionLabel={ customizeOptionsLabel }
			menuIsOpen={ menuView }
			menuPlacement="auto"
		/>
	);
};

export default CustomAsyncSelect;
