import React, { useState, useContext, forwardRef, useEffect, useRef } from 'react';
import { Form, Button } from 'react-bootstrap';
import { TriggersContext } from '../triggers';
import { popupTriggers } from '@jupiterx/control-panel';
import TriggerControl from '../controls';
import TriggerOperator from '../operators';
import './style.scss';

const TirggerRow = forwardRef( ( props, ref ) => {
	const [ triggerName, setTriggerName ] = useState( ( props.data && props.data.name ) || ( props.firstCondition && props.firstCondition.name ) || '' );
	const [ triggerControl, setTriggerControl ] = useState( {} );
	const [ triggerOperator, setTriggerOperator ] = useState( {} );
	const [ defaultOperator, setDefaultOperator ] = useState( '' );
	const { setRenderingRows } = useContext( TriggersContext );

	const rowName = 'triggers[' + props.row_number + ']';
	const skipNextTypeEffect = useRef( false );

	useEffect( () => {
		if ( ! _.isEmpty( props.data ) ) {
			setData();
			skipNextTypeEffect.current = true; // prevent overwriting loaded default on first run
		}

		if ( ! _.isEmpty( props.firstCondition ) ) {
			setTriggerName( props.firstCondition.name );

			if ( popupTriggers.triggers[ props.firstCondition.name ]?.control ) {
				const originalControl = popupTriggers.triggers[ props.firstCondition.name ].control;
				const newTriggerControl = { ...originalControl, defaultValue: props.firstCondition.control };
				setTriggerControl( newTriggerControl );
			}

			if ( popupTriggers.triggers[ props.firstCondition.name ]?.operators?.length > 0 ) {
				setTriggerOperator( popupTriggers.triggers[ props.firstCondition.name ].operators );
				setDefaultOperator( props.firstCondition.operator );
			}

			skipNextTypeEffect.current = true; // prevent overwriting firstCondition default on first run
		}
	}, [] );

	useEffect( () => {
		if ( ! triggerName ) {
			return;
		}

		if ( skipNextTypeEffect.current ) {
			skipNextTypeEffect.current = false;
			return; // keep the control set by initial data/firstCondition
		}

		// Always reset to trigger's native control on type change
		const originalControl = popupTriggers.triggers[ triggerName ].control;
		setTriggerControl( originalControl );
		setTriggerOperator( popupTriggers.triggers[ triggerName ].operators );
	}, [ triggerName ] );

	const setData = () => {
		setTriggerName( props.data.name );

		if ( popupTriggers.triggers[ props.data.name ]?.control ) {
			const originalControl = popupTriggers.triggers[ props.data.name ].control;
			const newTriggerControl = { ...originalControl, defaultValue: props.data.control };
			setTriggerControl( newTriggerControl );
		}

		if ( popupTriggers.triggers[ props.data.name ]?.operators?.length > 0 ) {
			setTriggerOperator( popupTriggers.triggers[ props.data.name ].operators );
			setDefaultOperator( props.data.operator );
		}
	};

	const removeCondtion = () => {
		setRenderingRows( ( prevRows ) => prevRows.filter( ( row ) => row.key !== `trigger-${ props.row_number }` ) );

		// Register and set isRemoved flag so save handler can drop it even if inputs unmount
		ref( rowName + '[isRemoved]' );
		try {
			if ( typeof props.conditionSetValue === 'function' ) {
				props.conditionSetValue( rowName + '[isRemoved]', 1 );
			}
		} catch ( e ) { /* noop */ }
	};

	const renderTriggerControl = ( event ) => {
		const conditionKey = event.currentTarget.selectedOptions[ 0 ].value;

		// Clear react-hook-form registered value to avoid stale '0' in DOM
		try {
			if ( typeof props.conditionUnregister === 'function' ) {
				props.conditionUnregister( rowName + '[control]' );
			}

			if ( typeof props.conditionSetValue === 'function' ) {
				props.conditionSetValue( rowName + '[control]', '' );
			}
		} catch ( e ) { /* noop */ }

		setTriggerName( conditionKey );
		setTriggerControl( {} );
		setTriggerOperator( {} );

		// Set default operator for the newly selected trigger type
		if ( popupTriggers.triggers[ conditionKey ]?.operators?.length > 0 ) {
			setDefaultOperator( popupTriggers.triggers[ conditionKey ].operators[ 0 ] );
		} else {
			setDefaultOperator( '' );
		}
	};

	// Clear any pre-existing registered control value on mount for new rows (without server data)
	useEffect( () => {
		if ( _.isEmpty( props.data ) && typeof props.conditionUnregister === 'function' ) {
			try {
				props.conditionUnregister( rowName + '[control]' );
				if ( typeof props.conditionSetValue === 'function' ) {
					props.conditionSetValue( rowName + '[control]', '' );
				}
			} catch ( e ) { /* noop */ }
		}
	}, [] );

	const expectedControlType = triggerName ? popupTriggers.triggers[ triggerName ]?.control?.type : undefined;

	return (
		<div className="popup-trigger-row">
			<div className={ `popup-trigger-select-wrapper popup-trigger-${ triggerName }` }>
				<Form.Group className="popup-trigger-name-group me-3">
					<Form.Control
						as="select"
						className="popup-trigger-name"
						name={ rowName + '[name]' }
						defaultValue={ ( typeof props.data !== 'undefined' ) && props.data.name }
						{ ...ref( rowName + '[name]' ) }
						onChange={ renderTriggerControl.bind() }
					>
						{
							Object.keys( popupTriggers.triggers ).map( ( key ) => {
								return (
									<option
										key={ key }
										value={ key }
									>
										{ popupTriggers.triggers[ key ].label }
									</option>
								);
							} )
						}
					</Form.Control>
				</Form.Group>
				{ triggerName && ! _.isEmpty( triggerOperator ) && <TriggerOperator
					key={ `${ rowName }_${ triggerName }_operator` }
					rowName={ rowName }
					name={ triggerName }
					triggerOperator={ triggerOperator }
					triggerOperatorDefault={ defaultOperator }
					ref={ ref }
				/> }
				{ triggerName && ! _.isEmpty( triggerControl ) && ( triggerControl.type === expectedControlType ) && <TriggerControl
					key={ `${ rowName }_${ triggerName }_control` }
					rowName={ rowName }
					name={ triggerName }
					triggerControl={ triggerControl }
					ref={ ref }
					conditionControl={ props.conditionControl }
				/> }
			</div>
			<Form.Group className="popup-trigger-remove-group">
				<Button
					onClick={ removeCondtion }
				>
					<i className="eicon-close" aria-hidden="true"></i>
				</Button>
			</Form.Group>
		</div>
	);
} );

export default TirggerRow;
