import React, { forwardRef, useEffect, useState } from 'react';
import { Form } from 'react-bootstrap';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import { getOptionPrimitive, withRegister } from '../utils';

const DropDownControl = forwardRef( ( props, ref ) => {
	const [ valueOptions, setValueOptions ] = useState( [] );
	const [ value, setValue ] = useState( '' );

	useEffect( () => {
		updateOptions();

		// Ensure the selected value reflects current default on mount and when dependencies change
		if ( ( typeof props.triggerControl !== 'undefined' ) && props.triggerControl?.defaultValue ) {
			setValue( getOptionPrimitive( props.triggerControl.defaultValue ) );
		} else {
			setValue( '' );
		}
	// Re-run when trigger type or default changes to avoid stale selection
	}, [ props.name, props.triggerControl?.defaultValue ] );

	const updateOptions = () => {
		wp.ajax.send( 'jupiterx_popup_get_options', {
			type: 'GET',
			data: {
				nonce,
				type: 'trigger',
				//eslint-disable-next-line
				condition_name: props?.name,
			},
			dataType: 'json',
			success: ( data ) => {
				const options = [];

				// eslint-disable-next-line
				data.map( ( value, key ) => {
					options.push( {
						value: value.id,
						label: value.name,
					} );
				} );

				setValueOptions( options );
			},
				error: () => {},
		} );
	};

	return (
		<Form.Group className={ `d-flex align-items-center popup-trigger-type-${ props.triggerControl.type }` }>
			{ (() => {
				const registerProps = withRegister( ref, props.rowName + '[control]', ( event ) => setValue( event.target.value ) );
				return (
					<Form.Control
						as="select"
						id={ props.rowName + '_control' }
						className="popup-trigger-control"
						name={ props.rowName + '[control]' }
						value={ value }
						{ ...registerProps }
						disabled={ _.isEmpty( valueOptions ) }
					>
				{
					_.isEmpty( valueOptions ) && <option value="">
						{ __( 'Loading...', 'jupiterx-core' ) }
					</option>
				}
				{
					! _.isEmpty( valueOptions ) && valueOptions.map( ( option, key ) => {
						return <option key={ key } value={ option.value } >{ option.label }</option>;
					} )
				}
			</Form.Control>
			);
			})() }
		</Form.Group>
	);
} );

export default DropDownControl;
