import React, { useContext, useEffect } from 'react';
import { __ } from '@wordpress/i18n';
import Dialog from '../../../components/dialog';
import { useForm } from 'react-hook-form';
import { Form, Row, Col } from 'react-bootstrap';
import { actionTypes } from './reducer';
import { SettingsContext } from './../../../store/settings';

const AddDialog = ( { state, dispatch } ) => {
	const { nonce } = useContext( SettingsContext );
	const {
		register,
		handleSubmit,
		formState: { errors },
		reset,
	} = useForm();

	// Reset form when dialog is opened
	useEffect( () => {
		if ( state.adding ) {
			reset( {
				size_n: '',
				size_w: '',
				size_h: '',
				size_c: false,
			} );
		}
	}, [ state.adding, reset ] );

	const addImageSize = ( size ) => {
		dispatch( { type: actionTypes.ADD_IMAGE_SIZE_STATUS, payload: 'progress' } );

		state.sizes.push( size );

		// Format the data to ensure it's properly sent to the server
		const formattedData = {
			_ajax_nonce: nonce,
			options: {},
		};

		// Explicitly format the data in the exact structure expected by the server
		state.sizes.forEach( ( item, index ) => {
			formattedData.options[ index ] = {};
			formattedData.options[ index ].size_n = item.size_n;
			formattedData.options[ index ].size_w = item.size_w;
			formattedData.options[ index ].size_h = item.size_h;
			formattedData.options[ index ].size_c = item.size_c;
		} );

		window.wp.ajax.post( 'jupiterx_core_cp_save_image_sizes', formattedData )
			.done( () => {
				dispatch( { type: actionTypes.TOGGLE_ADD_IMAGE_SIZE_DIALOG, payload: false } );
				dispatch( { type: actionTypes.ADD_IMAGE_SIZE_STATUS, payload: '' } );
			} ).fail( () => {
				dispatch( { type: actionTypes.ADD_IMAGE_SIZE_STATUS, payload: 'error' } );
			} );
	};

	const onSubmit = ( fields ) => {
		const formattedFields = {
			...fields,
			size_c: fields.size_c ? 'On' : 'Off',
		};
		addImageSize( formattedFields );
	};

	return (
		<Dialog
			title={ __( 'Add New Image Size', 'jupiterx-core' ) }
			variant={ state.addStatus }
			show={ state.adding }
			isLoading={ state.updating }
			okText={ __( 'Save', 'jupiterx-core' ) }
			cancelText={ __( 'Discard', 'jupiterx-core' ) }
			showCancel={ true }
			closeButton={ false }
			onOk={ handleSubmit( onSubmit ) }
			onCancel={ () => dispatch( { type: actionTypes.TOGGLE_ADD_IMAGE_SIZE_DIALOG, payload: false } ) }
		>
			<Form noValidate onSubmit={ handleSubmit( onSubmit ) }>
				<Row>
					<Form.Group as={ Col } sm="12">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Size Name', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="text"
							defaultValue=""
							{ ...register( 'size_n', { required: 'This field is required' } ) }
						/>
						{
							errors.size_n &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_n.message }
							</Form.Control.Feedback>
						}
					</Form.Group>
				</Row>
				<Row>
					<Form.Group as={ Col } sm="6" className="mt-3">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Image Width', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="number"
							defaultValue=""
							{ ...register( 'size_w', {
								required: 'This field is required',
								min: { value: 1, message: 'Minimum size allowed is 1' },
							} ) }
						/>
						{
							errors.size_w &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_w.message }
							</Form.Control.Feedback>
						}
					</Form.Group>
					<Form.Group as={ Col } sm="6" className="mt-3">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Image Height', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="number"
							defaultValue=""
							{ ...register( 'size_h', {
								required: 'This field is required',
								min: { value: 1, message: 'Minimum size allowed is 1' },
							} ) }
						/>
						{
							errors.size_h &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_h.message }
							</Form.Control.Feedback>
						}
					</Form.Group>
				</Row>
				<Row>
					<Form.Group as={ Col } sm="12" className="mt-3">
						<Form.Check
							type="switch"
							defaultValue={ false }
							label={ __( 'Hard Crop', 'jupiterx-core' ) }
							{ ...register( 'size_c' ) }
						/>
					</Form.Group>
				</Row>
			</Form>
		</Dialog>
	);
};

export default AddDialog;
