import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import Post from './post';
import ListTable from './list-table';
import Dialog from '../../components/dialog';
import './style.scss';

const CustomIcons = () => {
	const [ activeComponent, setActiveComponent ] = useState( 'list' );
	const [ postObject, setPostObject ] = useState( null );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ postToDelete, setPostToDelete ] = useState( 0 );

	useEffect( () => {
		setActiveComponent( activeComponent );
	} );

	const listTable = () => {
		return <ListTable
			active={ activeComponent }
			createNew={ listTableCreateNew }
			edit={ listTableEditPost }
			newButton={ () => {
				setPostObject( null );
				setActiveComponent( 'new' );
			} }
			remove={ ( post ) => remove( post ) }
			refresh
		/>;
	};

	const newIconForm = () => {
		return <Post
			mode={ 'new' }
			post={ 0 }
			removeBtn={ () => setActiveComponent( 'list' ) }
			afterSubmit={ () => setActiveComponent( 'list' ) }
			backButton={ () => setActiveComponent( 'list' ) }
		/>;
	};

	const editIconForm = () => {
		return <Post
			mode={ 'edit' }
			post={ postObject }
			removeBtn={ () => removePostButton( postObject ) }
			afterSubmit={ () => setActiveComponent( 'list' ) }
			backButton={ () => setActiveComponent( 'list' ) }
		/>;
	};

	const removePostButton = ( post ) => {
		setPostToDelete( post );
		setShowDialog( true );
	};

	const remove = ( post ) => {
		if ( 0 === post ) {
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_icons',
			sub_action: 'remove_post',
			nonce,
			post_id: post.ID,
		} )
			.done( () => {
				setActiveComponent( 'list' );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
				setActiveComponent( 'list' );
			} );
	};

	const listTableCreateNew = () => {
		setActiveComponent( 'new' );
	};

	const listTableEditPost = ( post ) => {
		setPostObject( post );
		setActiveComponent( 'edit' );
	};

	return (
		<div className="pt-3 custom-icon-wrapper" >
			{ 'list' === activeComponent && listTable() }
			{ 'new' === activeComponent && newIconForm() }
			{ 'edit' === activeComponent && editIconForm() }
			{
				showDialog &&
				<Dialog
					className="jupiterx-custom-icon-delete-confirm"
					show
					variant="warning"
					title={ __( 'Remove the custom icon', 'jupiterx-core' ) }
					onCancel={ () => setShowDialog( false ) }
					onOk={ () => {
						remove( postToDelete );
						setShowDialog( false );
					} }
					closeButton={ false }
					okText={ __( 'Remove', 'jupiterx-core' ) }
					cancelText={ __( 'Discard', 'jupiterx-core' ) }
				>
					{ __( 'Are you sure you want to delete this icon set? This action can’t be undone.', 'jupiterx-core' ) }
				</Dialog>
			}
		</div>
	);
};

export default CustomIcons;
