import React, { useState, useEffect, forwardRef } from 'react';
import { Form, Button } from 'react-bootstrap';
import TirggerRow from './row';
import { __ } from '@wordpress/i18n';
import { withRegister } from './controls/utils';

export const TriggersContext = React.createContext();

const Triggers = forwardRef( ( props, ref ) => {
	const [ rowNumber, setRowNumber ] = useState( 1 );
	const [ renderingRows, setRenderingRows ] = useState( [] );
	const [ relationLogic, setRelationLogic ] = useState( 'or' );

	useEffect( () => {
		let rows = [];

		if ( props.data ) {
			const keys = Object.keys( props.data );

			// Handle relation_logic separately
			keys.forEach( ( key ) => {
				if ( props.data[ key ].name === 'relation_logic' ) {
					setRelationLogic( props.data[ key ]?.control );
				}
			} );

			// Process numeric keys for trigger rows
			const numericKeys = keys
				.map( ( key ) => parseInt( key, 10 ) )
				.filter( ( num ) => Number.isFinite( num ) );

			const sortedKeys = numericKeys.sort( ( a, b ) => a - b );

			rows = sortedKeys.map( ( k ) => (
				<TirggerRow
					key={ `trigger-${ k }` }
					row_number={ k }
					ref={ ref }
					conditionControl={ props.conditionControl }
					conditionUnregister={ props.conditionUnregister }
					conditionSetValue={ props.conditionSetValue }
					data={ props.data[ k ] }
				/>
			) );

			const maxKey = sortedKeys.length ? Math.max( ...sortedKeys ) : 0;
			setRowNumber( maxKey );
		}

		setRenderingRows( rows );
	}, [] );

	const addNewCondtion = () => {
		const nextKey = rowNumber + 1;
		const newRow = [
			...renderingRows,
			<TirggerRow
				key={ `trigger-${ nextKey }` }
				row_number={ nextKey }
				ref={ ref }
				conditionControl={ props.conditionControl }
				conditionUnregister={ props.conditionUnregister }
				conditionSetValue={ props.conditionSetValue }
				firstCondition={ { name: 'after_inactivity', control: 0 } }
			/>,
		];

		setRowNumber( nextKey );
		setRenderingRows( newRow );
	};

	const relationLogicRegister = withRegister( ref, 'relation_logic', ( event ) => setRelationLogic( event.target.value ) );

	return (
		<TriggersContext.Provider value={ { renderingRows, setRenderingRows } } >
			<div className="popup-triggers-wrapper">
				<div className="popup-triggers-content">
					<div id="popup-trigger-logic-relation" className="popup-trigger-row">
						<Form.Group>
							{ __( 'Logic between Triggers', 'jupiterx-core' ) }
						</Form.Group>
						<Form.Group>
							<Form.Control
								as="select"
								className="popup-trigger-name"
								name={ 'relation_logic' }
								value={ relationLogic }
								{ ...relationLogicRegister }
							>
								<option value="or">{ __( 'Or', 'jupiterx-core' ) }</option>
								<option value="and">{ __( 'And', 'jupiterx-core' ) }</option>
							</Form.Control>
						</Form.Group>
					</div>
					{ renderingRows }
					<Button
						className="d-flex justify-content-center popup-add-new-conditions"
						variant="primary"
						onClick={ addNewCondtion }
					>
						{ __( 'Add Trigger Rule', 'jupiterx-core' ) }
					</Button>
				</div>
			</div>
		</TriggersContext.Provider>
	);
} );

export default Triggers;
