import React from 'react';
import { Card, Button } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { actionTypes } from './reducer';

const ImageSize = ( { dispatch, imageSize } ) => {
	return (
		<div className="jx-cp-settings-image-sizes-list-item me-sm-3 mb-3">
			<Card>
				<Card.Header>{ imageSize.size_n }</Card.Header>
				<Card.Body>
					<div className="mb-2"><strong>
						{ __( 'Size', 'jupiterx-core' ) }:</strong> { imageSize.size_w } x { imageSize.size_h }
					</div>
					<div className="mb-4">
						<strong>{ __( 'Hard Crop', 'jupiterx-core' ) } :</strong> { imageSize.size_c }
					</div>
					<Button
						variant="outline-success"
						className="me-2"
						onClick={ () => dispatch( { type: actionTypes.EDIT_IMAGE_SIZE, payload: imageSize } ) }>Edit</Button>
					<Button variant="outline-danger"
						onClick={ () => dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE, payload: imageSize } ) }>Remove</Button>
				</Card.Body>
			</Card>
		</div>
	);
};

export default ImageSize;
