import React, { useState, useContext } from 'react';
import $ from 'jquery';
import { __, sprintf } from '@wordpress/i18n';
import Dialog from '../../../../components/dialog';
import { TemplatesContext } from '../../../../store/templates';
import { clearText } from './index';
import { nonce } from '@jupiterx/control-panel';
import './style.scss';

const RemoveDialog = ( { show, onHide, title } ) => {
	const [ isLoading, setIsLoading ] = useState( false );
	const [ isCompleted, setIsCompleted ] = useState( false );
	const [ error, setError ] = useState( null );

	const { setTemplateInstalled } = useContext( TemplatesContext );

	const handleClose = () => {
		onHide();

		setTimeout( () => {
			setIsLoading( false );
			setIsCompleted( false );
			setError( null );
		}, 200 );
	};

	const handleSuccess = () => {
		onHide();

		setTimeout( () => {
			setIsLoading( false );
			setIsCompleted( false );
			setError( null );
			setTemplateInstalled( {} );
		}, 200 );
	};

	const handleRemove = () => {
		setIsLoading( true );

		$.post( _wpUtilSettings.ajax.url, {
			nonce,
			action: 'jupiterx_core_cp_uninstall_template',
		} ).done( () => {
			setIsCompleted( true );
		} ).fail( ( data ) => {
			setError( data );
		} );
	};

	if ( error ) {
		return (
			<Dialog
				title={ __( 'Something went wrong!', 'jupiterx-core' ) }
				variant="error"
				show={ show }
				onHide={ handleClose }
			>
				{ __( 'An error occurred while removing the template, please try again.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	if ( isCompleted ) {
		return (
			<Dialog
				title={ __( 'All Done!', 'jupiterx-core' ) }
				variant="success"
				show={ show }
				onHide={ handleSuccess }
			>
				{ __( 'The template is removed.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	if ( isLoading ) {
		return (
			<Dialog
				title={ __( 'Removing the Template', 'jupiterx-core' ) }
				variant="progress"
				show={ show }
				isLoading={ isLoading }
			>
				{ __( 'Please wait until the uninstalling process is finished.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	return (
		<Dialog
			title={ __( 'Important Notice', 'jupiterx-core' ) }
			variant="warning"
			show={ show }
			onHide={ handleClose }
			showCancel={ true }
			onOk={ handleRemove }
			okText={ sprintf(
				// translators: %s Template name
				__( 'Yes, remove %s', 'jupiterx-core' ),
				clearText( title )
			) }
		>
			{ __( 'Removing the template will delete all of your current data and settings. Do you want to proceed?', 'jupiterx-core' ) }
		</Dialog>
	);
};

export default RemoveDialog;
