import React, { useState, forwardRef, useEffect } from 'react';
import Spinner from '../../../../components/spinner/index';
import { nonce } from '@jupiterx/control-panel';
import PopupHeader from '../popup-header';
import Conditions from './conditions';
import { __ } from '@wordpress/i18n';

const PopupTabCondition = forwardRef( ( props, ref ) => {
	const [ loading, setLoading ] = useState( true );
	const [ conditions, setConditions ] = useState( [] );

	let documentId = null;

	useEffect( () => {
		if ( ! _.isEmpty( elementor.documents.getCurrent() ) ) {
			documentId = elementor.documents.getCurrent().id;
		}

		getConditions( documentId );
	}, [] );

	const getConditions = () => {
		setLoading( true );

		wp.ajax.post( {
			action: 'jupiterx_popup_get_conditions',
			nonce,
			popup_id: documentId,
		} ).done( ( result ) => {
			setConditions( result );
			setLoading( false );
		} ).fail( () => {
			setLoading( false );
		} );
	};

	const headerData = {
		icon: 'conditions',
		heading: __( 'Where Do You Want to Display Your Template?', 'jupiterx-core' ),
		firstDescription: __( 'Set the conditions that determine where your Template is used throughout your site.', 'jupiterx-core' ),
		secondDescription: __( 'For example, choose "Entire Site" to display the template across your site.', 'jupiterx-core' ),
	};

	return (
		<>
			<PopupHeader { ...headerData } />
			{ loading && <Spinner size="lg" /> }
			{ ! loading && <Conditions data={ conditions } ref={ ref } conditionControl={ props.conditionControl } /> }
		</>
	);
} );

export default PopupTabCondition;
