import React from 'react';
import { __ } from '@wordpress/i18n';
import { urls } from '@jupiterx/control-panel';
import { Card } from 'react-bootstrap';

const StartCard = ( {
	header = '',
	image = 'custom-icon.svg',
	title = __( 'Add Your First Custom Icon', 'jupiterx-core' ),
	text = __( 'Add even more icons to Jupiter\'s icon collection and use them across your website.', 'jupiterx-core' ),
	actionText = __( 'Add Custom Icon', 'jupiterx-core' ),
	action,
} ) => {
	const svg = urls.controlPanel + 'img/custom-icon.svg';

	return (
		<Card className="custom-icon-start-card" id="custom_icon_empty">
			<Card.Header as="h2">{ header }</Card.Header>
			<Card.Body className="text-center">
				<img src={ svg } alt="custom-icon-splash" />
				<Card.Title as="h3">{ title }</Card.Title>
				<div className="text-wrapper">
					<Card.Text>{ text }</Card.Text>
				</div>
				<span
					onClick={ action }
					id="custom-icon-empty-add-new"
					role="button"
					onKeyDown={ action }
					tabIndex={ 0 }
				>
					{ actionText }
				</span>
			</Card.Body>
		</Card>
	);
};

export default StartCard;
