export const getStringDefault = ( value ) => {
	if ( value === '' ) {
		return '';
	}

	if ( value === null || value === undefined || value === false ) {
		return '';
	}

	// For text fields, treat 0 (number or string) as empty
	if ( value === 0 || value === '0' ) {
		return '';
	}

	if ( typeof value === 'string' ) {
		return value;
	}

	if ( typeof value === 'number' ) {
		return String( value );
	}

	if ( Array.isArray( value ) ) {
		return value
			.map( ( item ) => {
				if ( item && typeof item === 'object' ) {
					return item.value ?? item.label ?? item.id ?? item.name ?? '';
				}

				return item;
			} )
			.filter( ( v ) => v !== null && v !== undefined )
			.join( ', ' );
	}

	if ( typeof value === 'object' ) {
		return value.value ?? value.label ?? value.id ?? value.name ?? value.url ?? '';
	}

	return '';
};

export const getOptionPrimitive = ( value ) => {
	if ( value && typeof value === 'object' ) {
		return value.value ?? value.id ?? '';
	}

	return value ?? '';
};

export const withRegister = ( registerFn, name, onChange ) => {
	const registerProps = registerFn( name );

	return {
		...registerProps,
		onChange: ( event ) => {
			if ( typeof onChange === 'function' ) {
				onChange( event );
			}

			if ( typeof registerProps.onChange === 'function' ) {
				registerProps.onChange( event );
			}
		},
	};
};
