import React, { createContext, useState } from 'react';
import { nonce, options as settings, postTypes, activePlugins, tabs, isMultilingual } from '@jupiterx/control-panel';

export const SettingsContext = createContext();

export const SettingsProvider = ( { children } ) => {
	const [ options, setOptions ] = useState( settings );
	const [ showHelpLink ] = useState( parseInt( options.white_label_help_links ) );

	const isWhiteLabel = parseInt( options.white_label );

	const store = {
		nonce,
		options,
		postTypes,
		activePlugins,
		isWhiteLabel,
		showHelpLink,
		setOptions,
		tabs,
		isMultilingual,
	};

	return (
		<SettingsContext.Provider value={ store }>
			{ children }
		</SettingsContext.Provider>
	);
};

SettingsContext.displayName = 'SettingsContext';
