import React from 'react';
import { Alert as RBAlert } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faExclamationCircle, faCheckCircle, faTimesCircle } from '@fortawesome/free-solid-svg-icons';
import classnames from 'classnames';
import './style.scss';

const ICONS = {
	success: faCheckCircle,
	warning: faExclamationCircle,
	danger: faTimesCircle,
};

const Alert = ( { variant, showIcon = true, children, ...props } ) => {
	const className = classnames( [
		'jx-cp-alert',
		props.className,
	] );

	let icon = null;
	if ( showIcon && variant && ICONS[ variant ] ) {
		icon = ICONS[ variant ];
	}

	return (
		<RBAlert { ...props } className={ className } variant={ variant }>
			{ ( showIcon && icon ) && (
				<span className="jx-cp-alert-icon">
					<FontAwesomeIcon icon={ icon } />
				</span>
			) }
			<div>
				{ children }
			</div>
		</RBAlert>
	);
};

export default Alert;
