import React, { useState } from 'react';
import { Button, Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { siteName } from '@jupiterx/control-panel';
import { useForm } from 'react-hook-form';
import { isEmpty } from 'lodash';
import Dialog from './dialog';

const ExportCard = () => {
	const [ data, setData ] = useState( {} );

	const { register, handleSubmit } = useForm();

	const onSubmit = ( { filename, config } ) => {
		if ( config.length ) {
			setData( {
				filename,
				config: [ 'Start', ...config, 'End' ],
			} );
		}
	};

	const handleClose = () => {
		setData( {} );
	};

	return (
		<>
			<Form onSubmit={ handleSubmit( onSubmit ) }>
				<Form.Group>
					<Form.Label htmlFor="export-filename">{ __( 'Filename', 'jupiterx-core' ) }</Form.Label>
					<Form.Control
						size="sm"
						type="text"
						id="export-filename"
						name="filename"
						placeholder={ `${ siteName }-jupiterx` }
						{ ...register( 'filename' ) }
					/>
				</Form.Group>
				<Form.Group>
					<Form.Check
						defaultChecked={ true }
						id="export-content"
						type="checkbox"
						name="config"
						value="Content"
						label={ __(	'Site Content', 'jupiterx-core' ) }
						{ ...register( 'config' ) }
					/>
					<Form.Check
						defaultChecked={ true }
						id="export-widgets"
						type="checkbox"
						name="config"
						value="Widgets"
						label={ __(	'Widgets', 'jupiterx-core' ) }
						{ ...register( 'config' ) }
					/>
					<Form.Check
						defaultChecked={ true }
						id="export-settings"
						type="checkbox"
						name="config"
						value="Settings"
						label={ __(	'Settings', 'jupiterx-core' ) }
						{ ...register( 'config' ) }
					/>
					<Form.Check
						defaultChecked={ true }
						id="export-custom-tables"
						type="checkbox"
						name="config"
						value="Custom Tables"
						label={ __(	'Custom Tables', 'jupiterx-core' ) }
						{ ...register( 'config' ) }
					/>
				</Form.Group>
				<Button type="submit" size="sm" variant="primary">{ __( 'Export', 'jupiterx-core' ) }</Button>
			</Form>
			<Dialog show={ ! isEmpty( data ) } onHide={ handleClose } formData={ data } />
		</>
	);
};

export default ExportCard;
