import React, { useState, useContext, useEffect, forwardRef } from 'react';
import { Form, Button } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { ConditionsContext } from '../conditions';
import { popupConditions } from '@jupiterx/control-panel';
import SubConditions from './sub-conditions';
import './style.scss';

const ConditionRow = forwardRef( ( props, ref ) => {
	const [ rowType, setRowType ] = useState( 'include' );
	const [ subName, setSubName ] = useState( '' );
	const [ subNameCondition, setSubCondition ] = useState( {} );
	const { setRenderingRows } = useContext( ConditionsContext );

	const rowName = 'conditions[' + props.row_number + ']';

	useEffect( () => {
		if ( ! _.isEmpty( props.data ) ) {
			setData();
		}
	}, [] );

	const setData = () => {
		if ( props.data.name !== 'general' ) {
			setSubCondition( popupConditions[ props.data.name ] );
		}

		setRowType( props.data.type );
	};

	const removeCondtion = () => {
		setRenderingRows( ( prevRows ) => {
			const result = prevRows.filter( ( row ) => {
				return parseInt( row.key ) !== parseInt( props.row_number );
			} );

			return [ ...result ];
		} );

		ref( rowName + '[isRemoved]' );
	};

	const firstLetterCapitalize = ( value ) => {
		return value.charAt( 0 ).toUpperCase() + value.slice( 1 );
	};

	const renderGeneralConditions = ( event ) => {
		const conditionKey = event.currentTarget.selectedOptions[ 0 ].value;

		if ( conditionKey === 'general' ) {
			setSubName( '' );
			setSubCondition( {} );

			return;
		}

		setSubName( conditionKey );
		setSubCondition( popupConditions[ conditionKey ] );
	};

	return (
		<div className="popup-conditions-row">
			<div className="popup-condition-select-wrapper">
				<Form.Group
					className={ 'popup-condition-type-group' + ( rowType === 'exclude' ? ' exclude-type' : '' ) }
				>
					<Form.Control
						as="select"
						className="popup-condition-type"
						name={ rowName + '[type]' }
						defaultValue={ ( typeof props.data !== 'undefined' ) && props.data.type }
						onChange={ ( event ) => setRowType( event.target.value ) }
						{ ...ref( rowName + '[type]' ) }
					>
						<option value="include">
							{ __( 'Include', 'jupiterx-core' ) }
						</option>
						<option value="exclude">
							{ __( 'Exclude', 'jupiterx-core' ) }
						</option>
					</Form.Control>
				</Form.Group>
				<Form.Group className="popup-condition-name-group">
					<Form.Control
						as="select"
						className="popup-condition-name"
						name={ rowName + '[name]' }
						defaultValue={ ( typeof props.data !== 'undefined' ) && props.data.name }
						{ ...ref( rowName + '[name]' ) }
						onChange={ renderGeneralConditions }
					>
						<option value="general">
							{ popupConditions.general.all_label }
						</option>
						{
							Object.keys( popupConditions.general.sub_conditions ).map( ( key ) => {
								const filedName = popupConditions.general.sub_conditions[ key ] === 'woo_commerce' ? __( 'WooCommerce', 'jupiterx-core' ) : firstLetterCapitalize( popupConditions.general.sub_conditions[ key ] );

								return (
									<option
										key={ key }
										value={ popupConditions.general.sub_conditions[ key ] }
									>
										{ filedName }
									</option>
								);
							} )
						}
					</Form.Control>
				</Form.Group>
				{ subNameCondition && ! _.isEmpty( subNameCondition.all_label ) && <SubConditions
					rowName={ rowName }
					name={ subName }
					subCondition={ subNameCondition }
					ref={ ref }
					conditionControl={ props.conditionControl }
					firstLetterCapitalize={ firstLetterCapitalize }
					data={ props.data }
				/> }
			</div>
			<Form.Group className="popup-condition-remove-group">
				<Button
					onClick={ removeCondtion }
				>
					<i className="eicon-close" aria-hidden="true"></i>
				</Button>
			</Form.Group>
		</div>
	);
} );

export default ConditionRow;
