import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import { Table, Button, Dropdown, Pagination } from 'react-bootstrap';
import Spinner from '../../components/spinner/index';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEdit, faTrashAlt } from '@fortawesome/free-solid-svg-icons';
import Dialog from '../../components/dialog';
import StartCard from './start-card';

const ListTable = ( {
	postType = 'jupiterx-fonts',
	actions = [ 'view', 'edit' ],
	edit = () => {},
	view = () => {},
	refresh,
	newButton,
	createNew,
} ) => {
	const [ loading, setLoading ] = useState( true );
	const [ posts, setPosts ] = useState( [] );
	const [ maxNumPages, setMaxNumPages ] = useState( 1 );
	const [ columns, setColumns ] = useState( [] );
	const [ paged, setPaged ] = useState( 1 );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ postToDelete, setPostToDelete ] = useState( 0 );

	// Initial post fetch and whenever paged is changed.
	useEffect( () => {
		fetchPosts();
	}, [ paged, refresh ] );

	// Fetch post.
	const fetchPosts = () => {
		setLoading( true );

		wp.ajax.send( 'jupiterx_custom_fonts_get_posts', {
			type: 'GET',
			data: {
				nonce,
				post_type: postType,
				paged,
			},
			dataType: 'json',
		} ).done( ( data ) => {
			setPosts( data.posts );
			setMaxNumPages( data.max_num_pages );
			setColumns( data.columns );
			setLoading( false );
		} ).fail( ( data ) => {
			// eslint-disable-next-line no-console
			console.error( data );
		} );
	};

	const remove = ( post ) => {
		if ( 0 === post ) {
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_fonts',
			sub_action: 'remove_post',
			nonce,
			post_id: post.ID,
		} )
			.done( () => {
				fetchPosts();
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	// Paginate.
	const paginate = ( number ) => {
		if ( number === paged ) {
			return;
		}

		setPaged( number );
	};

	// Display delete confirm dialog.
	const confirmRemove = ( post ) => {
		setPostToDelete( post );
		setShowDialog( true );
	};

	// Prepare pagination markup.
	const getPagination = () => {
		const active = paged;
		const items = [];

		for ( let number = 1; number <= maxNumPages; number++ ) {
			items.push(
				<Pagination.Item
					key={ number }
					active={ number === active }
					onClick={ () => paginate( number ) }>
					{ number }
				</Pagination.Item>,
			);
		}

		return <Pagination>{ items }</Pagination>;
	};

	function generatePreview( post, column ) {
		// Check if column or font_settings exists
		if ( ! column || ! column.font_settings || ! Array.isArray( column.font_settings ) || column.font_settings.length === 0 ) {
			return <p>{ __( 'No preview available', 'jupiterx-core' ) }</p>;
		}

		const settings = column.font_settings[ 0 ];

		/* eslint-disable camelcase */
		const {
			font_weight,
			font_style,
			woff2,
			woff,
			ttf,
			svg,
		} = settings || {};

		// Check if we have at least one font file
		if ( ! woff2 && ! woff && ! ttf && ! svg ) {
			return <p>{ __( 'No preview available', 'jupiterx-core' ) }</p>;
		}

		// Build src array with available formats
		const srcFormats = [];
		if ( woff2 ) {
			srcFormats.push( `url('${ woff2 }') format('woff2')` );
		}
		if ( woff ) {
			srcFormats.push( `url('${ woff }') format('woff')` );
		}
		if ( ttf ) {
			srcFormats.push( `url('${ ttf }') format('truetype')` );
		}
		if ( svg ) {
			srcFormats.push( `url('${ svg }') format('svg')` );
		}

		/* eslint-disable camelcase */
		const fontFace = `
		@font-face {
			font-family: ${ `jx-cp-` + post.ID };
			font-weight: ${ font_weight || 'normal' };
			font-style: ${ font_style || 'normal' };
			src: ${ srcFormats.join( ',\n\t\t\t\t' ) };
		}`;
		/* eslint-enable camelcase */

		return <>
			<style>
				{ fontFace }
			</style>
			<p
				/* eslint-disable camelcase */
				style={ {
					fontFamily: `jx-cp-` + post.ID,
					fontWeight: font_weight || 'normal',
					fontStyle: font_style || 'normal',
				} }>
				{ __( 'Almost before we knew it, we had left the ground.', 'jupiterx-core' ) }
			</p>
		</>;
	}

	return (
		<div className="custom-font-list-table">
			{ loading && <Spinner /> }
			{ ! loading && posts.length < 1 &&
				<StartCard action={ newButton }></StartCard>
			}
			{ ! loading && posts.length > 0 &&
				<>
					<div className="custom-fonts-list-header">
						<span>
							{ __( 'Custom Fonts', 'jupiterx-core' ) }
						</span>
						<Button
							onClick={ createNew }
							variant="primary">
							{ __( 'Add New', 'jupiterx-core' ) }
						</Button>
					</div>
					<Table bordered hover>
						<thead>
							<tr className="custom_fonts_table_head">
								<th className="position-relative header-boxer">
									<span> { __( 'Font Family Name', 'jupiterx-core' ) } </span>
								</th>
								{ columns.labels.map( ( column, index ) => (
									<th key={ index } className="ps-3">{ column }</th>
								) ) }
								<th></th>
							</tr>
						</thead>
						<tbody>
							{ posts.map( ( post, index ) => (
								<tr key={ index } className="custom_fonts_table_body">
									<td className="jupiterx-custom-font-field-name">
										<div className="title-wrapper">
											<span // eslint-disable-line
												className="custom-fonts-title"
												onClick={ () => edit( post ) }
												onKeyDown={ () => edit( post ) }
											>
												{ post.post_title }
											</span>
										</div>
									</td>
									{ Object.keys( columns.values ).length > 1 && columns.values[ `post_${ post.ID }` ].map(
										( column, counter ) => {
											// Counter starts from the column after the name.
											// Counter 1 is preview column.
											if ( 1 === counter ) {
												return <td key={ counter } className="ps-3"> { generatePreview( post, column ) } </td>;
											}

											// add the author edit link.
											// Counter 0 is the author.
											if ( 0 === counter ) {
												return <td className="ps-3" key={ counter }>
													<a href={ post.user_url } target="_blank" >
														{ column }
													</a>
												</td>;
											}
											return <td key={ counter } className="ps-3"> { column } </td>;
										}
									) }
									<td>
										<div className="actions-wrapper">
											{ actions.includes( 'edit' ) &&
											<Button
												variant="link"
												data-src={ post.ID }
												className="jupiterx-custom-font-action-edit text-decoration-none"
												onClick={ () => edit( post ) }
											>
											</Button>
											}
											<Dropdown className="jupiterx-custom-font-action-more">
												<Dropdown.Toggle variant="link">
													<i className="action-more-icon" aria-hidden="true"></i>
												</Dropdown.Toggle>

												<Dropdown.Menu>
													<Dropdown.Item
														className="jupiterx-custom-font-action-edit mt-2"
														onClick={ () => edit( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faEdit } />
														{ __( 'Edit', 'jupiterx-core' ) }
													</Dropdown.Item>

													<Dropdown.Item
														className="jupiterx-custom-font-action-delete mt-2"
														onClick={ () => confirmRemove( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faTrashAlt } />
														{ __( 'Delete', 'jupiterx-core' ) }
													</Dropdown.Item>
												</Dropdown.Menu>
											</Dropdown>
										</div>
									</td>
								</tr>
							) ) }
						</tbody>
					</Table>
					{
						showDialog &&
						<Dialog
							className="jupiterx-custom-font-delete-confirm"
							show
							variant="warning"
							title={ __( 'Remove the custom font', 'jupiterx-core' ) }
							onCancel={ () => setShowDialog( false ) }
							onOk={ () => {
								remove( postToDelete );
								setShowDialog( false );
							} }
							closeButton={ false }
							okText={ __( 'Remove', 'jupiterx-core' ) }
							cancelText={ __( 'Discard', 'jupiterx-core' ) }
						>
							{ __( 'Are you sure you want to delete this font? This action can’t be undone.', 'jupiterx-core' ) }
						</Dialog>
					}
				</>
			}
			{ maxNumPages > 1 && getPagination() }
		</div>
	);
};

export default ListTable;
