import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import Spinner from './../../../components/spinner';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
	faTrashAlt,
	faEye,
	faEdit,
	faExclamationTriangle,
} from '@fortawesome/free-solid-svg-icons';
import { __ } from '@wordpress/i18n';
import Dialog from './../../../components/dialog';
import Select from 'react-select';

const ConflictModal = ( props ) => {
	const [ loading, setLoading ] = useState( false );
	const [ meta, setMeta ] = useState( [] );
	const [ templates, setTemplates ] = useState( [] );

	useEffect( () => {
		fetchData();
	}, [] );

	const fetchData = () => {
		setLoading( true );

		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'check_templates_meta_conditions',
			template_id: props.identify,
			type: props.type,
			nonce,
		} )
			.always( () => {
				setLoading( false );
			} )
			.done( ( data ) => {
				setMeta( data.posts );
				prepareOptions( data.templates );
			} )
			.fail( () => {
				setMeta( [] );
			} );
	};

	const prepareOptions = ( data ) => {
		const items = [];

		// eslint-disable-next-line array-callback-return
		data.map( ( template ) => {
			items.push( { value: template.ID, label: template.post_title } );
		} );

		setTemplates( items );
	};

	const Item = ( { data } ) => {
		const [ changes, setChanges ] = useState( false );
		const [ active, setActive ] = useState( data.default_value );
		const [ saveText, setSaveText ] = useState( __( 'Apply Changes', 'jupiterx-core' ) );
		const [ showDelete, setShowDelete ] = useState( false );

		const changePostTemplate = () => {
			setSaveText( __( 'Applying...', 'jupiterx-core' ) );

			wp.ajax.post( {
				action: 'jupiterx_layout_builder',
				sub_action: 'change_post_template_part',
				post: data.ID,
				template: active,
				type: props.type,
				nonce,
			} )
				.always( () => {
					setTimeout( () => {
						setSaveText( __( 'Apply Changes', 'jupiterx-core' ) );
						fetchData();
					}, 1000 );
				} );
		};

		const removeData = ( id ) => {
			wp.ajax.post( {
				action: 'jupiterx_layout_builder',
				sub_action: 'remove_templates_meta_conditions',
				post_id: id,
				type: props.type,
				nonce,
			} )
				.always( () => {
					fetchData();
				} );
		};

		const RemoveDataModal = ( { showModal } ) => {
			return (
				<Dialog
					title={ __( 'Remove Post Meta Option', 'jupiterx-core' ) }
					variant="danger"
					icon={ faExclamationTriangle }
					iconClassName="text-danger rm-icon"
					show={ showModal }
					className="layout-template-delete-dialog"
					okText={ __( 'Remove', 'jupiterx-core' ) }
					onOk={ () => removeData( data.ID ) }
					onHide={ () => setShowDelete( false ) }
					showCancel={ true }
					cancelText={ __( 'Discard', 'jupiterx-core' ) }
					onCancel={ () => setShowDelete( false ) }
				>
					<span className="desc-text">
						{
							__( 'Are you sure you want to remove this post meta override for', 'jupiterx-core' ) + ' '
						}
						<a href={ data.permalink } target="_blank">{ data.post_title }</a>?
					</span>
				</Dialog>
			);
		};

		const defaultValue = () => {
			let value;
			// eslint-disable-next-line array-callback-return
			templates.map( ( template ) => {
				if ( parseInt( template.value ) === parseInt( active ) ) {
					value = template;
				}
			} );

			return value;
		};

		const handleOnChange = ( selected ) => {
			setChanges( true );
			setActive( selected.value );
		};

		return (
			<div className="jupiterx-layout-builder-template-meta-conditions-item">
				<div className="jupiterx-layout-builder-template-meta-conditions-header">
					<div className="header-bar" >
						<div className="jx-title">{ data.post_title }</div>
						<div className="jx-tools" >
							<a href={ data.permalink } target="_blank" >
								<FontAwesomeIcon icon={ faEye } ></FontAwesomeIcon>
							</a>
							<a href={ data.edit_link.replace( /&amp;/g, '&' ) } target="_blank" >
								<FontAwesomeIcon icon={ faEdit } ></FontAwesomeIcon>
							</a>
							<FontAwesomeIcon
								icon={ faTrashAlt }
								onClick={ () => {
									setShowDelete( true );
								} }
							></FontAwesomeIcon>
						</div>
					</div>
					<div className="jx-content">
						<div>
							{ /* eslint-disable-next-line jsx-a11y/no-onchange */ }
							<Select
								className="dropdown-template-list"
								onChange={ handleOnChange }
								defaultValue={ defaultValue() }
								options={ templates }
								isSearchable={ true }
								menuPlacement="auto"
							/>
						</div>
						{
							changes &&
							<div>
								<button
									className="jx-apply-changes"
									onClick={ () => {
										changePostTemplate();
									} }
								>
									{ saveText }
								</button>
							</div>
						}
					</div>
				</div>
				<RemoveDataModal
					showModal={ showDelete }
				/>
			</div>
		);
	};

	const LayoutBuilderHeader = () => {
		return (
			<>
				<div className="d-flex condition-info">
					<span><span style={ { textTransform: 'capitalize' } }>{ props.typeTitle } </span> / <b className="condition-header-title" >{ props.title }</b> </span>
				</div>

				<div className="meta-conditions-header-description">
					<span className="title-desc">{ __( 'Posts using this template in meta options', 'jupiterx-core' ) }</span>
					<span className="small-title">{ __( 'View and edit the post meta overrides', 'jupiterx-core' ) }</span>
				</div>
			</>
		);
	};

	return (
		<>
			<div className="jupiterx-layout-builder-meta-condition-content-wrapper">
				<div
					className="meta-condition-content"
					id="jupiterx-layout-builder-meta-condition-content"
				>
					<LayoutBuilderHeader />

					{
						loading &&
						<Spinner
							as="span"
							animation="border"
							size="lg"
							role="status"
							aria-hidden="true"
						/>
					}

					{
						! loading && meta.length > 0 &&
						meta.map( ( info, index ) => {
							return (
								<Item
									data={ info }
									key={ `key-item-${ index }` }
								/>
							);
						} )
					}

					{
						! loading && meta.length < 1 &&
						<h3 className="jupiterx-layout-builder-meta-condition-empty-message">
							{ __( 'No post is using this template through meta options.', 'jupiterx-core' ) }
						</h3>
					}
				</div>
				<div className="jupiterx-layout-builder-template-meta-conditions-footer">
					<button
						onClick={ () => props.hide() }
						className="jx-close"
					>
						{ __( 'Close', 'jupiterx-core' ) }
					</button>
				</div>
			</div>
		</>
	);
};

export default ConflictModal;
