import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Modal as RBModal } from 'react-bootstrap';
import disableScroll from 'disable-scroll';

const containerElement = document.createElement( 'div' );
containerElement.classList.add( 'jx-cp' );

const bodyElement = document.getElementsByTagName( 'body' )[ 0 ];
bodyElement.appendChild( containerElement );

const setOverflow = ( show, props ) => {
	const urlHash = window.location.hash;

	if ( ! _.isEmpty( props ) && props.className === 'jx-conditions-trigger-popup-dialog' ) {
		return;
	}

	if ( ! _.isEmpty( props ) && props.className === 'jupiterx-cp-enable-widgets-modal' ) {
		return;
	}

	if ( ! _.isEmpty( window.location.search ) && '?page=jupiterx-setup-wizard' === window.location.search ) {
		disableScroll.off();
		return;
	}

	if ( ! _.isEmpty( urlHash ) && urlHash.includes( '#/layout-builder' ) ) {
		disableScroll.off();
		return;
	}

	if ( show ) {
		disableScroll.on( '', {
			disableKeys: false,
		} );
	} else {
		disableScroll.off();
	}
};

const Modal = ( { children, show, ...props } ) => {
	useEffect( () => {
		return () => {
			setOverflow( false, props );
		};
	}, [] );

	useEffect( () => {
		setOverflow( show, props );
	}, [ show ] );

	return createPortal(
		<RBModal centered container={ containerElement } show={ show } { ...props }>
			{ children }
		</RBModal>,
		containerElement
	);
};

// Exports modal sub-components from React Bootstrap.
Modal.Dialog = RBModal.Dialog;
Modal.Header = RBModal.Header;
Modal.Title = RBModal.Title;
Modal.Body = RBModal.Body;
Modal.Footer = RBModal.Footer;

export default Modal;
