import React from 'react';
import { Badge } from 'react-bootstrap';

const UpdatesBadge = ( { appState } ) => {
	if ( appState.updates.fetching ) {
		return '';
	}

	if ( appState.updates.status !== 'success' ) {
		return '';
	}

	if ( appState.updates.list.length === 0 ) {
		return '';
	}

	const updatesLeft = appState.updates.list
		.filter( ( item ) => item.status !== 'updated' )
		.length;

	if ( updatesLeft === 0 ) {
		return '';
	}

	return <Badge variant="danger" pill={ true } className="ms-1">{ updatesLeft }</Badge>;
};

export default UpdatesBadge;
