import React from 'react';
import { __ } from '@wordpress/i18n';
import { urls } from '@jupiterx/control-panel';
import { Card } from 'react-bootstrap';

const StartCard = ( {
	header = '',
	image = 'snippet-splash.svg',
	title = __( 'Add Your First Custom Snippet', 'jupiterx-core' ),
	text = __( 'Customize your site even further with custom codes. Anything from adding tracking codes, meta titles, and other scripts to setting display conditions, locations, and priority. All within one place.', 'jupiterx-core' ),
	actionText = __( 'Add Custom Snippet', 'jupiterx-core' ),
	action,
} ) => {
	const svg = urls.controlPanel + 'img/snippet-splash.svg';

	return (
		<Card className="custom-snippet-start-card" id="custom_codes_empty">
			<Card.Header as="h2">{ header }</Card.Header>
			<Card.Body className="text-center">
				<img src={ svg } alt="snippet-splash" />
				<Card.Title as="h3">{ title }</Card.Title>
				<div className="text-wrapper">
					<Card.Text>{ text }</Card.Text>
				</div>
				<span
					onClick={ action }
					id="custom-snippet-empty-add-new"
					role="button"
					onKeyDown={ action }
					tabIndex={ 0 }
				>
					{ actionText }
				</span>
			</Card.Body>
		</Card>
	);
};

export default StartCard;
