import React, { useState, Fragment, useEffect, createContext } from 'react';
import { Row, Col, Container, ListGroup, ListGroupItem, Button, Form, Tab } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { urls, themeLicense, nonce } from '@jupiterx/control-panel';
import StepsControl from './steps';
import { useForm } from 'react-hook-form';
import './style.scss';

export const SetupWizardContext = createContext();

const SetupWizard = () => {
	const [ currentStep, setCurrentStep ] = useState( 'registration' );
	const [ doneSteps, setDoneSteps ] = useState( [ 'registration' ] );
	const [ templates, setTemplates ] = useState( [] );
	const [ templatesLoader, setTemplatesLoader ] = useState( false );
	const [ stepLoader, setStepLoader ] = useState( false );
	const [ isImport, setIsImport ] = useState( false );
	const [ importStep, setImportStep ] = useState( 999 );
	const [ importFields, setImportFields ] = useState( [] );
	const [ importFieldKey, setImportFieldKey ] = useState( '' );
	const [ hasError, setHasError ] = useState( '' );
	const [ submitButton, setSubmitButton ] = useState( false );
	const [ setupWizardStatus, setSetupWizardStatus ] = useState( 'process' );
	const [ registeredLicense, setRegisteredLicense ] = useState( themeLicense.is_registered );
	const [ retryStep, setRetryStep ] = useState( 0 );
	const [ isRetry, setIsRetry ] = useState( false );

	const importingSteps = {
		install_plugins: { 0: 'install_plugins' },
		colors: { 0: 'colors' },
		typography: { 0: 'typography' },
		layout: {
			0: 'logo',
			1: 'layout',
		},
		templates: {
			0: 'site_type',
			1: 'templates',
		},
	};

	const { register, handleSubmit } = useForm();
	const backgroundImage = urls.controlPanel + 'img/setup-wizard/background.png';

	const steps = [
		{ name: 'registration', label: __( 'Registration', 'jupiterx-core' ) },
		{ name: 'colors', label: __( 'Colors', 'jupiterx-core' ) },
		{ name: 'typography', label: __( 'Typography', 'jupiterx-core' ) },
		{ name: 'layout', label: __( 'Layout', 'jupiterx-core' ) },
		{ name: 'content', label: __( 'Content', 'jupiterx-core' ) },
		{ name: 'done', label: __( 'Done!', 'jupiterx-core' ) },
	];

	const changeStep = ( step ) => {
		setLocalStorage( 'current_step', step );

		setCurrentStep( step );

		const newSteps = [
			...doneSteps,
			step,
		];

		setDoneSteps( newSteps );
	};

	const updateRegisterLicense = () => {
		setRegisteredLicense( true );
	};

	const changeStepOnHeader = ( index, step ) => {
		if ( setupWizardStatus === 'done' ) {
			return;
		}

		setLocalStorage( 'current_step', step.name );

		if ( [ 'registration', 'done' ].includes( step.name ) || ! registeredLicense || stepLoader ) {
			return;
		}

		setCurrentStep( step.name );

		const newSteps = [];

		for ( let i = 0; i < index; ++i ) {
			newSteps[ i ] = steps[ i ].name;
		}

		setDoneSteps( newSteps );
	};

	const getTemplates = async () => {
		if ( templates.length > 0 ) {
			return;
		}

		setTemplatesLoader( true );
		try {
			const data = await wp.ajax.post( {
				action: 'jupiterx_setup_wizard_get_templates',
				nonce,
			} );

			const mergedData = {};

			Object.keys( data ).forEach( ( category ) => {
				// Skip merging for "header" and "footer" categories.
				if ( category === 'header' || category === 'footer' ) {
					mergedData[ category ] = data[ category ];
				} else {
					mergedData[ category ] = [
						...( data[ category ].dark || [] ),
						...( data[ category ].light || [] ),
					];
				}
			} );

			setTemplates( mergedData );
			setTemplatesLoader( false );
		} catch ( error ) {
			// eslint-disable-next-line no-console
			console.error( error );
			setTemplatesLoader( false );
		}
	};

	useEffect( () => {
		if ( registeredLicense ) {
			setCurrentStep( 'colors' );
			setDoneSteps( [ 'registration', 'colors' ] );

			getTemplates();

			if ( getLocalStorage( 'current_step' ) ) {
				setCurrentStep( getLocalStorage( 'current_step' ) );

				const currentIndex = steps.findIndex( ( step ) => step.name === getLocalStorage( 'current_step' ) );
				const newDoneSteps = steps.slice( 0, currentIndex + 1 ).map( ( step ) => step.name );

				setDoneSteps( newDoneSteps );
			}

			return;
		}

		setCurrentStep( 'registration' );
	}, [ registeredLicense ] );

	useEffect( () => {
		if ( ! isImport ) {
			return;
		}

		callAjax();
	}, [ importStep ] );

	const updateImportStep = ( newImportStep ) => {
		setRetryStep( newImportStep );
		setIsRetry( true );
	};

	const onSubmit = ( fields ) => {
		const newFields = Object.assign( { install_plugins: fields.site_type }, fields ),
			fieldKeys = Object.keys( importingSteps );

		setSubmitButton( true );
		setIsImport( true );

		setImportFieldKey( fieldKeys );
		setImportFields( newFields );

		if ( isRetry ) {
			setImportStep( retryStep );
			callAjax();

			return;
		}

		setImportStep( 0 );
	};

	const setLocalStorage = ( key, value ) => {
		// eslint-disable-next-line no-undef
		let storage = localStorage.getItem( 'jupiterxWizard' );

		if ( _.isEmpty( storage ) ) {
			storage = '{}';
		}

		storage = JSON.parse( storage );

		storage[ key ] = value;
		// eslint-disable-next-line no-undef
		localStorage.setItem( 'jupiterxWizard', JSON.stringify( storage ) );
	};

	const getLocalStorage = ( key ) => {
		// eslint-disable-next-line no-undef
		let storage = localStorage.getItem( 'jupiterxWizard' );

		if ( _.isEmpty( storage ) ) {
			storage = '{}';
		}

		storage = JSON.parse( storage );

		return ( storage.hasOwnProperty( key ) ) ? storage[ key ] : null;
	};

	const callAjax = () => {
		if ( ! importFieldKey[ importStep ] ) {
			return;
		}

		setHasError( '' );

		if ( importFieldKey[ importStep ] === 'install_plugins' ) {
			setStepLoader( true );

			wp.ajax.post( 'jupiterx_setup_install_plugins', {
				fields: importFields,
				steps: importingSteps,
				nonce,
			} ).always( () => {
				const newImportStep = importStep + 1;

				setImportStep( newImportStep );
			} );

			return;
		}

		setStepLoader( true );

		wp.ajax.post( 'jupiterx_setup_start_process', {
			fields: importFields,
			step: importFieldKey[ importStep ],
			steps: importingSteps,
			nonce,
		} ).fail( ( repsponse ) => {
			setHasError( repsponse.step );
		} ).done( ( repsponse ) => {
			if ( repsponse.state === 'done' ) {
				setSetupWizardStatus( repsponse.state );
				return;
			}

			const newImportStep = importStep + 1;

			setImportStep( newImportStep );
		} );
	};

	const contextValue = {
		setLocalStorage: ( key, value ) => setLocalStorage( key, value ),
		getLocalStorage: ( key ) => getLocalStorage( key ),
	};

	return (
		<SetupWizardContext.Provider value={ contextValue }>
			<div className="jx-setup-wizard">
				<Container fluid={ true }>
					<Row
						className="jx-setup-wizard-header"
						style={ { backgroundImage: `url(${ backgroundImage })` } }
					>
						<Col sm={ 12 } className="d-flex align-items-center justify-content-center jx-setup-wizard-header-title">
							<img src={ urls.controlPanel + 'img/setup-wizard/logo.svg' } alt="jupiterx logo" />
							<h3>
								{ __( 'Setup Wizard', 'jupiterx-core' ) }
							</h3>
						</Col>
						<ListGroup>
							{ steps.map( ( step, index ) => {
								return (
									<Fragment key={ index }>
										{ 'registration' !== step.name ? <hr className={ ( currentStep === step.name || doneSteps.includes( step.name ) ) ? 'list-item-seprator-active' : '' } key={ index + '-hr' } /> : '' }
										<ListGroupItem className={ ( currentStep === step.name || doneSteps.includes( step.name ) ) ? 'list-group-item-active' : '' } key={ index }>
											<Button
												className={ `list-group-item-button-${ step.name }` }
												onClick={ () => changeStepOnHeader( index, step ) }
											>
												<span>{ ++index }</span>
												<h6>{ step.label }</h6>
											</Button>
										</ListGroupItem>
									</Fragment>
								);
							} ) }
						</ListGroup>
					</Row>
					{ ( 'registration' === currentStep ) && <Row className={ `jx-setup-wizard-content mt-3 jx-setup-wizard-content-step-${ currentStep }` } >
						{
							<StepsControl currentStep={ currentStep } changeStep={ changeStep } updateRegisterLicense={ updateRegisterLicense } />
						}
					</Row> }
					{ ( 'registration' !== currentStep ) &&
						<Row className={ `jx-setup-wizard-content mt-3 jx-setup-wizard-content-step-${ currentStep }` } >
							<Form className="jx-setup-wizard-steps-form" onSubmit={ handleSubmit( onSubmit ) }>
								<Tab.Container activeKey={ currentStep } defaultActiveKey={ currentStep }>
									{ steps.map( ( step, index ) => (
										<Tab.Pane eventKey={ step.name } key={ index + '-tab' }>
											<StepsControl
												templates={ templates }
												templatesLoader={ templatesLoader }
												currentStep={ currentStep }
												changeStep={ changeStep }
												stepRef={ register }
												importStep={ importFieldKey[ importStep ] }
												updateImportStep={ updateImportStep }
												importError={ hasError }
												submitButton={ submitButton }
												setupWizardStatus={ setupWizardStatus }
												getTemplates={ getTemplates }
												handleSubmit={ () => handleSubmit }
											/>
										</Tab.Pane>
									) ) }
								</Tab.Container>
							</Form>
						</Row>
					}
				</Container>
			</div>
		</SetupWizardContext.Provider>
	);
};

export default SetupWizard;
