import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import { Table, Button, Dropdown, Pagination, Badge } from 'react-bootstrap';
import Spinner from '../../components/spinner/index';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEllipsisV, faEdit, faTrashAlt, faPowerOff } from '@fortawesome/free-solid-svg-icons';
import { Link } from 'react-router-dom';
import Dialog from '../../components/dialog';
import StartCard from './start-card';
import $ from 'jquery';

const ListTable = ( {
	postType = 'jupiterx-codes',
	actions = [ 'view', 'edit' ],
	edit = () => {},
	view = () => {},
	refresh,
	newButton,
	createNew,
} ) => {
	const [ loading, setLoading ] = useState( true );
	const [ posts, setPosts ] = useState( [] );
	const [ maxNumPages, setMaxNumPages ] = useState( 1 );
	const [ columns, setColumns ] = useState( [] );
	const [ paged, setPaged ] = useState( 1 );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ postToDelete, setPostToDelete ] = useState( 0 );
	const [ runBulkAction, setRunBulkAction ] = useState( false );

	// Initial post fetch and whenever paged is changed.
	useEffect( () => {
		fetchPosts();
	}, [ paged, refresh ] );

	// Fetch post.
	const fetchPosts = () => {
		setLoading( true );

		wp.ajax.send( 'jupiterx_custom_snippets_get_posts', {
			type: 'GET',
			data: {
				nonce,
				post_type: postType,
				paged,
			},
			dataType: 'json',
		} ).done( ( data ) => {
			setPosts( data.posts );
			setMaxNumPages( data.max_num_pages );
			setColumns( data.columns );
			setLoading( false );
		} ).fail( ( data ) => {
			// eslint-disable-next-line no-console
			console.error( data );
		} );
	};

	const remove = ( post ) => {
		if ( 0 === post ) {
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_snippets',
			sub_action: 'remove_post',
			nonce,
			post_id: post.ID,
		} )
			.done( () => {
				fetchPosts();
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	// Paginate.
	const paginate = ( number ) => {
		if ( number === paged ) {
			return;
		}

		setPaged( number );
	};

	// Toggle post status.
	const toggleStatus = ( post ) => {
		wp.ajax.post( {
			action: 'jupiterx_custom_snippets',
			sub_action: 'change_status',
			nonce,
			post,
		} )
			.done( () => {
				fetchPosts();
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	// Display delete confirm dialog.
	const confirmRemove = ( post ) => {
		setPostToDelete( post );
		setShowDialog( true );
	};

	// Prepare pagination markup.
	const getPagination = () => {
		const active = paged;
		const items = [];

		for ( let number = 1; number <= maxNumPages; number++ ) {
			items.push(
				<Pagination.Item
					key={ number }
					active={ number === active }
					onClick={ () => paginate( number ) }>
					{ number }
				</Pagination.Item>,
			);
		}

		return <Pagination>{ items }</Pagination>;
	};

	const bulkAction = ( location ) => {
		const action = document.getElementById( location ).value;

		if ( ! action ) {
			return;
		}

		const postsIds = [];
		$( 'input:checkbox[name=child-boxes]:checked' ).each( function() {
			postsIds.push( $( this ).val() );
		} );

		if ( postsIds.length < 1 ) {
			return;
		}

		setRunBulkAction( true );

		wp.ajax.post( {
			action: 'jupiterx_custom_snippets',
			sub_action: 'bulk_action',
			bulk_action: action,
			nonce,
			posts: postsIds,
		} )
			.done( () => {
				fetchPosts();
				setRunBulkAction( false );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
				setRunBulkAction( false );
			} );
	};

	return (
		<div className="custom-snippet-list-table">
			{ loading && <Spinner /> }
			{ ! loading && posts.length < 1 &&
				<StartCard action={ newButton }></StartCard>
			}
			{ ! loading && posts.length > 0 &&
				<>
					<div className="custom-snippets-list-header">
						<span>
							{ __( 'Custom Snippets', 'jupiterx-core' ) }
						</span>
						<Button
							onClick={ createNew }
							variant="primary">
							{ __( 'Add New', 'jupiterx-core' ) }
						</Button>
					</div>
					<div className="table-bulk-actions">
						<select
							className="w-10"
							id="top-action"
						>
							<option value="">{ __( 'Bulk Actions', 'jupiterx-core' ) }</option>
							<option value="active">{ __( 'Activate', 'jupiterx-core' ) }</option>
							<option value="inactive">{ __( 'Inactivate', 'jupiterx-core' ) }</option>
							<option value="remove">{ __( 'Remove', 'jupiterx-core' ) }</option>
						</select>
						<button onClick={ () => bulkAction( 'top-action' ) } >
							{
								false === runBulkAction &&
								__( 'Apply', 'jupiterx-core' )
							}
							{
								true === runBulkAction &&
								<Spinner />
							}
						</button>
					</div>
					<Table bordered hover>
						<thead>
							<tr className="custom_snippets_table_head">
								<th className="position-relative header-boxer">
									<input
										type="checkbox"
										className="me-2 parent-box"
										onClick={ () => {
											if ( $( '.parent-box' ).is( ':checked' ) ) {
												$( '.child-boxes' ).prop( 'checked', true );
											} else {
												$( '.child-boxes' ).prop( 'checked', false );
											}
										} }
									/>
									<span> { __( 'Name', 'jupiterx-core' ) } </span>
								</th>
								{ columns.labels.map( ( column, index ) => (
									<th key={ index } className="ps-3">{ column }</th>
								) ) }
								<th className="text-end pe-4">{ __( 'Actions', 'jupiterx-core' ) }</th>
							</tr>
						</thead>
						<tbody>
							{ posts.map( ( post, index ) => (
								<tr key={ index } className="custom_snippets_table_body">
									<td className="jupiterx-custom-snippet-field-name">
										<div className="title-wrapper">
											<input
												type="checkbox"
												className="child-boxes"
												name="child-boxes"
												value={ post.ID }
											/>
											<span // eslint-disable-line
												className="ps-2 custom-snippets-title"
												onClick={ () => props.edit( post ) }
												as={ Link } // eslint-disable-line
												variant={ Link } // eslint-disable-line
												onKeyDown={ () => props.edit( post ) }
											>
												{ post.post_title }
											</span>
											{
												post.post_status !== 'publish' &&
												<Badge pill bg="warning">
													{ __( 'Inactive', 'jupiterx-core' ) }
												</Badge>
											}
										</div>
									</td>
									{ Object.keys( columns.values ).length > 1 && columns.values[ `post_${ post.ID }` ].map( ( column, counter ) => (
										( 2 === counter )
											? <td key={ counter }>
												<a href={ post.userUrl } target="_blank" >
													{ column }
												</a>
											</td>
											: <td key={ counter } className="ps-3">{ column }</td>
									) ) }
									<td>
										<div className="actions-wrapper">
											{ actions.includes( 'edit' ) &&
											<Button
												variant="link"
												data-src={ post.ID }
												as={ Link }
												className="jupiterx-custom-snippet-action-edit text-decoration-none"
												onClick={ () => edit( post ) }
											>
												<FontAwesomeIcon className="me-1 mb-1" icon={ faEdit } />
												<span>{ __( 'Edit', 'jupiterx-core' ) }</span>
											</Button>
											}
											<Dropdown className="jupiterx-custom-snippet-action-more">
												<Dropdown.Toggle variant="link">
													<FontAwesomeIcon className="me-1 mb-1" icon={ faEllipsisV } />
												</Dropdown.Toggle>

												<Dropdown.Menu>
													<Dropdown.Item
														className="jupiterx-custom-snippet-action-status"
														onClick={ () => toggleStatus( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faPowerOff } />
														{ post.post_status === 'publish' ? __( 'Deactivate', 'jupiterx-core' ) : __( 'Activate', 'jupiterx-core' ) }
													</Dropdown.Item>
													<Dropdown.Item
														className="jupiterx-custom-snippet-action-delete mt-2"
														onClick={ () => confirmRemove( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faTrashAlt } />
														{ __( 'Delete', 'jupiterx-core' ) }
													</Dropdown.Item>
												</Dropdown.Menu>
											</Dropdown>
										</div>
									</td>
								</tr>
							) ) }
						</tbody>
					</Table>
					<div className="table-bulk-actions">
						<select id="bottom-action">
							<option value="">{ __( 'Bulk Actions', 'jupiterx-core' ) }</option>
							<option value="active">{ __( 'Activate', 'jupiterx-core' ) }</option>
							<option value="inactive">{ __( 'Inactivate', 'jupiterx-core' ) }</option>
							<option value="remove">{ __( 'Remove', 'jupiterx-core' ) }</option>
						</select>
						<button onClick={ () => bulkAction( 'bottom-action' ) } >
							{
								false === runBulkAction &&
								__( 'Apply', 'jupiterx-core' )
							}
							{
								true === runBulkAction &&
								<Spinner />
							}
						</button>
					</div>
					{
						showDialog &&
						<Dialog
							className="jupiterx-custom-snippet-delete-confirm"
							show
							variant="warning"
							title={ __( 'Remove the custom snippet', 'jupiterx-core' ) }
							onCancel={ () => setShowDialog( false ) }
							onOk={ () => {
								remove( postToDelete );
								setShowDialog( false );
							} }
							closeButton={ false }
							okText={ __( 'Remove', 'jupiterx-core' ) }
							cancelText={ __( 'Discard', 'jupiterx-core' ) }
						>
							{ __( 'Are you sure you want to delete this snippet? This action can’t be undone.', 'jupiterx-core' ) }
						</Dialog>
					}
				</>
			}
			{ maxNumPages > 1 && getPagination() }
		</div>
	);
};

export default ListTable;
