import Modal from '../../../components/modal';
import { __, sprintf } from '@wordpress/i18n';

const ContentModal = ( {
	showModal,
	setShowModal,
	templates,
	activeTemplate,
	activeTile,
	activeSection,
	staticTemplates,
	dynamicTemplates,
	context,
	setDynamicTemplates,
	setStaticTemplates,
} ) => {
	const SingleTemplatePreview = ( { data } ) => {
		const manageOnClick = ( e ) => {
			const target = e.firstChild ? e.firstChild.target : e.target;

			if ( 'svg' === target.tagName ) {
				return;
			}

			let state;

			if ( activeSection === 'static' ) {
				state = { ...staticTemplates };
			} else {
				state = { ...dynamicTemplates };
			}

			state[ activeTemplate ] = {
				...state[ activeTemplate ],
				data: {
					...state[ activeTemplate ].data,
					thumbnail: data.thumbnail,
					id: data.id,
				},
				status: 'selected',
				import: true,
			};

			context.setLocalStorage( `content_${ activeTemplate }`, state[ activeTemplate ].data );

			if ( 'static' === activeSection ) {
				setStaticTemplates( state );
			} else {
				setDynamicTemplates( state );
			}

			setShowModal( false );
			document.body.style.overflow = 'auto';
		};

		return (
			<>
				<div
					className="single-template-preview-wrap"
					role="button"
					tabIndex={ 0 }
					onClick={ manageOnClick }
					onKeyDown={ ( e ) => {
						if ( e.key === 'Enter' || e.key === 'Spacebar' || e.key === ' ' ) {
							manageOnClick();
						}
					} }
				>
					<img
						src={ data.thumbnail }
						className="mx-auto d-block"
						alt={ data.title }
						data-id={ data.id }
						data-url={ data.url }
						title={ data.title }
						aria-hidden={ true }
					/>
				</div>
			</>
		);
	};

	return (
		<Modal
			show={ showModal }
			size="xl"
			className="setup-wizard-step-content-popup"
			onHide={ () => {
				setShowModal( false );
				document.body.style.overflow = 'auto';
			} }
		>
			<Modal.Header closeButton>
				<Modal.Title>{ activeTile } { __( 'Templates', 'jupiterx-core' ) }</Modal.Title>
			</Modal.Header>
			<Modal.Body>
				{
					<div className="popup-inner-container">
						{

							! _.isEmpty( templates ) &&
							templates?.hasOwnProperty( activeTemplate ) &&
							templates[ activeTemplate ].map( ( item, index ) => {
								return (
									<SingleTemplatePreview
										data={ item }
										key={ index }
									/>
								);
							} )
						}
						{
							// In case there is no specific template for selected section, we display all available templates.
							! _.isEmpty( templates ) &&
							! templates?.hasOwnProperty( activeTemplate ) && <strong>
								{
									sprintf(
										// translators: %s is the name of the active tile/section
										__( 'No Templates Found for the %s.', 'jupiterx-core' ),
										activeTile,
									)
								}
							</strong>
						}
					</div>
				}
			</Modal.Body>
		</Modal>
	);
};

export default ContentModal;
