import React, { useState } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import Dialog from '../../../components/dialog';
import Alert from '../../../components/alert';

const VersionControlDialog = ( { show, onHide, product, selectedVersion } ) => {
	const [ status, setStatus ] = useState( 'initial' ); // initial, processing, success, error.
	const [ logs, setLogs ] = useState( [] );

	const handleClose = () => {
		onHide();
		setStatus( 'initial' );
		setLogs( [] );
	};

	const handleSubmit = ( event ) => {
		event.preventDefault();

		setStatus( 'processing' );

		setLogs( ( log ) => [ ...log, {
			type: '',
			message: __( 'Reinstallation process started.', 'jupiterx-core' ),
		} ] );

		const productCopy = Object.assign( {}, product );

		productCopy.selected_version = productCopy.versions.find( ( { name } ) => name === selectedVersion );

		if ( typeof productCopy.selected_version === 'undefined' ) {
			return;
		}

		delete productCopy.versions;

		wp.ajax.post( {
			action: 'jupiterx_cp_settings_reinstall',
			product: productCopy,
			nonce,
		} )
			.done( () => {
				setStatus( 'success' );

				setLogs( ( log ) => [ ...log, {
					type: 'success',
					message: __( 'The package updated successfully.', 'jupiterx-core' ),
				} ] );
			} )
			.fail( ( data ) => {
				setStatus( 'error' );

				// eslint-disable-next-line no-console
				console.error( data );

				setLogs( ( log ) => [ ...log, {
					type: 'danger',
					message: __( 'The process faced an error. Please try again later. If the issue persists, please contact support.', 'jupiterx-core' ),
				} ] );
			} );
	};

	const handleReload = ( event ) => {
		event.preventDefault();
		window.location.reload();
	};

	return (
		<Dialog
			title={ sprintf(
				// translators: 1: Product name 2: Product type
				__( 'Reinstall %1$s %2$s', 'jupiterx-core' ),
				product.name,
				product.type_label
			) }
			submitText={ [ 'initial', 'processing' ].includes( status ) ? __( 'Reinstall', 'jupiterx-core' ) : __( 'Reload', 'jupiterx-core' ) }
			cancelText={ [ 'initial', 'processing' ].includes( status ) ? __( 'Cancel', 'jupiterx-core' ) : __( 'Close', 'jupiterx-core' ) }
			show={ show }
			onHide={ handleClose }
			onSubmit={ [ 'initial', 'processing' ].includes( status ) ? handleSubmit : handleReload }
			isLoading={ status === 'processing' }
		>
			<Alert variant="warning">
				{ __( 'We highly recommend you to back up your site to prevent possible data loss before you proceed.', 'jupiterx-core' ) }
			</Alert>
			<p
				dangerouslySetInnerHTML={ {
					__html: sprintf(
						// translators: 1: Product name 2: Product version 3: Product type
						__( 'Are you sure you want to reinstall <strong>%1$s v%2$s</strong> %3$s?', 'jupiterx-core' ),
						product.name,
						selectedVersion,
						product.type_label
					),
				} }
			/>
			{ logs.length ? (
				<ul className="mt-3 mb-0" style={ { listStyle: 'inside' } }>
					{ logs.map( ( log, index ) => (
						<li key={ index } className={ `text-${ log.type }` }>{ log.message }</li>
					) ) }
				</ul>
			) : ( '' ) }
		</Dialog>
	);
};

export default VersionControlDialog;
