import React, { useContext } from 'react';
import { __ } from '@wordpress/i18n';
import Dialog from '../../../components/dialog';
import { useForm } from 'react-hook-form';
import { Form, Col, Row } from 'react-bootstrap';
import { actionTypes } from './reducer';
import { SettingsContext } from './../../../store/settings';

const EditDialog = ( { state, dispatch } ) => {
	const { nonce } = useContext( SettingsContext );
	const {
		register,
		handleSubmit,
		formState: { errors },
	} = useForm();

	const saveImageSizes = ( updatedFields = null ) => {
		dispatch( { type: actionTypes.SAVE_IMAGE_SIZES_STATUS, payload: 'progress' } );

		// Create a copy of state.sizes
		const updatedSizes = [ ...state.sizes ];

		// If we have updated fields, update the corresponding size in our copy
		if ( updatedFields ) {
			const index = updatedSizes.findIndex( ( size ) => size.size_n === state.selected.size_n );
			if ( index !== -1 ) {
				updatedSizes[ index ] = updatedFields;
			}
		}

		// Format the data to ensure it's properly sent to the server
		const formattedData = {
			_ajax_nonce: nonce,
			options: {},
		};

		// Explicitly format the data in the exact structure expected by the server
		updatedSizes.forEach( ( item, index ) => {
			formattedData.options[ index ] = {};
			formattedData.options[ index ].size_n = item.size_n;
			formattedData.options[ index ].size_w = item.size_w;
			formattedData.options[ index ].size_h = item.size_h;
			formattedData.options[ index ].size_c = item.size_c;
		} );

		window.wp.ajax.post( 'jupiterx_core_cp_save_image_sizes', formattedData )
			.done( () => {
				dispatch( { type: actionTypes.SAVE_IMAGE_SIZES_STATUS, payload: '' } );
				dispatch( { type: actionTypes.EDIT_IMAGE_SIZE, payload: null } );
			} ).fail( () => {
				dispatch( { type: actionTypes.SAVE_IMAGE_SIZES_STATUS, payload: 'error' } );
			} );
	};

	const onSubmit = ( fields ) => {
		for ( const name in fields ) {
			if ( name === 'size_c' ) {
				fields[ name ] = fields[ name ] === true ? 'On' : 'Off';
			}
		}

		// First save the updated fields
		dispatch( { type: actionTypes.UPDATE_IMAGE_SIZE, payload: fields } );

		// Then pass the updated fields directly to saveImageSizes
		saveImageSizes( fields );
	};

	if ( ! state.selected ) {
		return '';
	}

	return (
		<Dialog
			title={ __( 'Edit Image Size', 'jupiterx-core' ) }
			variant={ state.saveStatus }
			show={ state.selected !== null }
			isLoading={ state.updating }
			okText={ __( 'Save', 'jupiterx-core' ) }
			cancelText={ __( 'Discard', 'jupiterx-core' ) }
			showCancel={ true }
			closeButton={ false }
			onOk={ handleSubmit( onSubmit ) }
			onCancel={ () => dispatch( { type: actionTypes.EDIT_IMAGE_SIZE, payload: null } ) }
		>
			<Form>
				<Row>
					<Form.Group as={ Col } sm="12">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Size Name', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="text"
							id="size_n"
							name="size_n"
							defaultValue={ state.selected.size_n }
							{ ...register( 'size_n', { required: true } ) }
						/>
						{
							errors.size_n &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_n.message || 'This field is required' }
							</Form.Control.Feedback>
						}
					</Form.Group>
				</Row>
				<Row>
					<Form.Group as={ Col } sm="6" className="mt-3">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Image Width', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="text"
							id="size_w"
							name="size_w"
							defaultValue={ state.selected.size_w }
							{ ...register( 'size_w', { required: true, min: { value: 1, message: 'Minimum size allowed is 1' } } ) }
						/>
						{
							errors.size_w &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_w.message || 'This field is required' }
							</Form.Control.Feedback>
						}
					</Form.Group>
					<Form.Group as={ Col } sm="6" className="mt-3">
						<Form.Label className="d-flex align-items-center">
							{ __( 'Image Height', 'jupiterx-core' ) }
						</Form.Label>
						<Form.Control
							type="text"
							id="size_h"
							name="size_h"
							defaultValue={ state.selected.size_h }
							{ ...register( 'size_h', { required: true, min: { value: 1, message: 'Minimum size allowed is 1' } } ) }
						/>
						{
							errors.size_h &&
							<Form.Control.Feedback type="invalid" className="d-block">
								{ errors.size_h.message || 'This field is required' }
							</Form.Control.Feedback>
						}
					</Form.Group>
				</Row>
				<Row>
					<Form.Group as={ Col } sm="12" className="mt-3">
						<Form.Check
							type="switch"
							id="size_c"
							name="size_c"
							label={ __( 'Hard Crop', 'jupiterx-core' ) }
							defaultChecked={ state.selected.size_c === 'On' }
							{ ...register( 'size_c' ) }
						/>
					</Form.Group>
				</Row>
			</Form>
		</Dialog>
	);
};

export default EditDialog;
