import React, { useState } from 'react';
import { Card, Button, Spinner } from 'react-bootstrap';
import $ from 'jquery';
import { __ } from '@wordpress/i18n';
import { isPremium } from '@jupiterx/control-panel';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faInfoCircle } from '@fortawesome/free-solid-svg-icons';
import Tooltip from '../../../components/tooltip';
import ProBadge from '../../../components/pro-badge';
import SimplicityImportModal from './simplicity-modal';

const DOWNLOAD = {
	PSD: [ 'get_template_psd', 'psd_link' ],
	SKETCH: [ 'get_template_sketch', 'sketch_link' ],
};

const getFile = ( options, slug, setIsLoading ) => {
	setIsLoading( true );

	$.ajax( {
		type: 'POST',
		url: _wpUtilSettings.ajax.url,
		data: {
			action: `jupiterx_core_cp_${ options[ 0 ] }`,
			template_name: slug.replace( '-jupiterx', '' ),
		},
	} ).done( ( res ) => {
		if ( res.status && res.data[ options[ 1 ] ] ) {
			window.top.location.href = res.data[ options[ 1 ] ];
		}
	} ).always( () => {
		setIsLoading( false );
	} );
};

const TemplateCard = ( {
	id,
	title,
	slug,
	demo,
	psd,
	sketch,
	free,
	plugins,
	image,
	pro,
	onImport,
	simplicity,
} ) => {
	const [ isPSDLoading, setIsPSDLoading ] = useState( false );
	const [ isSketchLoading, setIsSketchLoading ] = useState( false );
	const [ showMoal, setShowModal ] = useState( false );

	const handleImport = () => {
		if ( simplicity === '1' || simplicity === true ) {
			setShowModal( true );
			return;
		}

		onImport( { id, title, image, demo } );
	};

	const handleShowModal = () => {
		setShowModal( false );
	};

	const handleImportOnModal = () => {
		setShowModal( false );

		onImport( { id, title, image, demo } );
	};

	return (
		<Card key={ id }>
			{ ( ! pro && free !== 'true' ) && <ProBadge /> }
			<Card.Img variant="top" style={ { backgroundImage: `url(${ image })` } } />
			<Card.Body>
				{ title && (
					<h5 className="mb-3">{ title.replace( ' Jupiterx', '' ) }</h5>
				) }
				{ ( ( isPremium && pro ) || free === 'true' ) && (
					<Button
						className="me-2"
						size="sm"
						onClick={ handleImport }
					>
						{ __( 'Import', 'jupiterx-core' ) }
					</Button>
				) }
				<Button
					className="me-2"
					size="sm"
					variant="outline-secondary"
					target="_blank"
					href={ demo }
				>
					{ __( 'Preview', 'jupiterx-core' ) }
				</Button>
				{ ( psd && pro ) && (
					<Button
						className="me-2"
						size="sm"
						variant="outline-primary"
						disabled={ isPSDLoading }
						onClick={ () => getFile( DOWNLOAD.PSD, slug, setIsPSDLoading ) }
					>
						{ isPSDLoading && (
							<Spinner className="me-1" size="sm" animation="border" role="status" />
						) }
						PSD
					</Button>
				) }
				{ ( sketch && sketch.toString() === 'true' && pro ) && (
					<Button
						className="me-2"
						size="sm"
						variant="outline-primary"
						disabled={ isSketchLoading }
						onClick={ () => getFile( DOWNLOAD.SKETCH, slug, setIsSketchLoading ) }
					>
						{ isSketchLoading && (
							<Spinner className="me-1" size="sm" animation="border" role="status" />
						) }
						.SKETCH
					</Button>
				) }
				{ ( plugins && plugins.length > 0 ) && (
					<Tooltip
						overlay={
							<div className="text-left">
								<strong>{ __( 'Plugins Used:', 'jupiterx-core' ) }</strong>
								<br />
								<span>{ plugins.join( ', ' ) }</span>
							</div>
						}
					>
						<span className="text-secondary align-bottom h5">
							<FontAwesomeIcon icon={ faInfoCircle } />
						</span>
					</Tooltip>
				) }
			</Card.Body>
			{ simplicity && showMoal && <SimplicityImportModal show={ showMoal } handleShowModal={ handleShowModal } handleImportOnModal={ handleImportOnModal } /> }
		</Card>
	);
};

export default TemplateCard;
