import React, { useState, useContext } from 'react';
import StepButton from '../compenents/step-button';
import { __ } from '@wordpress/i18n';
import TypographyCard from '../compenents/typography-card';
import TypographyCustomize from '../compenents/typography-customize';
import SkipWizardButton from '../compenents/skip-wizard-button';
import { SetupWizardContext } from '..';

const TypographyControl = ( props ) => {
	const context = useContext( SetupWizardContext );
	const [ selectedTypographyStyles, setSelectedTypographyStyles ] = useState( context.getLocalStorage( 'selected_typography' ) );
	const [ selectedCard, setSelectedCard ] = useState( context.getLocalStorage( 'selected_typography_card' ) );

	const handleTypographyStyleClick = ( typographyStyles, index ) => {
		setSelectedTypographyStyles( typographyStyles );
		setSelectedCard( index );

		context.setLocalStorage( 'selected_typography', typographyStyles );
		context.setLocalStorage( 'selected_typography_card', index );
	};

	const handleBackClick = () => {
		setSelectedTypographyStyles( null );
	};

	const typographyStyles = [
		{
			heading: {
				fontFamily: 'Big Shoulders Display',
			},
			body: {
				fontFamily: 'Manrope',
			},
		},
		{
			heading: {
				fontFamily: 'Yeseva One',
			},
			body: {
				fontFamily: 'Mukta',
			},
		},
		{
			heading: {
				fontFamily: 'Rubik',
			},
			body: {
				fontFamily: 'Inter',
			},
		},
		{
			heading: {
				fontFamily: 'Poppins',
			},
			body: {
				fontFamily: 'Nunito Sans',
			},
		},
		{
			heading: {
				fontFamily: 'Playfair Display',
			},
			body: {
				fontFamily: 'Roboto',
			},
		},
		{
			heading: {
				fontFamily: 'Inter',
				fontWeight: 700,
			},
			body: {
				fontFamily: 'Lato',
			},
		},
		{
			heading: {
				fontFamily: 'Pridi',
			},
			body: {
				fontFamily: 'Tajawal',
			},
		},
		{
			heading: {
				fontFamily: 'Sora',
			},
			body: {
				fontFamily: 'Montserrat',
			},
		},
		{
			heading: {
				fontFamily: 'Ubuntu',
			},
			body: {
				fontFamily: 'Open Sans',
			},
		},
	];

	return (
		<>
			<div className="step-typography-header">
				<h2>
					{ __( 'Font It Up!', 'jupiterx-core' ) }
				</h2>
				<p>
					{ __( 'Words have power, so let\'s make them look amazing.', 'jupiterx-core' ) + ' ' }
					<br />
					{ __( 'Select from a collection of stylish fonts that match your', 'jupiterx-core' ) + ' ' }
					<br />
					{ __( 'website\'s personality.', 'jupiterx-core' ) }
				</p>
			</div>

			{ selectedTypographyStyles ? (
				<TypographyCustomize typographyStyles={ selectedTypographyStyles } onBackClick={ handleBackClick } stepRef={ props.stepRef } />
			) : (
				<div className="step-typography-body">
					<div className="row">
						{ typographyStyles.map( ( colTypographyStyles, colIndex ) => (
							<div className="typography-col" key={ colIndex }>
								<button
									className={ `jx-setup-wizard-typography-card-wrapper ${ colIndex === parseInt( selectedCard ) ? 'selected' : '' }` }
									onClick={ () => handleTypographyStyleClick( colTypographyStyles, colIndex ) }
								>
									<span className="mark-holder"></span>
									<TypographyCard typographyStyles={ colTypographyStyles } />
								</button>
							</div>
						) ) }
					</div>
				</div>
			) }

			{ selectedTypographyStyles &&
				<StepButton nextStep={ 'layout' } { ...props } />
			}

			{ ! selectedTypographyStyles &&
				<SkipWizardButton />
			}
		</>
	);
};

export default TypographyControl;
