import React, { useState } from 'react';
import { nonce, elementorImportSecurity } from '@jupiterx/control-panel';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { Button } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import Dialog from './../../../components/dialog';
import Spinner from './../../../components/spinner';
import { faCloudDownloadAlt, faWarning } from '@fortawesome/free-solid-svg-icons';

/* eslint no-unused-vars: 0 */

const PostsAddNew = ( props ) => {
	const [ dialog, setDialog ] = useState( false );
	const [ title, setTitle ] = useState( '' );
	const [ createPost, setCreatePost ] = useState( false );
	const [ security, setSecurity ] = useState( elementorImportSecurity );
	const [ securityModal, setSecurityModal ] = useState( false );

	const createNewPost = () => {
		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'create_post',
			post_title: title,
			type: props.type,
			nonce,
			beforeSend: () => {
				setDialog( true );
				setTitle( '' );
				setCreatePost( true );
			},
		} )
			.done( ( data ) => {
				window.open( data.url, '_blank' );
				setDialog( false );
				setTitle( '' );
				setCreatePost( false );
				props.attach( data.post );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
				setDialog( false );
				setTitle( '' );
				setCreatePost( false );
			} );
	};

	const EnableSecurityModal = () => {
		const [ showModal, setShowModal ] = useState( true );
		const [ activating, setActivating ] = useState( false );

		const activeElementorImportSecurity = () => {
			wp.ajax.post( {
				action: 'jupiterx_layout_builder',
				sub_action: 'active_elementor_import_security',
				nonce,
			} )
				.done( () => {
					afterDecision();
				} )
				.fail( () => {
					setShowModal( false );
				} );
		};

		const afterDecision = () => {
			setShowModal( false );
			setSecurityModal( false );
			setSecurity( true );
			props.import();
		};

		return (
			<Dialog
				title={ __( 'Enable Unfiltered File Uploads', 'jupiterx-core' ) }
				variant="warning"
				icon={ faWarning }
				show={ showModal }
				className="layout-template-new-dialog layout-template-elementor-import-dialog-error"
				okText={ activating ? <Spinner /> : __( 'Enable and Import', 'jupiterx-core' ) }
				onOk={ activeElementorImportSecurity }
				onHide={ () => {
					setShowModal( false );
					setSecurityModal( false );
				} }
				showCancel={ true }
				cancelText={ __( 'Import Without Enabling', 'jupiterx-core' ) }
				onCancel={ () => {
					afterDecision();
				} }
			>
				<p>
					{ __( 'Before you enable unfiltered file upload, note that such files include a security risk. Jupiter does run a process to remove possible malicious code, but there is still a risk involved when using such files.', 'jupiterx-core' ) }
					<br></br>
					<br></br>
					{ __( 'If you do not enable uploading unfiltered files, any SVG or JSON (including Lottie files) used in the uploaded template will not be imported.', 'jupiterx-core' ) }
				</p>
			</Dialog>
		);
	};

	return (
		<div className="d-flex templates-header">
			<div className="col-6 jx-layout-builder-header-left-side">
				<span className="posts-header-title pt-1">{ props.title }</span>
				<Button
					variant="primary"
					className="posts-header-add"
					onClick={ () => {
						setDialog( true );
						setTitle( '' );
						setCreatePost( false );
					} }
				>
					{ '+ ' + __( 'Add New', 'jupiterx-core' ) }
				</Button>
			</div>
			<div className="col-6 jx-layout-builder-header-right-side p-0">
				{
					dialog &&
					<Dialog
						title={ __( 'Add New', 'jupiterx-core' ) }
						show
						className="layout-template-new-dialog layout-template-new-dialog-fixing"
						okText={ createPost ? <Spinner /> : __( 'Create', 'jupiterx-core' ) }
						onOk={ createNewPost }
						onHide={ () => {
							setDialog( false );
							setTitle( '' );
							setCreatePost( false );
						} }
						showCancel={ true }
						cancelText={ __( 'Discard', 'jupiterx-core' ) }
						onCancel={ () => {
							setDialog( false );
							setTitle( '' );
							setCreatePost( false );
						} }
					>
						<label htmlFor="dialog_new_post_title">{ __( 'Name', 'jupiterx-core' ) }</label>
						<input
							id="dialog_new_post_title"
							className="form-control"
							type="text"
							value={ title }
							onChange={ ( event ) => {
								setDialog( true );
								setTitle( event.target.value );
								setCreatePost( false );
							} }
						/>
					</Dialog>
				}
				{
					securityModal &&
					<EnableSecurityModal />
				}
				<Button
					variant="outline-secondary"
					className="post-header-import"
					id="layout-builder-import-button"
					onClick={ () => {
						if ( false === security || _.isEmpty( security ) || '0' === security ) {
							setSecurityModal( true );
							return;
						}

						props.import();
					} }
				>
					<FontAwesomeIcon icon={ faCloudDownloadAlt } size="sm" />
					<span>{ __( 'Import', 'jupiterx-core' ) }</span>
				</Button>
			</div>
		</div>
	);
};

export default PostsAddNew;
