import React, { useState } from 'react';
import { Spinner } from 'react-bootstrap';

const ItemIframe = ( props ) => {
	const [ loading, setLoading ] = useState( true );
	const [ visibility, setVisibility ] = useState( 'hidden' );

	const handleIframe = () => {
		setLoading( false );
		setVisibility( 'visible' );
	};

	return (
		<>
			{
				loading ? (
					<Spinner animation="border" role="status" className="template-loading-animation"></Spinner>
				) : null
			}
			<iframe
				loading="lazy"
				onLoad={ handleIframe }
				title="preview"
				src={ props.previewUrl }
				width="100%"
				style={ { visibility } }
			/>
		</>
	);
};

export default ItemIframe;
