import { __ } from '@wordpress/i18n';

const PARTIAL_MODE = [
	{
		title: __( 'Downloading package...', 'jupiterx-core' ),
		methods: [
			'preparation',
			'upload',
			'unzip',
			'validate',
		],
	},
	{
		title: __( 'Installing required plugins...', 'jupiterx-core' ),
		methods: [
			'install_plugins',
		],
	},
	{
		title: __( 'Importing content...', 'jupiterx-core' ),
		methods: [
			'theme_content',
			'activate_plugins',
			'plugins_content',
			'finalize',
		],
	},
];

const FULL_MODE = [
	{
		title: __( 'Creating database backup...', 'jupiterx-core' ),
		methods: [
			'preparation',
			'backup_db',
			'backup_media_records',
			'reset_db',
		],
	},
	{
		title: __( 'Downloading package...', 'jupiterx-core' ),
		methods: [
			'upload',
			'unzip',
			'validate',
		],
	},
	{
		title: __( 'Installing required plugins...', 'jupiterx-core' ),
		methods: [
			'install_plugins',
		],
	},
	{
		title: __( 'Importing content...', 'jupiterx-core' ),
		methods: [
			'custom_tables',
			'theme_content',
			'activate_plugins',
			'setup_pages',
			'plugins_content',
			'settings',
			'menu_locations',
			'theme_widget',
			'restore_media_records',
			'finalize',
		],
	},
];

const getModeData = ( mode ) => {
	return mode === 'partial' ? [ ...PARTIAL_MODE ] : [ ...FULL_MODE ];
};

const getProgress = ( mode, method ) => {
	const methods = getModeData( mode ).reduce( ( arr, step ) => {
		return arr.concat( step.methods );
	}, [] );

	return ( methods.indexOf( method ) / methods.length ) * 100;
};

export const initialState = {
	isCompleted: false,
	isLoading: false,
	config: {},
	query: [],
	steps: [],
	progress: 0,
	error: null,
};

export const actions = {
	CONFIG: 'CONFIG',
	INITIALIZE: 'INITIALIZE',
	NEXT_QUERY: 'NEXT_QUERY',
	RESET: 'RESET',
	ERROR: 'ERROR',
};

export const reducer = ( state, { type, payload } ) => {
	switch ( type ) {
		case actions.CONFIG:
			return {
				...state,
				config: {
					...state.config,
					...payload,
				},
			};
		case actions.INITIALIZE: {
			const steps = getModeData( state.config.mode );

			return {
				...state,
				isLoading: true,
				query: [ steps[ 0 ].methods[ 0 ], 0, 0 ],
				steps: [ ...steps ],
			};
		}
		case actions.NEXT_QUERY: {
			let [ method, stepId, methodId ] = state.query;

			// Update steps text.
			const steps = state.steps.map( ( step, key ) => {
				return key !== stepId
					? step
					: { ...step, text: payload };
			} );

			methodId = methodId + 1;
			// Go to next step when last method of the step reached.
			if ( methodId >= steps[ stepId ].methods.length ) {
				steps[ stepId ].done = true;
				stepId += 1;
				methodId = 0;
			}

			// Proceed to next step if last step not reached.
			if ( stepId < steps.length ) {
				// Set the next method.
				method = steps[ stepId ].methods[ methodId ];

				return {
					...state,
					query: [ method, stepId, methodId ],
					steps: [ ...steps ],
					isLoading: true,
					progress: getProgress( state.mode, method ),
				};
			}

			return {
				...state,
				query: [],
				steps: [],
				isLoading: false,
				progress: 0,
				isCompleted: true,
			};
		}
		case actions.ERROR:
			return {
				...initialState,
				error: payload,
			};
		case actions.RESET:
			return {
				...initialState,
			};
		default:
			return {
				...state,
			};
	}
};
