import React, { useState, useEffect, useContext, Fragment } from 'react';
import StepButton from '../compenents/step-button';
import { __ } from '@wordpress/i18n';
import { Button, Form } from 'react-bootstrap';
import { SetupWizardContext } from '..';
import { urls } from '@jupiterx/control-panel';
import ContentModal from '../compenents/content-modal';

const ContentControl = ( props ) => {
	const context = useContext( SetupWizardContext );
	let defaultSiteType = context.getLocalStorage( 'site_type' );

	if ( _.isEmpty( defaultSiteType ) ) {
		defaultSiteType = 'standard';
	}

	const [ siteType, setSiteType ] = useState( defaultSiteType );
	const [ showModal, setShowModal ] = useState( false );
	const [ activeTemplate, setActiveTemplate ] = useState( 'about' );
	const [ activeTile, setActiveTitle ] = useState( '' );
	const [ activeSection, setActiveSection ] = useState( 'static' );
	const [ staticTemplates, setStaticTemplates ] = useState( {} );
	const [ dynamicTemplates, setDynamicTemplates ] = useState( {} );

	const defaultImportSample = context.getLocalStorage( 'import_sample' ) ?? true;
	const [ isChecked, setIsChecked ] = useState( defaultImportSample );

	const handleCheckboxChange = () => {
		setIsChecked( ! isChecked );
		context.setLocalStorage( 'import_sample', ! isChecked );
	};

	useEffect( () => {
		setStaticTemplates( {
			homepage: {
				slug: 'homepage',
				title: __( 'Homepage', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'homepage' ),
				status: 'primary',
				kind: 'all',
			},
			about: {
				slug: 'about',
				title: __( 'About', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'about' ),
				status: 'primary',
				kind: 'all',
			},
			services: {
				slug: 'services',
				title: __( 'Services', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'services', 9393 ),
				status: 'primary',
				kind: 'all',
			},
			benefits: {
				slug: 'benefits',
				title: __( 'Benefits', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'benefits', 17195 ),
				status: 'primary',
				kind: 'all',
			},
			testimonials: {
				slug: 'testimonials',
				title: __( 'Reviews', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'testimonials', 22602 ),
				status: 'primary',
				kind: 'all',
			},
			contact: {
				slug: 'contact',
				title: __( 'Contact', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'contact', 8419 ),
				status: 'primary',
				kind: 'all',
			},
			portfolio: {
				slug: 'portfolio',
				title: __( 'Portfolio', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'portfolio', 23084 ),
				status: 'primary',
				kind: 'all',
			},
		} );

		setDynamicTemplates( {
			single_post: {
				slug: 'single_post',
				title: __( 'Single Post', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'single_post', 22983 ),
				status: 'primary',
				kind: 'all',
			},
			archive_post: {
				slug: 'archive_post',
				title: __( 'Post Archive', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'archive_post', 22868 ),
				status: 'primary',
				kind: 'all',
			},
			'404_page': {
				slug: '404_page',
				title: __( '404', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( '404_page', 10085 ),
				status: 'primary',
				kind: 'all',
			},
			product_archive: {
				slug: 'product_archive',
				title: __( 'Shop Archive', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'product_archive' ),
				status: 'primary',
				kind: 'woo',
			},
			single_product: {
				slug: 'single_product',
				title: __( 'Single Product', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'single_product', 23371 ),
				status: 'primary',
				kind: 'woo',
			},
			cart: {
				slug: 'cart',
				title: __( 'Cart', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'cart', 19735 ),
				status: 'primary',
				kind: 'woo',
			},
			checkout: {
				slug: 'checkout',
				title: __( 'Checkout', 'jupiterx-core' ),
				type: 'dynamic',
				data: getDefaultData( 'checkout' ),
				status: 'primary',
				kind: 'woo',
			},
		} );
	}, [ props.templates ] );

	const getDefaultData = ( key, id = 0 ) => {
		const localData = context.getLocalStorage( `content_${ key }` );

		if ( localData === null && props.templates.hasOwnProperty( key ) ) {
			let data = [];

			if ( id === 0 ) {
				data = props.templates[ key ][ id ];

				context.setLocalStorage( `content_${ key }`, data );

				return data;
			}

			data = props.templates[ key ].find( ( template ) => template.id === id );

			context.setLocalStorage( `content_${ key }`, data );

			return data;
		}

		return localData;
	};

	const WebsiteTypes = () => {
		const types = {
			standard: {
				title: __( 'Standard', 'jupiterx-core' ),
				description: __( 'Suitable for corporate, blog, portfolio or startup websites', 'jupiterx-core' ),
			},
			woo: {
				title: __( 'Online Shop', 'jupiterx-core' ),
				description: __( 'Suitable for E-Commerce websites', 'jupiterx-core' ),
			},
		};

		return (
			<div className="websites-type-box-wrap" >
				{
					Object.keys( types ).map( ( item, index ) => {
						return (
							<div // eslint-disable-line
								key={ index }
								className={ `websites-type-box ${ ( item === siteType ) ? 'active-site-type' : '' }` }
								onClick={ () => {
									setSiteType( item );
									context.setLocalStorage( 'site_type', item );
								} }
							>
								<span className="mark-holder"></span>
								<h6>{ types[ item ].title }</h6>
								<p>{ types[ item ].description }</p>
							</div>
						);
					} )
				}
			</div>
		);
	};

	const SingleTemplateSelectedBase = ( { data, section } ) => {
		let image = data.data?.thumbnail;
		const isSelected = !! context.getLocalStorage( `selected_${ data.slug }` );

		if ( context.getLocalStorage( `selected_${ data.slug }` ) === null ) {
			context.setLocalStorage( `selected_${ data.slug }`, true );
			data.status = 'selected';
		}

		if ( data.hasOwnProperty( 'import' ) && false === data.import ) {
			data.status = 'primary';
		}

		if ( _.isEmpty( image ) ) {
			image = urls.imgUrl + '/setup-wizard/placeholder.png';
			data.status = 'primary';
		}

		return (
			<div
				className={ `step-single-template ${ isSelected ? 'template-selected' : '' }` }
				onClick={ ( e ) => {
					if ( e.target.classList.contains( 'template-switcher' ) ) {
						return;
					}

					const currentlySelected = !! context.getLocalStorage( `selected_${ data.slug }` );

					const newStatus = currentlySelected ? 'primary' : 'selected';
					const newImport = ! currentlySelected;

					const updatedTemplate = {
						...data,
						status: newStatus,
						import: newImport,
					};

					if ( newStatus === 'selected' ) {
						context.setLocalStorage( `selected_${ data.slug }`, true );
					} else {
						context.setLocalStorage( `selected_${ data.slug }`, false );
					}

					if ( 'static' === section ) {
						setStaticTemplates( { ...staticTemplates, [ data.slug ]: updatedTemplate } );
					} else {
						setDynamicTemplates( { ...dynamicTemplates, [ data.slug ]: updatedTemplate } );
					}
				} }
				onKeyDown={ ( event ) => {
					if ( event.key === 'Enter' ) {
						return false;
					}

					return true;
				} }
				role="button"
				tabIndex={ 0 }
			>
				<span className="mark-holder"></span>
				<img
					alt="template"
					src={ image }
				/>
				<div className="action-bar">
					<span>{ data.title }</span>
					{
						'dynamic' === data.type &&
						<Button
							variant="secondary"
							className="template-switcher"
							onClick={ () => {
								setActiveTemplate( data.slug );
								setActiveSection( section );
								setShowModal( true );
								document.body.style.overflow = 'hidden';
								setActiveTitle( data.title );
							} }
						>
							{ __( 'Change', 'jupiterx-core' ) }
						</Button>
					}
				</div>
			</div>
		);
	};

	const SingleTemplateSelected = React.memo( SingleTemplateSelectedBase );

	const FormFields = () => {
		return (
			<div className="templates-form-fields">
				{
					Object.keys( staticTemplates ).map( ( item, index ) => {
						const field = staticTemplates[ item ];

						if ( field.hasOwnProperty( 'import' ) && false === field.import ) {
							return <Fragment key={ index }></Fragment>;
						}

						if ( parseInt( field.data?.id ) > 0 && context.getLocalStorage( `selected_${ item }` ) ) {
							return (
								<Fragment key={ index }>
									{

										( 'all' === field.kind || siteType === field.kind ) && <Form.Control
											name={ `templates[${ field.slug }]` }
											type="hidden"
											{ ...props.stepRef( `templates[${ field.slug }]` ) }
											value={ field.data?.id || '' }
										/>
									}
								</Fragment>
							);
						}

						return <Fragment key={ index }></Fragment>;
					} )
				}
				{
					Object.keys( dynamicTemplates ).map( ( item, index ) => {
						const field = dynamicTemplates[ item ];

						if ( field.hasOwnProperty( 'import' ) && false === field.import ) {
							return <Fragment key={ index }></Fragment>;
						}

						return (
							<Fragment key={ index }>
								{
									( 'all' === field.kind || siteType === field.kind ) && parseInt( field.data?.id ) > 0 && context.getLocalStorage( `selected_${ item }` ) &&
									<Form.Control
										name={ `templates[${ field.slug }]` }
										type="hidden"
										{ ...props.stepRef( `templates[${ field.slug }]` ) }
										value={ field.data?.id || '' }
									/>
								}
							</Fragment>
						);
					} )
				}
				<input type="hidden" name="site_type" { ...props.stepRef( 'site_type' ) } value={ siteType } />
				<input
					type="hidden"
					name="sample_content"
					{ ...props.stepRef( 'sample_content' ) }
					value={ isChecked ? 'true' : 'false' }
				/>
			</div>
		);
	};

	return (
		<>
			<div className="jupiterx-setup-wizard-content-step col-12" >
				<div className="step-content-header">
					<h2>{ __( 'Import Your Website\'s Building Blocks!', 'jupiterx-core' ) }</h2>
					<p>{ __( 'Give yourself a head start! Within just a few clicks, activate extra', 'jupiterx-core' ) }</p>
					<p>{ __( 'features and import a selection of dummy pages that serve as a', 'jupiterx-core' ) }</p>
					<p>{ __( 'foundation for your own content creation.', 'jupiterx-core' ) }</p>
				</div>
				<div className="step-website-type">
					<h4>{ __( 'Website Type', 'jupiterx-core' ) }</h4>
					<WebsiteTypes />
				</div>
				<div className="step-import-static">
					<h4>{ __( 'Import Static Page Templates', 'jupiterx-core' ) }</h4>
					<p>{ __( 'Pre-built templates for common pages to give you inspiration and save time.', 'jupiterx-core' ) }</p>
					<div className="templates-wrap">
						{
							Object.keys( staticTemplates ).map( ( item, index ) => {
								const single = staticTemplates[ item ];

								if ( 'woo' !== siteType && 'woo' === single.kind ) {
									return <Fragment key={ index }></Fragment>;
								}

								return (
									<SingleTemplateSelected
										key={ single.slug }
										data={ single }
										section="static"
									/>
								);
							} )
						}
					</div>
				</div>
				<div className="step-import-dynamic">
					<h4>{ __( 'Import Dynamic Page Templates', 'jupiterx-core' ) }</h4>
					<p>{ __( 'Pre-built templates for dynamic pages such as archive, product page, cart, and more.', 'jupiterx-core' ) }</p>
					<div className="templates-wrap">
						{
							Object.keys( dynamicTemplates ).map( ( item, index ) => {
								const single = dynamicTemplates[ item ];

								if ( 'woo' !== siteType && 'woo' === single.kind ) {
									return <Fragment key={ index }></Fragment>;
								}

								return (
									<SingleTemplateSelected
										key={ single.slug }
										data={ single }
										section="dynamic"
									/>
								);
							} )
						}
					</div>
				</div>

				<div className="step-import-sample-content-wrapper">
					<div className="step-import-sample-content">
						<div className="sample-content-checkbox">
							<input type="checkbox" checked={ isChecked } onChange={ handleCheckboxChange } />
							<button type="button" onClick={ handleCheckboxChange }>{ __( 'Import sample content', 'jupiterx-core' ) }</button>
						</div>
						<div className="sample-content-description">
							<p>{ __( 'Enabling this option will add dummy blog posts, projects, and products to populate all templates and layouts, demonstrating what your finished site may appear as when launched live. Get a complete vision.', 'jupiterx-core' ) }</p>
						</div>
					</div>
				</div>

				<FormFields ></FormFields>
				<ContentModal
					showModal={ showModal }
					setShowModal={ setShowModal }
					templates={ props.templates }
					activeTemplate={ activeTemplate }
					activeTile={ activeTile }
					activeSection={ activeSection }
					staticTemplates={ staticTemplates }
					dynamicTemplates={ dynamicTemplates }
					context={ context }
					setStaticTemplates={ setStaticTemplates }
					setDynamicTemplates={ setDynamicTemplates }
				/>
			</div>
			<StepButton nextStep={ 'done' } { ...props } />
		</>
	);
};

export default ContentControl;
