import React, { useContext, useState, useEffect } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { themeVersion, urls, tabs, checkSimplicityMode, freshInstall } from '@jupiterx/control-panel';
import { Button, Navbar, Nav, Badge, Dropdown } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPaintBrush, faQuestionCircle, faBars, faChevronDown } from '@fortawesome/free-solid-svg-icons';
import { Link, useLocation } from 'react-router-dom';
import { useMediaQuery } from 'react-responsive';
import { AppContext } from '../../';
import { SettingsContext } from '../../store/settings';
import UpdatesBadge from '../../views/tools/updates/badge';
import Tooltip from '../tooltip';
import logo from './logo';
import $ from 'jquery';
import './style.scss';

const Header = ( { simplicityMode, handleSetSimplicityMode } ) => {
	const [ menuExpanded, setMenuExpanded ] = useState( false );
	const [ menuItems, setMenuItem ] = useState( tabs );
	const [ subMenu, setSubMenu ] = useState( [] );
	const { appState } = useContext( AppContext );
	const { options, isWhiteLabel } = useContext( SettingsContext );

	const isBigScreen = useMediaQuery( { query: '(min-width: 1200px)' } );
	const { pathname } = useLocation();

	const validSubMenus = [
		'/updates',
		'/version-rollback',
		'/ready-made-websites',
		'/logs',
		'/export',
	];

	let newItems = {};

	const handleExpand = () => {
		if ( ! isBigScreen ) {
			setMenuExpanded( ! menuExpanded );
		}
	};

	// Determine active tab based purely on pathname
	const getActiveTabId = () => {
		// Check if path is in maintenance submenus AND not currently moved out to main menu
		if ( validSubMenus.includes( pathname ) ) {
			// If ready-made-websites is in subMenu array, it's been moved OUT of maintenance dropdown
			// So don't treat it as maintenance submenu
			const pathId = pathname.replace( '/', '' );
			if ( subMenu.includes( pathId ) ) {
				// It's currently a standalone menu item, find it in menuItems
				const currentMenu = menuItems.find( ( menu ) => menu.href === pathname );
				return currentMenu ? currentMenu.id : null;
			}
			return 'maintenance';
		}

		// Check for exact match first
		const exactMatch = menuItems.find( ( menu ) => menu.href === pathname );
		if ( exactMatch ) {
			return exactMatch.id;
		}

		// Check if pathname starts with any menu href (for routes with subroutes like /layout-builder/header)
		const prefixMatch = menuItems.find( ( menu ) => pathname.startsWith( menu.href + '/' ) );
		return prefixMatch ? prefixMatch.id : null;
	};

	const getActiveSubTabPath = () => {
		if ( validSubMenus.includes( pathname ) ) {
			// If the item is in subMenu, it's not actually a submenu right now
			const pathId = pathname.replace( '/', '' );
			if ( subMenu.includes( pathId ) ) {
				return null;
			}
			return pathname;
		}
		return null;
	};

	const activeTabId = getActiveTabId();
	const activeSubTabPath = getActiveSubTabPath();

	const isTabActive = ( tabId ) => {
		return activeTabId === tabId;
	};

	const isSubTabActive = ( subTabPath ) => {
		return activeSubTabPath === subTabPath;
	};

	useEffect( () => {
		handleMenuItems();
		responsiveMenuItems();

		const resizeHandler = () => {
			handleMenuItems();
			responsiveMenuItems();
		};

		window.addEventListener( 'resize', resizeHandler );

		return () => {
			window.removeEventListener( 'resize', resizeHandler );
		};
	}, [] );

	useEffect( () => {
		// eslint-disable-next-line
		if ( typeof options[ 'disable_theme_default_settings' ] !== 'undefined' && checkSimplicityMode ) {
			handleSetSimplicityMode( true );
			return;
		}

		const defaultValue = freshInstall ? 1 : '0';

		// eslint-disable-next-line
		const savedValue = options.hasOwnProperty( 'disable_theme_default_settings' ) ? options.disable_theme_default_settings : defaultValue;

		if ( ! [ '0', 0 ].includes( savedValue ) ) {
			handleSetSimplicityMode( true );
			return;
		}

		handleSetSimplicityMode( false );
	}, [ pathname ] );

	const handleMenuItems = () => {
		newItems = tabs.filter( ( tab ) => {
			if ( tab.whiteLabel === false ) {
				return true;
			}

			if ( options.white_label !== '1' ) {
				return true;
			}

			if ( typeof options.white_label_cpanel_pages === 'undefined' ) {
				return true;
			}

			return options.white_label_cpanel_pages.includes( tab.id );
		} );
	};

	const responsiveMenuItems = () => {
		setMenuItem( newItems );

		const navItem = document.getElementById( 'jx-nav-menu' ),
			navbar = document.getElementById( 'jx-navbar' );

		let navWidth = 1200,
			navbarWidth = 1200;

		if ( navItem ) {
			navWidth = navItem.clientWidth + 60;
		}

		if ( navbar ) {
			navbarWidth = navbar.clientWidth;
		}

		if ( navWidth >= navbarWidth ) {
			const modifiedItems = menuItems.filter( ( item ) => {
				if ( ! [ 'ready-made-websites' ].includes( item.id ) ) {
					return true;
				}

				return false;
			} );

			setMenuItem( modifiedItems );
			setSubMenu( [] );
			return;
		}

		const subMenuTemp = [];

		const modifiedItems = menuItems.filter( ( item ) => {
			if ( item.id === 'maintenance' ) {
				Object.values( item.subTabs ).filter( ( subItem ) => {
					if ( [ 'ready-made-websites' ].includes( subItem.id ) ) {
						subMenuTemp.push( subItem.id );

						return true;
					}

					return false;
				} );
			}

			return true;
		} );

		setMenuItem( modifiedItems );
		setSubMenu( subMenuTemp );
	};

	const renderHelpLink = () => {
		if (
			( options.white_label === '1' && options.white_label_help_links !== '1' ) ||
			_.isEmpty( menuItems )
		) {
			return;
		}

		const menus = menuItems.filter( ( menu ) => {
			return pathname === menu.href;
		} );

		// Default help data.
		let helpData = {
			overlay: __( 'Learn more about Jupiter X.', 'jupiterx-core' ),
			link: 'https://help.jupiterx.com/',
		};

		if ( menus.length && menus[ 0 ].help ) {
			helpData = {
				overlay: sprintf(
					// translators: %s Tab name
					__( 'Learn more about %s', 'jupiterx-core' ),
					menus[ 0 ].label.toLowerCase()
				),
				link: menus[ 0 ].help,
			};
		}

		return (
			<Tooltip overlay={ helpData.overlay }>
				<Nav.Link className="help-link" target="_blank" href={ helpData.link }>
					<FontAwesomeIcon className="me-1" icon={ faQuestionCircle } />
					<span>{ __( 'Help', 'jupiterx-core' ) }</span>
				</Nav.Link>
			</Tooltip>
		);
	};

	// Setup WordPress admin menu integration - only once on mount
	useEffect( () => {
		const wpMenuFirstItem = $( '#toplevel_page_jupiterx a.wp-first-item' );
		wpMenuFirstItem.addClass( 'current active' );
		wpMenuFirstItem.parent().addClass( 'current active' );

		// Get the hash part safely
		const hashParts = window.location.href.split( '#/' );
		let tab = hashParts.length > 1 ? hashParts[ 1 ] : '';

		if ( tab && tab.includes( '/' ) ) {
			tab = tab.split( '/' )[ 0 ];
		}

		$( '#toplevel_page_jupiterx a' ).each( function( index, items ) {
			if ( tab !== $( items ).attr( 'href' ).split( '#/' )[ 1 ] ) {
				return;
			}

			wpMenuFirstItem.removeClass( 'current active' );
			wpMenuFirstItem.parent().removeClass( 'current active' );

			$( items ).click();
		} );

		const wpMenuClickHandler = function() {
			$( '#toplevel_page_jupiterx a' ).parent().removeClass( 'current active' );
			$( this ).parent().addClass( 'active' );
		};

		const cpNavClickHandler = function() {
			if ( $( this ).attr( 'target' ) === '_blank' ) {
				return;
			}

			$( '#toplevel_page_jupiterx a' ).parent().removeClass( 'current active' );
		};

		$( '#toplevel_page_jupiterx a' ).on( 'click', wpMenuClickHandler );
		$( '.jx-cp-header .nav-link' ).on( 'click', cpNavClickHandler );

		return () => {
			$( '#toplevel_page_jupiterx a' ).off( 'click', wpMenuClickHandler );
			$( '.jx-cp-header .nav-link' ).off( 'click', cpNavClickHandler );
		};
	}, [] );

	const submenuHandler = ( event, parentId ) => {
		// Navigation is handled by React Router Link component
		// This handler is just for any special logic if needed in the future
	};

	const menuHandler = ( event, menuId ) => {
		if ( menuId === 'maintenance' ) {
			event.preventDefault();
			event.stopPropagation();

			const firstSubMenuItem = event.currentTarget.nextElementSibling?.firstChild;
			if ( firstSubMenuItem ) {
				firstSubMenuItem.click();
			}
			return;
		}

		// Navigation is handled by React Router Link component
		// Handle settings tab specific logic
		if ( menuId === 'settings' ) {
			setTimeout( () => {
				$( '.jupiterx-settings-list-wrap .jupiterx-settings-menu-item:first-child' )
					.addClass( 'active-item' )
					.siblings()
					.removeClass( 'active-item' );
				$( 'div.jx-cp-settings-content-advancegenerald' ).addClass( 'active' );
			}, 0 );
		}
	};

	return (
		<div className="jx-cp-header">
			<div className="jx-cp-header-top">
				<div className="jx-cp-header-logo d-flex flex-grow-1 align-items-center">
					{ isWhiteLabel && options.white_label_cpanel_logo
						? ( <img src={ options.white_label_cpanel_logo } alt="" /> )
						: logo
					}
					<Badge bg="unknown" className="jx-cp-theme-version">
						{
							// translators: %s Jupiter X version
							sprintf( __( 'Version %s', 'jupiterx-core' ), themeVersion )
						}
					</Badge>
				</div>
				<div className="jx-cp-header-navs d-flex">
					<Button className={ `jx-cp-theme-styles ${ simplicityMode ? 'hide-theme-styles' : '' }` } size="sm" variant="outline-primary" href={ urls.customize } target="_blank">
						<FontAwesomeIcon className="me-2" icon={ faPaintBrush } />
						{ __( 'Theme styles', 'jupiterx-core' ) }
					</Button>
					<Button
						size="sm"
						variant="secondary"
						className="ms-2 d-xl-none"
						onClick={ handleExpand }
					>
						<FontAwesomeIcon className="me-2" icon={ faBars } />
						{ __( 'Menu', 'jupiterx-core' ) }
					</Button>
				</div>
			</div>
			<Navbar id="jx-navbar" expanded={ menuExpanded } expand="xl" onSelect={ handleExpand }>
				<Navbar.Collapse>
					<Nav id="jx-nav-menu">
						{ menuItems.map( ( menu ) =>
							( ( menu.whiteLabel && menu.whiteLabelEnabled ) || ( ! menu.whiteLabel ) ) &&
							(
								<Nav.Item
									id={ `menu-item-${ menu.id }` }
									key={ menu.id }
									className={ isTabActive( menu.id ) ? 'active' : '' }
								>
									<Nav.Link
										as={ Link }
										id={ `navigation-${ menu.id }` }
										className={ isTabActive( menu.id ) ? 'nav-active' : '' }
										active={ false }
										{ ...( ! menu.subMenu &&
											{
												to: menu.href,
												href: menu.href,
											} ) }
										onClick={ ( event ) => menuHandler( event, menu.id ) }
									>
										{ menu.subMenu ? ( <FontAwesomeIcon className="me-2" icon={ faChevronDown } /> ) : ( '' ) }
										{ menu.label }
										{ menu.href === '/updates' && (
											<UpdatesBadge appState={ appState } />
										) }
									</Nav.Link>
									{ menu.subMenu ? (
										<Dropdown className="jx-cp-sub-menu-wrap">
											{ Object.values( menu.subTabs ).map(
												( subTab ) => (
													( subTab.whiteLabel && subTab.whiteLabelEnabled ) || ( ! subTab.whiteLabel ) ) &&
													(
														! subMenu.includes( subTab.id ) && ( <Link
															onClick={ ( event ) => submenuHandler( event, menu.id ) }
															href={ subTab.id }
															to={ subTab.id }
															className={ `dropdown-item${ isSubTabActive( '/' + subTab.id ) ? ' active' : '' }` }
															key={ subTab.id }
														>
															{ subTab.label }
														</Link> )
													) ) }
										</Dropdown>
									) : ( '' ) }
								</Nav.Item>
							) ) }
					</Nav>
					<div className="jx-cp-help-links-wrap">
						<Nav className="ms-auto">
							<Nav.Item className="jx-cp-help">
								{ renderHelpLink() }
							</Nav.Item>
						</Nav>
					</div>
				</Navbar.Collapse>
			</Navbar>
		</div>
	);
};

export default Header;
