import React, { useState } from 'react';
import AsyncSelect from 'react-select/async';
import { components } from 'react-select';
import { Form } from 'react-bootstrap';
import { Controller } from 'react-hook-form';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';

const MultiSelectControl = ( props ) => {
	const [ inputFields, setInputFields ] = useState( [] );

	let fetchingTimeoutId = '';

	const fetchOptions = ( resolve, inputValue ) => {
		if ( inputFields.length > 0 && inputValue ) {
			const newOptions = [];

			// eslint-disable-next-line
			inputFields.map( ( field, key ) => {
				if ( field.label.toLowerCase().includes( inputValue ) ) {
					newOptions.push( {
						value: field.value,
						label: field.label,
					} );
				}
			} );

			resolve( newOptions );
			return;
		}

		wp.ajax.send( 'jupiterx_popup_get_options', {
			type: 'GET',
			data: {
				nonce,
				type: 'trigger',
				//eslint-disable-next-line
				condition_name: props?.name,
				search_value: inputValue,
			},
			dataType: 'json',
			success: ( data ) => {
				const options = [];

				// eslint-disable-next-line
				data.map( ( value, key ) => {
					options.push( {
						value: value.id,
						label: value.name,
					} );
				} );

				setInputFields( options );
				resolve( options );
			},
				error: () => {},
		} );
	};

	const loadOptions = ( inputValue ) => {
		if ( _.isNumber( fetchingTimeoutId ) ) {
			clearTimeout( fetchingTimeoutId );
		}

		return new Promise( ( resolve ) => {
			fetchingTimeoutId = setTimeout( () => {
				fetchOptions( resolve, inputValue );
			}, 500 );
		} );
	};

	const onChangeHandler = () => {
		if ( _.isFunction( props.onUpdateCallback ) ) {
			props.onUpdateCallback();
		}
	};

	const Input = ( innerProps ) => {
		return (
			<div className="popup-trigger-control-plus-icon">
				<span></span>
				<components.Input { ...innerProps } />
			</div>
		);
	};

	return <Form.Group className="popup-trigger-control-group popup-trigger-type-multi-select">
		<Controller
			control={ props.conditionControl }
			name={ props.rowName + '[control]' }
			defaultValue={ ! _.isEmpty( props.triggerControl.defaultValue ) ? props.triggerControl.defaultValue : undefined }
			render={ ( { field } ) => {
				return <AsyncSelect
					isMulti
					cacheOptions
					name={ props.rowName + '[control]' }
					className="popup-trigger-control"
					placeholder=""
					autoComplete="off"
					loadOptions={ loadOptions }
					defaultValue={ ! _.isEmpty( props.triggerControl.defaultValue ) ? props.triggerControl.defaultValue : undefined }
					defaultOptions={ props?.openMenuOnClick ? true : ! props.isSearchable }
					openMenuOnClick={ props?.openMenuOnClick ? true : ! props.isSearchable }
					isSearchable={ true }
					loadingMessage={ () => __( 'Searching...', 'jupiterx-core' ) }
					onChange={ ( event ) => {
						field.onChange( event );
						onChangeHandler();
					} }
					value={ field.value }
					components={ {
						DropdownIndicator: () => null,
						IndicatorSeparator: () => null,
						ClearIndicator: () => null,
						Input,
					} }
					theme={ ( theme ) => ( {
						...theme,
						colors: {
							...theme.colors,
							primary: '#3f444b',
						},
					} ) }
					styles={ {
						control: ( provided ) => ( {
							...provided,
							width: '300px',
							boxShadow: 'none',
							minHeight: '27px',
							borderColor: '#D5D8DC',
							borderRadius: '3px',
							':hover': {
								borderColor: '#D5D8DC',
							},
						} ),
						multiValue: ( provided ) => ( {
							...provided,
							display: 'flex',
							flexDirection: 'row-reverse',
							color: '#6d7882',
							backgroundColor: '#f1f3f5',
							fontSize: '10px',
							border: 'none',
							borderRadius: 0,
							padding: '2px 3px',
							margin: '2px 4px 2px 0',
						} ),
						multiValueLabel: ( provided ) => ( {
							...provided,
							color: '#6d7882',
							fontSize: '10px',
							border: 'none',
							borderRadius: 0,
							padding: 0,
							paddingLeft: 0,
						} ),
						multiValueRemove: ( provided ) => ( {
							...provided,
							color: '#3f444b',
							fontSize: '10px',
							border: 'none',
							borderRadius: 0,
							padding: 0,
							marginRight: '5px',
							cursor: 'pointer',
							':hover': {
								backgroundColor: 'transparent',
								color: '#3f444b',
							},
						} ),
						valueContainer: ( provided ) => ( {
							...provided,
							padding: '0.5px 5px',
						} ),
					} }
				/>;
			} }
		/>
	</Form.Group>;
};

export default MultiSelectControl;
