import React from 'react';
import RegistrationControl from './registration';
import ColorsControl from './colors';
import TypographyControl from './typography';
import LayoutControl from './layout';
import ContentControl from './content';
import DoneControl from './done';

const StepsControl = ( props ) => {
	const steps = {
		registration: RegistrationControl,
		colors: ColorsControl,
		typography: TypographyControl,
		layout: LayoutControl,
		content: ContentControl,
		done: DoneControl,
	};

	if ( props.currentStep !== 'registration' ) {
		const TargetComponent = steps[ props.currentStep ];

		return (
			<TargetComponent { ...props } />
		);
	}

	return (
		React.createElement( steps[ props.currentStep ], props )
	);
};

export default StepsControl;
