import React, { useState, useContext, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { SettingsContext } from '../../store/settings';
import Dialog from '../../components/dialog';
import { Form, Button, Col } from 'react-bootstrap';
import { sprintf, __ } from '@wordpress/i18n';
import { urls, nonce } from '@jupiterx/control-panel';
import ElementorWidgets from '../../components/widgets';
import Spinner from '../../components/spinner/index';
import './style.scss';

const WidgetsModal = () => {
	const { options, setOptions } = useContext( SettingsContext );

	const { register, handleSubmit } = useForm();
	const [ remindMeLater, setRemindeMeLater ] = useState( false );
	const [ isSaving, setSaving ] = useState( false );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ allSelected, setAllSelected ] = useState( false );
	const title = <h4 dangerouslySetInnerHTML={ { __html: __( 'New in JupiterX v2.5: Manage Elementor Features', 'jupiterx-core' ) } } />;

	useEffect( () => {
		setTimeout( () => {
			if ( window.location.hash !== '#/settings#modules' ) {
				setShowDialog( true );
				handleCloseIcon();
			}
		}, 3000 );
	}, [] );

	function onSubmit( fields ) {
		setSaving( true );

		// Prepare the data for database save.
		for ( const field in fields ) {
			if ( fields[ field ] === true ) {
				fields[ field ] = 1;
			}

			if ( fields[ field ] === false ) {
				fields[ field ] = 0;
			}

			if (
				typeof fields[ field ] === 'object' &&
				! fields[ field ].length
			) {
				fields[ field ] = [ '' ];
			}

			options[ field ] = fields[ field ];
		}

		setOptions( options );
		handleSaveAndClose( options.elements );
	}

	const handleSelectAll = ( event ) => {
		event.preventDefault();

		let inputs = document.getElementsByClassName( 'jupiterx-enable-widget-item' );

		if ( inputs.length > 0 ) {
			inputs = [ ...inputs ];

			inputs.map( ( input ) => {
				const child = input.childNodes[ 0 ];

				if ( ! child.checked && ! allSelected ) {
					child.checked = true;
				}

				if ( child.checked && allSelected ) {
					child.checked = false;
				}

				return input;
			} );

			if ( allSelected ) {
				setAllSelected( false );
				return;
			}

			setAllSelected( true );
		}
	};

	const handleRemindeMeLater = () => {
		setRemindeMeLater( true );

		const data = {
			action: 'jupiterx_core_cp_reminde_me_later',
			nonce,
		};

		wp.ajax.post( data ).done( () => {
			setShowDialog( false );
			setRemindeMeLater( false );
		} ).fail( () => {
			setShowDialog( false );
		} );
	};

	const handleSaveAndClose = ( elements ) => {
		const data = {
			action: 'jupiterx_core_cp_update_elements',
			nonce,
			elements,
		};

		wp.ajax.post( data ).done( () => {
			setShowDialog( false );
			setSaving( false );
		} ).fail( () => {
			setShowDialog( false );
		} );
	};

	const handleCloseIcon = () => {
		const dialog = document.getElementsByClassName( 'jupiterx-cp-enable-widgets-modal' );

		if ( ! dialog ) {
			return;
		}

		const closeButton = dialog[ 0 ].getElementsByClassName( 'close' );

		closeButton[ 0 ].addEventListener( 'click', () => {
			const data = {
				action: 'jupiterx_core_cp_dismiss_enable_widgets',
				nonce,
			};

			wp.ajax.post( data ).done( () => {
				setShowDialog( false );
				setSaving( false );
			} ).fail( () => {
				setShowDialog( false );
			} );
		} );
	};

	return (
		showDialog && <Dialog
			size="xl"
			className="jupiterx-cp-enable-widgets-modal"
			show={ showDialog }
			title={ title }
			isLoading={ false }
			onCancel={ handleRemindeMeLater }
			onSubmit={ handleSubmit( onSubmit ) }
			submitText={ isSaving ? <Spinner /> : __( 'Save and Close', 'jupiterx-core' ) }
			cancelText={ remindMeLater ? <Spinner /> : __( 'Remind Me Later', 'jupiterx-core' ) }
		>
			<div className="enable-widgets-header d-flex align-items-center">
				<figure className="d-flex align-items-center justify-content-between">
					<img className="col-2 ps-0" src={ urls.imgUrl + '/performance.svg' } alt="enable widgets" />
					<figcaption
						className="col-10"
						dangerouslySetInnerHTML={
							{ __html: sprintf(
								/** translators: %s: elements link in jupiterx control panel */
								__( 'You can disable the unused features to achieve the highest site performance possible. Just uncheck the features you don’t need from the section below to disable them. You can always enable/disable these features from <a href="%s" target="_blank">JupiterX Settings</a>.', 'jupiterx-core' ),
								urls.controlPanelUrl + '#/settings#modules'
							) }
						}
					/>
				</figure>
			</div>
			<div id="enable-widgets-form" className="modal-form">
				<Form.Group as={ Col } sm="12" className="text-right mt-2 mb-0">
					<Button
						className="select-all"
						variant="secondary"
						size="sm"
						onClick={ handleSelectAll }
					>
						{ allSelected ? __( 'Deselect All', 'jupiterx-core' ) : __( 'Select All', 'jupiterx-core' ) }
					</Button>
				</Form.Group>
				<ElementorWidgets options={ options } register={ register } type={ 'modal' } />
			</div>
		</Dialog>
	);
};

export default WidgetsModal;
