import React, { useState } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { Form, Button } from 'react-bootstrap';
import { themeVersion } from '@jupiterx/control-panel';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faRedoAlt } from '@fortawesome/free-solid-svg-icons';
import Dialog from './dialog';

const VersionControlField = ( { product } ) => {
	const [ selectedVersion, setSelectedVersion ] = useState( product.type === 'theme' ? themeVersion : product.active_version );
	const [ reinstallDialog, setReinstallDialog ] = useState( false );

	return (
		<>
			<Form.Group className="d-flex align-items-center flex-row flex-wrap form-group-version mb-3">
				<Form.Label className="me-auto" dangerouslySetInnerHTML={ {
					__html: `${ product.name } <small class="text-muted">${ product.type_label }</small>`,
				} } />
				<Form.Control
					className="custom-select"
					as="select"
					size="sm"
					defaultValue={ selectedVersion }
					onChange={ ( event ) => setSelectedVersion( event.target.value ) }
				>
					{ product.versions.map( ( version, versionIndex ) => (
						<option
							key={ versionIndex }
							value={ version.name }
						>Version { version.name }</option>
					) ) }
				</Form.Control>
				<Button
					size="sm"
					onClick={ () => setReinstallDialog( true ) }
				>
					<FontAwesomeIcon icon={ faRedoAlt } />
					{ ' ' }
					<span>{ sprintf(
						// translators: The selected version.
						__( 'Reinstall v%s', 'jupiterx-core' ),
						selectedVersion
					) }</span>
				</Button>
			</Form.Group>
			<Dialog
				show={ reinstallDialog }
				onHide={ () => setReinstallDialog( false ) }
				selectedVersion={ selectedVersion }
				product={ product }
			/>
		</>
	);
};

export default VersionControlField;
