import React, { useState } from 'react';
import Select, { components } from 'react-select';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faMinusCircle, faPlusCircle } from '@fortawesome/free-solid-svg-icons';
import { __ } from '@wordpress/i18n';

const FirstAsyncSelect = ( props ) => {
	const [ menuView, setMenuView ] = useState( false ),
		{ Option } = components;

	//eslint-disable-next-line
	const CustomSelectOption = ( props ) => (
		<Option { ...props }>
			<FontAwesomeIcon
				icon={ props.data.icon }
				className="rounded-circle parameter-icons"
			/>
			<span className="dropdown-custom-select-text">
				{ props.data.label }
			</span>
		</Option>
	);

	//eslint-disable-next-line
	const CustomSelectValue = ( props ) => (
		<div>
			<FontAwesomeIcon
				icon={ props.data.icon }
				className="d-sm-none d-md-inline-flex me-md-1 rounded-circle"
			/>
			{ props.data.label }
		</div>
	);

	const options = [
		{ value: 'include', label: __( 'Include', 'jupiterx-core' ), icon: faPlusCircle, color: 'text-success', name: 'conditionA' },
		{ value: 'exclude', label: __( 'Exclude', 'jupiterx-core' ), icon: faMinusCircle, color: 'text-danger', name: 'conditionA' },
	];

	const handleOnChange = ( selectedOption ) => {
		props.handleInputChange( props.index, selectedOption );
	};

	return (
		<Select
			value={
				( 'include' === props.inputField.conditionA )
					? { label: __( 'Include', 'jupiterx-core' ), value: 'include', icon: faPlusCircle, color: 'text-success' }
					: { label: __( 'Exclude', 'jupiterx-core' ), value: 'exclude', icon: faMinusCircle, color: 'text-danger' }
			}
			className="basic-single-first"
			options={ options }
			id="conditionA"
			name="conditionA"
			isSearchable={ false }
			onChange={ handleOnChange }
			components={ { Option: CustomSelectOption, SingleValue: CustomSelectValue } }
			onFocus={ () => {
				setMenuView( true );
			} }
			onBlur={ () => {
				setMenuView( false );
			} }
			menuIsOpen={ menuView }
		/>
	);
};

export default FirstAsyncSelect;
