import React from 'react';
import './style.scss';

const ColorPalette = ( props ) => {
	return (
		<>
			{
				props.colors.map( ( color, index ) => (
					<div
						key={ index }
						className="color-palette__color col-2"
						style={ { backgroundColor: color } }
					/>
				) )
			}
		</>
	);
};

export default ColorPalette;
