import React, { useState, useContext, useEffect } from 'react';
import './style.scss';
import { __ } from '@wordpress/i18n';
import { urls } from '@jupiterx/control-panel';
import NavButton from './nav-button';
import { Form } from 'react-bootstrap';
import { SetupWizardContext } from '..';

const LayoutLogo = ( props ) => {
	const context = useContext( SetupWizardContext );
	const [ showUploadButton, setShowUploadButton ] = useState( true );
	const [ logoUrl, setLogoUrl ] = useState( context.getLocalStorage( 'logo_url' ) );
	const [ logoId, setLogoId ] = useState( context.getLocalStorage( 'logo_id' ) );

	const uploadIcon = urls.controlPanel + 'img/setup-wizard/upload.svg';
	const changeIcon = urls.controlPanel + 'img/setup-wizard/refresh.svg';
	const deleteIcon = urls.controlPanel + 'img/setup-wizard/delete.svg';

	useEffect( () => {
		if ( ! _.isEmpty( logoUrl ) ) {
			setShowUploadButton( false );
		}
	}, [] );

	const openMediaLibrary = ( event ) => {
		event.preventDefault();

		const inputElement = event.target.closest( '.body' ).querySelector( `.logo-input` );
		const inputElementId = event.target.closest( '.body' ).querySelector( `.logo-input-id` );
		const imageElement = event.target.closest( '.body' ).querySelector( '.logo-image' );

		const customMediaLibrary = wpMediaLibrary();

		customMediaLibrary.open();

		addSelectedImageUrlToFields( customMediaLibrary, imageElement, inputElement, inputElementId );
	};

	const wpMediaLibrary = () => {
		const mediaLibraryArgs = {
			title: __( 'Upload Logo', 'jupiterx-core' ),
			frame: 'select',
			multiple: false,
			library: {
				type: 'image',
				order: 'DESC',
				orderby: 'date',
			},
			button: {
				text: __( 'Select Logo', 'jupiterx-core' ),
			},
		};

		return window.wp.media( mediaLibraryArgs );
	};

	const addSelectedImageUrlToFields = ( mediaLibrary ) => {
		mediaLibrary.on( 'select', () => {
			const fileAttributes = mediaLibrary.state().get( 'selection' ).first().attributes;

			if ( fileAttributes ) {
				setLogoId( fileAttributes.id );
				context.setLocalStorage( 'logo_id', fileAttributes.id );
				setLogoUrl( fileAttributes.url );
				context.setLocalStorage( 'logo_url', fileAttributes.url );
				setShowUploadButton( false );
			}
		} );
	};

	const removeLogoImage = ( event ) => {
		event.target.closest( '.body' ).querySelector( '.logo-input' ).removeAttribute( 'value' );

		setLogoUrl( '' );
		setLogoId( '' );
		setShowUploadButton( true );
	};

	return (
		<div className="jx-setup-wizard-layout-logo">
			<div className="header">
				<div className="title">
					{ __( 'Logo', 'jupiterx-core' ) }
				</div>
				<div className="text">
					{ __( 'Upload a logo to establish your brand recognition. (optional)', 'jupiterx-core' ) }
				</div>
			</div>
			<div className="body">
				{ showUploadButton &&
					<NavButton
						className="upload-button"
						handleNavButtonClick={ openMediaLibrary }
						buttonText={ __( 'Upload Logo', 'jupiterx-core' ) }
						buttonIcon={ uploadIcon }
					/>
				}

				<div className="logo-wrapper">
					{
						_.isEmpty( logoUrl ) &&
						<img
							className={ 'logo-image ' + ( ! showUploadButton ? ' active' : '' ) }
							alt={ __( 'Logo', 'jupiterx-core' ) }
						/>
					}
					{
						! _.isEmpty( logoUrl ) &&
						<img
							className={ 'logo-image ' + ( ! showUploadButton ? ' active' : '' ) }
							alt={ __( 'Logo', 'jupiterx-core' ) }
							src={ logoUrl }
						/>
					}

					{ ! showUploadButton &&
						<div className="logo-buttons-wrapper">
							<NavButton
								className="logo-change-button"
								handleNavButtonClick={ openMediaLibrary }
								buttonIcon={ changeIcon }
							/>

							<NavButton
								className="logo-delete-button"
								handleNavButtonClick={ removeLogoImage }
								buttonIcon={ deleteIcon }
							/>
						</div>
					}
				</div>

				<Form.Control
					className="logo-input"
					name="logo[url]"
					type="hidden"
					{ ...props.stepRef( 'logo[url]' ) }
					value={ logoUrl || '' }
				/>

				<Form.Control
					className="logo-input-id"
					name="logo[id]"
					type="hidden"
					{ ...props.stepRef( 'logo[id]' ) }
					value={ logoId || '' }
				/>
			</div>
		</div>
	);
};

export default LayoutLogo;
