import React from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { Card, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faComment } from '@fortawesome/free-solid-svg-icons';
import { isPremium } from '@jupiterx/control-panel';

const Support = () => {
	let supportText = sprintf(
		// translators: 1: Documentation page url
		__(
			'Our <a href="%1$s" target="_blank">documentation</a> could not help? <br> Contact our support team and we will get back to you <strong>within 24 hours</strong>.',
			'jupiterx-core'
		),
		'http://help.jupiterx.com/',
	);

	if ( ! isPremium ) {
		supportText = __( 'Got any questions? Ask away and we will get back to you shortly.', 'jupiterx-core' );
	}

	return (
		<Card className="jx-cp-support">
			<Card.Header>
				<FontAwesomeIcon icon={ faComment } />
				{ ' ' }
				<span>{ __( 'Help Desk', 'jupiterx-core' ) }</span>
			</Card.Header>
			<Card.Body>
				<Card.Text
					dangerouslySetInnerHTML={ {
						__html: supportText,
					} }
				/>
				<Button size="sm" href="https://themes.artbees.net/dashboard/new-topic" type="primary" target="_blank">
					{ __( 'Contact support', 'jupiterx-core' ) }
				</Button>
			</Card.Body>
		</Card>
	);
};

export default Support;
