import React from 'react';
import { Modal, Button } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import WizardSpinner from '../compenents/spinner';
import { urls } from '@jupiterx/control-panel';

const alertIcon = urls.controlPanel + 'img/setup-wizard/alert.svg';

const SkipWizardModal = ( { showModal, handleCloseModal, handleSkipSetup, skipWizard } ) => (
	<Modal show={ showModal } onHide={ handleCloseModal } className="skip-wizard-modal">
		<Modal.Header>
			<img src={ alertIcon } alt="Skip alert" />
			<Modal.Title>{ __( 'Skip setup wizard?', 'jupiterx-core' ) }</Modal.Title>
		</Modal.Header>
		<Modal.Body>{ __( 'Are you sure you want to cancel the setup wizard? Canceling the wizard will discard any changes made during the setup process.', 'jupiterx-core' ) }</Modal.Body>
		<Modal.Footer>
			<Button variant="secondary" onClick={ handleCloseModal }>
				{ __( 'Continue Wizard', 'jupiterx-core' ) }
			</Button>
			<Button variant="primary" onClick={ handleSkipSetup }>
				{ skipWizard ? <WizardSpinner /> : __( 'Skip Wizard', 'jupiterx-core' ) }
			</Button>
		</Modal.Footer>
	</Modal>
);

export default SkipWizardModal;
