import React, { useContext, useEffect, useState } from 'react';
import { urls, activePlugins } from '@jupiterx/control-panel';
import { Spinner } from 'react-bootstrap';
import { AppContext } from '../../../';
import { __, sprintf } from '@wordpress/i18n';
import UpdateListItem from './item';
import Alert from '../../../components/alert';

const List = ( {} ) => {
	const { appState } = useContext( AppContext );
	const [ allUpdated, setAllUpdated ] = useState( false );

	useEffect( () => {
		if ( appState.updates.list.length === 0 ) {
			return;
		}

		const newList = appState.updates.list.filter( ( item ) => {
			if ( item.type === 'plugin' && ! activePlugins.includes( item.basename ) ) {
				return false;
			}

			return true;
		} );

		if ( newList.length === 0 ) {
			setAllUpdated( true );
		}
	}, [ appState.updates.list ] );

	if ( appState.updates.fetching ) {
		return <div className="jx-cp-updates-fetching d-flex justify-content-center my-5">
			<Spinner
				as="span"
				animation="border"
				size="lg"
				role="status"
				aria-hidden="true"></Spinner>
		</div>;
	}

	if ( appState.updates.status === 'error' ) {
		return <div className="jx-cp-updates-error d-flex my-5">
			<Alert variant="danger" className="m-0">
				<span dangerouslySetInnerHTML={ {
					__html: sprintf(
						// translators: 1: Site health url, 2: API error message.
						__( 'There is a problem in fetching the updates from API. Please check <a href="%1$s" target="_blank">Site Health</a> to fix possible issues. If the issue persists, please contact support. (%2$s)', 'jupiterx-core' ),
						urls.siteHealth,
						appState.updates.error
					),
				} } />
			</Alert>
		</div>;
	}

	if ( appState.updates.list.length === 0 || allUpdated ) {
		return <div className="jx-cp-updates-empty d-flex justify-content-center my-5">
			{ __( 'You are all good. Everything is up to date.', 'jupiterx-core' ) + ' 👍' }
		</div>;
	}

	return <div className="jx-cp-updates-list">
		{ appState.updates.list.map( ( update ) => {
			if ( update.type === 'plugin' && ! activePlugins.includes( update.basename ) ) {
				return ( '' );
			}

			return (
				<UpdateListItem key={ update.id } update={ update } />
			);
		} ) }
	</div>;
};

export default List;
