import React, { forwardRef, useEffect, useState } from 'react';
import { Form } from 'react-bootstrap';
import { withRegister } from '../controls/utils';

const TriggerOperator = forwardRef( ( props, ref ) => {
	const [ value, setValue ] = useState( '' );

	useEffect( () => {
		if ( props.triggerOperatorDefault ) {
			setValue( props.triggerOperatorDefault );
		} else if ( Array.isArray( props.triggerOperator ) && props.triggerOperator.length > 0 ) {
			setValue( props.triggerOperator[ 0 ] );
		}
	}, [ props.triggerOperatorDefault, props.triggerOperator ] );

	return (
		<Form.Group className="popup-trigger-operator-group me-3">
			{ (() => {
				const registerProps = withRegister( ref, props.rowName + '[operator]', ( event ) => setValue( event.target.value ) );
				return (
					<Form.Control
				id={ props.rowName + '_operator' }
				className="popup-trigger-operator"
				as="select"
				name={ props.rowName + '[operator]' }
						value={ value }
						{ ...registerProps }
					>
				{
					props.triggerOperator.map( ( operatorItem, operatorKey ) => {
						return (
							<option
								key={ operatorKey }
								value={ operatorItem }
							>
								{ operatorItem }
							</option>
						);
					} )
				}
			</Form.Control>
			);
			})() }
		</Form.Group>
	);
} );

export default TriggerOperator;
