import React from 'react';
import { Tab, Row, Nav } from 'react-bootstrap';
import { urls } from '@jupiterx/control-panel';
import PopupTabCondition from './conditions/conditions-content';
import PopupTabTrigger from './triggers/triggers-content';
import { __ } from '@wordpress/i18n';

const PopupTabs = ( props ) => {
	const tabItems = [
		{ id: 'conditions', title: __( 'Display Conditions', 'jupiterx-core' ), description: __( 'Display this popup on specific pages.', 'jupiterx-core' ) },
		{ id: 'triggers', title: __( 'Triggers', 'juspiterx-core' ), description: __( 'Display this popup based on specific events and user interactions.', 'jupiterx-core' ) },
	];

	return (
		<Tab.Container
			className="jupiterx-popup-condtion-trigger-tabs"
			defaultActiveKey={ props.default }
			activeKey={ props.current }
			id="jupiterx-popup-condtion-trigger-tabs"
		>
			<Row className="jupiterx-popup-condtion-trigger-row">
				<div className="jupiterx-popup-tabs-nav ps-0 pe-0">
					<Nav variant="pills" className="flex-column">
						{ tabItems.map( ( item, index ) => (
							<Nav.Item key={ item.id }>
								<Nav.Link
									className="d-flex align-items-center"
									eventKey={ item.id }
									href="#"
									onClick={ () => props.changeTabs( item.id ) }
								>
									<img src={ urls.imgUrl + '/popup/' + item.id + '.svg' } alt={ item.title } />
									<div className="d-flex flex-column ms-3 text-left">
										<h5>{ item.title }</h5>
										<p>{ item.description }</p>
									</div>
								</Nav.Link>
							</Nav.Item>
						) ) }
					</Nav>
				</div>
				<div className="jupiterx-popup-tabs-content">
					<Tab.Content>
						<Tab.Pane eventKey="conditions">
						<PopupTabCondition ref={ props.conditionRef } conditionControl={ props.conditionControl } conditionUnregister={ props.conditionUnregister } conditionSetValue={ props.conditionSetValue } />
						</Tab.Pane>
						<Tab.Pane eventKey="triggers">
						<PopupTabTrigger ref={ props.conditionRef } conditionControl={ props.conditionControl } conditionUnregister={ props.conditionUnregister } conditionSetValue={ props.conditionSetValue } />
						</Tab.Pane>
					</Tab.Content>
				</div>
			</Row>
		</Tab.Container>
	);
};

export default PopupTabs;
