import React, { useEffect } from 'react';
import { tabs } from '@jupiterx/control-panel';
import { Tab, Col, Row } from 'react-bootstrap';
import './style.scss';

const Tools = () => {
	const toolsTab = tabs.find( ( { id } ) => id === 'maintenance' );

	useEffect( () => {
		document.getElementById( 'ready-made-websites' ).classList.add( 'active' );
	} );

	return (
		<div id="jx-cp-maintenance">
			<Tab.Container mountOnEnter={ true } defaultActiveKey={ 'ready-made-websites' }>
				<Row>
					<Col as={ Col } sm="12">
						{ Object.values( toolsTab.subTabs ).map( ( subTab ) => (
							<Tab.Content id={ subTab.id } className={ `jx-cp-maintenance-content-${ subTab.id }` } key={ subTab.id } data-section="maintenance"></Tab.Content>
						) ) }
					</Col>
				</Row>
			</Tab.Container>
		</div>
	);
};

export default Tools;
