import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { __ } from '@wordpress/i18n';
import { Button, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faQuestionCircle, faPlusCircle, faMinusCircle } from '@fortawesome/free-solid-svg-icons';
import { nonce, urls } from '@jupiterx/control-panel';
import WizardSpinner from '../compenents/spinner';
import Alert from '../../../components/alert';
import SkipWizardModal from '../compenents/skip-wizard-modal';

const RegistrationControl = ( props ) => {
	const [ isSaving, setSaving ] = useState( false );
	const [ error, setError ] = useState( {} );
	const { register, handleSubmit, setValue } = useForm();
	const [ isApiKeyVisible, setIsApiKeyVisible ] = useState( false );
	const [ skipWizard, setSkipWizard ] = useState( false );
	const [ showModal, setShowModal ] = useState( false );
	const handleCloseModal = () => {
		setShowModal( false );
	};

	const handleSkipWizard = () => {
		setShowModal( true );
	};

	const handleSkipSetup = () => {
		setSkipWizard( true );

		wp.ajax
			.post( 'jupiterx_skip_setup_wizard', {
				nonce,
			} )
			.fail( () => {
				setSkipWizard( false );
				handleCloseModal();
			} )
			.done( () => {
				setSkipWizard( false );
				handleCloseModal();
				window.localStorage.removeItem( 'jupiterxWizard' );
				window.location.href = urls.controlPanelUrl;
			} );
	};

	function onSubmit( fields ) {
		setSaving( true );
		setError( {} );

		const params = {
			nonce,
		};

		if ( isApiKeyVisible ) {
			params.mode = 'api_key';
			params.api_key = fields.api_key;
		} else {
			params.mode = 'purchase_code';
			params.email = fields.email;
			params.purchase_code = fields.purchase_code;
		}

		wp.ajax.post( 'jupiterx_cp_register_license', params ).fail( ( res ) => {
			setError( res );
			setSaving( false );
		} ).done( () => {
			setSaving( false );
			props.changeStep( 'colors' );
			props.updateRegisterLicense();
		} );
	}

	const handleClickApiKey = () => {
		setIsApiKeyVisible( ( prevState ) => ! prevState );
	};

	return (
		<>
			<div className="step-registration-header">
				<h2>
					{ __( 'Let\'s Get Started!', 'jupiterx-core' ) }
				</h2>
				<p> { __( 'Begin your website-building journey by registering your Jupiter X license.', 'jupiterx-core' ) } </p>
				<p> { __( 'It gives you access to updates, premium plugins, customer support and more.', 'jupiterx-core' ) } </p>
			</div>
			<Form className="step-registration-form" onSubmit={ handleSubmit( onSubmit ) }>
				<div className={ `step-registration-fields-wrapper ${ ! isApiKeyVisible ? 'visible' : 'hidden' }` }>
					<div>
						<Form.Group className="mb-3" controlId="email">
							<Form.Control
								required={ ! isApiKeyVisible }
								name="email"
								type="email"
								placeholder={ __( 'Email Address', 'jupiterx-core' ) }
								{ ...register( 'email' ) }
								tabIndex={ isApiKeyVisible ? -1 : 0 }
							/>
						</Form.Group>
						<Form.Group className="mb-3" controlId="purchase_code">
							<Form.Control
								required={ ! isApiKeyVisible }
								name="purchase_code"
								type="text"
								placeholder={ __( 'Envato Purchase Code', 'jupiterx-core' ) }
								{ ...register( 'purchase_code' ) }
								tabIndex={ isApiKeyVisible ? -1 : 0 }
							/>
						</Form.Group>
					</div>
				</div>

				<div className="d-flex align-items-center justify-content-between mb-3">
					<div className={ `d-flex align-items-center ${ isApiKeyVisible ? 'step-registration-form-api-key-active' : '' }` }>
						<FontAwesomeIcon className="step-registration-form-api-icon" icon={ isApiKeyVisible ? faMinusCircle : faPlusCircle } />
						<Button
							className="step-registration-form-button p-0"
							size="sm"
							variant="link"
							onClick={ handleClickApiKey }
						>
							{ isApiKeyVisible ? __( 'Back to Envato Registration', 'jupiterx-core' ) : __( 'Register with API key', 'jupiterx-core' ) }
						</Button>
					</div>

					<div className={ `step-registration-help-link-wrapper ${ ! isApiKeyVisible ? 'visible' : 'hidden' }` }>
						<a
							className="step-registration-form-link"
							href="https://help.jupiterx.com/article/20-how-to-locate-your-purchase-code-on-themeforest"
							target="_blank"
							tabIndex={ isApiKeyVisible ? -1 : 0 }
						>
							<FontAwesomeIcon icon={ faQuestionCircle } />
							{ __( 'How to find my purchase code?', 'jupiterx-core' ) }
						</a>
					</div>
				</div>

				<div className={ `step-registration-api-key-wrapper ${ isApiKeyVisible ? 'visible' : 'hidden' }` }>
					<div>
						<Form.Group className="mb-3" controlId="api_key">
							<Form.Control
								required={ isApiKeyVisible }
								name="api_key"
								type="text"
								placeholder={ __( 'API Key', 'jupiterx-core' ) }
								{ ...register( 'api_key' ) }
								tabIndex={ ! isApiKeyVisible ? -1 : 0 }
							/>
						</Form.Group>
					</div>
				</div>

				<div className={ `step-registration-terms-wrapper ${ ! isApiKeyVisible ? 'visible' : 'hidden' }` }>
					<div>
						<Form.Group className="step-registration-form-checkbox" controlId="terms">
							<Form.Check
								required={ ! isApiKeyVisible }
								name="terms"
								type="checkbox"
								label={ __(
									'I consent to Artbees Themes collecting my personal information according to its Privacy policy and Terms of use.',
									'jupiterx-core'
								) }
								{ ...register( 'terms' ) }
								tabIndex={ isApiKeyVisible ? -1 : 0 }
							/>
						</Form.Group>
					</div>
				</div>
				{
					! _.isEmpty( error ) &&
					<Alert className="step-registration-alert" variant="danger">
						{ __( 'Registration failed, please double-check the information provided and enter the correct account details.', 'jupiterx-core' ) }
					</Alert>
				}
				<div className="jx-setup-wizard-steps-control">
					<Button className="skip-step" variant="secondary" onClick={ handleSkipWizard }>
						{ skipWizard ? <WizardSpinner /> : __( 'Skip Wizard', 'jupiterx-core' ) }
					</Button>

					<Button
						className="next-step"
						type="submit"
						disabled={ isSaving }
					>
						{ isSaving ? <WizardSpinner /> : __( 'Continue', 'jupiterx-core' ) }
					</Button>
				</div>

				<SkipWizardModal
					showModal={ showModal }
					handleCloseModal={ handleCloseModal }
					handleSkipSetup={ handleSkipSetup }
					skipWizard={ skipWizard }
				/>
			</Form>
		</>
	);
};

export default RegistrationControl;
