import React, { useState, useEffect } from 'react';
import { Dropdown, Form, Accordion, Card } from 'react-bootstrap';
import { useMediaQuery } from 'react-responsive';
import { __ } from '@wordpress/i18n';
import decodeHtml from 'decode-html';
import './style.scss';

const CustomSelect = ( {
	title,
	options = {},
	onChange,
	value = [],
	name,
} ) => {
	const [ state, setState ] = useState( value );

	useEffect( () => {
		setState( value );
	}, [ value ] );

	const handleChange = ( event ) => {
		const newValue = event.target.checked
			? [ ...state, event.target.value ]
			: state.filter( ( selected ) => selected !== event.target.value );

		setState( newValue );
		onChange( newValue );
	};

	const handleClear = ( event ) => {
		event.preventDefault();
		event.stopPropagation();
		setState( [] );
		onChange( [] );
	};

	const isTabletOrMobile = useMediaQuery( {
		query: '(max-width: 782px)',
	} );

	const selectedOptions = state.length > 0
		? state.map( ( key ) => decodeHtml( options[ key ] ) ).join( ', ' )
		: __( 'All', 'jupiterx-core' );

	const renderOptions = Object.keys( options ).map( ( key ) => {
		const uniqueId = `${ name }-${ key }`;

		return (
			<Form.Check
				key={ uniqueId }
				value={ key }
				id={ uniqueId }
				name={ uniqueId }
				type="checkbox"
				label={ decodeHtml( options[ key ] ) }
				onChange={ handleChange }
				checked={ state.indexOf( key ) >= 0 }
			/>
		);
	} );

	const hasValue = state.length > 0;

	return (
		<div className="jx-cp-custom-select">
			{ ! isTabletOrMobile ? (
				<Dropdown className="jx-cp-custom-select">
					<Dropdown.Toggle variant={ false } id="dropdown-basic">
						<div>
							<div className="jx-cp-custom-select-title">
								{ title }
								{ hasValue && (
									// eslint-disable-next-line jsx-a11y/anchor-is-valid
									<a className="jx-cp-custom-select-clear" onClick={ handleClear } href="#">
										{ __( 'Clear', 'jupiterx-core' ) }
									</a>
								) }
							</div>
							<div className="jx-cp-custom-select-selected">
								{ selectedOptions }
							</div>
						</div>
					</Dropdown.Toggle>
					<Dropdown.Menu>
						{ renderOptions }
					</Dropdown.Menu>
				</Dropdown>
			) : (
				<Accordion>
					<Card>
						<Accordion.Toggle as={ Card.Header } eventKey={ name }>
							{ title }
						</Accordion.Toggle>
						<Accordion.Collapse eventKey={ name }>
							<Card.Body>
								{ renderOptions }
							</Card.Body>
						</Accordion.Collapse>
					</Card>
				</Accordion>
			) }
		</div>
	);
};

export default CustomSelect;
