import React, { useContext } from 'react';
import { __ } from '@wordpress/i18n';
import Dialog from '../../../components/dialog';
import { actionTypes } from './reducer';
import { SettingsContext } from './../../../store/settings';

const EditDialog = ( { state, dispatch } ) => {
	const { nonce } = useContext( SettingsContext );

	const removeImageSize = () => {
		dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE_STATUS, payload: 'progress' } );

		const sizes = state.sizes.filter( ( size ) => {
			return size.size_n !== state.removeSelected.size_n;
		} );

		window.wp.ajax.post( 'jupiterx_core_cp_save_image_sizes', {
			_ajax_nonce: nonce,
			options: sizes,
		} )
			.done( ( response ) => {
				dispatch( { type: actionTypes.UPDATE_IMAGE_SIZES, payload: response } );
				dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE_STATUS, payload: '' } );
				dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE, payload: null } );
			} ).fail( () => {
				dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE_STATUS, payload: 'error' } );
			} );
	};

	return (
		<Dialog
			title={ __( 'Remove Image Size', 'jupiterx-core' ) }
			variant={ state.removeStatus }
			show={ state.removeSelected !== null }
			cancelText={ __( 'Discard', 'jupiterx-core' ) }
			okText={ __( 'Yes', 'jupiterx-core' ) }
			showCancel={ true }
			closeButton={ false }
			onOk={ () => removeImageSize() }
			onCancel={ () => dispatch( { type: actionTypes.REMOVE_IMAGE_SIZE, payload: null } ) }
		>
			{ __( 'Are you sure you want to remove this image size?', 'jupiterx-core' ) }
		</Dialog>
	);
};

export default EditDialog;
