import React, { useState, useCallback } from 'react';
import { useForm } from 'react-hook-form';
import { Button, Form, Spinner } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAngleLeft, faPlus } from '@fortawesome/free-solid-svg-icons';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import FontVariationFields from './font-variation-fields';

const Post = ( props ) => {
	// Parse previous data safely
	const getPreviousData = () => {
		try {
			if ( props.post && props.post.post_content ) {
				const parsed = JSON.parse( props.post.post_content );
				return Array.isArray( parsed ) ? parsed : [];
			}
		} catch ( e ) {
			// eslint-disable-next-line no-console
			console.error( 'Error parsing font data:', e );
		}
		return [];
	};

	const previousData = getPreviousData();

	// Initialize variations as data array instead of JSX elements
	const getInitialVariations = () => {
		if ( 'edit' === props.mode && previousData.length > 0 ) {
			return previousData.map( ( variation, index ) => ( {
				id: index,
				data: variation,
			} ) );
		}
		return [];
	};

	const [ variations, setVariations ] = useState( getInitialVariations );
	const [ nextVariationId, setNextVariationId ] = useState( previousData.length || 0 );
	const [ submit, setSubmit ] = useState( 'creating' );
	const [ errorMessage, setErrorMessage ] = useState( '' );

	const { register, handleSubmit, setValue, getValues } = useForm( {
		defaultValues: {
			custom_fonts_post_title: props.post?.post_title || '',
			custom_fonts_submit_mode: props.post?.ID || '',
		},
	} );

	const onSubmit = ( formData ) => {
		setSubmit( 'saving' );
		setErrorMessage( '' );

		// Build the post data structure
		const postData = {
			custom_fonts_post_title: formData.custom_fonts_post_title,
			custom_fonts_submit_mode: formData.custom_fonts_submit_mode || '',
			custom_fonts_post_variation_url: [],
		};

		// Collect variation data from form
		if ( formData.custom_fonts_post_variation_url ) {
			// Filter out empty/null entries and ensure proper structure
			postData.custom_fonts_post_variation_url = Object.values( formData.custom_fonts_post_variation_url )
				.filter( ( variation ) => {
					if ( ! variation || typeof variation !== 'object' ) {
						return false;
					}
					// Check if at least one font file is provided
					return variation.woff || variation.woff2 || variation.ttf || variation.svg;
				} )
				.map( ( variation ) => ( {
					font_weight: variation.font_weight || 'normal',
					font_style: variation.font_style || 'normal',
					woff: variation.woff || '',
					woff2: variation.woff2 || '',
					ttf: variation.ttf || '',
					svg: variation.svg || '',
				} ) );
		}

		if ( postData.custom_fonts_post_variation_url.length === 0 ) {
			setSubmit( 'creating' );
			setErrorMessage( __( 'Please add at least one font variation with a font file.', 'jupiterx-core' ) );
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_fonts',
			sub_action: 'save_post',
			post: postData,
			nonce,
		} )
			.done( () => {
				setSubmit( 'creating' );
				props.afterSubmit();
			} )
			.fail( ( data ) => {
				setSubmit( 'creating' );
				setErrorMessage( data || __( 'An error occurred while saving.', 'jupiterx-core' ) );
			} );
	};

	const addNewFontVariationField = () => {
		const newId = nextVariationId;
		setVariations( [ ...variations, { id: newId, data: null } ] );
		setNextVariationId( newId + 1 );
	};

	const removeVariation = useCallback( ( variationId ) => {
		setVariations( ( prevVariations ) =>
			prevVariations.filter( ( v ) => v.id !== variationId )
		);
	}, [] );

	const getSubmitButton = () => {
		if ( 'creating' === submit ) {
			return <button
				className="mt-2 new-custom-fonts-submit"
				type="submit">
				{ props.mode === 'edit' ? __( 'Update', 'jupiterx-core' ) : __( 'Create', 'jupiterx-core' ) }
			</button>;
		}

		if ( 'saving' === submit ) {
			return <button
				className="mt-2 new-custom-fonts-submit saving-mode"
				type="button"
				disabled>
				<Spinner as="span"
					animation="border"
					size="sm"
					role="status"
					aria-hidden="true"
					className="me-2" />
				<span>{ __( 'Saving', 'jupiterx-core' ) }</span>
			</button>;
		}
	};

	return (
		<div className="custom-fonts-add-new">
			<div className="header-wrapper">
				<span className="header">
					{
						'new' === props.mode
							? __( 'Add New Font Family', 'jupiterx-core' )
							: __( 'Edit Font Family', 'jupiterx-core' )
					}
				</span>
				{
					<Button
						variant="secondary"
						className="px-4 post-back-button"
						onClick={ props.backButton }
					>
						<FontAwesomeIcon icon={ faAngleLeft } className="me-2" />
						{ __( 'Back', 'jupiterx-core' ) }
					</Button>
				}
			</div>
			<Form onSubmit={ handleSubmit( onSubmit ) } className="add-edit-fonts">
				<Form.Group className="font-family-name">
					<Form.Label>
						{ __( '1. What is the name of this font family?', 'jupiterx-core' ) }
					</Form.Label>
					<Form.Control
						type="text"
						id="custom_title"
						className="w-25"
						placeholder={ __( 'Enter a name', 'jupiterx-core' ) }
						{ ...register( 'custom_fonts_post_title', { required: true } ) }
					/>
				</Form.Group>
				<hr />
				<Form.Group className="variations">
					<Form.Label>
						{ __( '2. Specify the variations for this font family', 'jupiterx-core' ) }
					</Form.Label>
					<div className="variation" id="variations-container">
						{ variations.map( ( variation ) => (
							<FontVariationFields
								key={ variation.id }
								register={ register }
								indexValue={ variation.id }
								previousData={ variation.data }
								onRemove={ () => removeVariation( variation.id ) }
							/>
						) ) }
					</div>
					<Button
						onClick={ addNewFontVariationField }
						className="btn-primary add-new-variation"
						type="button"
					>
						<FontAwesomeIcon icon={ faPlus }></FontAwesomeIcon>
						<span className="ms-3">{ __( 'Add Font Variations', 'jupiterx-core' ) }</span>
					</Button>
				</Form.Group>
				<input
					type="hidden"
					{ ...register( 'custom_fonts_submit_mode' ) }
				/>
				<hr />
				<div className="submit-area">
					{ getSubmitButton() }
					<Button
						variant="outline-danger"
						className="float-end mt-2 remove-btn"
						onClick={ props.removeBtn }
						type="button"
					>
						{ __( 'Remove', 'jupiterx-core' ) }
					</Button>
					{ errorMessage && <p className="show-error-result text-danger">{ errorMessage }</p> }
				</div>
			</Form>
		</div>
	);
};

export default Post;
