import React, { useEffect, useContext, useReducer } from 'react';
import { __ } from '@wordpress/i18n';
import { Button, Spinner, Alert } from 'react-bootstrap';
import { SettingsContext } from './../../../store/settings';
import ImageSize from './image-size';
import EditDialog from './edit-dialog';
import RemoveDialog from './remove-dialog';
import AddDialog from './add-dialog';
import { initialState, reducer, actionTypes } from './reducer';
import './style.scss';

const ImageSizes = () => {
	const { nonce } = useContext( SettingsContext );
	const [ state, dispatch ] = useReducer( reducer, initialState );

	useEffect( () => {
		fetchSizes();
	}, [] );

	const fetchSizes = () => {
		window.wp.ajax.post( 'jupiterx_core_cp_get_image_sizes', {
			_ajax_nonce: nonce,
		} )
			.done( ( response ) => {
				dispatch( { type: actionTypes.UPDATE_IMAGE_SIZES, payload: response } );
				dispatch( { type: actionTypes.FETCH_IMAGE_SIZES_STATUS, payload: 'success' } );
			} ).fail( () => {
				dispatch( { type: actionTypes.FETCH_IMAGE_SIZES_STATUS, payload: 'error' } );
			} );
	};

	const renderSizes = () => {
		if ( state.fetchStatus === 'fetching' ) {
			return <div className="d-flex my-5 justify-content-center"><Spinner
				as="span"
				animation="border"
				role="status"
				aria-hidden="true"></Spinner>
			</div>;
		}

		if ( state.fetchStatus !== 'success' ) {
			return 	<div className="jx-cp-plugins-optional-notice d-flex">
				<Alert variant="danger">
					{ __( 'Could not connect to Artbees server, please try again and if the issue persists contact support', 'jupiterx-core' ) }
				</Alert>
			</div>;
		}

		return <div className="jx-cp-settings-image-sizes-list d-flex flex-column flex-sm-row flex-wrap">
			{ state.sizes.map( ( imageSize, index ) => <ImageSize dispatch={ dispatch } imageSize={ imageSize } key={ index } /> ) }
		</div>;
	};

	return (
		<div className="jx-cp-settings-image-sizes">
			<Button
				className="mb-4"
				variant="primary"
				onClick={ () => {
					dispatch( { type: actionTypes.EDIT_IMAGE_SIZE, payload: null } );
					dispatch( { type: actionTypes.TOGGLE_ADD_IMAGE_SIZE_DIALOG, payload: true } );
				} }>{ __( 'Add a New Size', 'jupiterx-core' ) }</Button>
			{ renderSizes() }
			<EditDialog state={ state } dispatch={ dispatch } />
			<AddDialog state={ state } dispatch={ dispatch } />
			<RemoveDialog state={ state } dispatch={ dispatch } />
		</div>
	);
};

export default ImageSizes;
