import React from 'react';
import Dialog from '../../components/dialog';
import { __ } from '@wordpress/i18n';

const SimplicityModal = ( { handleSimplicityModal } ) => {
	const disableSimplicity = () => {
		handleSimplicityModal( false, null );
	};

	return (
		<Dialog
			title={ __( 'Important Notice: Read Carefully Before Proceeding', 'jupiterx-core' ) }
			variant="warning"
			titleAs="strong"
			show
			okText={ __( 'Confirm', 'jupiterx-core' ) }
			onOk={ () => handleSimplicityModal( true, null ) }
			onCancel={ disableSimplicity }
			onHide={ disableSimplicity }
			closeButton={ false }
		>
			{ __( 'If you are upgrading from JupiterX version 3.7 or earlier, please note that enabling Simplicity Mode will disable your current Customizer and meta post settings. You will need to reconfigure specific features manually using Elementor and Layout Builder.', 'jupiterx-core' ) }
			<br />
			<br />
			<strong>
				{ __( 'Strongly Advised: Do not activate Simplicity Mode on live and production website without conducting comprehensive tests. Make sure you have a complete backup of your website before enabling this feature.', 'jupiterx-core' ) }
			</strong>
		</Dialog>
	);
};

export default SimplicityModal;
