import React, { useState, useContext, useEffect } from 'react';
import './style.scss';
import { __ } from '@wordpress/i18n';
import NavButton from './nav-button';
import DarkModeButton from './dark-mode-button';
import Modal from '../../../components/modal';
import WizardSpinner from './spinner';
import { Form } from 'react-bootstrap';
import SingleTemplatePreview from './single-template-preview';
import { SetupWizardContext } from '..';

const LayoutFooter = ( props ) => {
	const context = useContext( SetupWizardContext );
	const [ showModal, setShowModal ] = useState( false );
	const [ selectedTemplate, setSelectedTemplate ] = useState( context.getLocalStorage( 'layout_footer' ) );
	const [ layoutMode, setLayoutMode ] = useState( context.getLocalStorage( 'footer_dark_mode' ) );
	const [ hasDarkLight, setHasDarkLight ] = useState( true );

	const onSingeLayoutClick = ( templateData, modalData ) => {
		context.setLocalStorage( 'layout_footer', templateData );
		setSelectedTemplate( templateData );
		setShowModal( modalData );
	};

	useEffect( () => {
		if ( showModal ) {
			document.body.style.overflow = 'hidden';
		} else {
			document.body.style.overflow = 'auto';
		}

		// Cleanup function to restore scroll when component unmounts
		return () => {
			document.body.style.overflow = 'auto';
		};
	}, [ showModal ] );

	useEffect( () => {
		if ( layoutMode === null || layoutMode === false ) {
			setLayoutMode( 'light' );
			return;
		}

		setLayoutMode( 'dark' );
	}, [] );

	useEffect( () => {
		if ( props.templates.hasOwnProperty( 'footer' ) && Object.keys( props.templates?.footer ).length > 1 ) {
			setHasDarkLight( true );
			return;
		}

		setHasDarkLight( false );
	}, [ props.templates ] );

	return (
		<div className="jx-setup-wizard-layout-footer">
			<div className="footer">
				<div className="title">
					{ __( 'Footer', 'jupiterx-core' ) }
				</div>
				<div className="text">
					{ __( 'Select your default footer. This will be your global footer.', 'jupiterx-core' ) }
				</div>
			</div>
			<div className="body">
				<div className="row mt-4">
					<div className="col-6 d-flex">
						<NavButton
							className="change-button"
							buttonText={ __( 'Change Footer', 'jupiterx-core' ) }
							handleNavButtonClick={ () => {
								setShowModal( true );
							} }
						/>
					</div>
				</div>

				{ props.templates?.hasOwnProperty( 'footer' ) && <div className="row mt-4">
					<div className="col-12">
						<img
							className="footer-template-image"
							alt="footer-template"
							src={ ! _.isEmpty( selectedTemplate ) ? selectedTemplate.thumbnail : props.templates.footer.light.find( ( template ) => template.id === 21572 )?.thumbnail }
						/>
					</div>
				</div> }

				<Modal
					show={ showModal }
					size="xl"
					className="setup-wizard-step-layout-popup"
					onHide={ () => {
						setShowModal( false );
					} }
				>
					<Modal.Header closeButton>
						<Modal.Title>{ __( 'Footer Templates', 'jupiterx-core' ) }</Modal.Title>
						{ hasDarkLight && <DarkModeButton
							handleDarkModeClick={ () => {
								context.setLocalStorage( 'footer_dark_mode', ! context.getLocalStorage( 'footer_dark_mode' ) );
								setLayoutMode( 'light' === layoutMode ? 'dark' : 'light' );
							} }
							default={ null === context.getLocalStorage( 'footer_dark_mode' ) ? false : context.getLocalStorage( 'footer_dark_mode' ) }
						/> }
					</Modal.Header>
					<Modal.Body>
						{
							props.templatesLoader &&
							<WizardSpinner />
						}
						{
							! props.templatesLoader &&
							<div className="popup-inner-container">
								{ props.templates?.hasOwnProperty( 'footer' ) && props.templates.footer?.hasOwnProperty( layoutMode ) &&
								props.templates.footer[ layoutMode ].map( ( item, index ) => {
									return (
										<SingleTemplatePreview
											data={ item }
											key={ index }
											onSingeLayoutClick={ onSingeLayoutClick }
										/>
									);
								} ) }
							</div>
						}
					</Modal.Body>
				</Modal>

				{ props.templates?.hasOwnProperty( 'footer' ) && <Form.Control
					name="layout[footer]"
					type="hidden"
					{ ...props.stepRef( 'layout[footer]' ) }
					value={ ! ( selectedTemplate?.template_id ) ? props.templates.footer.light.find( ( template ) => template.id === 21572 )?.id : selectedTemplate?.[ 'template_id' ] } // eslint-disable-line
				/> }
			</div>
		</div>
	);
};

export default LayoutFooter;
