import React, { forwardRef, useEffect, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import DatePicker from 'react-datepicker';
import { faCalendarAlt } from '@fortawesome/free-solid-svg-icons';
import { Form } from 'react-bootstrap';

const DateRangeControl = forwardRef( ( props, ref ) => {
	const [ startDate, setStartDate ] = useState();
	const [ endDate, setEndDate ] = useState();
	const [ calendarOpen, setCalendarOpen ] = useState( false );

	useEffect( () => {
		// eslint-disable-next-line
		if ( _.isEmpty( props.triggerControl?.defaultValue?.start_date ) || _.isEmpty( props.triggerControl?.defaultValue?.end_date ) ) {
			return;
		}

		const startTime = props.triggerControl.defaultValue.start_date,
			endTime = props.triggerControl.defaultValue.end_date;

		setStartDate( startTime * 1000 );
		setEndDate( endTime * 1000 );
	}, [] );

	const onUpdateHandler = ( start, end ) => {
		const startTime = Math.floor( new Date( start ).getTime() );
		const endTime = Math.floor( new Date( end ).getTime() );

		setStartDate( startTime );
		setEndDate( endTime );

		if ( _.isFunction( props.onUpdateCallback ) ) {
			props.onUpdateCallback();
		}
	};

	return <>
		<Form.Group className={ `jupiterx-popup-date-input-wrapper d-flex align-items-center popup-trigger-type-${ props.triggerControl.type } ${ calendarOpen ? 'jupiterx-popup-date-input-open' : '' }` }>
			<DatePicker
				selectsRange={ true }
				className="jupiterx-popup-date-input"
				startDate={ startDate }
				dateFormat="dd MMM yyyy"
				endDate={ endDate }
				popperPlacement="top-start"
				onChange={ ( updatedDate ) => {
					onUpdateHandler( updatedDate[ 0 ], updatedDate[ 1 ] );
				} }
				onFocus={ () => setCalendarOpen( true ) }
				onClickOutside={ () => setCalendarOpen( false ) }
			/>
			<FontAwesomeIcon icon={ faCalendarAlt } />
		</Form.Group>
		<input
			type="hidden"
			name={ props.rowName + '[control][start_date]' }
			value={ _.isNumber( startDate ) ? ( startDate / 1000 ) : '' }
			{ ...ref( props.rowName + '[control][start_date]' ) }
		/>
		<input
			type="hidden"
			name={ props.rowName + '[control][end_date]' }
			value={ _.isNumber( endDate ) ? ( endDate / 1000 ) : '' }
			{ ...ref( props.rowName + '[control][end_date]' ) }
		/>
	</>;
} );

export default DateRangeControl;
