import React from 'react';
import { OverlayTrigger, Tooltip as RBTooltip } from 'react-bootstrap';

const rootElement = document.getElementById( 'jx-cp-root' );

const Tooltip = ( {
	children,
	overlay,
	placement = 'top',
	trigger = [ 'hover', 'focus' ],
	...props
} ) => {
	const renderOverlay = ( overlayProps ) => (
		<RBTooltip { ...overlayProps } children={ overlay } />
	);

	return (
		<OverlayTrigger
			{ ...props }
			trigger={ trigger }
			rootClose={ trigger === 'click' }
			placement={ placement }
			container={ rootElement }
			overlay={ renderOverlay }
		>
			{ children }
		</OverlayTrigger>
	);
};

export default Tooltip;
