import React, { useContext } from 'react';
import { Button, Spinner } from 'react-bootstrap';
import { AppContext } from '../../../';
import { __, sprintf } from '@wordpress/i18n';
import { updateAjaxPlugin } from './util';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCheck } from '@fortawesome/free-solid-svg-icons';

const updateItem = ( { appDispatch, update } ) => {
	updateAjaxPlugin( { appDispatch, plugin: update } );
};

const isUpdatingTheme = ( appState ) => {
	return appState.updates.list
		.filter( ( item ) => item.status === 'updating' && item.type === 'theme' )
		.length > 0;
};

const isUpdating = ( update ) => {
	return update.status === 'updating';
};

const isUpdated = ( update ) => {
	return update.status === 'updated';
};

const isQueued = ( update ) => {
	return update.status === 'queued';
};

const isUpdateError = ( update ) => {
	return update.status === 'error';
};

const updateBtnText = ( update ) => {
	if ( isUpdated( update ) ) {
		return __( 'Updated', 'jupiterx-core' );
	}

	if ( isQueued( update ) ) {
		return __( 'Queued', 'jupiterx-core' );
	}

	if ( isUpdating( update ) ) {
		return __( 'Updating', 'jupiterx-core' );
	}

	return __( 'Update', 'jupiterx-core' );
};

const getChangeLogLink = ( update ) => {
	if ( typeof update.source !== 'undefined' && update.source === 'wp-repo' ) {
		return 'https://wordpress.org/plugins/' + update.slug + '/#developers';
	}

	if ( typeof update.slug !== 'undefined' && update.slug === 'jupiterx' ) {
		return 'https://themes.artbees.net/support/jupiterx/release-notes/';
	}

	if ( typeof update.post_id !== 'undefined' ) {
		return 'https://themes.artbees.net/?p=' + update.post_id;
	}

	return false;
};

const Item = ( { update } ) => {
	const { appState, appDispatch } = useContext( AppContext );

	return 	<div className="jx-cp-updates-list-item mb-3 d-flex align-items-sm-center flex-column flex-sm-row">
		<div className="jx-cp-updates-list-item-img">
			<img src={ update.img_url } alt="Plugin" />
		</div>
		<div className="jx-cp-updates-list-item-details mt-2 mt-sm-0">
			<div className="jx-cp-updates-list-item-title">
				{ update.title }
			</div>
			<div className="jx-cp-updates-list-item-cversion">
				{ __( 'Current version:', 'jupiterx-core' ) + ' ' + update.current_version }
			</div>
			<div className="jx-cp-updates-list-item-nversion">
				<a href={ getChangeLogLink( update ) } target="_blank">
					{
						getChangeLogLink( update ) ? sprintf(
							// translators: %s version
							__( 'View version %s details', 'jupiterx-core' ),
							update.new_version
						) : __( 'New version:', 'jupiterx-core' ) + ' ' + update.new_version
					}
				</a>
			</div>
		</div>
		<div className="jx-cp-updates-list-item-action d-sm-flex flex-sm-column justify-content-sm-end mt-2 mt-sm-0">
			<Button
				size="sm"
				variant={ isUpdated( update ) ? 'success' : 'primary' }
				disabled={ ( isUpdatingTheme( appState ) && ! isUpdated( update ) ) || isUpdating( update ) || isQueued( update ) }
				onClick={ () => updateItem( { appDispatch, update } ) }
				className="align-self-sm-end">
				{
					isUpdating( update ) &&
					<Spinner
						className="me-1"
						as="span"
						animation="border"
						size="sm"
						role="status"
						aria-hidden="true"></Spinner>
				}
				{ isUpdated( update ) && <FontAwesomeIcon className="me-1" icon={ faCheck } /> }
				<span>
					{ updateBtnText( update ) }
				</span>
			</Button>
			{ isUpdateError( update ) && <div className="jx-cp-updates-list-item-update-error mt-2 text-left text-sm-right">{ update.status_message || __( 'Something went wrong, please try again.' ) }</div> }
		</div>
	</div>;
};

export default Item;
