import { appActionTypes } from '../../../reducer';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import $ from 'jquery';

export const updateAjaxPlugin = ( { appDispatch, plugin, successCallback, errorCallback } ) => {
	appDispatch( {
		type: appActionTypes.APP_UPDATE_ITEM,
		payload: { id: plugin.id, status: 'updating' },
	} );

	wp.ajax.send( 'jupiterx_cp_settings_reinstall', {
		data: {
			nonce,
			product: plugin,
		},
		success: () => {
			appDispatch( {
				type: appActionTypes.APP_UPDATE_ITEM_STATUS,
				payload: { id: plugin.id, status: 'updated' },
			} );

			if ( typeof successCallback === 'function' ) {
				successCallback();
			}
		},
		error: () => {
			appDispatch( {
				type: appActionTypes.APP_UPDATE_ITEM_STATUS,
				payload: { id: plugin.id, status: 'error' },
			} );

			if ( typeof errorCallback === 'function' ) {
				errorCallback();
			}
		},
	} );
};

export const updatePlugin = ( { appDispatch, plugin, successCallback, errorCallback } ) => {
	appDispatch( {
		type: appActionTypes.APP_UPDATE_ITEM,
		payload: { id: plugin.id, status: 'updating' },
	} );

	$.ajax( {
		url: window._.unescape( plugin.update_url ),
		success: () => {
			$.ajax( {
				url: window._.unescape( plugin.activate_url ),
				success: () => {
					appDispatch( {
						type: appActionTypes.APP_UPDATE_ITEM_STATUS,
						payload: { id: plugin.id, status: 'updated' },
					} );

					if ( typeof successCallback === 'function' ) {
						successCallback();
					}
				},
				error: () => {
					appDispatch( {
						type: appActionTypes.APP_UPDATE_ITEM_STATUS,
						payload: { id: plugin.id, status: 'error' },
					} );

					if ( typeof errorCallback === 'function' ) {
						errorCallback();
					}
				},
			} );
		},
		error: () => {
			appDispatch( {
				type: appActionTypes.APP_UPDATE_ITEM_STATUS,
				payload: { id: plugin.id, status: 'error' },
			} );

			if ( typeof errorCallback === 'function' ) {
				errorCallback();
			}
		},
	} );
};

export const updateTheme = ( { appDispatch, theme, successCallback, errorCallback } ) => {
	appDispatch( {
		type: appActionTypes.APP_UPDATE_ITEM,
		payload: { id: theme.id, status: 'updating' },
	} );

	wp.ajax.send( 'jupiterx_core_cp_modify_auto_update', {
		data: {
			_ajax_nonce: nonce,
			release_id: theme.release_id,
			release_version: theme.new_version,
		},
		success: () => {
			wp.updates.ajax( 'update-theme', {
				slug: theme.slug,
				success: () => {
					appDispatch( {
						type: appActionTypes.APP_UPDATE_ITEM_STATUS,
						payload: { id: theme.id, status: 'updated' },
					} );

					if ( typeof successCallback === 'function' ) {
						successCallback();
					}

					window.location.reload();
				},
				error: ( response ) => {
					const errorCode = response && response.errorCode ? response.errorCode : '';

					if ( errorCode === 'files_not_writable' || errorCode === 'remove_old_failed' ) {
						appDispatch( {
							type: appActionTypes.APP_UPDATE_ITEM_STATUS,
							payload: {
								id: theme.id,
								status: 'error',
								status_message: __( 'Please check file or folder permissions on your server.', 'jupiterx-core' ),
							},
						} );
					} else {
						appDispatch( {
							type: appActionTypes.APP_UPDATE_ITEM_STATUS,
							payload: { id: theme.id, status: 'error' },
						} );
					}

					if ( typeof errorCallback === 'function' ) {
						errorCallback();
					}
				},
			} );
		},
		error: () => {
			appDispatch( {
				type: appActionTypes.APP_UPDATE_ITEM_STATUS,
				payload: { id: theme.id, status: 'error' },
			} );

			if ( typeof errorCallback === 'function' ) {
				errorCallback();
			}
		},
	} );
};

export const fetchUpdates = ( { appDispatch, post } ) => {
	appDispatch( { type: appActionTypes.APP_FETCH_UPDATES, payload: true } );

	post = post || {};
	post._ajax_nonce = nonce;

	wp.ajax.post( 'jupiterx_core_cp_get_updates', post )
		.done( ( data ) => {
			appDispatch( { type: appActionTypes.APP_FETCH_UPDATES_STATUS, payload: { status: 'success', message: null } } );
			appDispatch( { type: appActionTypes.APP_ADD_UPDATES_LAST_CHECKED, payload: data.last_checked } );
			appDispatch( { type: appActionTypes.APP_ADD_UPDATES, payload: data.updates } );
			appDispatch( { type: appActionTypes.APP_AUTO_UPDATER_STATUS, payload: data.auto_updater_state } );
		} ).fail( ( data ) => {
			const payload = { status: 'error', message: null };

			if ( typeof data.error !== 'undefined' ) {
				payload.message = data.error;
			}

			appDispatch( { type: appActionTypes.APP_FETCH_UPDATES_STATUS, payload } );
		} ).always( () => {
			appDispatch( { type: appActionTypes.APP_FETCH_UPDATES, payload: false } );
		} );
};

export const toggleAutoUpdater = ( { appDispatch, appState } ) => {
	const state = appState.updates.auto;

	appDispatch( { type: appActionTypes.APP_AUTO_UPDATER_STATUS, payload: 'saving' } );

	wp.ajax.post( 'jupiterx_core_cp_toggle_auto_updater', {
		_ajax_nonce: nonce,
		enable: state === 'enabled' ? false : true,
	} )
		.done( ( data ) => {
			appDispatch( { type: appActionTypes.APP_AUTO_UPDATER_STATUS, payload: data.state } );
		} ).fail( () => {
			appDispatch( { type: appActionTypes.APP_AUTO_UPDATER_STATUS, payload: state } );
		} );
};
