import React, { useState, useEffect } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import Dialog from '../../../components/dialog';
import { isEmpty } from 'lodash';
import decodeHtml from 'decode-html';

const ExportDialog = ( { show, onHide, formData } ) => {
	const [ isLoading, setIsLoading ] = useState( false );
	const [ data, setData ] = useState( null );
	const [ error, setError ] = useState( null );
	const [ step, setStep ] = useState( 0 );

	const { config, filename } = formData;

	useEffect( () => {
		if ( ! show ) {
			return;
		}

		wp.ajax.send( 'jupiterx_core_cp_export_import', {
			data: {
				nonce,
				type: 'Export',
				step: config[ step ],
				data: {	filename },
			},
			success( res ) {
				const nextStep = step + 1;

				if ( ! config[ nextStep ] ) {
					setData( res.download_url );
					return;
				}

				setStep( nextStep );
			},
			error( res ) {
				setError( res );
			},
		} );
	}, [ show, formData, step ] );

	const handleClose = () => {
		onHide();

		setTimeout( () => {
			setIsLoading( false );
			setData( null );
			setError( null );
			setStep( 0 );
		}, 200 );
	};

	const handleDownload = () => {
		window.location.href = data;
		handleClose();
	};

	if ( isEmpty( config ) ) {
		return null;
	}

	if ( error ) {
		return (
			<Dialog
				title={ __( 'Error!', 'jupiterx-core' ) }
				variant="error"
				show={ show }
				onHide={ handleClose }
			>
				{ decodeHtml( error ) }
			</Dialog>
		);
	}

	if ( data ) {
		return (
			<Dialog
				title={ __( 'Export Done', 'jupiterx-core' ) }
				variant="success"
				show={ show }
				onHide={ handleClose }
				okText={ __( 'Download', 'jupiterx-core' ) }
				onOk={ handleDownload }
			>
				{ __( 'Export has been finished successfully.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	return (
		<Dialog
			title={ sprintf(
				// translators: %s Export step name
				__( 'Exporting %s...', 'jupiterx-core' ),
				config[ step ]
			) }
			variant="progress"
			show={ show }
			isLoading={ isLoading }
		>
			{ __( 'Please wait for the export to finish...', 'jupiterx-core' ) }
		</Dialog>
	);
};

export default ExportDialog;
