import React, { useState, useEffect } from 'react';
import { Tab, Col, Row, ListGroup, Nav } from 'react-bootstrap';
import { tabs, isPremium } from '@jupiterx/control-panel';
import { useNavigate } from 'react-router-dom';
import { __ } from '@wordpress/i18n';
import General from './general';
import $ from 'jquery';
import './style.scss';

const Settings = ( { handleSetSimplicityMode, simplicityMode } ) => {
	const [ defaultTabItem, setDefaultTabItem ] = useState( 'general' );
	const [ trackingCode, setTrackingCode ] = useState( true );
	const [ imageSizesTab, setImageSizesTab ] = useState( true );

	let defaultTab = 'general';
	const navigate = useNavigate();

	useEffect( () => {
		if ( ! _.isEmpty( location.hash ) && defaultTab ) {
			defaultTab = location.hash.replace( '#/settings#', '' );
		}

		if ( _.isEmpty( defaultTab ) || '#/settings' === defaultTab ) {
			defaultTab = 'general';
		}

		setDefaultTabItem( defaultTab );
		document.getElementById( defaultTab ).classList.add( 'active' );
	} );

	const menuItems = tabs.filter( ( tab ) => {
		if ( 'settings' === tab.id ) {
			return tab;
		}

		return false;
	} );

	const handleActiveItem = ( event ) => {
		jQuery( event.target ).addClass( 'active-item' ).siblings().removeClass( 'active-item' );
	};

	const handleSection = ( event ) => {
		const clickedMenu = $( event.currentTarget ).data( 'value' );

		$( '.jx-cp-sub-menu-wrap a[href="' + clickedMenu + '"]' ).addClass( 'active' ).siblings().removeClass( 'active' );

		setTimeout(
			function() {
				const parentType = $( '#' + clickedMenu ).data( 'section' );

				$( 'div[class*="jx-cp-' + parentType + '-"]' ).removeClass( 'active' );
				$( '#' + clickedMenu ).addClass( 'active' );
			},
			10
		);
	};

	const removeUnusedTabs = ( action, type ) => {
		if ( action === 'add' ) {
			if ( type === 'tracking-codes' ) {
				setTrackingCode( true );
			}

			if ( type === 'image-sizes' ) {
				setImageSizesTab( true );
			}

			return true;
		}

		if ( type === 'image-sizes' ) {
			setImageSizesTab( false );
		}

		if ( type === 'tracking-codes' ) {
			setTrackingCode( false );
		}
		return false;
	};

	return (
		<div id="jx-cp-settings" className="jx-cp-tab-content-wrap">
			<Row className="jx-cp-settings border-bottom p-0 m-0">
				<Col sm={ 12 } className="header">
					<h3 className="jx-cp-settings-title">
						{ __( 'Settings', 'jupiterx-core' ) }
					</h3>
				</Col>
			</Row>
			<Tab.Container>
				<Row>
					<Col className="jupiterx-settings-list-wrap  px-0" sm={ 2 } >
						<ListGroup>
							{ menuItems.map( ( menu ) => (
								menu.subTabs ? (
									Object.values( menu.subTabs ).map( ( subTab ) => {
										if ( ! trackingCode && subTab.id === 'tracking-codes' ) {
											return '';
										}

										if ( ! imageSizesTab && subTab.id === 'image-sizes' ) {
											return '';
										}

										return (
											<Nav.Link
												className={ `jupiterx-settings-menu-item w-100 ${ subTab.id === 'post-types' && simplicityMode ? 'hide-post-type' : '' } ${ subTab.id === defaultTabItem ? 'active-item' : '' }` } // Add selected class by default
												key={ subTab.id }
												data-value={ subTab.id }
												data-parent={ `navigation-${ menu.id }` }
												onClick={ ( event ) => {
													handleActiveItem( event );
													handleSection( event );
													navigate( `#${ subTab.id }` );
												} }
												disabled={ ! isPremium && [ 'modules', 'tracking-codes', 'woocommerce' ].includes( subTab.id ) }
											>
												{ subTab.label }
											</Nav.Link>
										);
									} )
								) : ( '' )
							) ) }
						</ListGroup>
					</Col>
					<Col as={ Col } sm="10">
						<General
							handleSetSimplicityMode={ handleSetSimplicityMode }
							simplicityMode={ simplicityMode }
							removeUnusedTabs={ removeUnusedTabs }
						/>
					</Col>
				</Row>
			</Tab.Container>
		</div>
	);
};

export default Settings;
