import React, { useState, useContext, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { SettingsContext } from '../../store/settings';
import { __, sprintf } from '@wordpress/i18n';
import { Tab, Form, InputGroup, Button, Col, Row } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faInfoCircle } from '@fortawesome/free-solid-svg-icons';
import Alert from '../../components/alert';
import HelpLink from '../../components/help-link';
import { stripSlashes } from 'slashes';
import ImageSizes from './image-sizes';
import { isPremium, freshInstall, imageSizes } from '@jupiterx/control-panel';
import ElementorWidgets from '../../components/widgets';
import SimplicityModal from './simplicity-modal';
const $ = jQuery;

const donutPostTypes = [
	{ name: 'clients', label: __( 'Clients', 'jupiterx-core' ) },
	{ name: 'animated-columns', label: __( 'Animated Columns', 'jupiterx-core' ) },
	{ name: 'banner_builder', label: __( 'Banner Builder', 'jupiterx-core' ) },
	{ name: 'edge', label: __( 'Edge Slider', 'jupiterx-core' ) },
	{ name: 'employees', label: __( 'Employees', 'jupiterx-core' ) },
	{ name: 'faq', label: __( 'FAQ', 'jupiterx-core' ) },
	{ name: 'news', label: __( 'News', 'jupiterx-core' ) },
	{ name: 'pricing', label: __( 'Pricing Tables', 'jupiterx-core' ) },
	{ name: 'slideshow', label: __( 'FlexSlider', 'jupiterx-core' ) },
	{ name: 'tab_slider', label: __( 'Tab Slider', 'jupiterx-core' ) },
	{ name: 'testimonial', label: __( 'Testimonial', 'jupiterx-core' ) },
	{ name: 'photo_album', label: __( 'Photo Album', 'jupiterx-core' ) },
];

const General = ( { handleSetSimplicityMode, simplicityMode, removeUnusedTabs } ) => {
	const {
		nonce,
		options,
		postTypes,
		activePlugins,
		setOptions,
		tabs,
		isMultilingual,
	} = useContext( SettingsContext );

	const [ isRegenerating, setRegenerating ] = useState( false );
	const [ regenerateFeedback, setRegenerateFeedback ] = useState( '' );
	const [ isSaving, setSaving ] = useState( false );
	const [ saveFeedback, setSaveFeedback ] = useState( '' );
	const [ whiteLabelCpanelLogo, setWhiteLabelCpanelLogo ] = useState( options.white_label_cpanel_logo );
	const [ whiteLabelModeChanged, setWhiteLabelModeChanged ] = useState( false );
	const [ isWhiteLabel, setWhiteLabel ] = useState( getCheckboxValue( options.white_label ) );
	const [ mediaControls, setMediaControls ] = useState( getCheckboxValue( options.enable_media_controls ) );
	const [ autoPlay, setAutoplay ] = useState( getCheckboxValue( options.enable_autoplay_video ) );
	const [ trackingCode, setTrackingCode ] = useState( true );
	const [ imgaeSizes, setImageSizes ] = useState( true );
	const [ adobeFont, setAdobeFont ] = useState( true );
	const [ googleAnalytics, setGoogleAnalytics ] = useState( true );
	const [ showSimplicityModal, setShowSimplicityModal ] = useState( false );

	const { register, handleSubmit, setValue } = useForm( {
		defaultValues: {
			dev_mode: false,
			svg_support: false,
			white_label_cpanel_pages: [],
			white_label_cpanel_logo: whiteLabelCpanelLogo,
		},
	} );

	useEffect( () => {
		if ( ! simplicityMode ) {
			setTrackingCode( removeUnusedTabs( 'add', 'tracking-codes' ) );
			return;
		}

		if (
			! _.isEmpty( options.tracking_codes_after_body ) ||
			! _.isEmpty( options.tracking_codes_after_head ) ||
			! _.isEmpty( options.tracking_codes_before_body ) ||
			! _.isEmpty( options.tracking_codes_before_head )
		) {
			setTrackingCode( removeUnusedTabs( 'add', 'tracking-codes' ) );
			return;
		}

		setTrackingCode( removeUnusedTabs( 'remove', 'tracking-codes' ) );
	}, [ simplicityMode ] );

	useEffect( () => {
		if ( imageSizes.length > 0 ) {
			setImageSizes( removeUnusedTabs( 'add', 'image-sizes' ) );
			return;
		}

		if ( ! simplicityMode ) {
			setImageSizes( removeUnusedTabs( 'add', 'image-sizes' ) );
			return;
		}

		setImageSizes( removeUnusedTabs( 'remove', 'image-sizes' ) );
	}, [ simplicityMode ] );

	useEffect( () => {
		if ( ! _.isEmpty( options.adobe_fonts_project_id ) ) {
			return;
		}

		if ( ! simplicityMode ) {
			setAdobeFont( true );
			return;
		}

		setAdobeFont( false );
	}, [ simplicityMode ] );

	useEffect( () => {
		if ( ! _.isEmpty( options.google_analytics_id ) ) {
			return;
		}

		if ( ! simplicityMode ) {
			setGoogleAnalytics( true );
			return;
		}

		setGoogleAnalytics( false );
	}, [ simplicityMode ] );

	function onSubmit( fields ) {
		setSaving( true );

		// Prepare the data for database save.
		for ( const field in fields ) {
			if ( fields[ field ] === true ) {
				fields[ field ] = 1;
			}

			if ( fields[ field ] === false ) {
				fields[ field ] = 0;
			}

			if (
				typeof fields[ field ] === 'object' &&
				! fields[ field ].length
			) {
				fields[ field ] = [ '' ];
			}

			options[ field ] = fields[ field ];
		}

		setOptions( options );

		wp.ajax.post( {
			action: 'jupiterx_core_cp_settings',
			_wpnonce: nonce,
			type: 'save',
			fields,
		} ).done( ( data ) => {
			if ( whiteLabelModeChanged ) {
				window.location.reload();
				return;
			}

			setSaveFeedback( data );
			setTimeout( () => setSaveFeedback( '' ), 2000 );

			setSaving( false );
		} );
	}

	function onRegenerate() {
		setRegenerating( true );

		wp.ajax.post( {
			action: 'jupiterx_core_cp_settings',
			_wpnonce: nonce,
			type: 'flush',
		} ).done( ( data ) => {
			setRegenerateFeedback( data );
			setTimeout( () => setRegenerateFeedback( '' ), 2000 );

			setRegenerating( false );
		} );
	}

	function onUploadImage() {
		const frame = wp.media( {
			multiple: false,
		} );

		frame.on( 'select', function() {
			const attachment = frame.state().get( 'selection' ).first().toJSON();
			setWhiteLabelCpanelLogo( attachment.url );
			setValue( 'white_label_cpanel_logo', attachment.url );
			onWhiteLabelFieldChange();
		} );

		if ( frame ) {
			frame.open();
			return;
		}

		frame.open();
	}

	function onRemoveUploadImage() {
		setWhiteLabelCpanelLogo( '' );
		onWhiteLabelFieldChange();
	}

	function getCheckboxValue( option, defaultVal, settingName = '' ) {
		if ( typeof option !== 'undefined' ) {
			let newOption = option;

			if ( typeof option === 'boolean' && settingName === 'simplicity' ) {
				newOption = option ? 1 : 0;
			}

			return parseInt( newOption );
		}

		if ( typeof defaultVal !== 'undefined' ) {
			return defaultVal;
		}

		return 0;
	}

	const onWhiteLabelFieldChange = () => {
		setWhiteLabelModeChanged( true );
	};

	const submitButton = () => {
		return (
			<Form.Group as={ Col } sm="12" className="text-center">
				<Button
					style={ { maxWidth: 528 } }
					className="w-100"
					variant="primary"
					size="sm"
					type="submit"
					disabled={ isSaving } >
					{ isSaving ? __( 'Saving…', 'jupiterx-core' ) : __( 'Save settings', 'jupiterx-core' ) }
				</Button>
				<Form.Text muted>{ saveFeedback }</Form.Text>
			</Form.Group>
		);
	};

	const handleAutoplay = ( event ) => {
		setAutoplay( autoPlay ? 0 : 1 );

		if ( event.target.checked ) {
			const mute = document.getElementById( 'jupiterx-cp-settings-mute-video-sound' );

			mute.checked = true;
		}
	};

	const handleSimplicityModal = ( close, event ) => {
		if ( ! close && ! event ) {
			const simplicityBtn = $( '#jupiterx-cp-settings-disable-theme-default-settings' );

			simplicityBtn.removeAttr( 'checked' );
			simplicityBtn.trigger( 'change' );

			setShowSimplicityModal( false );
			handleSetSimplicityMode( false );

			return;
		}

		if ( close ) {
			setShowSimplicityModal( false );
			return;
		}

		setShowSimplicityModal( event.target.checked );
	};

	return (
		<div className="jx-cp-wrap-settings-contents">
			<Form onSubmit={ handleSubmit( onSubmit ) }>
				<Row>
					<Tab.Content id="general" className="jx-cp-settings-content-advancegenerald" key="general" data-section="settings">
						<Col sm="12">
							<Button
								variant="primary"
								size="sm"
								type="button"
								disabled={ isRegenerating }
								onClick={ ! isRegenerating ? onRegenerate : null } >
								{ isRegenerating ? __( 'Regenerating…', 'jupiterx-core' ) : __( 'Regenerate assets', 'jupiterx-core' ) }
							</Button>
							<small className="text-muted ms-2 text-sm">{ regenerateFeedback }</small>
							<Form.Text muted>
								{ __( 'Styles, Javascript and image files of Elementor and theme are saved in the uploads folder. Recreate those files, according to the most recent settings.', 'jupiterx-core' ) }
							</Form.Text>
						</Col>
						<Col sm="12"><hr /></Col>
						<Col sm="12">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-disable-theme-default-settings"
								name="disable_theme_default_settings"
								label={ __( 'Simplicity Mode', 'jupiterx-core' ) }
								defaultChecked={ getCheckboxValue( options.disable_theme_default_settings, freshInstall, 'simplicity' ) }
								{ ...register( 'disable_theme_default_settings', {
									onChange: ( event ) => {
										handleSetSimplicityMode( event.target.checked );
										handleSimplicityModal( false, event );
									},
								} ) }
							/>
							<Form.Text muted dangerouslySetInnerHTML={ {
								__html: sprintf(
									// translators: %s Simplicity learn more link
									__(
										'Simplicity Mode offers a simplified and intuitive website-building experience for customers who rely on Elementor and the Layout Builder. By enabling Simplicity Mode, you can declutter your workspace by removing complex customizer settings, excessive meta options, and unnecessary CSS and JS code. With this option, you\'ll experience improved website performance and faster loading times, enabling you to work efficiently and seamlessly. <a target="_blank" href="%s">Learn more</a>',
										'jupiterx-core'
									),
									'https://help.jupiterx.com/article/341-simplicity-mode',
								),
							} } />
						</Col>
						{ ! simplicityMode && <Col sm="12"><hr /></Col> }
						{ ! simplicityMode && <Col sm="6" className="px-1">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-dev-mode"
								name="dev_mode"
								label={ __( 'Development Mode', 'jupiterx-core' ) }
								defaultChecked={ getCheckboxValue( options.dev_mode ) }
								{ ...register( 'dev_mode' ) }
							/>
							<Form.Text muted>
								{ __( 'This option should be enabled while your website is in development.', 'jupiterx-core' ) }
							</Form.Text>
						</Col> }
						{ ! simplicityMode && <Col sm="6" className="px-1">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-cache-busting">
								<Form.Check.Input
									name="cache_busting"
									type="checkbox"
									defaultChecked={ getCheckboxValue( options.cache_busting, 1 ) }
									{ ...register( 'cache_busting' ) }
								/>
								<Form.Check.Label>
									{ __( 'Cache Busting', 'jupiterx-core' ) }
									<HelpLink href="https://help.jupiterx.com/article/438-working-with-general-settings-in-jupiter-x" title={ __( 'Handling Cache in Jupiter X', 'jupiterx-core' ) } />
								</Form.Check.Label>
							</Form.Check>
							<Form.Text muted>
								{ __( 'Enable cache busting technique.', 'jupiterx-core' ) }
							</Form.Text>
						</Col> }
						<Col sm="12"><hr /></Col>
						{ ! simplicityMode && <Col sm="6" className="px-1">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-svg-support"
								name="svg_support"
								label={ __( 'SVG Support', 'jupiterx-core' ) }
								defaultChecked={ getCheckboxValue( options.svg_support ) }
								{ ...register( 'svg_support' ) }
							/>
							<Form.Text muted>
								{ __( 'Enable this option to upload SVG to WordPress Media Library.', 'jupiterx-core' ) }
							</Form.Text>
						</Col> }
						<Col sm="6" className="px-1">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-smooth-scroll"
								name="smooth_scroll"
								label={ __( 'Smooth Scroll', 'jupiterx-core' ) }
								defaultChecked={ getCheckboxValue( options.smooth_scroll, 1 ) && isPremium }
								{ ...register( 'smooth_scroll' ) }
								disabled={ ! isPremium }
							/>
							<Form.Text muted>
								{ __( 'Enable this option to activate automatic smooth scroll on anchor links.', 'jupiterx-core' ) }
							</Form.Text>
						</Col>
						{ ! simplicityMode && <Col sm="12"><hr /></Col> }
						<Col sm="6" className="px-1">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-google-analytics-anonymization"
								name="google_analytics_anonymization"
								label={ __( 'Google IP Anonymization', 'jupiterx-core' ) }
								defaultChecked={ getCheckboxValue( options.google_analytics_anonymization, 1 ) }
								{ ...register( 'google_analytics_anonymization' ) }
							/>
							<Form.Text muted>
								{ __( 'Enable IP Anonymization for Google Analytics.', 'jupiterx-core' ) }
							</Form.Text>
						</Col>
						{ isMultilingual ? (
							<Col sm="6" className="px-1">
								<Form.Check
									type="switch"
									id="jupiterx-cp-settings-multilingual-customizer"
									name="multilingual_customizer"
									label={ __( 'Multilingual Customizer', 'jupiterx-core' ) }
									defaultChecked={ getCheckboxValue( options.multilingual_customizer, 0 ) }
									{ ...register( 'multilingual_customizer' ) }
								/>
								<Form.Text muted>
									{ __( 'Enable separate Customizer options for each language. It\'s recommended to disable this option for performance issues.', 'jupiterx-core' ) }
								</Form.Text>
							</Col>
						) : ( '' ) }
						<Col sm="12"><hr /></Col>
						<Col sm="6" className="px-1">
							<Form.Label className="d-flex align-items-center">
								{ __( 'Google & Adobe Fonts', 'jupiterx-core' ) }
							</Form.Label>
							<Form.Control
								size="sm"
								className="mw-100"
								name="font_loader_type"
								as="select"
								id="jupiterx-cp-settings-font-loader-type"
								defaultValue={ options.font_loader_type || 'javascript' }
								{ ...register( 'font_loader_type' ) }
								disabled={ ! isPremium }
							>
								<option value="javascript">{ __( 'JavaScript (Web Font Loader)', 'jupiterx-core' ) }</option>
								<option value="css">{ __( 'CSS', 'jupiterx-core' ) }</option>
								<option value="disable">{ __( 'Disable', 'jupiterx-core' ) }</option>
							</Form.Control>
							{ adobeFont && <Form.Text muted>
								{ __( 'By default, Jupiter X loads the Google and Adobe font via Javascript ( Web Font Loader ). If facing any issue, you can select CSS option', 'jupiterx-core' ) }
							</Form.Text> }
							{ ! adobeFont && <Form.Text muted>
								{ __( 'By default, Jupiter X loads the Google via Javascript ( Web Font Loader ). If facing any issue, you can select CSS option', 'jupiterx-core' ) }
							</Form.Text> }
						</Col>
						{ googleAnalytics && adobeFont && <Col sm="12"><hr /></Col> }
						{ googleAnalytics && <Col sm="6" className="px-1">
							<Form.Label className="d-flex align-items-center">
								{ __( 'Google Analytics ID', 'jupiterx-core' ) }
								<HelpLink href="https://help.jupiterx.com/article/438-working-with-general-settings-in-jupiter-x" title={ __( 'Adding Google Analytics code into Jupiter X', 'jupiterx-core' ) } />
							</Form.Label>
							<Form.Control
								size="sm"
								type="text"
								id="jupiterx-cp-settings-google-analytics-id"
								name="google_analytics_id"
								placeholder="UA-45******-*"
								defaultValue={ options.google_analytics_id }
								{ ...register( 'google_analytics_id' ) }
							/>
						</Col> }
						{ adobeFont && <Col sm="6" className="px-1">
							<Form.Label className="d-flex align-items-center">
								{ __( 'Adobe Fonts Project ID', 'jupiterx-core' ) }
								<HelpLink href="https://help.jupiterx.com/article/438-working-with-general-settings-in-jupiter-x" title={ __( 'Using Adobe fonts (formerly Typekit) in Jupiter X', 'jupiterx-core' ) } />
							</Form.Label>
							<Form.Control
								size="sm"
								type="text"
								id="jupiterx-cp-settings-adobe-project-id"
								name="adobe_fonts_project_id"
								placeholder="ezv****"
								defaultValue={ options.adobe_fonts_project_id }
								{ ...register( 'adobe_fonts_project_id' ) }
								disabled={ ! isPremium }
							/>
						</Col> }
						<Col sm="12"><hr /></Col>
						{ submitButton() }
						{ showSimplicityModal && <SimplicityModal handleSimplicityModal={ handleSimplicityModal } /> }
					</Tab.Content>
					{ trackingCode && <Tab.Content id="tracking-codes" className="jx-cp-settings-content-tracking-codes" key="tracking-codes" data-section="settings">
						<Col sm="6" className="px-3 mb-3">
							<Form.Label
								htmlFor="jupiterx-cp-settings-tracking-codes-after-head"
								dangerouslySetInnerHTML={ {
									__html: __( 'Tracking Codes After <code>&lt;head&gt;</code> Tag', 'jupiterx-core' ),
								} }
							/>
							<Form.Control
								size="sm"
								type="textarea"
								as="textarea"
								rows="7"
								id="jupiterx-cp-settings-tracking-codes-after-head"
								name="tracking_codes_after_head"
								defaultValue={ stripSlashes( options.tracking_codes_after_head || '' ) }
								{ ...register( 'tracking_codes_after_head' ) }
								disabled={ ! isPremium }
							/>
						</Col>
						<Col sm="6" className="px-3 mb-3">
							<Form.Label
								htmlFor="jupiterx-cp-settings-tracking-codes-before-head"
								dangerouslySetInnerHTML={ {
									__html: __( 'Tracking Codes Before <code>&lt;/head&gt;</code> Tag', 'jupiterx-core' ),
								} }
							/>
							<Form.Control
								size="sm"
								type="textarea"
								as="textarea"
								rows="7"
								id="jupiterx-cp-settings-tracking-codes-before-head"
								name="tracking_codes_before_head"
								defaultValue={ stripSlashes( options.tracking_codes_before_head || '' ) }
								{ ...register( 'tracking_codes_before_head' ) }
								disabled={ ! isPremium }
							/>
						</Col>
						<Col sm="6" className="px-3 mb-3">
							<Form.Label
								htmlFor="jupiterx-cp-settings-tracking-codes-after-body"
								dangerouslySetInnerHTML={ {
									__html: __( 'Tracking Codes After <code>&lt;body&gt;</code> Tag', 'jupiterx-core' ),
								} }
							/>
							<Form.Control
								size="sm"
								type="textarea"
								as="textarea"
								rows="7"
								id="jupiterx-cp-settings-tracking-codes-after-body"
								name="tracking_codes_after_body"
								defaultValue={ stripSlashes( options.tracking_codes_after_body || '' ) }
								{ ...register( 'tracking_codes_after_body' ) }
								disabled={ ! isPremium }
							/>
						</Col>
						<Col sm="6" className="px-3 mb-3">
							<Form.Label
								htmlFor="jupiterx-cp-settings-tracking-codes-before-body"
								dangerouslySetInnerHTML={ {
									__html: __( 'Tracking Codes Before <code>&lt;/body&gt;</code> Tag', 'jupiterx-core' ),
								} }
							/>
							<Form.Control
								size="sm"
								type="textarea"
								as="textarea"
								rows="7"
								id="jupiterx-cp-settings-tracking-codes-before-body"
								name="tracking_codes_before_body"
								defaultValue={ stripSlashes( options.tracking_codes_before_body || '' ) }
								{ ...register( 'tracking_codes_before_body' ) }
								disabled={ ! isPremium }
							/>
						</Col>
						<Col sm="12"><hr /></Col>
						{ isPremium && submitButton() }
					</Tab.Content> }
					<Tab.Content id="modules" className="jx-cp-settings-content-elementor" key="modules" data-section="settings">
						<h5 className="col-md-12">{ __( 'JupiterX Feature Management', 'jupiterx-core' ) }</h5>
						<Form.Text className="col-md-12 mb-3" muted>
							{ __( 'In this panel, select the JupiterX modules that best fit your website\'s needs. Disabling unnecessary features can improve your Elementor building experience and increase your page speed.', 'jupiterx-core' ) }
						</Form.Text>
						<Form.Group as={ Col } sm="12">
							<Form.Check
								className="d-none"
								type="checkbox"
								name="elements"
								value=" "
								{ ...register( 'elements' ) }
								disabled={ ! isPremium }
							/>
							<ElementorWidgets options={ options } register={ register } type={ 'settings' } />
						</Form.Group>
						<Col sm="12"><hr /></Col>
						{ isPremium && submitButton() }
					</Tab.Content>
					<Tab.Content id="post-types" className="jx-cp-settings-content-post-types" key="post-types" data-section="settings">
						<Form.Group as={ Col } sm="12">
							<Form.Label>
								{ __( 'Custom Post Types', 'jupiterx-core' ) }
							</Form.Label>
							<Form.Text className="mb-2" muted>
								{ __( 'Enable Jupiter X features (Customizer, Meta options, etc.) for these post types.', 'jupiterx-core' ) }
							</Form.Text>
							<div className="jx-cp-checkbox-wrap">
								<Form.Check
									className="d-none"
									type="checkbox"
									name="post_types"
									value=" "
									{ ...register( 'post_types' ) }
								/>
								{ postTypes.map( ( postType, index ) => (
									<Form.Check
										key={ index }
										type="checkbox"
										id={ `jupiterx-post-types-${ postType.name }` }
										name="post_types"
										value={ postType.name }
										label={ postType.label }
										defaultChecked={ Array.isArray( options.post_types ) && options.post_types.includes( postType.name ) }
										{ ...register( 'post_types' ) }
									/>
								) ) }
							</div>
							{ ! postTypes.length ? (
								<span>
									<FontAwesomeIcon className="me-1 mb-1" icon={ faInfoCircle } />
									{ __( 'No custom post type was found.', 'jupiterx-core' ) }
								</span>
							) : ( '' ) }
						</Form.Group>
						<Col sm="12"><hr /></Col>
						{ submitButton() }
					</Tab.Content>
					<Tab.Content id="white-label" className="jx-cp-settings-content-white-label" key="white-label" data-section="settings">
						<Form.Group as={ Col } sm="12">
							<Form.Check
								type="switch"
								id="jupiterx-cp-settings-white-label-mode"
								name="white_label"
								label={ <>
									{ __( 'White Label', 'jupiterx-core' ) }
									<HelpLink href="https://help.jupiterx.com/article/17-white-labeling-jupiterx" title={ __( 'Enabling white label in Jupiter X', 'jupiterx-core' ) } />
								</> }
								onClick={ () => setWhiteLabel( isWhiteLabel ? 0 : 1 ) }
								defaultChecked={ isWhiteLabel }
								{ ...register( 'white_label', {
									onChange: () => onWhiteLabelFieldChange(),
								} ) }
							/>
							<Form.Text muted>
								{ __( 'Enable the while label settings.', 'jupiterx-core' ) }
							</Form.Text>
						</Form.Group>
						{
							isWhiteLabel ? ( <Row className="w-100 ms-0 me-0">
								<Col sm="12"><hr /></Col>
								<Col sm="6" className="px-1 mb-3">
									<Form.Label>
										{ __( 'Control Panel Tabs', 'jupiterx-core' ) }
									</Form.Label>
									<Form.Text className="mb-2" muted>
										{ __( 'Enable or disable control panel tabs.', 'jupiterx-core' ) }
									</Form.Text>
									<div className="jx-cp-checkbox-wrap">
										{ Object.values( tabs ).map( ( tab, index ) => (
											tab.whiteLabel ? (
												<Form.Check
													key={ index }
													type="checkbox"
													id={ `jupiterx_white_label_cpanel_pages-${ tab.id }` }
													name="white_label_cpanel_pages"
													value={ tab.id }
													label={ tab.label }
													defaultChecked={ typeof options.white_label_cpanel_pages !== 'undefined' ? options.white_label_cpanel_pages.includes( tab.id ) : true }
													{ ...register( 'white_label_cpanel_pages', {
														onChange: () => onWhiteLabelFieldChange(),
													} ) }
												/>
											) : ( '' )
										) ) }
									</div>
								</Col>
								<Col sm="6" className="px-1 mb-3">
									<Form.Label>{ __( 'Control Panel Logo', 'jupiterx-core' ) }</Form.Label>
									<InputGroup>
										<Form.Control
											size="sm"
											type="text"
											id="jupiterx-cp-settings-white-label-cpanel-logo"
											name="white_label_cpanel_logo"
											placeholder={ __( 'Select an image', 'jupiterx-core' ) }
											{ ...register( 'white_label_cpanel_logo', {
												onChange: () => onWhiteLabelFieldChange(),
											} ) }
										/>
										<div>
											{ whiteLabelCpanelLogo ? (
												<Button
													size="sm"
													variant="danger"
													onClick={ onRemoveUploadImage }
												>
													{ __( 'Remove', 'jupiterx-core' ) }
												</Button>
											) : ( '' ) }
											<Button
												size="sm"
												variant="secondary"
												onClick={ onUploadImage }
											>
												{ __( 'Upload', 'jupiterx-core' ) }
											</Button>
										</div>
									</InputGroup>
									<Form.Text muted>
										{ __( 'Change control panel logo.', 'jupiterx-core' ) }
									</Form.Text>
								</Col>
								<Col sm="6" className="px-1 mb-3">
									<Form.Label>{ __( 'Text Occurrence', 'jupiterx-core' ) }</Form.Label>
									<Form.Control
										size="sm"
										type="text"
										id="jupiterx-cp-settings-white-label-text-occurence"
										name="white_label_text_occurence"
										defaultValue={ options.white_label_text_occurence }
										{ ...register( 'white_label_text_occurence', {
											onChange: () => onWhiteLabelFieldChange(),
										} ) }
									/>
									<Form.Text muted>
										{ __( 'Replace \'Jupiter X\' text to the entire admin pages.', 'jupiterx-core' ) }
									</Form.Text>
								</Col>
								<Col sm="6" className="px-1 mb-3">
									<Form.Label>{ __( 'Menu Icon', 'jupiterx-core' ) }</Form.Label>
									<Form.Control
										size="sm"
										type="text"
										id="jupiterx-cp-settings-white-label-menu-icon"
										name="white_label_menu_icon"
										placeholder="dashicons-admin-generic"
										defaultValue={ options.white_label_menu_icon }
										{ ...register( 'white_label_menu_icon', {
											onChange: () => onWhiteLabelFieldChange(),
										} ) }
									/>
									<Form.Text muted dangerouslySetInnerHTML={ {
										__html: sprintf(
											// translators: Icons url
											__(
												'<a href="%s" target="_blank">Choose</a> an icon and paste the class name.',
												'jupiterx-core'
											),
											'https://developer.wordpress.org/resource/dashicons',
										),
									} } />
								</Col>
								<Col sm="4" className="mb-3">
									<Form.Check
										type="switch"
										id="jupiterx-cp-settings-white-label-help-links"
										name="white_label_help_links"
										label={ __( 'Help Links', 'jupiterx-core' ) }
										defaultChecked={ getCheckboxValue( options.white_label_help_links, 1 ) }
										{ ...register( 'white_label_help_links', {
											onChange: () => onWhiteLabelFieldChange(),
										} ) }
									/>
									<Form.Text muted>
										{ __( 'Enable help links from Theme settings.', 'jupiterx-core' ) }
									</Form.Text>
								</Col>
								<Col sm="4" className="mb-3">
									<Form.Check
										type="switch"
										id="jupiterx-cp-settings-white-label-menu-help"
										name="white_label_menu_help"
										label={ __( 'Menu Help', 'jupiterx-core' ) }
										defaultChecked={ getCheckboxValue( options.white_label_menu_help, 1 ) }
										{ ...register( 'white_label_menu_help', {
											onChange: () => onWhiteLabelFieldChange(),
										} ) }
									/>
									<Form.Text muted>
										{ __( 'Enable help link from menu.', 'jupiterx-core' ) }
									</Form.Text>
								</Col>
								<Alert variant="info">
									<p className="mb-0" dangerouslySetInnerHTML={ {
										__html: sprintf(
											// translators: Child theme url
											__(
												'For further customization on theme name, slug, thumbnail and description that appears in Appearance &gt; Themes, please install the <a href="%s" target="_blank">Child theme</a>.',
												'jupiterx-core'
											),
											'https://themes.artbees.net/docs/installing-the-child-theme-for-jupiter-x/',
										),
									} } />
								</Alert>
							</Row> ) : ( '' )
						}
						<Col sm="12"><hr /></Col>
						{ isPremium && submitButton() }
					</Tab.Content>
					{ typeof activePlugins !== 'undefined' && activePlugins.includes( 'woocommerce/woocommerce.php' ) ? (
						<Tab.Content id="woocommerce" className="jx-cp-settings-content-woocommerce" key="woocommerce" data-section="settings">
							<h5 className="col-md-12">{ __( 'Product Media Settings', 'jupiterx-core' ) }</h5>
							<Form.Text
								className="col-md-12 mb-4"
								muted
								dangerouslySetInnerHTML={ {
									__html: __( 'JupiterX adds video capability to product gallery images. To learn more <a href="https://help.jupiterx.com/article/439-adding-a-video-to-the-product-gallery-in-jupiter-x" target="_blank">click here</a>.', 'jupiterx-core' ),
								} }
							>
							</Form.Text>
							<Form.Group as={ Col } sm="6">
								<Form.Check
									type="switch"
									id="jupiterx-cp-settings-enable-media-controls"
									name="enable_media_controls"
									label={ __( 'Show Media Controls', 'jupiterx-core' ) }
									onClick={ () => setMediaControls( mediaControls ? 0 : 1 ) }
									defaultChecked={ mediaControls }
									{ ...register( 'enable_media_controls' ) }
								/>
								<Form.Text muted>{ __( 'When enabled, the video control will be visible.' ) }</Form.Text>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Check
									type="switch"
									id="jupiterx-cp-settings-enable-quantity-field-switch"
									name="quantity_field_switch"
									label={ __( 'Quantity Field Switch', 'jupiterx-core' ) }
									defaultChecked={ _.isUndefined( options.quantity_field_switch ) ? '1' : ( options.quantity_field_switch === '1' ) }
									{ ...register( 'quantity_field_switch' ) }
								/>
								<Form.Text muted>{ __( 'When enabled, JupiterX will override the default WooCommerce quantity field switch styling.' ) }</Form.Text>
							</Form.Group>
							{ mediaControls ? <Form.Group as={ Col } sm="6">
								<Form.Check
									type="switch"
									id="jupiterx-cp-settings-enable-autoplay-video"
									name="enable_autoplay_video"
									label={ __( 'Autoplay Video', 'jupiterx-core' ) }
									defaultChecked={ getCheckboxValue( options.enable_autoplay_video ) }
									{ ...register( 'enable_autoplay_video', {
										onChange: () => handleAutoplay(),
									} ) }
								/>
								<Form.Text muted>{ __( 'The autoplay will mute the video once the page has loaded. Note: autoplay may not work on all devices and videos may cause usability issues for some visitors.' ) }</Form.Text>
							</Form.Group> : ( '' ) }
							<Col sm="12"><hr /></Col>
							{ mediaControls ? ( <>
								<Form.Group as={ Col } sm="6">
									<Form.Check
										type="switch"
										id="jupiterx-cp-settings-play-video-inline"
										name="play_video_inline"
										label={ __( 'Play Video Inline', 'jupiterx-core' ) }
										defaultChecked={ getCheckboxValue( options.play_video_inline ) }
										{ ...register( 'play_video_inline' ) }
									/>
									<Form.Text muted>{ __( 'On mobile browsers, play the video on the page instead of opening fullscreen.' ) }</Form.Text>
								</Form.Group>
								<Form.Group as={ Col } sm="6">
									<Form.Check
										type="switch"
										id="jupiterx-cp-settings-play-video-loop"
										name="play_video_loop"
										label={ __( 'Loop', 'jupiterx-core' ) }
										defaultChecked={ getCheckboxValue( options.play_video_loop ) }
										{ ...register( 'play_video_loop' ) }
									/>
									<Form.Text muted>{ __( 'The video will loop continuously.' ) }</Form.Text>
								</Form.Group>
								<Col sm="12"><hr /></Col>
								<Form.Group as={ Col } sm="6">
									<Form.Check
										type="switch"
										id="jupiterx-cp-settings-mute-video-sound"
										name="mute_video_sound"
										label={ __( 'Mute Video Sound', 'jupiterx-core' ) }
										defaultChecked={ getCheckboxValue( options.mute_video_sound ) || autoPlay }
										{ ...register( 'mute_video_sound' ) }
										disabled={ autoPlay }
									/>
									<Form.Text muted>{ __( 'Video sound will be muted.' ) }</Form.Text>
								</Form.Group>
							</> ) : ( '' ) }
							{ submitButton() }
						</Tab.Content>
					) : ( '' ) }
					{ typeof activePlugins !== 'undefined' && activePlugins.includes( 'jupiter-donut/jupiter-donut.php' ) ? (
						<Tab.Content id="third-party-integration" className="jx-cp-settings-content-third-party-integration" key="third-party-integration" data-section="settings">
							<h5 className="col-md-12 mb-3">Donut Plugin</h5>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Theme Accent Color', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-skin-color"
									name="donut_skin_color"
									placeholder="Enter color hex codes (#f97352)"
									defaultValue={ options.donut_skin_color }
									{ ...register( 'donut_skin_color' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Twitter Consumer Key', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-twitter-consumer-key"
									name="donut_twitter_consumer_key"
									defaultValue={ options.donut_twitter_consumer_key }
									{ ...register( 'donut_twitter_consumer_key' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Twitter Consumer Secret', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-twitter-consumer-secret"
									name="donut_twitter_consumer_secret"
									defaultValue={ options.donut_twitter_consumer_secret }
									{ ...register( 'donut_twitter_consumer_secret' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Twitter Access Token', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-twitter-access-token"
									name="donut_twitter_access_token"
									defaultValue={ options.donut_twitter_access_token }
									{ ...register( 'donut_twitter_access_token' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Twitter Access Token Secret', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-twitter-access-token-secret"
									name="donut_twitter_access_token_secret"
									defaultValue={ options.donut_twitter_access_token_secret }
									{ ...register( 'donut_twitter_access_token_secret' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'MailChimp API Key', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-mailchimp-api-key"
									name="donut_mailchimp_api_key"
									defaultValue={ options.donut_mailchimp_api_key }
									{ ...register( 'donut_mailchimp_api_key' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Mailchimp List ID', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-mailchimp-list-id"
									name="donut_mailchimp_list_id"
									defaultValue={ options.donut_mailchimp_list_id }
									{ ...register( 'donut_mailchimp_list_id' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>{ __( 'Google Maps API Key', 'jupiterx-core' ) }</Form.Label>
								<Form.Control
									size="sm"
									type="text"
									id="jupiterx-cp-settings-donut-google-maps-api-key"
									name="donut_google_maps_api_key"
									defaultValue={ options.donut_google_maps_api_key }
									{ ...register( 'donut_google_maps_api_key' ) }
								/>
							</Form.Group>
							<Form.Group as={ Col } sm="6">
								<Form.Label>
									{ __( 'Custom Post Types', 'jupiterx-core' ) }
								</Form.Label>
								<div className="jx-cp-checkbox-wrap">
									<Form.Check
										className="d-none"
										type="checkbox"
										name="donut_post_types"
										value=" "
										{ ...register( 'donut_post_types' ) }
									/>
									{ donutPostTypes.map( ( postType, index ) => (
										<Form.Check
											key={ index }
											type="checkbox"
											id={ `jupiterx-donut-post-types-${ postType.name }` }
											name="donut_post_types"
											value={ postType.name }
											label={ postType.label }
											defaultChecked={ typeof options.donut_post_types !== 'undefined' ? options.donut_post_types.includes( postType.name ) : true }
											{ ...register( 'donut_post_types' ) }
										/>
									) ) }
								</div>
							</Form.Group>
							<Col sm="12"><hr /></Col>
							{ submitButton() }
						</Tab.Content>
					) : ( '' ) }
				</Row>
			</Form>
			{ imgaeSizes && <Tab.Content id="image-sizes" className="jx-cp-settings-content-image-sizes" key="image-sizes" data-section="settings">
				<ImageSizes />
			</Tab.Content> }
		</div>
	);
};

export default General;
