import React, { useEffect, useState, Fragment } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __, sprintf } from '@wordpress/i18n';
import Item from './item';
import Dialog from './../../../components/dialog';
import { faExclamationTriangle } from '@fortawesome/free-solid-svg-icons';
import useInfiniteScroll from 'react-infinite-scroll-hook';
import ImportForm from './import-form';

const ContentView = ( props ) => {
	const [ posts, setPosts ] = useState( [] );
	const [ dialog, setDialog ] = useState( [ false, '', '' ] ); // show dialog : stat, post_title, post_id
	const [ deleteDialog, setDeleteDialog ] = useState( [ false, '', '' ] ); // state, title, id
	const [ title, setTitle ] = useState( '' );
	const [ content, setContent ] = useState( '' );
	const [ hiddenPosts, setHiddenPosts ] = useState( [] );
	const [ deletingAjax, setDeletingAjax ] = useState( false );
	const $ = jQuery;
	const mediumHeight = [ 'header', 'footer', 'page-title-bar' ];
	const itemsContainer = [ 'header', 'footer', 'page-title-bar' ].includes( props.type ) ? 'items-one-column' : '';
	const [ allConditions, setAllConditions ] = useState( props.allConditions );

	useEffect( () => {
		if ( props.posts ) {
			const postsList = orderPosts( props.posts );
			setPosts( postsList );
		}

		if ( props.content ) {
			setContent( props.content );
		}
	}, [ props.posts, props.content ] );

	/**
	 * Order posts and move activated templated to the top of the list.
	 *
	 * @param {Object} postsList list of posts.
	 * @since 3.7.0
	 */
	const orderPosts = ( postsList ) => {
		postsList.sort( ( a, b ) => {
			return b.priority - a.priority;
		} );

		return postsList;
	};

	const renameTitle = () => {
		const PostTitle = document.getElementById( 'dialog_post_title' ).value;
		const PostId = dialog[ 2 ];

		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'rename_post',
			id: PostId,
			title: PostTitle,
			nonce,
		} )
			.done( () => {
				setDialog( [ false, '', '' ] );
				document.getElementsByClassName( 'title-' + PostId )[ 0 ].innerText = PostTitle;
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const removePost = ( PostID ) => {
		setDeletingAjax( true );

		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'remove_post',
			id: PostID,
			nonce,
		} )
			.done( () => {
				setDeletingAjax( false );
				setDeleteDialog( [ false, '', '' ] );

				setAllConditions( allConditions.filter( ( condition ) => condition.ID === PostID ) );

				$( `.post-${ PostID }` ).slideUp( 1000 ).promise().then( function() {
					setTimeout( () => {
						if ( posts.length > 0 ) {
							posts.forEach( ( post ) => {
								if ( post.ID === PostID ) {
									const hide = hiddenPosts;
									hide.push( PostID );
									setHiddenPosts( hide );
								}
							} );
						}
					}, 2000 );
				} );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const infiniteRef = useInfiniteScroll( {
		onLoadMore: props.fetchPosts,
		loading: props.loading,
		rootMargin: '100px',
		hasNextPage: props.hasNextPage,
	} );

	const importTemplate = () => {
		setContent( 'import' );
	};

	const afterImportTemplateView = ( type ) => {
		setContent( type );
		props.afterImportTemplate( type );
	};

	const resortAfterSaveConditions = ( postId ) => {
		const element = document.querySelector( '.post-' + postId );

		if ( ! element ) {
			return;
		}

		element.classList.remove( 'priority-5', 'priority-10' );
		element.classList.add( 'priority-15' );

		element.scrollIntoView( {
			behavior: 'smooth',
			block: 'start',
			inline: 'nearest',
		} );
	};

	return (
		<>
			{
				'import' === content &&
				<ImportForm
					type={ props.type }
					setContent={ setContent }
					afterImportTemplateView={ afterImportTemplateView }
					fetchPosts={ props.fetchPosts }
				/>
			}
			{
				'posts' === content &&
				<>
					<div className={ `items-container ${ itemsContainer }` }>
						{
							'posts' === props.content && posts.length > 0 &&
							posts.map( ( post, i ) => (
								<Fragment key={ i }>
									{
										! hiddenPosts.includes( post.ID ) &&
										<Item
											key={ `post-${ post.ID }` }
											post={ post.ID }
											title={ post.post_title }
											author={ post.author_name }
											date={ post.custom_date }
											editUrl={ post.editor_url }
											previewUrl={ post.preview_url }
											conditionsString={ post.conditions_string }
											import={ () => importTemplate() }
											section={ props.type }
											sectionTitle={ props.title }
											allConditions={ allConditions }
											expandAllConditions={ ( singlePostArray ) => props.gatherAllConditions( singlePostArray ) }
											simplicityMode={ props.simplicityMode }
											className={ `priority-${ post.priority }  post-${ post.ID } ${ mediumHeight.includes( props.type ) ? ' medium-height' : ' large-height' } ` }
											remove={ () => {
												setDeleteDialog( [ true, post.post_title, post.ID ] );
											} }
											editTitle={ () => {
												setDialog( [ true, post.post_title, post.ID ] );
												setTitle( document.getElementsByClassName( 'title-' + post.ID )[ 0 ].innerText );
											} }
											resort={ ( postId ) => resortAfterSaveConditions( postId ) }
										/>
									}
								</Fragment>
							) )
						}
						{ posts.length > 0 && props.hasNextPage && (
							<div ref={ infiniteRef } style={ { height: '1px' } } />
						) }
					</div>
					{
						dialog[ 0 ] &&
						<Dialog
							title={ __( 'Edit Template Name', 'jupiterx-core' ) }
							className="layout-builder-dialog-edit"
							show
							okText={ __( 'Update', 'jupiterx-core' ) }
							onOk={ renameTitle }
							closeButton={ true }
							onHide={ () => setDialog( false ) }
							showCancel={ true }
							onCancel={ () => setDialog( false ) }
							cancelText={ __( 'Discard', 'jupiterx-core' ) }
						>
							<label htmlFor="dialog_post_title">{ __( 'Title', 'jupiterx-core' ) }</label>
							<input
								id="dialog_post_title"
								defaultValue={ title }
								className="w-100"
								type="text"
							/>
						</Dialog>
					}

					{
						deleteDialog[ 0 ] &&
						<Dialog
							title={ __( 'Remove item', 'jupiterx-core' ) }
							variant="danger"
							icon={ faExclamationTriangle }
							iconClassName="text-danger rm-icon"
							show
							className="layout-template-delete-dialog"
							okText={ `${ __( 'Remove', 'jupiterx-core' ) }  ` }
							onOk={ () => removePost( deleteDialog[ 2 ] ) }
							onHide={ () => setDeleteDialog( [ false, '', '' ] ) }
							showCancel={ true }
							cancelText={ __( 'Discard', 'jupiterx-core' ) }
							onCancel={ () => setDeleteDialog( [ false, '', '' ] ) }
							okBtnAjax={ deletingAjax }
						>
							<span className="desc-text">
								{
									sprintf(
										// translators: %s Title
										__( 'Are you sure you want to remove this item %s ?', 'jupiterx-core' ),
										deleteDialog[ 1 ],
									)
								}
							</span>

						</Dialog>
					}
				</>
			}
		</>
	);
};

export default ContentView;
