import React, { useState, useCallback } from 'react';
import { InputGroup, FormControl, Button } from 'react-bootstrap';
import { searchFilters } from '@jupiterx/control-panel';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSearch, faSlidersH } from '@fortawesome/free-solid-svg-icons';
import { __, sprintf } from '@wordpress/i18n';
import { useMediaQuery } from 'react-responsive';
import { debounce } from 'lodash';
import classnames from 'classnames';
import CustomSelect from './custom-select';

const SELECT_FIELDS = [
	[ 'category', __( 'Category', 'jupiterx-core' ) ],
	[ 'style', __( 'Style', 'jupiterx-core' ) ],
	[ 'header_type', __( 'Header Type', 'jupiterx-core' ) ],
	[ 'menu_type', __( 'Menu Type', 'jupiterx-core' ) ],
	[ 'components', __( 'Components', 'jupiterx-core' ) ],
	[ 'content_type', __( 'Content Type', 'jupiterx-core' ) ],
];

const getSelectValue = ( value ) => {
	return typeof value === 'string' && value
		? value.split( ',' )
		: [];
};

const SearchFilters = ( { filters = {}, foundPosts, onChange } ) => {
	// For mobile filters.
	const [ isActive, setIsActive ] = useState( false );

	const handleChange = useCallback( debounce( ( key, value ) => {
		if ( Array.isArray( value ) ) {
			value = value.join( ',' );
		}

		onChange( {
			...filters,
			[ `${ key }` ]: value,
		} );
	}, 350 ), [ filters ] );

	// For mobile clear.
	const handleClear = () => {
		// Search term is not included from clear.
		onChange( {
			s: filters.s,
		} );
	};

	const isTabletOrMobile = useMediaQuery( {
		query: '(max-width: 782px)',
	} );

	const renderSearch = (
		<div className="jx-cp-search-filter jx-cp-search-filter-s">
			<InputGroup>
				<FormControl
					id="s"
					name="s"
					placeholder={ __( 'e.g. Portfolio, Real estate, Minimal, Dark, ...', 'jupiterx-core' ) }
					onChange={ ( event ) => handleChange( 's', event.target.value ) }
				/>
				<InputGroup.Text as="label" htmlFor="s">
					<FontAwesomeIcon icon={ faSearch } />
				</InputGroup.Text>
			</InputGroup>
		</div>
	);

	const renderSelects = SELECT_FIELDS.map( ( [ name, title ] ) => (
		<div key={ name } className={ `jx-cp-search-filter jx-cp-search-filter-${ name.replace( '_', '-' ) }` }>
			<CustomSelect
				title={ title }
				options={ searchFilters[ name ] }
				onChange={ ( value ) => handleChange( name, value ) }
				name={ name }
				value={ getSelectValue( filters[ name ] ) }
			/>
		</div>
	) );

	const filtersCount = Object.keys( filters ).length;

	return (
		<div className="jx-cp-search-filters">
			{ ! isTabletOrMobile ? ( <>
				{ renderSearch }
				{ renderSelects }
			</> ) : ( <>
				{ renderSearch }
				<div className="d-flex align-items-center">
					<Button
						className="jx-cp-search-filters-toggle"
						type="button"
						variant="outline-secondary"
						size="sm"
						onClick={ () => setIsActive( true ) }
					>
						<FontAwesomeIcon icon={ faSlidersH } />
						{ sprintf(
							// translators: 1: Template filters count
							__( 'Filters (%d)', 'jupiterx-core' ),
							filters.s ? filtersCount - 1 : filtersCount
						) }
					</Button>
					<span>
						{ sprintf(
							// translators: 1: Templates count
							__( '%d template was found.', 'jupiterx-core' ),
							foundPosts
						) }
					</span>
				</div>
				<div className={ classnames( {
					'jx-cp-search-filters-overlay': true,
					active: isActive,
				} ) }>
					<div className="jx-cp-search-filters-overlay-header">
						<strong>{ __( 'Filters & Refine', 'jupiterx-core' ) }</strong>
						<Button
							type="button"
							variant="secondary"
							size="sm"
							onClick={ handleClear }
						>
							{ __( 'Clear Filters', 'jupiterx-core' ) }
						</Button>
						<Button
							type="button"
							variant="primary"
							size="sm"
							onClick={ () => setIsActive( false ) }
						>
							{ __( 'Done', 'jupiterx-core' ) }
						</Button>
					</div>
					{ renderSelects }
				</div>
			</> ) }
		</div>
	);
};

export default SearchFilters;
