import React, { useState, useEffect } from 'react';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import { Form, Col, Button, Row } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faRedoAlt } from '@fortawesome/free-solid-svg-icons';
import Spinner from '../../../components/spinner';
import VersionControlField from './field';
import Alert from '../../../components/alert';
import HelpLink from '../../../components/help-link';

const VersionControl = () => {
	const [ loading, setLoading ] = useState( true );
	const [ products, setProducts ] = useState( [] );
	const [ refreshing, setRefreshing ] = useState( false );
	const [ error, setError ] = useState( false );

	useEffect( () => {
		fetchProducts( false );
	}, [] );

	const fetchProducts = ( force ) => {
		wp.ajax.post( {
			action: 'jupiterx_cp_get_products',
			nonce,
			force,
		} )
			.done( ( data ) => {
				data.map( ( item ) => (
					setProducts( ( product ) => [ ...product, item ] )
				) );

				setLoading( false );
				setRefreshing( false );
				setError( false );
			} )
			.fail( ( data ) => {
				setLoading( false );
				setRefreshing( false );
				setError( true );

				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const handleRefresh = () => {
		setError( false );
		setRefreshing( true );
		setProducts( [] );
		setLoading( true );
		fetchProducts( true );
	};

	return (
		<Form className="jx-cp-version-control">
			<Row>
				<Form.Group as={ Col } sm="12" className="jx-cp-version-control-content">
					<Form.Label>
						{ __( 'Rollback versions', 'jupiterx-core' ) }
						<HelpLink href="https://help.jupiterx.com/article/35-how-to-rollback-to-previous-versions-for-jupiterx-and-plugins" title={ __( 'Controlling theme and plugins version in Jupiter X', 'jupiterx-core' ) } />
					</Form.Label>
					<Button
						className="ms-2 float-end"
						variant="primary"
						size="sm"
						disabled={ refreshing }
						onClick={ handleRefresh }
					>
						<FontAwesomeIcon
							icon={ faRedoAlt }
							spin={ refreshing }
						/>
						{ ' ' }
						<span>{ __( 'Refresh data', 'jupiterx-core' ) }</span>
					</Button>
					<Form.Text className="mb-4" muted>
						{ __( 'Experiencing an issue with current version of Jupiter X or its bundled plugins? Rollback to previous versions.', 'jupiterx-core' ) }
					</Form.Text>
					{ loading && <Spinner /> }
					{ products.map( ( product, index ) => (
						<VersionControlField key={ index } product={ product } />
					) ) }
					{ error ? (
						<Alert variant="danger" className="mb-0">
							{ __( 'An error occurred while fetching data. Please try later again. If the issue persists, please contact support.', 'jupiterx-core' ) }
						</Alert>
					) : ( '' ) }
				</Form.Group>
			</Row>
		</Form>
	);
};

export default VersionControl;
