import React, { useState, useEffect, Fragment, useRef } from 'react';
import { Form, Spinner, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTrashAlt } from '@fortawesome/free-solid-svg-icons';
import { __ } from '@wordpress/i18n';
import Loading from '../spinner/';
import { nonce, wpmlActive } from '@jupiterx/control-panel';
import CustomAsyncSelect from './async-select';
import FirstAsyncSelect from './first-parameter-async-select';
import './style.scss';
const $ = jQuery;

const App = ( props ) => {
	const [ inputFields, setInputFields ] = useState( [] );
	const [ singulars, setSingulars ] = useState( [] );
	const [ archives, setArchives ] = useState( [] );
	const [ woocommerce, setWoocommerce ] = useState( [] );
	const [ users, setUsers ] = useState( [] );
	const [ wpml, setWpml ] = useState( [] );
	const [ saveProcess, setSaveProcess ] = useState( false );
	const [ load, setLoad ] = useState( true );
	const [ excludeArray, setExcludeArray ] = useState( [ 'all', 'front_page', 'error_404', 'date', 'search', 'woo_search', 'all_product_archive', 'shop_archive', 'shop_manager' ] );
	const containerRef = useRef( null );
	const [ scrollTop, setScrollTop ] = useState( 0 );
	const [ conflictRow, setConflictRow ] = useState( -1 );
	const [ conflictTemplate, setConflictTemplate ] = useState( '' );

	useEffect( () => {
		if ( containerRef.current ) {
			containerRef.current.scrollTop = scrollTop;
		}
	}, [ inputFields, conflictRow ] );

	// Run when initial loading. we get some parameters just once.
	useEffect( () => {
		setLoad( true );
		get3rdParameterDefaultOptions();
		get4thParameterDefaultOptions();

		const exceptions = [ 'header', 'footer', 'page-title-bar' ];

		loadPostConditions();

		// Create base types array and conditionally add WPML
		const baseTypes = [ 'singular', 'archive', 'woocommerce', 'users' ];
		const wpmlTypes = wpmlActive ? [ ...baseTypes, 'wpml' ] : baseTypes;

		if ( 'custom-snippet' === props.place ) {
			getSingulars( wpmlTypes );
			return;
		}

		if ( 'archive' === props.type ) {
			const excludes = excludeArray;
			excludes.push( 'single_post' );
			setExcludeArray( excludes );
		}

		if ( exceptions.includes( props.type ) ) {
			getSingulars( wpmlTypes );
			return;
		}

		if ( 'single' === props.type ) {
			const singleTypes = [ 'singular', 'woocommerce', 'users' ];
			const singleWpmlTypes = wpmlActive ? [ ...singleTypes, 'wpml' ] : singleTypes;
			getSingulars( singleWpmlTypes );
			return;
		}

		if ( 'archive' === props.type ) {
			const archiveTypes = [ 'archive', 'users' ];
			const archiveWpmlTypes = wpmlActive ? [ ...archiveTypes, 'wpml' ] : archiveTypes;
			getSingulars( archiveWpmlTypes );
			return;
		}

		if ( 'product' === props.type || 'product-archive' === props.type ) {
			const productTypes = [ 'woocommerce', 'users' ];
			const productWpmlTypes = wpmlActive ? [ ...productTypes, 'wpml' ] : productTypes;
			getSingulars( productWpmlTypes );
		}
	}, [] );

	const getSingulars = ( types = [] ) => {
		let context = '';

		if ( 'layout-builder' === props.place ) {
			context = props.defaultOptions.default3rdParameter;
		}
		let activeSection = props.type;

		if ( 'custom-snippet' === props.place ) {
			activeSection = 'custom-snippet';
		}

		// if already loaded in context, we do not get them through ajax.
		if ( 'layout-builder' === props.place ) {
			const newTypes = [];

			for ( const type in types ) {
				const realType = types[ type ];

				if ( ! _.isEmpty( context[ activeSection ][ realType ] ) ) {
					if ( 'singular' === realType ) {
						setSingulars( context[ activeSection ][ realType ] );
					}
					if ( 'archive' === realType ) {
						setArchives( context[ activeSection ][ realType ] );
					}
					if ( 'woocommerce' === realType ) {
						setWoocommerce( context[ activeSection ][ realType ] );
					}
					if ( 'users' === realType ) {
						setUsers( context[ activeSection ][ realType ] );
					}
					if ( 'wpml' === realType ) {
						setWpml( context[ activeSection ][ realType ] );
					}
				} else {
					newTypes.push( realType );
				}
			}

			if ( _.isEmpty( newTypes ) ) {
				setTimeout( () => {
					setLoad( false );
				}, 1500 );

				return;
			}
		}

		wp.ajax.post( {
			action: 'jupiterx_conditional_manager',
			sub_action: 'get_list_singular',
			list: types,
			section: activeSection,
			nonce,
		} )
			.done( ( data ) => {
				for ( const key in data ) {
					if ( 'singular' === data[ key ].type ) {
						setSingulars( data[ key ].list );
					}
					if ( 'archive' === data[ key ].type ) {
						setArchives( data[ key ].list );
					}
					if ( 'woocommerce' === data[ key ].type ) {
						setWoocommerce( data[ key ].list );
					}
					if ( 'users' === data[ key ].type ) {
						setUsers( data[ key ].list );
					}
					if ( 'wpml' === data[ key ].type ) {
						setWpml( data[ key ].list );
					}

					get3rdParameterDefaultOptions( data[ key ].type, data[ key ].list );
				}

				setLoad( false );
			} )
			.fail( () => {
				setSingulars( [] );
			} );
	};

	const get3rdParameterDefaultOptions = ( type, value ) => {
		const context = props.defaultOptions;

		if ( _.isEmpty( context ) ) {
			return;
		}

		context.initDefault3rd( props.type, type, value );
	};

	const get4thParameterDefaultOptions = () => {
		const context = props.defaultOptions,
			global = [ 'header', 'footer', 'page-title-bar' ],
			postTypes = [];

		if ( _.isEmpty( context ) ) {
			return;
		}

		let toGet = [];

		if ( global.includes( props.type ) ) {
			toGet = [ 'post', 'page', 'product' ];
		}

		if ( 'single' === props.type ) {
			toGet = [ 'post', 'page', 'portfolio' ];
		}

		if ( 'product' === props.type ) {
			toGet = [ 'product' ];
		}

		/**
		 * WPML compatibility.
		 *
		 * @since 4.9.2
		 */
		if ( wpmlActive ) {
			toGet.push( 'wpml_languages' );
		}

		for ( const i in toGet ) {
			const currentValue = toGet[ i ];

			if ( ! context.defaults4thParameter.hasOwnProperty( currentValue ) ) {
				postTypes.push( currentValue );
			}
		}

		if ( _.isEmpty( postTypes ) ) {
			return;
		}

		context.initDefault4th( postTypes );
	};

	// Load post conditions from database.
	const loadPostConditions = () => {
		wp.ajax.post( {
			action: 'jupiterx_conditional_manager',
			sub_action: 'load_post_conditions',
			post: props.post,
			nonce,
		} )
			.done( ( data ) => {
				setInputFields( data );
				if ( 'layout-builder' === props.place ) {
					setTimeout( () => {
						props.setSize();
					}, 0 );
				}
			} )
			.fail( () => {
				setInputFields( [] );
			} );
	};

	/**
	 * Each condition row or array includes 4 items. 4th item is an array itself, since it's an asyncselect( both label and value get saved ).
	 */
	const handleAddFields = () => {
		if ( containerRef.current ) {
			setScrollTop( containerRef.current.scrollTop );
		}

		const values = [ ...inputFields ];
		values.push( {
			conditionA: 'include',
			conditionB: '',
			conditionC: '',
			conditionD: '',
		} );

		setInputFields( values );

		if ( props.fields ) {
			props.fields( values );
		}

		if ( 'layout-builder' === props.place ) {
			const wrapper = document.getElementById( 'jupiterx-condition-form-inner-wrapper' );
			wrapper.scrollTop = wrapper.scrollHeight;
		}
	};

	const handleRemoveFields = ( index ) => {
		$( `.jx-row-condition-${ index }` ).hide( 'slow' ).promise().done( function() {
			const values = [ ...inputFields ];
			values.splice( index, 1 );
			setInputFields( values );
			if ( props.fields ) {
				props.fields( values );
			}
		} );
	};

	/*
	* Create a customized array from the conditions array to be ready for database.
	 * We run this on every change event of conditions.
	 *
	 * @param {number} index Condition row or array index.
	 * @param {Object} selectedOption The selected input or select.
	 */
	const handleInputChange = ( index, selectedOption ) => {
		// Prevents scroll top on changing values.
		if ( containerRef.current ) {
			setScrollTop( containerRef.current.scrollTop );
		}

		const values = [ ...inputFields ];
		let conflictHelper = false;

		if ( _.isNull( selectedOption ) ) {
			return;
		}

		// Setup values.
		if ( selectedOption.value && 'conditionA' !== selectedOption.name ) { // Async select. condition D.
			values[ index ].conditionD = [ selectedOption.value, selectedOption.label ];
			conflictHelper = true;
		} else if ( selectedOption.name === 'conditionA' ) { // simple react-select . condition A
			values[ index ].conditionA = selectedOption.value;
		} else if ( selectedOption.target.name === 'conditionB' ) { // Condition B.
			values[ index ].conditionB = selectedOption.target.value;
		} else if ( selectedOption.target.name === 'conditionC' ) { // Condition C.
			values[ index ].conditionC = selectedOption.target.value;
			values[ index ].conditionD = '';
			$( '.jx-row-condition-' + index ).find( '#conditionD' ).find( '*[class*=singleValue]:visible' ).text( __( 'Search...', 'jupiterx-core' ) );
		}

		// Set all for conditionD by default.
		if ( _.isEmpty( values[ index ].conditionD ) && ! _.isEmpty( values[ index ].conditionC ) ) {
			values[ index ].conditionD = [ 'all', __( 'All', 'jupiterx-core' ) ];
		}

		// Make conditionC and conditionD empty in case ConditionB has following values.
		if ( 'entire' === values[ index ].conditionB || 'maintenance' === values[ index ].conditionB ) {
			values[ index ].conditionC = '';
			values[ index ].conditionD = '';
		}

		setInputFields( values );
		if ( props.fields ) {
			props.fields( values );
		}

		// Check for conflicts in layout builder.
		if ( 'layout-builder' === props.place ) {
			if ( conflictHelper && 'all' !== values[ index ].conditionD[ 0 ] ) {
				values[ index ].conditionD[ 0 ] = values[ index ].conditionD[ 0 ].toString();
			}

			checkForConflicts( values[ index ], index );
		}
	};

	/*
	 * Check if last created condition with user in the current view has conflict with other templates conditions.
	 * We already have loaded all other templates conditions through Props.
	 *
	 * @param {Array} arrayToCheck Last created condition by user in the current view.
	 * @param {number} index condition row index.
	 */
	const checkForConflicts = ( arrayToCheck, index ) => {
		const allConditions = props.allConditions;
		let conflict = false;

		_.each( allConditions, ( object ) => {
			// Do not check current post conditions.
			if ( parseInt( object.id ) === parseInt( props.post ) || _.isUndefined( object.id ) ) {
				return;
			}

			const conditions = object.conditions;

			if ( ! Array.isArray( conditions ) ) {
				return;
			}

			conditions.forEach( ( array ) => {
				if ( _.isEqual( arrayToCheck, array ) ) {
					setConflictTemplate( object.title );
					setConflictRow( index );
					conflict = true;
				}
			} );
		} );

		if ( true === conflict ) {
			return;
		}

		setConflictRow( -1 );
		setConflictTemplate( '' );
	};

	const handleSubmit = ( e ) => {
		e.preventDefault();
		setSaveProcess( true );
		savePostConditions( props.post, inputFields );
	};

	const savePostConditions = ( id, ConditionArray ) => {
		wp.ajax.post( {
			action: 'jupiterx_conditional_manager',
			sub_action: 'save_post_conditions',
			post: id,
			conditions: ConditionArray,
			nonce,
		} )
			.done( ( data ) => {
				showResult( data );
				closeAfterSave();
			} )
			.fail( ( data ) => {
				showResult( data );
				closeAfterSave();
			} );
	};

	const closeAfterSave = () => {
		if ( 'layout-builder' === props.place ) {
			props.extra();
		}
	};

	const OptionsHtml = ( { type } ) => {
		return (
			Object.keys( type ).map( ( key ) => {
				const parent = type[ key ];
				return (
					<Fragment key={ String( key ) }>
						{
							'object' === typeof ( type[ key ] )
								? <optgroup label={
									// eslint-disable-next-line no-nested-ternary
									archives === type ? key + ' Archives'
										// eslint-disable-next-line no-nested-ternary
										: singulars === type ? key
											// eslint-disable-next-line no-nested-ternary
											: woocommerce === type ? key
												// eslint-disable-next-line no-nested-ternary
												: users === type ? key
													: '' } >
									<SubOptions value={ parent } />
								</optgroup>
								: <option key={ String( key ) } value={ key } >{ type[ key ] }</option>
						}
					</Fragment>
				);
			} )
		);
	};

	const SubOptions = ( { value } ) => {
		const parent = value;

		return (
			Object.keys( parent ).map( ( subKey ) => {
				return (
					<option
						key={ String( subKey ) }
						value={ subKey }
					>
						{ parent[ subKey ] }
					</option>
				);
			} )
		);
	};

	const showResult = ( data ) => {
		setSaveProcess( false );

		if ( null === document.getElementById( 'save-result' ) ) {
			return;
		}

		document.getElementById( 'save-result' ).innerText = data;
		setTimeout( () => {
			if ( null === document.getElementById( 'save-result' ) ) {
				return;
			}

			document.getElementById( 'save-result' ).innerText = '';
		}, 5000 );
	};

	const Parents = () => {
		const exceptions = [ 'header', 'footer', 'page-title-bar' ];

		if ( 'custom-snippet' === props.place || exceptions.includes( props.type ) ) {
			return (
				<>
					<option value="entire">{ __( 'Entire Site', 'jupiterx-core' ) }</option>
					<option value="archive">{ __( 'Archive', 'jupiterx-core' ) }</option>
					<option value="singular">{ __( 'Singular', 'jupiterx-core' ) }</option>
					<option value="woocommerce">{ __( 'WooCommerce', 'jupiterx-core' ) }</option>
					<option value="users">{ __( 'User Attributes', 'jupiterx-core' ) }</option>
					{ wpmlActive && <option value="wpml">{ __( 'WPML', 'jupiterx-core' ) }</option> }
				</>
			);
		}

		if ( 'single' === props.type ) {
			return (
				<>
					<option value="entire">{ __( 'Entire Site', 'jupiterx-core' ) }</option>
					<option value="singular">{ __( 'Singular', 'jupiterx-core' ) }</option>
					<option value="woocommerce">{ __( 'WooCommerce', 'jupiterx-core' ) }</option>
					<option value="users">{ __( 'User Attributes', 'jupiterx-core' ) }</option>
					{ wpmlActive && <option value="wpml">{ __( 'WPML', 'jupiterx-core' ) }</option> }
				</>
			);
		}

		if ( 'archive' === props.type ) {
			return (
				<>
					<option value="archive">{ __( 'Archive', 'jupiterx-core' ) }</option>
					<option value="users">{ __( 'User Attributes', 'jupiterx-core' ) }</option>
					{ wpmlActive && <option value="wpml">{ __( 'WPML', 'jupiterx-core' ) }</option> }
				</>
			);
		}

		if ( 'product' === props.type || 'product-archive' === props.type ) {
			return (
				<>
					<option value="woocommerce">{ __( 'WooCommerce', 'jupiterx-core' ) }</option>
					<option value="users">{ __( 'User Attributes', 'jupiterx-core' ) }</option>
					{ wpmlActive && <option value="wpml">{ __( 'WPML', 'jupiterx-core' ) }</option> }
				</>
			);
		}
	};

	const LayoutBuilderHeader = () => {
		return (
			<>
				<div className="d-flex condition-info">
					<span><span style={ { textTransform: 'capitalize' } }>{ props.typeTitle } </span> / <b className="condition-header-title" >{ props.title }</b> </span>
				</div>
				<div className="row condition-header">{ __( 'Where do you want to display this template?', 'jupiterx-core' ) }</div>
				<div className="row condition-header-desc">{ __( 'Set conditions that determine where in your website this template is displayed. To display templates globally across your website, use “Entire site”.', 'jupiterx-core' ) }</div>
			</>
		);
	};

	const randomString = ( length ) => {
		let result = '';
		const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
		const charactersLength = characters.length;

		for ( let i = 0; i < length; i++ ) {
			result += characters.charAt( Math.floor( Math.random() * charactersLength ) );
		}

		return result;
	};

	return (
		<>
			{
				load && 'custom-snippet' === props.place &&
				<Loading />
			}
			{
				<>
					<form
						onSubmit={ handleSubmit }
						className="jupiterx-form-condition-manager"
					>
						<div
							className="jupiterx-condition-form-inner-wrapper"
							id="jupiterx-condition-form-inner-wrapper"
							ref={ containerRef }
						>
							{
								'layout-builder' === props.place &&
								<LayoutBuilderHeader />
							}
							{
								load && 'layout-builder' === props.place &&
								<Loading />
							}
							{
								! load &&
								<div
									className="jupiterx-conditions-rows-wrapper"
								>
									{ inputFields.map( ( inputField, index ) => (

										<Fragment key={ index }>
											<div className={ `row jupiterx-layout-condition-row position-relative jx-row-condition-${ index } ${ index === conflictRow ? 'row-includes-conflict' : '' } ` }>
												<div
													className={
														'entire' === inputField.conditionB || 'maintenance' === inputField.conditionB || '' === inputField.conditionB // eslint-disable-line no-nested-ternary
															? 'mb-3 col-12 col-sm-12 col-md-5 col-lg-3'
															: excludeArray.includes( inputField.conditionC ) || ! inputField.conditionC.includes( '_' ) || 'users' === inputField.conditionB
																? 'mb-3 col-12 col-sm-12 col-md-6 col-lg-4'
																: 'mb-3 col-12 col-sm-12 col-md-6 col-lg-2'
													}
												>
													<FirstAsyncSelect
														index={ index }
														handleInputChange={ ( indexed, event ) => handleInputChange( indexed, event ) }
														inputField={ inputField }
														inputFields={ inputFields }
														setInputFields={ ( fields ) => setInputFields( fields ) }
													/>
												</div>
												<div
													className={
														'entire' === inputField.conditionB || 'maintenance' === inputField.conditionB || '' === inputField.conditionB // eslint-disable-line no-nested-ternary
															? 'mb-3 col-12 col-sm-12 col-md-7 col-lg-9'
															: excludeArray.includes( inputField.conditionC ) || ! inputField.conditionC.includes( '_' ) || 'users' === inputField.conditionB
																? 'mb-3 col-12 col-sm-12 col-md-6 col-lg-4'
																: 'mb-3 col-12 col-sm-12 col-md-6 col-lg-2'
													}
												>
													<Form.Control
														as="select"
														className="form-control"
														id="conditionB"
														name="conditionB"
														value={ inputField.conditionB }
														onChange={ ( event ) => handleInputChange( index, event ) }
													>
														<option value="">{ __( 'Select an option', 'jupiterx-core' ) }</option>
														<Parents />
													</Form.Control>
												</div>
												<div
													className={
														'entire' === inputField.conditionB || 'maintenance' === inputField.conditionB || '' === inputField.conditionB // eslint-disable-line no-nested-ternary
															? 'd-none'
															: excludeArray.includes( inputField.conditionC ) || ! inputField.conditionC.includes( '_' ) || 'users' === inputField.conditionB
																? 'mb-3 col-12 col-sm-12 col-md-6 col-lg-4'
																: 'mb-3 col-12 col-sm-12 col-md-6 col-lg-3'
													}
												>
													<Form.Control
														as="select"
														className="form-control"
														id="conditionC"
														name="conditionC"
														value={ ( inputField.conditionC ) ? inputField.conditionC : '' }
														onChange={ ( event ) => handleInputChange( index, event ) }
													>
														{
															'archive' === inputField.conditionB &&
															<OptionsHtml type={ archives } />
														}
														{
															'singular' === inputField.conditionB &&
															<OptionsHtml type={ singulars } />
														}
														{
															'woocommerce' === inputField.conditionB &&
															<OptionsHtml type={ woocommerce } />
														}
														{
															'users' === inputField.conditionB &&
															<OptionsHtml type={ users } />
														}
														{
															'wpml' === inputField.conditionB &&
															<OptionsHtml type={ wpml } />
														}
													</Form.Control>
												</div>
												<div
													className={
														'entire' === inputField.conditionB || 'maintenance' === inputField.conditionB || '' === inputField.conditionB // eslint-disable-line no-nested-ternary
															? 'd-none'
															: excludeArray.includes( inputField.conditionC ) || ! inputField.conditionC.includes( '_' ) || 'users' === inputField.conditionB
																? 'd-none'
																: 'mb-3 col-xs-12 col-sm-12 col-md-5 col-lg-5'
													}
												>
													<CustomAsyncSelect
														index={ index }
														handleInputChange={ ( indexed, event ) => handleInputChange( indexed, event ) }
														inputField={ inputField }
														inputFields={ inputFields }
														setInputFields={ ( fields ) => setInputFields( fields ) }
														defaultOptions={ props.defaultOptions }
														type={ props.type }
														place={ props.place }
													/>
												</div>
												<div className="mb-3 ps-0 delete-row">
													<button
														className="btn btn-sm text-decoration-none ps-0"
														type="button"
														onClick={ () => handleRemoveFields( index ) }
													>
														<FontAwesomeIcon
															icon={ faTrashAlt }
															className="fa-lg trash-icon"
														/>
													</button>
												</div>
												<div
													className={ `col-12 jx-row-condition-conflict ${ index === conflictRow ? 'd-block' : 'd-none' } ` }
												>
													{
														__( 'JupiterX recognized that you have set this condition for other templates', 'jupiterx-core' ) + ': ' + conflictTemplate
													}
												</div>
											</div>
										</Fragment>
									) ) }
									<div className="row condition-row-add-button position-relative">
										<Button
											variant="outline-secondary"
											onClick={ () => handleAddFields() }
											className={ ( 'custom-snippet' === props.place ) ? props.place + ' add-new' : 'add-new col-12' }
										>
											+ { __( 'Add Conditions', 'jupiterx-core' ) }
										</Button>
									</div>
								</div>
							}
						</div>
						<div className={ `jupiterx-condition-submit-button ${ 'layout-builder' === props.place ? '' : 'row' }` } >
							{
								'layout-builder' === props.place &&
								<>
									<hr className="jupiterx-layout-builder-save-line" />
									<Button
										className="btn btn-primary condition-saver mt-5"
										type="submit"
										onSubmit={ handleSubmit }
									>
										{
											false === saveProcess ? __( 'Save and Close', 'jupiterx-core' ) : <Spinner animation="border" size="sm" variant="light" />
										}
									</Button>
									<span id="save-result"></span>
								</>
							}
						</div>
					</form>
				</>
			}
		</>
	);
};

export default App;
