import React, { useEffect, useState } from 'react';
import { __ } from '@wordpress/i18n';
import { urls, nonce } from '@jupiterx/control-panel';
import { Button } from 'react-bootstrap';

const DoneControl = ( props ) => {
	const [ wizardFinished, setWizardFinished ] = useState( 'proccess' );
	const [ disableSubmit, setDisableSubmit ] = useState( props.submitButton );
	const [ activeKit, setActiveKit ] = useState( '' );
	const [ doneSteps, setDoneSteps ] = useState( [] );
	const [ steps, setSteps ] = useState( {
		install_plugins: {
			state: 'mark-not-started',
			label: __( 'Install required plugins', 'jupiterx-core' ),
			parent_class: '',
			error_message: '',
		},
		colors: {
			state: 'mark-not-started',
			label: __( 'Setup Colors', 'jupiterx-core' ),
			parent_class: '',
			error_message: '',
		},
		typography: {
			state: 'mark-not-started',
			label: __( 'Setup Typography', 'jupiterx-core' ),
			parent_class: '',
			error_message: '',
		},
		layout: {
			state: 'mark-not-started',
			label: __( 'Import Layout', 'jupiterx-core' ),
			parent_class: '',
			error_message: '',
		},
		templates: {
			state: 'mark-not-started',
			label: __( 'Import Content', 'jupiterx-core' ),
			parent_class: 'last-row',
			error_message: '',
		},
	} );

	useEffect( () => {
		setDisableSubmit( props.submitButton );
	}, [ props.submitButton ] );

	useEffect( () => {
		if ( props.setupWizardStatus !== 'done' ) {
			return;
		}

		setWizardFinished( 'done' );
		getActiveKit();
		window.localStorage.removeItem( 'jupiterxWizard' );
	}, [ props.setupWizardStatus ] );

	useEffect( () => {
		if ( _.isEmpty( props.importStep ) ) {
			return;
		}

		updateStepState( props.importStep, 'mark-started', 'step', '' );

		const newDoneSteps = [
			...doneSteps,
			props.importStep,
		];

		setDoneSteps( newDoneSteps );
	}, [ props.importStep, props.updateImportStep ] );

	useEffect( () => {
		if ( _.isEmpty( props.importError ) ) {
			return;
		}

		updateStepState( props.importStep, 'mark-failed', 'error', props.importError );
	}, [ props.importError ] );

	const updateStepState = ( step, newState, type, errorMessage ) => {
		const status = steps;

		if ( _.isEmpty( status[ step ] ) ) {
			return;
		}

		doneSteps.forEach( ( doneStep ) => {
			status[ doneStep ].state = 'mark-finished';
		} );

		if ( type === 'error' ) {
			status[ step ].error_message = errorMessage;
			status[ step ].state = 'mark-has-error';
		}

		const newStatus = { ...status };
		newStatus[ step ].state = newState;

		setSteps( newStatus );
	};

	const onSubmit = ( step ) => {
		let newImportStep = 0;

		switch ( step ) {
			case 'install_plugins':
				newImportStep = 0;
				break;

			case 'colors':
				newImportStep = 1;
				break;

			case 'typography':
				newImportStep = 2;
				break;

			case 'layout':
				newImportStep = 3;
				break;

			case 'templates':
				newImportStep = 4;
				break;

			default:
				break;
		}

		props.updateImportStep( newImportStep );
	};

	const CustomCards = ( { classes, label, descriptions, href, target } ) => {
		return (
			<a className={ classes } href={ href } target={ target } >
				<span className="icon-holder"></span>
				<h2>{ label }</h2>
				<p>{ descriptions }</p>
			</a>
		);
	};

	const getActiveKit = async () => {
		try {
			const data = await wp.ajax.post( {
				action: 'jupiterx_setup_wizard_get_active_kit',
				nonce,
			} );

			setActiveKit( data );
		} catch ( error ) {
			// eslint-disable-next-line no-console
			console.error( error );
		}
	};

	return (
		<>
			<div className="jupiterx-setup-wizard-step-done">
				{
					'done' !== wizardFinished &&
					<>
						<div className="step-done-description">
							<h2>{ __( 'Your website is almost ready!', 'jupiterx-core' ) }</h2>
							<p>{ __( 'You\'re nearly there! Here\'s a quick checklist outlining the steps', 'jupiterx-core' ) }</p>
							<p>{ __( 'we will undertake to finalize your website setup. Simply click', 'jupiterx-core' ) }</p>
							<p>{ __( 'the "Complete Setup" button to wrap up the process.', 'jupiterx-core' ) }</p>
							<table>
								<tbody>
									{
										Object.keys( steps ).map( ( step, index ) => {
											const details = steps[ step ];

											return (
												<tr key={ index }>
													<td className={ details.parent_class }>
														<span className={ `mark-holder ${ details.state }` }></span>
														<span className="label-holder">{ details.label }</span>

														{ details.state === 'mark-failed' && (
															<button className="done-step-retry-btn" onClick={ () => onSubmit( step ) }>{ __( 'Retry', 'jupiterx-core' ) }</button>
														) }
													</td>
												</tr>
											);
										} )
									}
								</tbody>
							</table>
							<Button
								disabled={ disableSubmit }
								className={ `run-jupiterx-setup-wizard ${ ( true === disableSubmit ) ? 'btn-is-disabled' : '' }` }
								type="submit"
								onClick={ props.handleSubmit }
							>
								{ __( 'Complete Setup', 'jupiterx-core' ) }
							</Button>
						</div>
					</>
				}
				{
					'done' === wizardFinished &&
					<>
						<div className="step-done-description step-done-completed">
							<h2>{ __( 'You\'re all set!', 'jupiterx-core' ) }</h2>
							<p>{ __( 'Congratulations! Your website is ready to make its', 'jupiterx-core' ) }</p>
							<p>{ __( 'grand debut. Now you can start adding new content,', 'jupiterx-core' ) }</p>
							<p>{ __( 'edit or customize your website.', 'jupiterx-core' ) }</p>
							<a
								className="view-website-btn"
								href={ urls.siteUrl }
								target="_blank"
							>
								{ __( 'View Website', 'jupiterx-core' ) }
							</a>
							<div className="divider"></div>
							<h2 className="after-wizard-section">{ __( 'Customize your website', 'jupiterx-core' ) }</h2>
							<div className="step-done-cards">
								<CustomCards
									classes="step-card global-styles-card"
									label={ __( 'Global Styles', 'jupiterx-core' ) }
									descriptions={ __( 'Manage global typography, colors, and more.', 'jupiterx-core' ) }
									href={ `post.php?post=${ activeKit }&action=elementor` }
									target="_blank"
								></CustomCards>
								<CustomCards
									classes="step-card layout-builder-card"
									label={ __( 'Layout Builder', 'jupiterx-core' ) }
									descriptions={ __( 'Manage site header, footer, single pages, and more.', 'jupiterx-core' ) }
									href={ urls.controlPanelUrl + '#/layout-builder' }
									target="_blank"
								></CustomCards>
								<CustomCards
									classes="step-card jupiter-settings-card"
									label={ __( 'Jupiter X Settings', 'jupiterx-core' ) }
									descriptions={ __( 'Theme settings, modules, white label options, and more.', 'jupiterx-core' ) }
									href={ urls.controlPanelUrl + '#/settings' }
									target="_blank"
								></CustomCards>
							</div>
							<h2 className="after-wizard-section">{ __( 'Need help?', 'jupiterx-core' ) }</h2>
							<div className="step-done-cards">
								<CustomCards
									classes="step-card documentation-card"
									label={ __( 'Documentation', 'jupiterx-core' ) }
									descriptions={ __( 'Read our in-depth tutorials, articles, and tips.', 'jupiterx-core' ) }
									href="https://themes.artbees.net/docs/getting-started-with-jupiter-x/"
									target="_blank"
								></CustomCards>
								<CustomCards
									classes="step-card submit-ticket-card"
									label={ __( 'Submit a Ticket', 'jupiterx-core' ) }
									descriptions={ __( 'Ask your questions directly from our dedicated support team.', 'jupiterx-core' ) }
									href="https://themes.artbees.net/dashboard/tickets/"
									target="_blank"
								></CustomCards>
								<CustomCards
									classes="step-card facebook-group-card"
									label={ __( 'Jupiter X Facebook Group', 'jupiterx-core' ) }
									descriptions={ __( 'Learn, share tips, and connect with Jupiter X community.', 'jupiterx-core' ) }
									href="https://www.facebook.com/groups/jupiterx/"
									target="_blank"
								></CustomCards>
							</div>
						</div>
					</>
				}
			</div>
		</>
	);
};

export default DoneControl;
