import React, { createContext, useState } from 'react';
import { templateInstalled as initialState } from '@jupiterx/control-panel';

export const TemplatesContext = createContext();

export const TemplatesProvider = ( { children } ) => {
	const [ templateInstalled, setTemplateInstalled ] = useState( initialState );

	const { id, title } = templateInstalled;

	const store = {
		templateInstalled,
		hasTemplateInstalled: !! ( id && title ),
		setTemplateInstalled,
	};

	return (
		<TemplatesContext.Provider value={ store }>
			{ children }
		</TemplatesContext.Provider>
	);
};

TemplatesContext.displayName = 'TemplatesContext';
