import { activePlugins } from '@jupiterx/control-panel';

export const appActionTypes = {
	APP_FETCH_UPDATES: 'APP_FETCH_UPDATES',
	APP_ADD_UPDATES_LAST_CHECKED: 'APP_ADD_UPDATES_LAST_CHECKED',
	APP_ADD_UPDATES: 'APP_ADD_UPDATES',
	APP_FETCH_UPDATES_STATUS: 'APP_FETCH_UPDATES_STATUS',
	APP_UPDATE_ITEM: 'APP_UPDATE_ITEM',
	APP_UPDATE_ALL: 'APP_UPDATE_ALL',
	APP_UPDATE_ITEM_STATUS: 'APP_UPDATE_ITEM_STATUS',
	APP_QUEUE_ALL_UPDATES: 'APP_QUEUE_ALL_UPDATES',
	APP_AUTO_UPDATER_STATUS: 'APP_AUTO_UPDATER_STATUS',
};

export const appInitialState = {
	updates: {
		list: [],
		fetching: true,
		status: '',
		all: false,
		lastChecked: '',
		auto: '',
	},
};

export const appReducer = ( state, action ) => {
	switch ( action.type ) {
		case appActionTypes.APP_FETCH_UPDATES:
			return {
				...state,
				updates: { ...state.updates, fetching: action.payload },
			};
		case appActionTypes.APP_ADD_UPDATES_LAST_CHECKED:
			return {
				...state,
				updates: { ...state.updates, lastChecked: action.payload },
			};
		case appActionTypes.APP_ADD_UPDATES:
			return {
				...state,
				updates: { ...state.updates, list: action.payload },
			};
		case appActionTypes.APP_FETCH_UPDATES_STATUS:
			return {
				...state,
				updates: { ...state.updates, status: action.payload.status, statusMessage: action.payload.message },
			};
		case appActionTypes.APP_UPDATE_ITEM:
			const items = state.updates.list;

			items[ _.findIndex( items, { id: action.payload.id } ) ].status = action.payload.status;

			return {
				...state,
				updates: {
					...state.updates,
					list: items,
				},
			};
		case appActionTypes.APP_UPDATE_ALL:
			const newList = state.updates.list.filter( ( item ) => {
				if ( item.type === 'plugin' && ! activePlugins.includes( item.basename ) ) {
					return false;
				}

				return true;
			} );

			state.updates.list = newList;

			return {
				...state,
				updates: {
					...state.updates,
					all: action.payload,
				},
			};
		case appActionTypes.APP_QUEUE_ALL_UPDATES:
			for ( const item of state.updates.list ) {
				if ( item.status === 'updated' ) {
					continue;
				}

				item.status = 'queued';
			}

			return {
				...state,
				updates: {
					...state.updates,
					list: state.updates.list,
				},
			};
		case appActionTypes.APP_UPDATE_ITEM_STATUS:
			const itemIndex = _.findIndex( state.updates.list, { id: action.payload.id } );

			state.updates.list[ itemIndex ].status = action.payload.status;
			state.updates.list[ itemIndex ].status_message = action.payload.status_message || '';

			return {
				...state,
				updates: {
					...state.updates,
					list: state.updates.list,
				},
			};
		case appActionTypes.APP_AUTO_UPDATER_STATUS:
			return {
				...state,
				updates: {
					...state.updates,
					auto: action.payload,
				},
			};
		default:
			return state;
	}
};
