import React, { useState, useEffect, forwardRef, useRef } from 'react';
import DatePicker from 'react-datepicker';
import { faCalendarAlt } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { Form } from 'react-bootstrap';

const DateControl = forwardRef( ( props, ref ) => {
	const [ startDate, setStartDate ] = useState();
	const [ value, setValue ] = useState();
	const datePickerRef = useRef();

	useEffect( () => {
		if ( _.isEmpty( props.triggerControl.defaultValue ) ) {
			return;
		}

		setStartDate( new Date( props.triggerControl.defaultValue * 1000 ) );
		setValue( props.triggerControl.defaultValue );
	}, [] );

	useEffect( () => {
		if ( ! startDate ) {
			return;
		}

		const options = {};
		let startTime = '';

		if ( ! _.isEmpty( props.timezone ) ) {
			options.timeZone = props.timezone;
		}

		if ( props.showTimeInput ) {
			startTime = new Date( new Date( startDate ).toLocaleString( 'en-US', options ) ).getTime() / 1000;
		}

		if ( ! props.showTimeInput ) {
			const date = new Date( startDate );

			const offset = date.getTimezoneOffset();
			const year = date.getFullYear();
			const month = date.getMonth();
			const day = date.getDate();

			startTime = new Date( year, month, day, 0, 0, 0, 0 ).getTime();
			startTime = ( startTime / 1000 ) - ( offset * 60 );
		}

		setValue( startTime );

		if ( _.isFunction( props.onUpdateCallback ) ) {
			props.onUpdateCallback();
		}

		if ( _.isFunction( props.onDateChange ) ) {
			props.onDateChange( startTime );
		}
	}, [ startDate ] );

	return <>
		<Form.Group className={ `jupiterx-popup-date-input-wrapper d-flex align-items-center popup-trigger-type-${ props.triggerControl.type }` }>
			<DatePicker
				selected={ startDate }
				dateFormat={ ! props.showTimeInput ? 'yyyy/MM/dd' : 'yyyy/MM/dd h:mm aa' }
				className="jupiterx-popup-date-input"
				onChange={ ( date ) => setStartDate( date ) }
				showTimeInput={ props.showTimeInput }
				timeInputLabel="Time:"
				selectsEnd={ props.selectsEnd || undefined }
				selectsStart={ props.selectsStart || undefined }
				startDate={ props.minDate || undefined }
				minDate={ props.minDate || undefined }
				endDate={ props.maxDate || undefined }
				shouldCloseOnSelect={ props.shouldCloseOnSelect }
				ref={ datePickerRef }
				disabled={ props.isDisabled || false }
				popperPlacement="top-start"
			/>
			<FontAwesomeIcon icon={ faCalendarAlt } onClick={ () => datePickerRef.current.setFocus() } />
			<input
				type="hidden"
				name={ props.rowName + '[control]' }
				value={ ( value !== null && value !== undefined ) ? String( value ) : '' }
				{ ...ref( props.rowName + '[control]' ) }
			/>
		</Form.Group>
	</>;
} );

export default DateControl;
