import React, { forwardRef } from 'react';
import { Form } from 'react-bootstrap';

const NumberControl = forwardRef( ( props, ref ) => {
    const getDefaultValue = () => {
        const defaultValue = props.triggerControl?.defaultValue;
        const fallbackValue = props.triggerControl?.default;

        // Use provided defaultValue when defined (including 0 or '0')
        if ( defaultValue !== null && defaultValue !== undefined ) {
            return String(defaultValue);
        }

        // Otherwise use control's default (including 0)
        if ( fallbackValue !== null && fallbackValue !== undefined ) {
            return String(fallbackValue);
        }

        // As a last resort for numeric controls, default to 0
        return '0';
    };

	return (
		<Form.Group className="d-flex align-items-center">
			<Form.Label htmlFor={ props.rowName + '_control' }>
				{ props.triggerControl.label }
			</Form.Label>
			<Form.Control
				id={ props.rowName + '_control' }
				className="popup-trigger-control"
				type="number"
				name={ props.rowName + '[control]' }
				min={ props.triggerControl.min }
				step={ props.triggerControl.step }
				defaultValue={ getDefaultValue() }
				{ ...ref( props.rowName + '[control]' ) }
			/>
		</Form.Group>
	);
} );

export default NumberControl;
