import React from 'react';
import { Card, Button } from 'react-bootstrap';

const ShadowCards = ( { count } ) => {
	const cards = [];

	for ( let i = 0; i < count; i++ ) {
		cards.push(
			<Card key={ i } className="jx-cp-shadow-card">
				<Card.Img variant="top" />
				<Card.Body >
					<Card.Title />
					<Button />
				</Card.Body>
			</Card>
		);
	}

	return cards;
};

export default ShadowCards;
