import React, { useState, useEffect, createContext } from 'react';
import { Link, useParams } from 'react-router-dom';
import { Row, Col, ListGroup } from 'react-bootstrap';
import { __, sprintf } from '@wordpress/i18n';
import { nonce, layoutTemplates, elementorActive } from '@jupiterx/control-panel';
import Templates from './templates/index';
import Alert from '../../components/alert';
import './style.scss';

export const LayoutBuilderContext = createContext();

const LayoutBuilder = ( { simplicityMode } ) => {
	const { templateKey } = useParams();
	const types = layoutTemplates;
	// Gets active menu and assign it a class attribute.
	const [ activeMenu, setActiveMenu ] = useState( '' );
	const [ default4thOptions, setDefault4thOptions ] = useState( {} );
	const [ default3rdOptions, setDefault3rdOptions ] = useState( {} );

	useEffect( () => {
		// Update active menu when templateKey changes
		if ( templateKey && types.hasOwnProperty( templateKey ) ) {
			setActiveMenu( templateKey );
		} else if ( ! templateKey ) {
			// Default active menu is header when no templateKey
			setActiveMenu( 'header' );
		}
	}, [ templateKey, types ] );

	useEffect( () => {
		if ( ! types.hasOwnProperty( templateKey ) ) {
			const url = window.location.href;
			const newUrl = url.split( '#' )[ 0 ] + '#/' + templateKey;
			location.href = newUrl;
		}
	}, [ templateKey, types ] );

	const handleTabClick = ( key ) => {
		setActiveMenu( key );
	};

	const getDefaultOptions = ( postTypes ) => {
		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'get_default_options',
			post_types: postTypes,
			nonce,
		} )
			.done( ( data ) => {
				addItemToDefault4th( data, postTypes );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const addItemToDefault4th = ( data, postType ) => {
		const currentDefaults = default4thOptions;

		for ( const i in postType ) {
			const target = postType[ i ];
			currentDefaults[ target ] = data[ target ];
		}

		setDefault4thOptions( currentDefaults );
	};

	const addItemToDefault3rd = ( section, type, value ) => {
		const currentDefaults = default3rdOptions;

		if ( ! currentDefaults.hasOwnProperty( section ) ) {
			currentDefaults[ section ] = {};
		}

		if ( ! currentDefaults[ section ].hasOwnProperty( type ) ) {
			currentDefaults[ section ][ type ] = {};
		}

		currentDefaults[ section ][ type ] = value;

		setDefault3rdOptions( currentDefaults );
	};

	const contextValue = {
		initDefault4th: ( postTypes ) => getDefaultOptions( postTypes ),
		initDefault3rd: ( section, type, value ) => addItemToDefault3rd( section, type, value ),
		defaults4thParameter: default4thOptions,
		default3rdParameter: default3rdOptions,
	};

	// translators: 1: Opening HTML span tag, 2: Closing HTML span tag.
	const elementorRequired = sprintf( __( 'Layout Builder requires %1$s Elementor %2$s to be installed and activated.', 'jupiterx-core' ), '<span>', '</span>' );

	return (
		<>
			<LayoutBuilderContext.Provider value={ contextValue }>
				<Row className="jupiterx-layout-builder border-bottom p-0 m-0">
					<Col sm={ 12 } className="header">
						<h3 className="layout-builder-title">
							{ __( 'Layout Builder', 'jupiterx-core' ) }
						</h3>
						<p className="layout-builder-description">
							{ __( 'Layout builder provides a complete visual overview of all parts of your website so you can easily customize your website down to the last detail', 'jupiterx-core' ) }
						</p>
					</Col>
					{
						'1' !== elementorActive &&
						<Col sm={ 12 } className="elementor-warning">
							<Alert variant="warning">
								<div dangerouslySetInnerHTML={ { __html: elementorRequired } } />
							</Alert>
						</Col>
					}
				</Row>
				<Row className={ `jupiterx-layout-builder-list p-0 m-0 ${ '1' !== elementorActive ? 'jupiterx-layout-builder-list-blurred' : '' }` }>
					<div className="layout-list-wrap px-0" >
						<ListGroup>
							{
								Object.keys( types ).map( ( key, index ) => {
									const isActive = key === activeMenu;
									const className = `layout-menu-item w-100 ${ isActive ? 'list-focus' : '' }`;
									return (
										<Link
											key={ `index-${ index }` }
											to={ '/layout-builder/' + key }
											href={ '/layout-builder/' + key }
											className={ className }
											onClick={ () => handleTabClick( key ) }
										>
											{ types[ key ] }
										</Link>
									);
								} )
							}
						</ListGroup>
					</div>
					<div className="p-0 m-0 templates-posts">
						<Templates
							key={ templateKey }
							type={ templateKey }
							title={ types[ templateKey ] }
							navigation={ activeMenu }
							content="posts"
							simplicityMode={ simplicityMode }
						/>
					</div>
				</Row>
			</LayoutBuilderContext.Provider>
		</>
	);
};

export default LayoutBuilder;
