import React, { useState, useRef, useCallback } from 'react';
import { Button, FormControl, FormGroup } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import Dialog from '../../components/dialog';
import { faQuestion } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import Tooltip from '../../components/tooltip';

const FontVariationFields = ( { register, indexValue, previousData, onRemove } ) => {
	const [ showRemoveDialog, setShowRemoveDialog ] = useState( false );
	const [ showWrongFormatDialog, setShowWrongFormatDialog ] = useState( false );
	const [ isCollapsed, setIsCollapsed ] = useState( !! previousData );

	// State for preview only (form values are managed by react-hook-form)
	const [ previewWeight, setPreviewWeight ] = useState( previousData?.font_weight || 'normal' );
	const [ previewStyle, setPreviewStyle ] = useState( previousData?.font_style || 'normal' );
	const [ previewWoff, setPreviewWoff ] = useState( previousData?.woff || '' );
	const [ previewWoff2, setPreviewWoff2 ] = useState( previousData?.woff2 || '' );
	const [ previewTtf, setPreviewTtf ] = useState( previousData?.ttf || '' );
	const [ previewSvg, setPreviewSvg ] = useState( previousData?.svg || '' );

	const FONT_FAMILY = `jx-cf-${ indexValue }`;
	const CONTAINER_ID = `variation-${ indexValue }`;
	const weightFieldId = `font-weight-${ indexValue }`;
	const styleFieldId = `font-style-${ indexValue }`;

	// Generate field name for react-hook-form
	const getFieldName = ( field ) => `custom_fonts_post_variation_url.${ indexValue }.${ field }`;

	// Get register props with custom onChange
	const getRegisterProps = ( field, customOnChange ) => {
		const registerProps = register( getFieldName( field ) );
		return {
			...registerProps,
			onChange: ( e ) => {
				registerProps.onChange( e );
				if ( customOnChange ) {
					customOnChange( e.target.value );
				}
			},
		};
	};

	const openVariationField = () => {
		setIsCollapsed( false );
	};

	const saveVariationFields = () => {
		setIsCollapsed( true );
	};

	const handleRemove = () => {
		if ( onRemove ) {
			onRemove();
		}
	};

	const discardVariationFieldsChanges = () => {
		// Revert preview to previous data
		setPreviewWeight( previousData?.font_weight || 'normal' );
		setPreviewStyle( previousData?.font_style || 'normal' );
		setPreviewWoff( previousData?.woff || '' );
		setPreviewWoff2( previousData?.woff2 || '' );
		setPreviewTtf( previousData?.ttf || '' );
		setPreviewSvg( previousData?.svg || '' );
		setIsCollapsed( true );
	};

	const openMediaLibrary = useCallback( ( event, mimeType, setPreviewState, inputId ) => {
		event.preventDefault();

		const mediaLibraryArgs = {
			title: __( 'Upload or select the font file', 'jupiterx-core' ),
			frame: 'select',
			multiple: false,
			library: {
				type: mimeType,
				order: 'DESC',
				orderby: 'date',
			},
			button: {
				text: __( 'Select Font', 'jupiterx-core' ),
			},
		};

		const customMediaLibrary = window.wp.media( mediaLibraryArgs );

		customMediaLibrary.on( 'select', () => {
			const fileAttributes = customMediaLibrary.state().get( 'selection' ).first().attributes;

			if ( mimeType !== fileAttributes.mime ) {
				setShowWrongFormatDialog( true );
				return false;
			}

			// Update preview state
			setPreviewState( fileAttributes.url );

			// Update the input field value directly
			const inputElement = document.getElementById( inputId );
			if ( inputElement ) {
				// Set native value
				const nativeInputValueSetter = Object.getOwnPropertyDescriptor( window.HTMLInputElement.prototype, 'value' ).set;
				nativeInputValueSetter.call( inputElement, fileAttributes.url );

				// Dispatch input event for react-hook-form
				const inputEvent = new Event( 'input', { bubbles: true } );
				inputElement.dispatchEvent( inputEvent );
			}
		} );

		customMediaLibrary.open();
	}, [] );

	// Generate CSS for preview
	const getFontFaceCSS = () => {
		const srcParts = [];
		if ( previewWoff2 ) {
			srcParts.push( `url('${ previewWoff2 }') format('woff2')` );
		}
		if ( previewWoff ) {
			srcParts.push( `url('${ previewWoff }') format('woff')` );
		}
		if ( previewTtf ) {
			srcParts.push( `url('${ previewTtf }') format('truetype')` );
		}
		if ( previewSvg ) {
			srcParts.push( `url('${ previewSvg }') format('svg')` );
		}

		if ( srcParts.length === 0 ) {
			return '';
		}

		return `
			@font-face {
				font-family: '${ FONT_FAMILY }';
				font-weight: ${ previewWeight };
				font-style: ${ previewStyle };
				src: ${ srcParts.join( ',\n\t\t\t\t' ) };
			}
		`;
	};

	const fontPreviewStyle = {
		fontFamily: FONT_FAMILY,
		fontWeight: previewWeight,
		fontStyle: previewStyle,
	};

	const hasAnyFontFile = previewWoff || previewWoff2 || previewTtf || previewSvg;

	// Generate unique IDs for inputs
	const woffInputId = `woff-input-${ indexValue }`;
	const woff2InputId = `woff2-input-${ indexValue }`;
	const ttfInputId = `ttf-input-${ indexValue }`;
	const svgInputId = `svg-input-${ indexValue }`;

	return <div className={ `font-variations-container ${ isCollapsed ? 'status-collapsed' : 'status-open' }` } id={ CONTAINER_ID } data-field-index={ indexValue }>
		{ /* CSS for font preview */ }
		{ hasAnyFontFile && <style>{ getFontFaceCSS() }</style> }

		<div className="collapsed">
			<div className="top-preview-style">
				<div className="d-flex flex-row">
					<span className="font-variation-weight me-3">
						{ __( 'Weight:', 'jupiterx-core' ) + ' ' }
						<strong>{ previewWeight }</strong>
					</span>
					<span className="font-variation-style me-3">
						{ __( 'Style:', 'jupiterx-core' ) + ' ' }
						<strong>{ previewStyle }</strong>
					</span>
					<div className="font-variation-preview me-3">
						<span>{ __( 'Preview:', 'jupiterx-core' ) + ' ' }</span>
						<span className="preview ms-2" style={ hasAnyFontFile ? fontPreviewStyle : {} }>
							{ __( 'Almost before we knew it, we had left the ground.', 'jupiterx-core' ) }
						</span>
					</div>
				</div>
				<div className="font-variation-actions">
					<Button
						onClick={ openVariationField }
						className="text-primary bg-transparent border-none"
						type="button"
					>
						{ __( 'Edit', 'jupiterx-core' ) }
					</Button>
					<Button
						onClick={ () => setShowRemoveDialog( true ) }
						className="text-danger bg-transparent border-none"
						type="button"
					>
						{ __( 'Remove', 'jupiterx-core' ) }
					</Button>
				</div>
			</div>
		</div>
		<div className="open">
			<div className="top-preview-style">
				<div className="d-flex flex-row align-items-center">
					<FormGroup className="me-3 mb-0 font-variation-weight d-flex align-items-center">
						<label className="me-1 mb-0" htmlFor={ weightFieldId }>{ __( 'Weight:', 'jupiterx-core' ) + ' ' }</label>
						<select
							id={ weightFieldId }
							className="font_weight form-select"
							defaultValue={ previousData?.font_weight || 'normal' }
							{ ...getRegisterProps( 'font_weight', setPreviewWeight ) }
						>
							<option value="normal">{ __( 'Normal', 'jupiterx-core' ) }</option>
							<option value="bold">{ __( 'Bold', 'jupiterx-core' ) }</option>
							<option value="100">100</option>
							<option value="200">200</option>
							<option value="300">300</option>
							<option value="400">400</option>
							<option value="500">500</option>
							<option value="600">600</option>
							<option value="700">700</option>
							<option value="800">800</option>
							<option value="900">900</option>
						</select>
					</FormGroup>
					<FormGroup className="me-3 mb-0 font-variation-style d-flex align-items-center">
						<label className="me-1 mb-0" htmlFor={ styleFieldId }>{ __( 'Style:', 'jupiterx-core' ) + ' ' }</label>
						<select
							id={ styleFieldId }
							className="font_style form-select"
							defaultValue={ previousData?.font_style || 'normal' }
							{ ...getRegisterProps( 'font_style', setPreviewStyle ) }
						>
							<option value="normal">{ __( 'Normal', 'jupiterx-core' ) }</option>
							<option value="italic">{ __( 'Italic', 'jupiterx-core' ) }</option>
							<option value="oblique">{ __( 'Oblique', 'jupiterx-core' ) }</option>
						</select>
					</FormGroup>
					<div className="font-variation-preview me-3">
						<span>{ __( 'Preview:', 'jupiterx-core' ) + ' ' }</span>
						<span className="preview ms-2" style={ hasAnyFontFile ? fontPreviewStyle : {} }>
							{ __( 'Almost before we knew it, we had left the ground.', 'jupiterx-core' ) }
						</span>
					</div>
				</div>
				<div className="font-variation-actions">
					<Button className="text-primary bg-transparent border-none" type="button">{ __( 'Edit', 'jupiterx-core' ) }</Button>
					<Button
						onClick={ () => setShowRemoveDialog( true ) }
						className="text-danger bg-transparent border-none"
						type="button"
					>
						{ __( 'Remove', 'jupiterx-core' ) }
					</Button>
				</div>
			</div>
			<hr />
			<FormGroup className="variation-wrapper mt-3">
				<div className="font-variation-format">
					<strong>{ __( 'WOFF File', 'jupiterx-core' ) }</strong>
					<span className="jx-cp-help-link">
						<Tooltip
							overlay={
								<div className="text-start">
									{ __( 'The Web Open Font Format, used by Modern Browsers', 'jupiterx-core' ) }
								</div>
							}>
							<FontAwesomeIcon icon={ faQuestion } />
						</Tooltip>
					</span>
				</div>
				<FormControl
					type="text"
					id={ woffInputId }
					className="w-100 ms-1"
					placeholder={ __( 'Upload a file or paste a url in this field', 'jupiterx-core' ) }
					defaultValue={ previousData?.woff || '' }
					{ ...getRegisterProps( 'woff', setPreviewWoff ) }
				/>
				<Button
					onClick={ ( e ) => openMediaLibrary( e, 'application/font-woff', setPreviewWoff, woffInputId ) }
					className="ms-2"
					variant="secondary"
					type="button"
				>
					{ __( 'Upload', 'jupiterx-core' ) }
				</Button>
			</FormGroup>
			<FormGroup className="variation-wrapper mt-3">
				<div className="font-variation-format">
					<strong>{ __( 'WOFF2 File', 'jupiterx-core' ) }</strong>
					<span className="jx-cp-help-link">
						<Tooltip
							overlay={
								<div className="text-start">
									{ __( 'The Web Open Font Format 2, used by Super Modern Browsers', 'jupiterx-core' ) }
								</div>
							}>
							<FontAwesomeIcon icon={ faQuestion } />
						</Tooltip>
					</span>
				</div>
				<FormControl
					type="text"
					id={ woff2InputId }
					className="w-100 ms-2"
					placeholder={ __( 'Upload a file or paste a url in this field', 'jupiterx-core' ) }
					defaultValue={ previousData?.woff2 || '' }
					{ ...getRegisterProps( 'woff2', setPreviewWoff2 ) }
				/>
				<Button
					onClick={ ( e ) => openMediaLibrary( e, 'application/font-woff2', setPreviewWoff2, woff2InputId ) }
					className="ms-2"
					variant="secondary"
					type="button"
				>
					{ __( 'Upload', 'jupiterx-core' ) }
				</Button>
			</FormGroup>
			<FormGroup className="variation-wrapper mt-3">
				<div className="font-variation-format">
					<strong>{ __( 'TTF File', 'jupiterx-core' ) }</strong>
					<span className="jx-cp-help-link">
						<Tooltip
							overlay={
								<div className="text-start">
									{ __( 'TrueType Fonts, used for better supporting Safari, Android, iOS', 'jupiterx-core' ) }
								</div>
							}>
							<FontAwesomeIcon icon={ faQuestion } />
						</Tooltip>
					</span>
				</div>
				<FormControl
					type="text"
					id={ ttfInputId }
					className="w-100 ms-2"
					placeholder={ __( 'Upload a file or paste a url in this field', 'jupiterx-core' ) }
					defaultValue={ previousData?.ttf || '' }
					{ ...getRegisterProps( 'ttf', setPreviewTtf ) }
				/>
				<Button
					onClick={ ( e ) => openMediaLibrary( e, 'application/x-font-ttf', setPreviewTtf, ttfInputId ) }
					className="ms-2"
					variant="secondary"
					type="button"
				>
					{ __( 'Upload', 'jupiterx-core' ) }
				</Button>
			</FormGroup>
			<FormGroup className="variation-wrapper mt-3">
				<div className="font-variation-format">
					<strong>{ __( 'SVG File', 'jupiterx-core' ) }</strong>
					<span className="jx-cp-help-link">
						<Tooltip
							overlay={
								<div className="text-start">
									{ __( 'SVG fonts allow SVG to be used as glyphs when displaying text, used by Legacy iOS', 'jupiterx-core' ) }
								</div>
							}>
							<FontAwesomeIcon icon={ faQuestion } />
						</Tooltip>
					</span>
				</div>
				<FormControl
					type="text"
					id={ svgInputId }
					className="w-100 ms-2"
					placeholder={ __( 'Upload a file or paste a url in this field', 'jupiterx-core' ) }
					defaultValue={ previousData?.svg || '' }
					{ ...getRegisterProps( 'svg', setPreviewSvg ) }
				/>
				<Button
					onClick={ ( e ) => openMediaLibrary( e, 'image/svg+xml', setPreviewSvg, svgInputId ) }
					className="ms-2"
					variant="secondary"
					type="button"
				>
					{ __( 'Upload', 'jupiterx-core' ) }
				</Button>
			</FormGroup>
			<div className="font-variation-footer d-flex flex-row">
				<Button
					onClick={ saveVariationFields }
					className="btn-primary save-variation"
					type="button"
				>
					{ __( 'Save', 'jupiterx-core' ) }
				</Button>
				<Button
					onClick={ discardVariationFieldsChanges }
					className="ms-3"
					variant="secondary"
					type="button"
				>
					{ __( 'Discard', 'jupiterx-core' ) }
				</Button>
			</div>
		</div>
		{
			showRemoveDialog &&
			<Dialog
				className="jupiterx-custom-font-delete-confirm"
				show
				variant="warning"
				title={ __( 'Remove the custom font variation', 'jupiterx-core' ) }
				onCancel={ () => setShowRemoveDialog( false ) }
				onOk={ () => {
					handleRemove();
					setShowRemoveDialog( false );
				} }
				closeButton={ false }
				okText={ __( 'Remove', 'jupiterx-core' ) }
				cancelText={ __( 'Cancel', 'jupiterx-core' ) }
			>
				{ __( 'Are you sure you want to delete this font variation?', 'jupiterx-core' ) }
			</Dialog>
		}
		{
			showWrongFormatDialog &&
			<Dialog
				className="jupiterx-custom-font-variation-delete-confirm"
				show
				variant="warning"
				title={ __( 'Wrong format', 'jupiterx-core' ) }
				onOk={ () => setShowWrongFormatDialog( false ) }
				okText={ __( 'Ok', 'jupiterx-core' ) }
			>
				{ __( `Please upload or select a valid format for this field.`, 'jupiterx-core' ) }
			</Dialog>
		}
	</div>;
};

export default FontVariationFields;
