import React, { useEffect, useState } from 'react';
import Dialog from '../../components/dialog';
import { __ } from '@wordpress/i18n';
import PopupTabs from './conditions-triggers/tabs';
import { useForm } from 'react-hook-form';
import { nonce, topBar } from '@jupiterx/control-panel';
import $ from 'jquery';
import JXIcon from '../../../img/jupiterx-logo';

const PopupCondition = () => {
	const { register, handleSubmit, control, unregister, setValue } = useForm();
	const [ addNewDialog, SetAddNewDialog ] = useState( false );
	const [ defaultTab, setDefaulTab ] = useState( 'conditions' );
	const [ currentTab, setCurrentTab ] = useState( 'conditions' );
	const [ startSaving, setStartSaving ] = useState( false );
	const [ isSaved, setIsSaved ] = useState( false );
	const [ theme, setTheme ] = useState( 'light' );

	const conditionButton = `<div id="jupiterx-editor-conditions-content" class="elementor-panel-footer-sub-menu-item">
		<i class="elementor-icon eicon-flow" aria-hidden="true"></i>
		<span class="elementor-title" data-key="conditions">${ __( 'Display Conditions', 'jupiterx-core' ) }</span>
	</div>`;

	const triggerButton = `<div id="jupiterx-editor-trigger-content" class="elementor-panel-footer-sub-menu-item">
		<i class="elementor-icon eicon-click" aria-hidden="true"></i>
		<span class="elementor-title" data-key="triggers">${ __( 'Triggers', 'jupiterx-core' ) }</span>
	</div>`;

	const conditionButtonTopBar = `<div id="jupiterx-editor-conditions-content" class="elementor-panel-footer-sub-menu-item">
		<span class="elementor-title" data-key="conditions">${ __( 'Display Conditions', 'jupiterx-core' ) }</span>
	</div>`;

	const triggerButtonTopBar = `<hr class="jupiterx-editor-template-hr"><div id="jupiterx-editor-trigger-content" class="elementor-panel-footer-sub-menu-item">
		<span class="elementor-title" data-key="triggers">${ __( 'Triggers', 'jupiterx-core' ) }</span>
	</div>`;

	useEffect( () => {
		addConditionButton();

		setTimeout( () => {
			handleSaveButton();
		}, 300 );
	}, [] );

	const handleDarkMode = () => {
		const uiTheme = window.elementor?.getPreferences?.( 'ui_theme' );

		if ( uiTheme === 'dark' ) {
			setTheme( 'dark' );

			return;
		}

		if ( uiTheme === 'light' ) {
			setTheme( 'light' );

			return;
		}

		if ( uiTheme === 'auto' && window.matchMedia && window.matchMedia( `(prefers-color-scheme: dark)` ).matches ) {
			setTheme( 'dark' );

			return;
		}

		setTheme( 'light' );
	};

	const handleSaveButton = () => {
		if ( ! window.elementor ) {
			return;
		}

		elementor.on( 'document:loaded', ( document ) => {
			if ( 'draft' !== document.container.settings.get( 'post_status' ) ) {
				return;
			}

			$( '#elementor-panel-saver-button-publish' ).on( 'click', ( event ) => {
				if ( $( event.currentTarget ).hasClass( 'elementor-disabled' ) ) {
					return;
				}

				event.stopPropagation();
				event.preventDefault();

				setDefaulTab( 'conditions' );
				setCurrentTab( 'conditions' );
				SetAddNewDialog( true );
				setStartSaving( true );
			} );

			$( '.eui-button-group > button, .MuiButtonGroup-root > button' ).on( 'click', ( event ) => {
				if ( $( event.currentTarget ).hasClass( 'Mui-disabled' ) ) {
					return;
				}

				event.stopPropagation();
				event.preventDefault();

				setDefaulTab( 'conditions' );
				setCurrentTab( 'conditions' );
				SetAddNewDialog( true );
				setStartSaving( true );
			} );
		} );
	};

	if ( isSaved ) {
		$( '#elementor-panel-saver-button-publish' ).off( 'click' );
		$( '.eui-button-group > button, .MuiButtonGroup-root > button' ).off( 'click' );
	}

	const addConditionButton = () => {
		let saveOptionsId = '#elementor-panel-saver-button-save-options';

		if ( topBar !== '1' ) {
			$( document ).on( 'click', `${ saveOptionsId }, ${ saveOptionsId } > *`, () => {
				const saveButton = document.getElementById( 'elementor-panel-footer-sub-menu-item-save-template' ),
					wrapper = document.getElementsByClassName( 'elementor-panel-footer-sub-menu-wrapper' );

				if ( ! saveButton || ! wrapper.length ) {
					return;
				}

				if ( wrapper[ 0 ].querySelector( '#jupiterx-editor-conditions-content' ) === null ) {
					saveButton.insertAdjacentHTML( 'beforebegin', conditionButton );

					const condition = document.getElementById( 'jupiterx-editor-conditions-content' );
					condition.addEventListener( 'click', openDialog );
				}

				if ( wrapper[ 0 ].querySelector( '#jupiterx-editor-trigger-content' ) === null ) {
					saveButton.insertAdjacentHTML( 'beforebegin', triggerButton );

					const trigger = document.getElementById( 'jupiterx-editor-trigger-content' );
					trigger.addEventListener( 'click', openDialog );
				}
			} );
		}

		if ( topBar === '1' ) {
			saveOptionsId = '.MuiBox-root button';

			$( document ).on( 'click', `${ saveOptionsId }, ${ saveOptionsId } > *`, () => {
				let saveButton = document.getElementsByClassName( 'MuiMenuItem-root' );
				const wrapper = document.getElementsByClassName( 'MuiList-root' );

				if ( saveButton.length > 1 ) {
					saveButton = saveButton[ 1 ];
				}

				if ( ! saveButton || ! wrapper.length ) {
					return;
				}

				if ( wrapper[ 0 ].querySelector( '#jupiterx-editor-conditions-content' ) === null ) {
					saveButton.insertAdjacentHTML( 'afterend', conditionButtonTopBar );

					const condition = document.getElementById( 'jupiterx-editor-conditions-content' );
					condition.addEventListener( 'click', openDialog );
				}

				if ( wrapper[ 0 ].querySelector( '#jupiterx-editor-trigger-content' ) === null ) {
					saveButton.insertAdjacentHTML( 'afterend', triggerButtonTopBar );

					const trigger = document.getElementById( 'jupiterx-editor-trigger-content' );
					trigger.addEventListener( 'click', openDialog );
				}
			} );
		}
	};

	const openDialog = ( event ) => {
		handleDarkMode();

		let dataKey = event.target.dataset.key;

		if ( ! dataKey ) {
			dataKey = event.target.querySelector( '.elementor-title' );
			dataKey = dataKey.dataset.key;
		}

		setDefaulTab( dataKey );
		setCurrentTab( dataKey );
		SetAddNewDialog( true );
	};

	const handleNextButton = ( event ) => {
		event.preventDefault();
		event.stopPropagation();
		setCurrentTab( 'triggers' );
	};

	const handleChangeTabs = ( key ) => {
		setCurrentTab( key );
	};

	const dialogHeader = () => {
		return (
			<div className="d-flex align-items-center justify-content-between jx-conditions-trigger-popup-dialog-header">
				<div className="d-flex align-items-center popup-dialog-header-content">
					<span className="header-logo">
						<JXIcon />
					</span>
					<h4>{ __( 'Publish Settings', 'jupiterx-core' ) }</h4>
				</div>
				<button
					className="d-flex justify-content-center align-items-center close-button"
					onClick={ () => SetAddNewDialog( false ) }
				>
					<i className="eicon-close" aria-hidden="true" title="Close"></i>
				</button>
			</div>
		);
	};

	const removeIsRemovedRows = ( data ) => {
		const newData = {};

		for ( const key in data ) {
			if ( Array.isArray( data[ key ] ) ) {
				newData[ key ] = data[ key ].filter( ( item ) => ! ( 'isRemoved' in item ) );
			} else {
				newData[ key ] = data[ key ];
			}

			if ( Array.isArray( newData[ key ] ) && newData[ key ].length === 0 ) {
				delete newData[ key ];
			}
		}

		return newData;
	};

	//eslint-disable-next-line
	const onSubmit = ( fields ) => {
		fields = removeIsRemovedRows( fields );
		let conditions = {},
			triggers = {},
			relationLogic = { name: 'relation_logic', operator: 'is', control: 'or' }; // eslint-disable-line prefer-const

		if ( ! _.isEmpty( fields.conditions ) ) {
			conditions = fields.conditions.filter( ( condition ) => condition );
		}

		if ( ! _.isEmpty( fields.triggers ) ) {
			// Keep the first occurrence per trigger name (original behavior)
			const seen = [];
			triggers = fields.triggers.filter( ( trigger ) => {
				const isDuplicate = seen.includes( trigger.name );
				seen.push( trigger.name );
				return ! isDuplicate;
			} );
		}

		if ( fields.relation_logic && ! _.isEmpty( triggers ) ) {
			relationLogic.control = fields.relation_logic;
			triggers.push( relationLogic );
		}

		wp.ajax.send( 'jupiterx_popup_save_conditions_triggers', {
			data: {
				nonce,
				popup_id: elementor.config.document.id,
				conditions,
				triggers,
			},
			success: () => {
				SetAddNewDialog( false );

				if ( startSaving && window?.elementorCommon ) {
					window.elementorCommon.api.run( 'document/save/default' );
					setIsSaved( true );
					setStartSaving( false );
				}
			},
			error: ( data ) => {
				SetAddNewDialog( false );

				// eslint-disable-next-line no-console
				console.error( data );
			},
		} );
	};

	return (
		<>
			{ addNewDialog && <Dialog
				className={ `jx-conditions-trigger-popup-dialog jx-popup-dialog-${ currentTab } jx-popup-theme-${ theme }` }
				title={ dialogHeader() }
				show={ true }
				showCancel={ true }
				closeButton={ false }
				cancelText={ ' ' }
				cancelProps={ { type: 'submit' } }
				onCancel={ handleSubmit( onSubmit ) }
				submitText={ currentTab === 'triggers' ? __( 'Save & Close', 'jupiterx-core' ) : __( 'NEXT', 'jupiterx-core' ) }
				onSubmit={ currentTab === 'triggers' ? handleSubmit( onSubmit ) : handleNextButton }
			>
				<PopupTabs default={ defaultTab } current={ currentTab } changeTabs={ handleChangeTabs } conditionRef={ register } conditionControl={ control } conditionUnregister={ unregister } conditionSetValue={ setValue } />
			</Dialog> }
		</>
	);
};

export default PopupCondition;
