import React from 'react';
import { urls } from '@jupiterx/control-panel';
import './style.scss';

const DarkModeButton = ( props ) => {
	const moonIcon = urls.controlPanel + 'img/setup-wizard/moon.svg';
	const sunIcon = urls.controlPanel + 'img/setup-wizard/sun.svg';

	return (
		<>
			<button
				className="jx-setup-wizard-dark-mode-btn"
				onClick={ props.handleDarkModeClick }
			>
				<label htmlFor="mode-checkbox" aria-label="Toggle dark mode">
					<input
						className="toggle-checkbox"
						id="mode-checkbox"
						type="checkbox"
						defaultChecked={ props.default }
					/>
					<div className="toggle-slot" >
						<div className="sun-icon-wrapper">
							<img src={ sunIcon } alt="sun" />
						</div>
						<div className="toggle-button"></div>
						<div className="moon-icon-wrapper">
							<img src={ moonIcon } alt="moon" />
						</div>
					</div>
				</label>
			</button>
		</>
	);
};

export default DarkModeButton;
