import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import { Table, Button, Dropdown, Pagination } from 'react-bootstrap';
import Spinner from '../../components/spinner/index';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEdit, faTrashAlt } from '@fortawesome/free-solid-svg-icons';
import { Link } from 'react-router-dom';
import Dialog from '../../components/dialog';
import StartCard from './start-card';

const ListTable = ( {
	postType = 'jupiterx-icons',
	actions = [ 'view', 'edit' ],
	edit = () => {},
	view = () => {},
	refresh,
	newButton,
	createNew,
} ) => {
	const [ loading, setLoading ] = useState( true );
	const [ posts, setPosts ] = useState( [] );
	const [ maxNumPages, setMaxNumPages ] = useState( 1 );
	const [ columns, setColumns ] = useState( [] );
	const [ paged, setPaged ] = useState( 1 );
	const [ showDialog, setShowDialog ] = useState( false );
	const [ postToDelete, setPostToDelete ] = useState( 0 );

	// Initial post fetch and whenever paged is changed.
	useEffect( () => {
		fetchPosts();
	}, [ paged, refresh ] );

	// Fetch post.
	const fetchPosts = () => {
		setLoading( true );

		wp.ajax.send( 'jupiterx_custom_icons_get_posts', {
			type: 'GET',
			data: {
				nonce,
				post_type: postType,
				paged,
			},
			dataType: 'json',
		} ).done( ( data ) => {
			addIconCountToTitle( data.posts );
			setPosts( data.posts );
			setMaxNumPages( data.max_num_pages );
			setColumns( data.columns );
			setLoading( false );
		} ).fail( ( data ) => {
			// eslint-disable-next-line no-console
			console.error( data );
		} );
	};

	const addIconCountToTitle = ( postsData ) => {
		postsData.map( ( post ) => {
			const postContent = JSON.parse( post.post_content );
			post.display_title = post.post_title + ` (${ postContent.count })`;

			return post;
		} );

		return postsData;
	};

	const remove = ( post ) => {
		if ( 0 === post ) {
			return;
		}

		wp.ajax.post( {
			action: 'jupiterx_custom_icons',
			sub_action: 'remove_post',
			nonce,
			post_id: post.ID,
		} )
			.done( () => {
				fetchPosts();
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	// Paginate.
	const paginate = ( number ) => {
		if ( number === paged ) {
			return;
		}

		setPaged( number );
	};

	// Display delete confirm dialog.
	const confirmRemove = ( post ) => {
		setPostToDelete( post );
		setShowDialog( true );
	};

	// Prepare pagination markup.
	const getPagination = () => {
		const active = paged;
		const items = [];

		for ( let number = 1; number <= maxNumPages; number++ ) {
			items.push(
				<Pagination.Item
					key={ number }
					active={ number === active }
					onClick={ () => paginate( number ) }>
					{ number }
				</Pagination.Item>,
			);
		}

		return <Pagination>{ items }</Pagination>;
	};

	return (
		<div className="custom-icon-list-table">
			{ loading && <Spinner /> }
			{ ! loading && posts.length < 1 &&
				<StartCard action={ newButton }></StartCard>
			}
			{ ! loading && posts.length > 0 &&
				<>
					<div className="custom-icons-list-header">
						<span>
							{ __( 'Custom icons', 'jupiterx-core' ) }
						</span>
						<Button
							onClick={ createNew }
							variant="primary">
							{ __( 'Add New', 'jupiterx-core' ) }
						</Button>
					</div>
					<Table bordered hover>
						<thead>
							<tr className="custom_icons_table_head">
								<th className="position-relative header-boxer">
									<span> { __( 'Icon Set Name', 'jupiterx-core' ) } </span>
								</th>
								{ columns.labels.map( ( column, index ) => (
									<th key={ index } className="ps-3">{ column }</th>
								) ) }
								<th></th>
							</tr>
						</thead>
						<tbody>
							{ posts.map( ( post, index ) => (
								<tr key={ index } className="custom_icons_table_body">
									<td className="jupiterx-custom-icon-field-name">
										<div className="title-wrapper">
											<span // eslint-disable-line
												className="custom-icons-title"
												onClick={ () => props.edit( post ) }
												onKeyDown={ () => props.edit( post ) }
											>
												{ post.display_title }
											</span>
										</div>
									</td>
									{ Object.keys( columns.values ).length > 1 && columns.values[ `post_${ post.ID }` ].map(
										( column, counter ) => {
											// add the author edit link.
											// Counter 0 is the author.
											if ( 0 === counter ) {
												return <td className="ps-3" key={ counter }>
													<a href={ post.user_url } target="_blank" >
														{ column }
													</a>
												</td>;
											}
											return <td key={ counter } className="ps-3"> { column } </td>;
										}
									) }
									<td>
										<div className="actions-wrapper">
											{ actions.includes( 'edit' ) &&
											<Button
												variant="link"
												data-src={ post.ID }
												as={ Link }
												to={ 'custom-icons' }
												className="jupiterx-custom-icon-action-edit text-decoration-none"
												onClick={ () => edit( post ) }
											>
											</Button>
											}
											<Dropdown className="jupiterx-custom-icon-action-more">
												<Dropdown.Toggle variant="link">
													<i className="action-more-icon"></i>
												</Dropdown.Toggle>

												<Dropdown.Menu>
													<Dropdown.Item
														className="jupiterx-custom-icon-action-edit mt-2"
														onClick={ () => edit( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faEdit } />
														{ __( 'Edit', 'jupiterx-core' ) }
													</Dropdown.Item>

													<Dropdown.Item
														className="jupiterx-custom-icon-action-delete mt-2"
														onClick={ () => confirmRemove( post ) }
													>
														<FontAwesomeIcon className="me-2 mb-1" icon={ faTrashAlt } />
														{ __( 'Delete', 'jupiterx-core' ) }
													</Dropdown.Item>
												</Dropdown.Menu>
											</Dropdown>
										</div>
									</td>
								</tr>
							) ) }
						</tbody>
					</Table>
					{
						showDialog &&
						<Dialog
							className="jupiterx-custom-icon-delete-confirm"
							show
							variant="warning"
							title={ __( 'Remove the icon set', 'jupiterx-core' ) }
							onCancel={ () => setShowDialog( false ) }
							onOk={ () => {
								remove( postToDelete );
								setShowDialog( false );
							} }
							closeButton={ false }
							okText={ __( 'Remove', 'jupiterx-core' ) }
							cancelText={ __( 'Discard', 'jupiterx-core' ) }
						>
							{ __( 'Are you sure you want to delete this icon set? This action can’t be undone.', 'jupiterx-core' ) }
						</Dialog>
					}
				</>
			}
			{ maxNumPages > 1 && getPagination() }
		</div>
	);
};

export default ListTable;
