import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import logo from '../../components/header/logo';
import { Button, Form, Col, Row } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import Dialog from '../../components/dialog';
import { nonce } from '@jupiterx/control-panel';
import Spinner from '../../components/spinner';
import './style.scss';

const PopupHeader = () => {
	const [ isLoading, setIsLoading ] = useState( false );
	const [ addNewDialog, setAddNewDialog ] = useState( false );
	const [ unfilteredDialog, setUnfilteredDialog ] = useState( false );
	const [ isTemplateLoaded, setIsTemplateLoaded ] = useState( false );
	const { register, errors = {}, handleSubmit } = useForm();

	useEffect( () => {
		handlePopupSubMenu();
		loadTemplate();
	}, [] );

	const handlePopupSubMenu = () => {
		const JxMenu = document.getElementById( 'toplevel_page_jupiterx' );

		if ( ! JxMenu.classList.contains( 'wp-menu-open' ) ) {
			return;
		}

		const popupMenuItem = JxMenu.querySelectorAll( 'a[href*="edit.php?post_type=jupiterx-popups"]' );

		if ( ! popupMenuItem ) {
			return;
		}

		popupMenuItem[ 0 ].classList.add( 'current', 'active' );
		popupMenuItem[ 0 ].parentNode.classList.add( 'current', 'active' );
	};

	const handleNewPopup = ( data ) => {
		if ( ! data.url ) {
			return;
		}

		window.open( data.url, '_self' );
	};

	const onSubmit = ( fields ) => {
		setIsLoading( true );

		wp.ajax.post( {
			action: 'jupiterx_add_new_popup',
			nonce,
			title: fields.template_name,
		} )
			.done( ( data ) => {
				handleNewPopup( data );
				setAddNewDialog( false );
				setIsLoading( false );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
				setIsLoading( false );
			} );
	};

	const loadTemplate = () => {
		const headerEnd = document.getElementsByClassName( 'wp-header-end' );

		wp.ajax.send( 'jupiterx_get_import_form', {
			type: 'GET',
			dataType: 'json',
		} ).done( ( data ) => {
			headerEnd[ 0 ].insertAdjacentHTML( 'afterend', data.content );

			setIsTemplateLoaded( true );
		} ).fail( ( data ) => {
			// eslint-disable-next-line no-console
			console.error( data );
		} );
	};

	const uploadTemplate = ( event ) => {
		event.preventDefault();
		const importTemplate = document.getElementById( 'jupiterx-import-template-area' ),
			importForm = document.getElementById( 'jupiterx-import-template-form' );

		if ( ! importTemplate ) {
			return;
		}

		importTemplate.style.display = window.getComputedStyle( importTemplate ).display === 'none' ? 'block' : 'none';

		importForm.addEventListener( 'submit', handleUploadTemplate );
	};

	const handleUploadTemplate = ( event ) => {
		if ( window.elementorCommon.config.filesUpload.unfilteredFiles ) {
			return;
		}

		event.preventDefault();
		setUnfilteredDialog( true );
	};

	const enableAndUpload = () => {
		wp.ajax.post( {
			action: 'enable_unfiltered_files_upload',
			nonce,
		} )
			.done( () => {
				setUnfilteredDialog( true );
				const importForm = document.getElementById( 'jupiterx-import-template-form' );

				importForm.submit();
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const importWithoutEnabling = () => {
		setUnfilteredDialog( false );

		window.elementorCommon.config.filesUpload.unfilteredFiles = true;

		const importForm = document.getElementById( 'jupiterx-import-template-form' );

		importForm.submit();
	};

	const unfilteredFiltesDialog = () => {
		return (
			<Dialog
				className="jx-filtered-files-popup-import-dialog"
				title={ __( 'Enable Unfiltered File Uploads', 'jupiterx-core' ) }
				show={ true }
				okText={ __( 'Enable and Import', 'jupiterx-core' ) }
				cancelText={ __( 'Import Without Enabling', 'jupiterx-core' ) }
				showCancel={ true }
				closeButton={ false }
				onHide={ () => {
					setUnfilteredDialog( false );
				} }
				onOk={ enableAndUpload }
				onCancel={ importWithoutEnabling }
			>
				{ __( 'Before you enable unfiltered files upload, note that such files include a security risk. Elementor does run a process to remove possible malicious code, but there is still risk involved when using such files.', 'jupiterx-core' ) }
				<br />
				<br />
				{ __( 'If you do not enable uploading unfiltered files, any SVG or JSON (including lottie) files used in the uploaded template will not be imported.', 'jupiterx-core' ) }
			</Dialog>
		);
	};

	return (
		<>
			<div className="jx-popup-admin-wrapper">
				<div className="jx-popup-admin-header">
					<div className="logo">
						{ logo }
						<h6>{ __( 'POPUPS', 'jupiterx' ) }</h6>
					</div>
					<ul className="d-flex align-items-center">
						<Button
							onClick={ () => setAddNewDialog( true ) }
						>
							{ __( 'Add New', 'jupiterx-core' ) }
						</Button>
						<Button
							onClick={ uploadTemplate }
							disabled={ ! isTemplateLoaded }
						>
							{ __( 'Import Templates', 'jupiterx-core' ) }
						</Button>
					</ul>
				</div>
			</div>
			<Dialog
				className="jx-add-new-popup-dialog"
				title={ __( 'Add New Popup Template', 'jupiterx-core' ) }
				show={ addNewDialog }
				okText={ isLoading ? <Spinner /> : __( 'Create', 'jupiterx-core' ) }
				cancelText={ __( 'Discard', 'jupiterx-core' ) }
				showCancel={ true }
				closeButton={ true }
				onOk={ handleSubmit( onSubmit ) }
				onCancel={ () => setAddNewDialog( false ) }
				onHide={ () => setAddNewDialog( false ) }
				cancelProps={ { variant: 'outline-secondary' } }
			>
				<Form onSubmit={ ( event ) => event.preventDefault() }>
					<Row>
						<Form.Group as={ Col } sm="12" className="mb-3">
							<Form.Label htmlFor="template_name" className="d-flex align-items-center">
								{ __( 'Template Name', 'jupiterx-core' ) }
							</Form.Label>
							<Form.Control
								type="text"
								id="template_name"
								name="template_name"
								defaultValue=""
								placeholder={ __( 'Optional', 'jupiterx-core' ) }
								{ ...register( 'template_name', { required: 'This field is required' } ) }
							/>
							{
								errors.template_name &&
								<Form.Control.Feedback type="invalid" className="d-block">
									{ errors.template_name.message || 'This field is required' }
								</Form.Control.Feedback>
							}
						</Form.Group>
					</Row>
				</Form>
			</Dialog>
			{ unfilteredDialog && unfilteredFiltesDialog() }
		</>
	);
};

export default PopupHeader;
