import React, { useReducer, useEffect, useState, useMemo } from 'react';
import $ from 'jquery';
import useInfiniteScroll from 'react-infinite-scroll-hook';
import { __ } from '@wordpress/i18n';
import Spinner from '../../../components/spinner';
import TemplateCard from './template-card';
import ShadowCards from './shadow-cards';
import ImportDialog from './import-dialog';
import SearchFilters from './search-filters';
import Empty from './empty';
import TemplateInstalled from './template-installed';
import { initialState, reducer, actions } from './reducer';
import { nonce } from '@jupiterx/control-panel';
import './style.scss';

const useJQHXR = () => {
	const [ jqxhr, setJQXHR ] = useState( null );

	const abort = () => {
		if ( jqxhr && jqxhr.abort ) {
			jqxhr.abort();
		}
	};

	useEffect( () => () => {
		abort();
	}, [ jqxhr ] );

	return ( state ) => {
		abort();
		return setJQXHR( state );
	};
};

const Templates = ( { handleSetSimplicityMode } ) => {
	const [ {
		data,
		foundPosts,
		filters,
		page,
		isLoading,
		hasNextPage,
		postsPerPage,
		productId,
		isPro,
		templateImport,
		simplicityMode,
	}, dispatch ] = useReducer( reducer, initialState );

	const jqxhr = useJQHXR();

	const handleFetch = () => {
		dispatch( {
			type: actions.LOADING,
			payload: true,
		} );

		jqxhr( $.ajax( {
			type: 'POST',
			url: _wpUtilSettings.ajax.url,
			data: {
				action: 'jupiterx_core_cp_get_templates',
				filters: {
					...filters,
					product_id: productId,
					posts_per_page: postsPerPage,
					page,
				},
				nonce,
			},
		} ).done( ( res ) => {
			dispatch( {
				type: actions.FETCH,
				payload: res,
			} );
		} ) );
	};

	const handleImport = ( post ) => {
		dispatch( {
			type: actions.IMPORT,
			payload: post,
		} );
	};

	const handleFilters = ( newFilters ) => {
		dispatch( {
			type: actions.FILTERS,
			payload: newFilters,
		} );
	};

	const handleCancel = () => {
		dispatch( {
			type: actions.IMPORT,
			payload: false,
		} );
	};

	/**
	 * todo: Use ratio threshold https://github.com/onderonur/react-infinite-scroll-hook/issues/8
	 */
	const [ infiniteRef ] = useInfiniteScroll( {
		onLoadMore: handleFetch,
		loading: isLoading,
		rootMargin: '800px',
		hasNextPage,
	} );

	useEffect( () => {
		handleFetch();
	}, [ filters ] );

	const renderCards = useMemo( () => data.map( ( post ) => (
		<TemplateCard
			key={ post.id }
			id={ post.id }
			title={ post.title }
			slug={ post.slug }
			demo={ post.demo_url }
			psd={ post.psd }
			sketch={ post.is_sketch }
			free={ post.free_template }
			plugins={ post.list_of_used_plugins }
			image={ post.featured_image }
			pro={ isPro }
			simplicity={ simplicityMode }
			onImport={ handleImport }
		/>
	) ), [ data ] );

	const hasData = data && data.length > 0;

	return (
		<>
			<TemplateInstalled />
			<ImportDialog show={ !! templateImport } onHide={ handleCancel } templateImport={ templateImport } handleSetSimplicityMode={ handleSetSimplicityMode } simplicity={ simplicityMode } />
			<h6 className="d-flex align-items-center font-weight-bold mb-3">
				{ __( 'Templates', 'jupiterx-core' ) }
			</h6>
			<SearchFilters foundPosts={ foundPosts } filters={ filters } onChange={ handleFilters } />
			<div className="jx-cp-templates">
				{ hasData && renderCards }
				{ ( ! hasData && isLoading ) && (
					<ShadowCards count={ postsPerPage } />
				) }
				{ ( isLoading && hasData ) && (
					<Spinner size="lg" />
				) }
				{ ( ! hasData && ! isLoading ) && (
					<Empty />
				) }
				{ hasData && hasNextPage && (
					<div ref={ infiniteRef } style={ { height: '1px' } } />
				) }
			</div>
		</>
	);
};

export default Templates;
