import React, { useState } from 'react';
import { __ } from '@wordpress/i18n';
import Spinner from '../../components/spinner/index';
import { nonce } from '@jupiterx/control-panel';
import IconSetList from './icon-set-list';
const $ = jQuery;

const IconHandler = ( props ) => {
	const [ uploadedFile, setUploadedFile ] = useState( null );
	const [ uploaded, setUploaded ] = useState( false );
	const [ iconSetData, setIconSetData ] = useState( props.previousData || [] );

	const handleZipUpload = ( event ) => {
		setUploaded( false );
		const file = event.target.closest( '#iconZip' ).files;
		setUploadedFile( file[ 0 ] );
		uploadZip();
	};

	const uploadZip = () => {
		const form = new FormData();
		const file = $( '#iconZip' ).prop( 'files' )[ 0 ];
		form.append( 'action', 'jupiterx_custom_icons' );
		form.append( 'sub_action', 'upload_handler' );
		form.append( 'nonce', nonce );
		form.append( 'file', file, file.name );
		form.append( 'ext', 'zip' );

		wp.ajax.send( 'jupiterx_custom_icons_get_posts', {
			type: 'post',
			processData: false,
			contentType: false,
			cache: false,
			dataType: 'json',
			data: form,
			nonce,
		} ).done( ( data ) => {
			setUploaded( true );
			setIconSetData( data.config );
			document.querySelector( '.show-upload-error-result' ).innerText = '';
		} ).fail( ( data ) => {
			// eslint-disable-next-line no-console
			console.error( data );
			setUploaded( 'failed' );
			document.querySelector( '.show-upload-error-result' ).innerText = data;
		} );
	};

	return (
		<>
			{ ( uploadedFile && ! uploaded && uploaded !== 'failed' ) && <Spinner /> }
			{ ( ( ! uploadedFile || ( uploadedFile && uploaded === 'failed' ) ) && ! props.previousData ) && <>
				<input type="file" name="iconZip" id="iconZip" accept=".zip" onChange={ ( e ) => handleZipUpload( e ) } />
				<label htmlFor="iconZip" className="mt-2 btn btn-md btn-primary px-4">
					{ __( 'Upload Icon File', 'jupiterx-core' ) }
				</label>
				<p className="text-muted text-secondary">
					{ __( 'Please upload Fontastic, Fontello or Icomoon package as a .zip file', 'jupiterx-core' ) }
				</p>
			</> }
			<p className="show-upload-error-result text-danger"></p>
			{ iconSetData.name && <IconSetList formRef={ props.formRef } data={ iconSetData } defaultValues={ props.defaultValues } /> }
		</>
	);
};

export default IconHandler;
