import React, { forwardRef, useState, useEffect } from 'react';
import { Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { withRegister } from '../utils';

const DirectionControl = forwardRef( ( props, ref ) => {
	const [ value, setValue ] = useState( 'down' );

	useEffect( () => {
		if ( ( typeof props.triggerControl !== 'undefined' ) && props.triggerControl?.defaultValue ) {
			setValue( props.triggerControl.defaultValue?.direction );
		}
	}, [] );

	const getDefaultValue = () => {
		const defaultValue = props.triggerControl?.defaultValue?.value;
		const fallbackValue = props.triggerControl?.default;

		// For number fields, 0 can be a valid value, so we check more carefully
		if ( defaultValue !== null && defaultValue !== undefined && defaultValue !== false ) {
			// Convert to string to ensure compatibility with form inputs
			return typeof defaultValue === 'number' ? String( defaultValue ) : defaultValue;
		}

		// Fall back to the default from trigger control definition
		if ( fallbackValue !== null && fallbackValue !== undefined && fallbackValue !== false ) {
			// Convert to string to ensure compatibility with form inputs
			return typeof fallbackValue === 'number' ? String( fallbackValue ) : fallbackValue;
		}

		// Return empty string if no valid default
		return '';
	};

	return (
		<>
			<Form.Group className="d-flex align-items-center me-3 popup-trigger-type-direction">
				<Form.Label htmlFor={ props.rowName + '_control' }>
					{ __( 'Direction', 'jupiterx-core' ) }
				</Form.Label>
				{ (() => {
					const registerProps = withRegister( ref, props.rowName + '[control][direction]', ( event ) => setValue( event.target.value ) );
					return (
						<Form.Control
					as="select"
					id={ props.rowName + '_control' }
					className="popup-trigger-control"
					name={ props.rowName + '[control][direction]' }
							value={ value }
							{ ...registerProps }
				>
					{
						! _.isEmpty( props.triggerControl.values ) && Object.keys( props.triggerControl.values ).map( ( option, key ) => {
							return <option key={ key } value={ option } >{ props.triggerControl.values[ option ] }</option>;
						} )
					}
				</Form.Control>
				);
				})() }
			</Form.Group>
			{ ( 'down' === value ) && <Form.Group className="d-flex align-items-center">
				<Form.Label htmlFor={ props.rowName + '_control' }>
					{ props.triggerControl.label }
				</Form.Label>
				{ (() => {
					const registerProps = withRegister( ref, props.rowName + '[control][value]' );
					return (
						<Form.Control
					className="popup-trigger-control"
					type="number"
					name={ props.rowName + '[control][value]' }
					min={ props.triggerControl.min }
					step={ props.triggerControl.step }
					defaultValue={ getDefaultValue() }
					{ ...registerProps }
				/>
				);
				})() }
			</Form.Group> }
		</>
	);
} );

export default DirectionControl;
