import React from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCircle } from '@fortawesome/free-regular-svg-icons';
import { faCheckCircle } from '@fortawesome/free-solid-svg-icons';
import classnames from 'classnames';

const Steps = ( { steps = [] } ) => {
	return (
		<div className="jx-cp-import-steps">
			{ steps.map( ( { title, text, done }, key ) => {
				const className = classnames( {
					'd-flex align-items-center': true,
					'mb-2': key < ( steps.length - 1 ),
				} );
				const iconClassName = classnames( {
					'd-block me-2': true,
					'text-secondary': ! done,
					'text-success': done,
				} );
				const icon = done ? faCheckCircle : faCircle;

				return (
					<div key={ key } className={ className }>
						<span><FontAwesomeIcon icon={ icon } className={ iconClassName } /></span>
						<span>{ title }</span>
						{ text && (
							<small className="ms-2">{ text }</small>
						) }
					</div>
				);
			} ) }
		</div>
	);
};

export default Steps;
