import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { __ } from '@wordpress/i18n';
import { Button, Form, Spinner } from 'react-bootstrap';
import { nonce, customSnippetsLocations } from '@jupiterx/control-panel';
import Conditions from '../../components/conditions';
import AceEditor from 'react-ace';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAngleLeft } from '@fortawesome/free-solid-svg-icons';
import 'ace-builds/src-noconflict/theme-terminal';
import 'ace-builds/src-noconflict/theme-github';
import 'ace-builds/src-noconflict/mode-php';

const Post = ( props ) => {
	const { register, handleSubmit } = useForm();
	const [ switchStatus, setSwitchStats ] = useState( true );
	const [ conditions, setConditions ] = useState( [] );
	const [ snippet, setSnippet ] = useState( '' );
	const [ submit, setSubmit ] = useState( 'creating' );

	useEffect( () => {
		if ( _.isUndefined( props.post ) ) {
			return;
		}

		if ( props.post.conditions ) {
			setConditions( props.post.conditions );
		}

		if ( props.post.post_content ) {
			setSnippet( props.post.post_content );
		}
	}, [] );

	const onSubmit = ( post ) => {
		setSubmit( 'saving' );
		setSnippet( post.custom_snippets_post_content );

		post.custom_snippets_post_content = document.getElementById( 'custom-snippet-value-on-change' ).value;

		wp.ajax.post( {
			action: 'jupiterx_custom_snippets',
			sub_action: 'save_post',
			post,
			conditions,
			nonce,
		} )
			.done( () => {
				setSubmit( 'creating' );
				props.afterSubmit();
			} )
			.fail( ( data ) => {
				setSubmit( 'creating' );
				document.getElementsByClassName( 'show-error-result' )[ 0 ].innerHTML = data;
			} );
	};

	const Locations = customSnippetsLocations;

	const Editor = () => {
		return (
			<AceEditor
				name="aceEditor"
				setOptions={ { useWorker: false } }
				mode="php"
				theme="github"
				onChange={ EditorChange }
				width="100%"
				value={ snippet }
				height="250px" />
		);
	};

	const EditorChange = ( value ) => {
		document.getElementById( 'custom-snippet-value-on-change' ).value = value;
	};

	const switchClick = () => {
		let status = false;
		if ( false === switchStatus ) {
			status = true;
		}
		setSwitchStats( status );
	};

	const setFields = ( fields ) => {
		setConditions( fields );
		setSnippet( document.getElementById( 'custom-snippet-value-on-change' ).value );
	};

	return (
		<div className="custom-snippets-add-new">
			<div className="header-wrapper">
				<span className="header">
					{
						'new' === props.mode
							? __( 'Add Custom Snippet', 'jupiterx-core' )
							: __( 'Edit Custom Snippet', 'jupiterx-core' )
					}
				</span>
				{
					<Button
						variant="secondary"
						className="px-4 post-back-button"
						onClick={ props.backButton }
					>
						<FontAwesomeIcon icon={ faAngleLeft } className="me-2" />
						{ __( 'Back', 'jupiterx-core' ) }
					</Button>
				}
			</div>
			<Form onSubmit={ handleSubmit( onSubmit ) }>
				<Form.Group className="step-wrapper">
					<Form.Label className="steps-desc">
						{ __( '1. What is the name of this custom snippet?', 'jupiterx-core' ) }
					</Form.Label>
					<Form.Control
						type="text"
						id="custom_title"
						defaultValue={ props.post.post_title }
						name="custom_snippets_post_title"
						className="w-25"
						placeholder={ __( 'Enter a name', 'jupiterx-core' ) }
						{ ...register( 'custom_snippets_post_title' ) }
					/>
				</Form.Group>
				<hr />
				<Form.Group className="step-wrapper">
					<Form.Label className="steps-desc">
						{ __( '2. Where do you want to insert your custom snippet?', 'jupiterx-core' ) }
					</Form.Label>
					<div className="d-flex">
						<Form.Control
							as="select"
							id="custom_location"
							defaultValue={ props.post.location }
							className="w-25"
							name="custom_snippets_post_location"
							{ ...register( 'custom_snippets_post_location' ) }
						>
							{
								Object.keys( Locations ).map( ( oneKey, i ) => {
									return (
										<option key={ i } value={ oneKey }>{ Locations[ oneKey ] }</option>
									);
								} )
							}
						</Form.Control>
					</div>
				</Form.Group>
				<hr />
				<Form.Group className="step-wrapper">
					<Form.Label className="steps-desc">
						{ __( '3. In which priority the custom snippet will be inserted?', 'jupiterx-core' ) }
					</Form.Label>
					<div className="d-flex">
						<Form.Control
							as="select"
							id="custom_priority"
							defaultValue={ props.post.priority }
							className="w-25"
							name="custom_snippets_post_priority"
							{ ...register( 'custom_snippets_post_priority' ) }
						>
							<option value="1">1</option>
							<option value="2">2</option>
							<option value="3">3</option>
							<option value="4">4</option>
							<option value="5">5</option>
							<option value="6">6</option>
							<option value="7">7</option>
							<option value="8">8</option>
							<option value="9">9</option>
							<option value="10">10</option>
							<option value="20">20</option>
							<option value="30">30</option>
							<option value="40">40</option>
							<option value="50">50</option>
							<option value="60">60</option>
							<option value="70">70</option>
							<option value="80">80</option>
							<option value="90">90</option>
							<option value="100">100</option>
						</Form.Control>
					</div>
				</Form.Group>
				<hr />
				<Form.Group className="step-wrapper">
					<div className="mt-3" id="editor_wrapper" style={ { minHeight: 300 + 'px' } } >
						<Form.Label className="steps-desc">
							{ __( '4. What is the content of this custom snippet?', 'jupiterx-core' ) }
						</Form.Label>
						<Editor />
						<input
							type="hidden"
							id="custom-snippet-value-on-change"
							name="custom_snippets_post_content"
							defaultValue={ snippet }
							{ ...register( 'custom_snippets_post_content' ) }
						/>
					</div>
				</Form.Group>
				<hr />
				<Form.Group className="step-wrapper snippets-conditions-wrapper">
					<Form.Label className="steps-desc">
						{ __( '5. In which condition do you want to insert this code?', 'jupiterx-core' ) }
					</Form.Label>
					<Conditions
						place="custom-snippet"
						post={ props.post.ID }
						fields={ ( fields ) => setFields( fields ) }
					/>
				</Form.Group>
				<hr />
				<div className="submit-area">
					<div className="checkbox-wrap">
						<Form.Check
							type="switch"
							id="custom_snippets_status"
							checked={ switchStatus }
							onChange={ switchClick }
							value="active"
							name="custom_snippets_post_status"
							label={
								'new' === props.mode
									? __( 'Active this immediately after it is created.', 'jupiterx-core' )
									: __( 'Activate', 'jupiterx-core' )
							}
							{ ...register( 'custom_snippets_post_status' ) }
						/>
						<Form.Control
							size="sm"
							className="d-none"
							type="text"
							defaultValue={ props.post.ID }
							name="custom_snippets_submit_mode"
							id="custom_snippets_submit_mode"
							{ ...register( 'custom_snippets_submit_mode' ) }
							onChange={ handleSubmit }
						/>
					</div>
					{
						'creating' === submit &&
						<Button
							variant="primary"
							className="mt-2 new-custom-snippets-submit"
							type="submit"
							onClick={ handleSubmit }
						>
							{
								props.mode === 'edit'
									? __( 'Update', 'jupiterx-core' )
									: __( 'Create', 'jupiterx-core' )
							}
						</Button>
					}
					{
						'saving' === submit &&
						<Button
							variant="primary"
							className="mt-2 new-custom-snippets-submit saving-mode"
						>
							<Spinner
								as="span"
								animation="border"
								size="sm"
								role="status"
								aria-hidden="true"
								className="me-2"
							/>
							<span>{ __( 'Saving', 'jupiterx-core' ) }</span>
						</Button>
					}
					<Button
						variant="outline-danger"
						className="float-end mt-2 remove-btn"
						onClick={ props.removeBtn }
					>
						{ __( 'Remove', 'jupiterx-core' ) }
					</Button>
					<p className="show-error-result"></p>
				</div>
			</Form>
		</div>
	);
};

export default Post;
