import React, { useState, useEffect } from 'react';
import { __ } from '@wordpress/i18n';
import Dialog from '../../components/dialog';

const IconSetList = ( props ) => {
	const [ showDialog, setShowDialog ] = useState( props.data.duplicatePrefix );
	const [ iconsList, setIconsList ] = useState( [] );
	const [ postContent, setPostContent ] = useState( '' );

	useEffect( () => {
		const iconSetData = props.data;
		const prefix = iconSetData.prefix;

		const list = iconSetData.icons.map( ( icon, index ) => {
			const iconName = icon.replace( '-', ' ' );

			return <div key={ index + icon } className={ 'iconset-icon ' + icon }>
				<i className={ prefix + icon }></i>
				<span className="jx-icon-title">{ iconName }</span>
			</div>;
		} );

		const content = {
			name: iconSetData.name,
			prefix,
			count: iconSetData.count,
			icons: [
				...iconSetData.icons,
			],
			path: iconSetData.path,
			url: iconSetData.url,
			ver: iconSetData.ver,
		};

		setPostContent( JSON.stringify( content ) );
		setIconsList( list );
		removePreviousLinkTags();
		addStylesheetToHeader( iconSetData.url, iconSetData.name );
	}, [ props.data ] );

	/*
	 * Remove previously added link tags for style files of the icon sets.
	 */
	const removePreviousLinkTags = () => {
		const previousLinkTagStyles = document.querySelectorAll( '[id$="-jx-custom-icon-stylesheet"]' );
		if ( previousLinkTagStyles.length ) {
			previousLinkTagStyles.forEach( ( previousLinkTagStyle ) => {
				previousLinkTagStyle.remove();
			} );
		}
	};

	/*
	 * Create and add new stylesheet link tag to head.
	 */
	const addStylesheetToHeader = ( url, name ) => {
		const linkTag = document.createElement( 'link' );
		const attributes = {
			rel: 'stylesheet',
			id: name + '-jx-custom-icon-stylesheet',
			href: url,
		};

		Object.assign( linkTag, attributes );
		document.head.appendChild( linkTag );
	};

	return (
		<>
			<div className="jx-icon-set-data">
				<div className="jx-icon-name">
					<span>{ __( 'Name:', 'jupiterx-core' ) } </span>
					<strong>{ props.data.name }</strong>
				</div>
				<span className="separator">|</span>
				<div className="jx-icon-css-prefix">
					<span>{ __( 'CSS Prefix:', 'jupiterx-core' ) } </span>
					<strong>{ props.data.prefix }</strong>
				</div>
				<span className="separator">|</span>
				<div className="jx-icon-count">
					<span>{ __( 'Icons Count:', 'jupiterx-core' ) } </span>
					<strong>{ props.data.count }</strong>
				</div>
			</div>
			<div className="iconset-icons-wrapper">
				{ iconsList }
			</div>
			<input type="hidden" { ...props.formRef( 'icon_set_config' ) } defaultValue={ JSON.stringify( props.data ) } />
			<input type="hidden" { ...props.formRef( 'icon_set_path' ) } defaultValue={ props.data.path } />
			<input type="hidden" { ...props.formRef( 'icon_set_content' ) } defaultValue={ postContent } id="icon_set_content" />
			{
				showDialog &&
				<Dialog
					className="jupiterx-custom-icon-duplicate-prefix"
					show
					variant="warning"
					title={ __( 'Duplicate icon set prefix', 'jupiterx-core' ) }
					onOk={ () => setShowDialog( false ) }
					okText={ __( 'Ok', 'jupiterx-core' ) }
				>
					{ __( 'The Icon Set prefix already exists in your site. In order to avoid conflicts we recommend to use a unique prefix per Icon Set.', 'jupiterx-core' ) }
				</Dialog>
			}
		</>
	);
};

export default IconSetList;
