import React, { forwardRef } from 'react';
import NumberControl from './fields/number';
import TextControl from './fields/text';
import DateControl from './fields/date';
import DirectionControl from './fields/direction';
import DateRangeControl from './fields/date-range';
import TimeRangeControl from './fields/time-range';
import DropDownControl from './fields/drop-down';
import MultiSelectControl from './fields/multi-select';
import 'react-datepicker/dist/react-datepicker.css';
import './style.scss';

const TirggerControl = forwardRef( ( props, ref ) => {
	const fieldProps = { ...props };

	const fields = {
		direction: DirectionControl,
		number: NumberControl,
		text: TextControl,
		date: DateControl,
		'date-range': DateRangeControl,
		'time-range': TimeRangeControl,
		'multi-select': MultiSelectControl,
		'drop-down': DropDownControl,
	};

	if ( props.triggerControl.type !== 'multi-select' ) {
		fieldProps.ref = ref;
	}

	return (
		React.createElement( fields[ props.triggerControl.type ], fieldProps )
	);
} );

export default TirggerControl;
