import React, { forwardRef } from 'react';
import { Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { timezones } from '@jupiterx/control-panel';

const TimeRangeControl = forwardRef( ( props, ref ) => {
	const getDefaultValue = ( value ) => {
		// If no value, return empty string
		if ( ! value && value !== '' && value !== 0 ) {
			return '';
		}

		// If it's already a string, return it
		if ( typeof value === 'string' ) {
			return value;
		}

		// If it's a number, convert to string
		if ( typeof value === 'number' ) {
			return String( value );
		}

		// For any other type, return empty string
		return '';
	};

	return (
		<Form.Group className={ `jupiterx-popup-time-range-wrapper d-flex align-items-center popup-trigger-type-${ props.triggerControl.type }` }>
			<Form.Label htmlFor={ props.rowName + '[control][start_time]' }>
				{ __( 'Start Time', 'jupiterx-core' ) }
			</Form.Label>
			<Form.Control
				className="jupiterx-popup-time-range-value form-control me-3"
				type="time"
				name={ props.rowName + '[control][start_time]' }
				defaultValue={ getDefaultValue( props?.triggerControl?.defaultValue?.start_time ) }
				{ ...ref( props.rowName + '[control][start_time]' ) }
			/>
		<Form.Label htmlFor={ props.rowName + '[control][due_time]' }>
			{ __( 'End Time', 'jupiterx-core' ) }
		</Form.Label>
		<Form.Control
			className="jupiterx-popup-time-range-value form-control me-2"
			type="time"
			name={ props.rowName + '[control][due_time]' }
			defaultValue={ getDefaultValue( props?.triggerControl?.defaultValue?.due_time ) }
			{ ...ref( props.rowName + '[control][due_time]' ) }
		/>
		<div className="jupiterx-popup-time-range-timezone-wrapper ms-2">
			<Form.Control
				as="select"
				className="jupiterx-popup-time-range-timezone form-control"
				name={ props.rowName + '[control][timezone]' }
				defaultValue={ getDefaultValue( props?.triggerControl?.defaultValue?.timezone ) }
				{ ...ref( props.rowName + '[control][timezone]' ) }
			>
					<option key={ 0 } value="UTC" >{ __( 'Select Timezone', 'jupiterx-core' ) }</option>
					{ timezones.map( ( timezone, index ) => <option key={ index } value={ timezone }> { timezone }</option> ) }
				</Form.Control>
			</div>
		</Form.Group>
	);
} );

export default TimeRangeControl;
