import React, { useState } from 'react';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import Dialog from '../../../components/dialog';

const Revoke = ( { show, onHide } ) => {
	const [ isLoading, setIsLoading ] = useState( false );
	const [ data, setData ] = useState( null );
	const [ error, setError ] = useState( null );

	const handleOk = () => {
		setIsLoading( true );

		wp.ajax.post( 'jupiterx_cp_revoke_license', { nonce } ).fail( ( res ) => {
			setError( res );
		} ).done( ( res ) => {
			setData( res );
		} ).always( () => {
			setIsLoading( false );
		} );
	};

	const handleReload = () => {
		setIsLoading( true );
		window.location.reload();
	};

	const handleClose = () => {
		onHide();

		// Put delay before updating local state to avoid modal content flash.
		setTimeout( () => {
			setIsLoading( false );
			setData( null );
			setError( null );
		}, 200 );
	};

	if ( data ) {
		return (
			<Dialog
				variant="success"
				onHide={ handleReload }
				show={ show }
				title={ __( 'Revoke successful', 'jupiterx-core' ) }
				isLoading={ isLoading }
				onOk={ handleReload }
			>
				{ data.message }
			</Dialog>
		);
	} else if ( isLoading ) {
		return (
			<Dialog
				variant="progress"
				show={ show }
				title={ __( 'Revoke API key', 'jupiterx-core' ) }
			>
				{ __(
					'Please wait while your API key is being revoked.',
					'jupiterx-core'
				) }
			</Dialog>
		);
	} else if ( error ) {
		return (
			<Dialog
				variant="error"
				onHide={ handleClose }
				show={ show }
				title={ __( 'Revoke was unsuccessful', 'jupiterx-core' ) }
			>
				{ error.message || __( 'An error occured while revoking the license, please try again.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	return (
		<Dialog
			title={ __( 'Revoke API key', 'jupiterx-core' ) }
			showCancel={ true }
			variant="warning"
			show={ show }
			onHide={ onHide }
			onOk={ handleOk }
			okText={ __( 'Yes', 'jupiterx-core' ) }
		>
			{ __( 'You are about to remove API key from this website. Are you sure you want to continue?', 'jupiterx-core' ) }
		</Dialog>
	);
};

export default Revoke;
