import React, { useEffect, forwardRef, useState } from 'react';
import { Form } from 'react-bootstrap';
import { popupConditions } from '@jupiterx/control-panel';
import SubIdCondition from './sub-id-condition';

const SubConditions = forwardRef( ( props, ref ) => {
	const [ subName, setSubName ] = useState( '' );
	const [ subNameCondition, setSubCondition ] = useState( {} );

	useEffect( () => {
		if ( ! _.isEmpty( props.data ) && _.isEmpty( props.name ) && ! typeof props.data.sub_id !== 'undefined' ) {
			setSubName( props.data.sub_name );
			setSubCondition( popupConditions[ props.data.sub_name ] );
		} else {
			setSubName( '' );
			setSubCondition( {} );
		}
	}, [ props.name ] );

	const handleSubCondition = ( event ) => {
		const conditionKey = event.currentTarget.selectedOptions[ 0 ].value;

		if ( _.isEmpty( popupConditions[ conditionKey ].sub_id ) ) {
			setSubName( '' );
			setSubCondition( {} );
		}

		setSubName( conditionKey );
		setSubCondition( popupConditions[ conditionKey ] );
	};

	return (
		<>
			<Form.Group className="popup-condition-sub-name-group">
				<Form.Control
					as="select"
					className="popup-condition-sub-name"
					name={ props.rowName + '[sub_name]' }
					defaultValue={ ( typeof props.data !== 'undefined' ) && props.data.sub_name }
					{ ...ref( props.rowName + '[sub_name]' ) }
					onChange={ handleSubCondition }
				>
					<option value={ props.name }>
						{ props.subCondition.all_label }
					</option>
					{
						Object.keys( props.subCondition.sub_conditions ).map( ( subCondition, key ) => {
							if ( ! _.isEmpty( popupConditions[ props.subCondition.sub_conditions[ key ] ].sub_conditions ) ) {
								return (
									<optgroup label={ popupConditions[ props.subCondition.sub_conditions[ key ] ].all_label } key={ key }>
										<option value={ props.subCondition.sub_conditions[ key ] }>
											{ popupConditions[ props.subCondition.sub_conditions[ key ] ].all_label }
										</option>
										{
											popupConditions[ props.subCondition.sub_conditions[ key ] ].sub_conditions.map( ( optItem, optKey ) => {
												return (
													<option
														key={ optKey }
														value={ optItem }
													>
														{
															popupConditions[ optItem ]?.label
														}
													</option>
												);
											} )
										}
									</optgroup>
								);
							}

							return (
								<option
									key={ key }
									value={ props.subCondition.sub_conditions[ key ] }
								>
									{
										popupConditions[ props.subCondition.sub_conditions[ key ] ].label
									}
								</option>
							);
						} )
					}
				</Form.Control>
			</Form.Group>
			{
				// eslint-disable-next-line
				! _.isEmpty( subNameCondition?.sub_id ) && <SubIdCondition
					rowName={ props.rowName }
					name={ subName }
					subIdCondition={ subNameCondition }
					ref={ ref }
					conditionControl={ props.conditionControl }
					data={ props.data }
				/>
			}
		</>
	);
} );

export default SubConditions;
