import React, { useContext, useState, useEffect } from 'react';
import $ from 'jquery';
import { Card, Button } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { TemplatesContext } from '../../../../store/templates';
import ShadowCards from '../shadow-cards';
import RemoveDialog from './remove-dialog';
import HelpLink from '../../../../components/help-link';
import { nonce } from '@jupiterx/control-panel';
import './style.scss';

export const clearText = ( text ) => {
	return text.replace( 'jupiterx', '' ).replace( 'Jupiterx', '' );
};

const TemplateInstalled = () => {
	const [ showRemove, setShowRemove ] = useState( false );
	const [ isLoading, setIsLoading ] = useState( false );

	const {
		templateInstalled: { id, title, image, demo },
		setTemplateInstalled,
	} = useContext( TemplatesContext );

	// When image and demo urls are not available, try fetching from API server.
	useEffect( () => {
		// Required before fetch.
		if ( ! id && ! title ) {
			return;
		}
		// Also, when image and demo exists. Do nothing.
		if ( image && demo ) {
			return;
		}

		setIsLoading( true );

		$.post( _wpUtilSettings.ajax.url, {
			action: 'jupiterx_core_cp_template_lazy_load',
			from: 0,
			count: 1,
			template_id: id,
			template_name: title,
			nonce,
		} ).done( ( { status, data } ) => {
			setIsLoading( false );

			if ( status === true && data.templates.length > 0 ) {
				setTemplateInstalled( {
					id,
					title: data.templates[ 0 ].name,
					image: data.templates[ 0 ].img_url,
					demo: `https://jupiterx.artbees.net/${ data.templates[ 0 ].slug.replace( '-jupiterx', '' ) }`,
				} );
			}
		} );
	}, [ id, title, image, demo ] );

	if ( ! title || ! id ) {
		return null;
	}

	return (
		<>
			<RemoveDialog show={ showRemove } onHide={ () => setShowRemove( false ) } title={ title } />
			<div className="jx-cp-template-installed">
				<h6 className="d-flex align-items-center font-weight-bold mb-3">
					{ __( 'Installed Template', 'jupiterx-core' ) }
					<HelpLink href="https://themes.artbees.net/docs/installing-a-template/" title={ __( 'Installing a Template', 'jupiterx-core' ) } />
				</h6>
				{ isLoading ? (
					<ShadowCards count={ 1 } />
				) : (
					<Card>
						<Card.Img variant="top" style={ { backgroundImage: `url(${ image })` } } />
						<Card.Body>
							{ title && (
								<h5 className="mb-3">{ clearText( title ) }</h5>
							) }
							<Button
								className="me-2"
								size="sm"
								variant="danger"
								onClick={ () => setShowRemove( true ) }
							>
								{ __( 'Remove', 'jupiterx-core' ) }
							</Button>
							{ demo && (
								<Button
									className="me-2"
									size="sm"
									variant="outline-secondary"
									target="_blank"
									href={ demo }
								>
									{ __( 'Preview', 'jupiterx-core' ) }
								</Button>
							) }
						</Card.Body>
					</Card>
				) }
			</div>
		</>
	);
};

export default TemplateInstalled;
