import React from 'react';
import classnames from 'classnames';
import { ProgressBar, Button, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCheckCircle, faTimesCircle, faExclamationCircle } from '@fortawesome/free-solid-svg-icons';
import { __ } from '@wordpress/i18n';
import Modal from './modal';
import Spinner from './spinner/index';

const noop = () => {};

const DEFAULT_ICONS = {
	success: faCheckCircle,
	warning: faExclamationCircle,
	error: faTimesCircle,
};

const ICONS_COLOR = {
	success: 'text-success',
	warning: 'text-warning',
	error: 'text-danger',
};

const Dialog = ( {
	className,
	show,
	title,
	titleAs,
	header,
	footer,
	children,
	variant,
	onOk,
	onCancel,
	onSubmit,
	icon,
	iconClassName,
	okText,
	cancelText,
	submitText,
	okProps = {},
	cancelProps = {},
	submitProps = {},
	isLoading = false,
	onHide = noop,
	closeButton = true,
	showOk = true,
	showCancel = false,
	progressNow = 100,
	okBtnAjax = false,
	...props
} ) => {
	const isProgress = variant === 'progress';

	const headerClassName = classnames( {
		'align-items-center': true,
		'flex-wrap': isProgress,
	} );

	if ( icon ) {
		icon = icon;
	} else if ( ! isProgress ) {
		icon = DEFAULT_ICONS[ variant ];
	}

	iconClassName = classnames( {
		'h4 m-0 me-2': true,
		[ `${ iconClassName }` ]: iconClassName,
		[ `${ ICONS_COLOR[ variant ] }` ]: ICONS_COLOR[ variant ],
	} );

	if ( typeof header === 'undefined' ) {
		header = (
			<>
				{ isProgress && (
					<ProgressBar className="w-100 mb-3" now={ progressNow } animated />
				) }
				{ ( title || icon ) && (
					<Modal.Title className="d-flex align-items-center" as={ titleAs }>
						{ icon && (
							<FontAwesomeIcon
								className={ iconClassName }
								icon={ icon }
							/>
						) }
						{ title }
					</Modal.Title>
				) }
			</>
		);
	}

	if ( typeof footer === 'undefined' && ! isProgress ) {
		footer = (
			<>
				{ onSubmit && (
					<Button disabled={ isLoading } type="submit" size="sm" { ...submitProps }>
						{ submitText || __( 'Submit', 'jupiterx-core' ) }
					</Button>
				) }
				{ ( ! onSubmit && showOk ) && (
					<Button disabled={ isLoading } onClick={ onOk || onHide } size="sm" { ...okProps } >
						{ okText || __( 'OK', 'jupiterx-core' ) }
						{ okBtnAjax && <Spinner /> }
					</Button>
				) }
				{ ( onSubmit || onCancel || showCancel ) && (
					<Button disabled={ isLoading } onClick={ onCancel || onHide } variant="secondary" size="sm" { ...cancelProps }>
						{ cancelText || __( 'Cancel', 'jupiterx-core' ) }
					</Button>
				) }
			</>
		);
	}

	const content = (
		<>
			{ header && (
				<Modal.Header className={ headerClassName }	closeButton={ closeButton && ! isProgress }>
					{ header }
				</Modal.Header>
			) }
			{ children && (
				<Modal.Body>
					{ children }
				</Modal.Body>
			) }
			{ footer && (
				<Modal.Footer>
					{ footer }
				</Modal.Footer>
			) }
		</>
	);

	return (
		<Modal
			show={ show }
			className={ className }
			onHide={ ( ! isLoading && ! isProgress ) ? onHide : noop }
			{ ...props }>
			{ onSubmit ? <Form onSubmit={ onSubmit }>{ content }</Form> : content }
		</Modal>
	);
};

export default Dialog;
