import React, { useContext, useState } from 'react';
import { Button, Spinner } from 'react-bootstrap';
import dayjs from 'dayjs';
import { AppContext } from '../../../';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSync } from '@fortawesome/free-solid-svg-icons';
import { __, sprintf } from '@wordpress/i18n';
import { appActionTypes } from '../../../reducer';
import UpdateList from './list';
import './style.scss';
import { updateAjaxPlugin, fetchUpdates, toggleAutoUpdater } from './util';
import Alert from '../../../components/alert';
import Register from '../../dashboard/license/register';
import { themeLicense, isPremium, activePlugins } from '@jupiterx/control-panel';

const isUpdating = ( appState ) => {
	return appState.updates.list
		.filter( ( item ) => item.status === 'updating' ).length > 0;
};

const isUpdatingAll = ( appState ) => {
	return appState.updates.all;
};

const isUpdatedAll = ( appState ) => {
	const newList = appState.updates.list.filter( ( item ) => {
		if ( item.type === 'plugin' && ! activePlugins.includes( item.basename ) ) {
			return false;
		}

		return true;
	} );

	if ( newList.length === 0 ) {
		return true;
	}

	const updated = appState.updates.list
		.filter( ( item ) => item.status === 'updated' )
		.length;

	return updated === appState.updates.list.length;
};

const isAutoUpdateBtnDisabled = ( appState ) => {
	return isUpdating( appState ) ||
		isUpdatingAll( appState ) ||
		appState.updates.fetching ||
		appState.updates.auto === 'saving';
};

const isUpdateAllBtnDisabled = ( appState ) => {
	return isUpdating( appState ) ||
	isUpdatingAll( appState ) ||
	isUpdatedAll( appState ) ||
	appState.updates.fetching;
};

const isCheckUpdatesBtnDisabled = ( appState ) => {
	return isUpdating( appState ) ||
		isUpdatingAll( appState ) ||
		appState.updates.fetching;
};

const updateAll = ( { appState, appDispatch } ) => {
	if ( isUpdatedAll( appState ) ) {
		return;
	}

	appDispatch( {
		type: appActionTypes.APP_UPDATE_ALL,
		payload: true,
	} );

	appDispatch( {
		type: appActionTypes.APP_QUEUE_ALL_UPDATES,
	} );

	updatePlugins( { appState, appDispatch } );
};

const updatePlugins = ( { appState, appDispatch } ) => {
	const plugins = appState.updates.list
		.filter( ( item ) => ( item.type === 'plugin' || item.type === 'theme' ) && item.status !== 'updated' && item.status !== 'error' );

	if ( plugins.length === 0 ) {
		appDispatch( {
			type: appActionTypes.APP_UPDATE_ALL,
			payload: ! isUpdatedAll( appState ),
		} );

		return;
	}

	updateAjaxPlugin( {
		appDispatch,
		plugin: plugins[ 0 ],
		successCallback: () => {
			updatePlugins( { appState, appDispatch } );
		},
		errorCallback: () => {
			updatePlugins( { appState, appDispatch } );
		},
	} );
};

const formatLastChecked = ( timestamp ) => {
	let format = __( 'Last checked on', 'jupiterx-core' ) + ' ';
	format += dayjs.unix( timestamp ).format( 'MMM D, YYYY ' );
	format += __( 'at', 'jupiterx-core' );
	format += dayjs.unix( timestamp ).format( ' H:mm' );

	return format;
};

const Updates = () => {
	const { appState, appDispatch } = useContext( AppContext );
	const [ showRegisterModal, setShowRegisterModal ] = useState( false );

	const handleToggleRegisterModal = () => {
		setShowRegisterModal( ! showRegisterModal );
	};

	const notRegisteredUserContent = (
		<div>
			<Alert className="d-flex align-items-center" variant="danger">
				{ __( 'This section is disabled because you have not registered a license yet.', 'jupiterx-core' ) + ' ' }
				<Button className="mb-1 p-0" size="sm" variant="link" onClick={ handleToggleRegisterModal }>Register your license now.</Button>
			</Alert>
			<Button size="sm" onClick={ handleToggleRegisterModal }>
				{ __( 'Register license', 'jupiterx-core' ) }
			</Button>
			<Register
				show={ showRegisterModal }
				onHide={ handleToggleRegisterModal }
			/>
		</div>
	);

	const updateContent = <div className="jx-cp-updates">
		<div className="jx-cp-updates-actions d-flex flex-column flex-md-row mt-3 mt-md-0 justify-content-between align-items-start">
			<div className="d-flex flex-column">
				<Button
					size="sm"
					variant="outline-secondary"
					className="align-self-start"
					disabled={ isCheckUpdatesBtnDisabled( appState ) }
					onClick={ () => fetchUpdates( { appDispatch, post: { force: true } } ) }>
					{ __( 'Check for updates', 'jupiterx-core' ) }
				</Button>
				{
					appState.updates.lastChecked &&
					! appState.updates.fetching &&
					<div className="jx-cp-updates-last-updated">{ formatLastChecked( appState.updates.lastChecked ) }</div>
				}
			</div>
			<div className="d-flex align-items-sm-center mt-3 mt-md-0 flex-column flex-sm-row">
				<Button
					size="sm"
					variant={ `outline-${ appState.updates.auto === 'enabled' ? 'primary' : 'secondary' }` }
					className="me-3"
					disabled={ isAutoUpdateBtnDisabled( appState ) }
					onClick={ () => toggleAutoUpdater( { appDispatch, appState } ) }>
					<FontAwesomeIcon icon={ faSync } className={ `me-2 ${ appState.updates.auto === 'saving' ? 'fa-spin' : '' }` } />
					{ 	// translators: %s State
						sprintf( __( '%s auto update', 'jupiterx-core' ), appState.updates.auto !== 'enabled' ? __( 'Enable', 'jupiterx-core' ) : __( 'Disable', 'jupiterx-core' ) ) }
				</Button>
				<Button
					size="sm"
					variant="primary"
					className="mt-3 mt-sm-0"
					disabled={ isUpdateAllBtnDisabled( appState ) }
					onClick={ () => updateAll( { appState, appDispatch } ) }>
					{
						isUpdatingAll( appState ) &&
						<Spinner
							className="me-2"
							as="span"
							animation="border"
							size="sm"
							role="status"
							aria-hidden="true"></Spinner>
					}
					<span>{ __( 'Update all', 'jupiterx-core' ) }</span>
				</Button>
			</div>
		</div>
		{ <UpdateList appState={ appState } /> }
	</div>;

	return ( ! isPremium || themeLicense.is_registered ) ? updateContent : notRegisteredUserContent;
};

export default Updates;
