import React, { useState } from 'react';
import { Button, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faQuestionCircle } from '@fortawesome/free-regular-svg-icons';
import { __, sprintf } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import Dialog from '../../../components/dialog';
import Tooltip from '../../../components/tooltip';

const Register = ( { show, onHide } ) => {
	const [ isUseAPIKey, setIsUseAPIKey ] = useState( false );
	const [ isLoading, setIsLoading ] = useState( false );
	const [ data, setData ] = useState( null );
	const [ error, setError ] = useState( null );

	const handleSubmit = ( event ) => {
		event.preventDefault();

		const elements = event.target.elements;
		const action = 'jupiterx_cp_register_license';
		const params = {
			nonce,
		};

		if ( isUseAPIKey ) {
			params.mode = 'api_key';
			params.api_key = elements.api_key.value;
		} else {
			params.mode = 'purchase_code';
			params.email = elements.email.value;
			params.purchase_code = elements.purchase_code.value;
		}

		setIsLoading( true );
		wp.ajax.post( action, params ).fail( ( res ) => {
			setError( res );
		} ).done( ( res ) => {
			setData( res );
		} ).always( () => {
			setIsLoading( false );
		} );
	};

	const handleToggleUseAPIKey = () => {
		setIsUseAPIKey( ! isUseAPIKey );
	};

	const handleClose = () => {
		onHide();

		// Put delay before updating local state to avoid modal content flash.
		setTimeout( () => {
			setIsUseAPIKey( false );
			setIsLoading( false );
			setData( null );
			setError( null );
		}, 200 );
	};

	const handleReload = () => {
		setIsLoading( true );
		// Reload on success.
		window.location.reload();
	};

	if ( data ) {
		return (
			<Dialog
				variant="success"
				onHide={ handleReload }
				show={ show }
				title={ __( 'Thanks for registration!', 'jupiterx-core' ) }
				isLoading={ isLoading }
				onOk={ handleReload }
			>
				{ data.message }
			</Dialog>
		);
	} else if ( isLoading ) {
		return (
			<Dialog
				variant="progress"
				show={ show }
				title={ __( 'Register Jupiter X', 'jupiterx-core' ) }
			>
				{ __(
					'Please wait while your API key is being verified.',
					'jupiterx-core'
				) }
			</Dialog>
		);
	} else if ( error ) {
		return (
			<Dialog
				variant="error"
				onHide={ handleClose }
				show={ show }
				title={ __( 'Oops! Registration was unsuccessful', 'jupiterx-core' ) }
			>
				{ error.message || __( 'An error occured while registering the license, please try again.', 'jupiterx-core' ) }
			</Dialog>
		);
	}

	return (
		<Dialog
			title={ __( 'Register Jupiter X', 'jupiterx-core' ) }
			show={ show }
			onHide={ handleClose }
			onSubmit={ handleSubmit }
		>
			{ isUseAPIKey ? (
				<>
					<Form.Group className="d-flex align-items-center mb-3" controlId="api_key">
						<Form.Control
							required
							name="api_key"
							type="text"
							placeholder={ __(
								'Artbees API Key',
								'jupiterx-core'
							) }
						/>
						<Tooltip
							trigger="click"
							overlay={
								<span dangerouslySetInnerHTML={ {
									__html: sprintf(
										// translators: %s Link to help
										__( 'Please check <a class="dashboard-register-tooltip-link" target="_blank" href="%s">this</a> to learn how to find your API key.', 'jupiterx-core' ),
										'https://themes.artbees.net/docs/registering-the-jupiter-x-theme/#getting_an_api_key',
									),
								} } />
							}
						>
							<FontAwesomeIcon
								icon={ faQuestionCircle }
								className="text-primary ms-2"
								style={ { fontSize: '16px' } }
							/>
						</Tooltip>
					</Form.Group>
					<Form.Group className="m-0">
						<Button
							className="p-0"
							size="sm"
							variant="link"
							onClick={ handleToggleUseAPIKey }
						>
							{ __(
								'Insert Envato purchase code',
								'jupiterx-core'
							) }
						</Button>
					</Form.Group>
				</>
			) : (
				<>
					<Form.Group className="d-flex align-items-center mb-3" controlId="email">
						<Form.Control
							required
							name="email"
							type="email"
							placeholder={ __(
								'Email Address',
								'jupiterx-core'
							) }
						/>
						<Tooltip trigger="click" overlay={ __( 'This address will be used to provide you technical support', 'jupiterx-core' ) }>
							<FontAwesomeIcon
								icon={ faQuestionCircle }
								className="text-primary ms-2"
								style={ { fontSize: '16px' } }
							/>
						</Tooltip>
					</Form.Group>
					<Form.Group className="d-flex align-items-center mb-3" controlId="purchase_code">
						<Form.Control
							required
							name="purchase_code"
							type="text"
							placeholder={ __(
								'Envato Purchase Code',
								'jupiterx-core'
							) }
						/>
						<Tooltip
							trigger="click"
							overlay={
								<span dangerouslySetInnerHTML={ {
									__html: sprintf(
										// translators: %s Link to help
										__( 'Please check <a class="dashboard-register-tooltip-link" target="_blank" href="%s">this</a> to learn how to find your purchase code.', 'jupiterx-core' ),
										'https://help.jupiterx.com/article/20-how-to-locate-your-purchase-code-on-themeforest',
									),
								} } />
							}
						>
							<FontAwesomeIcon
								icon={ faQuestionCircle }
								className="text-primary ms-2"
								style={ { fontSize: '16px' } }
							/>
						</Tooltip>
					</Form.Group>
					<Form.Group className="mb-3">
						<Button
							className="p-0"
							size="sm"
							variant="link"
							onClick={ handleToggleUseAPIKey }
						>
							{ __( 'Or insert API key', 'jupiterx-core' ) }
						</Button>
					</Form.Group>
					<Form.Group controlId="terms" className="m-0">
						<Form.Check
							required
							name="terms"
							type="checkbox"
							label={ __(
								'I consent to Artbees Themes collecting my personal information according to its Privacy policy and Terms of use.',
								'jupiterx-core'
							) }
						/>
					</Form.Group>
				</>
			) }
		</Dialog>
	);
};

export default Register;
