
import { urls } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';

const PopupHeader = ( props ) => {
	return (
		<div className="conditions-triggers-header-wrapper">
			<img className="conditions-triggers-logo" src={ urls.imgUrl + '/popup/' + props.icon + '.svg' } alt={ __( 'popup builder', 'jupiterx-core' ) } />
			<h5 className="conditions-triggers-title">
				{ props.heading }
			</h5>
			<div className="conditions-triggers-text">
				{ props.firstDescription }
				{
					! _.isEmpty( props.secondDescription ) &&
					<>
						<br />
						{ props.secondDescription }
					</>
				}
			</div>
		</div>
	);
};

export default PopupHeader;
