import React, { useState, forwardRef, useEffect } from 'react';
import Spinner from '../../../../components/spinner/index';
import PopupHeader from '../popup-header';
import Triggers from './triggers';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';

const PopupTabTirgger = forwardRef( ( props, ref ) => {
	const [ loading, setLoading ] = useState( true );
	const [ triggers, setTriggers ] = useState( [] );

	let documentId = null;

	useEffect( () => {
		if ( ! _.isEmpty( elementor.documents.getCurrent() ) ) {
			documentId = elementor.documents.getCurrent().id;
		}

		getTriggers( documentId );
	}, [] );

	const getTriggers = () => {
		setLoading( true );

		wp.ajax.post( {
			action: 'jupiterx_popup_get_triggers',
			nonce,
			popup_id: documentId,
		} ).done( ( result ) => {
			setTriggers( result );
			setLoading( false );
		} ).fail( () => {
			setLoading( false );
		} );
	};

	const headerData = {
		icon: 'triggers',
		heading: __( 'Trigger Rules', 'jupiterx-core' ),
		firstDescription: __( 'Define trigger rules that will show Popup when conditions are met.', 'jupiterx-core' ),
		secondDescription: '',
	};

	return (
		<>
			<PopupHeader { ...headerData } />
			{ loading && <Spinner size="lg" /> }
			{ ! loading && <Triggers data={ triggers } ref={ ref } conditionControl={ props.conditionControl } conditionUnregister={ props.conditionUnregister } conditionSetValue={ props.conditionSetValue } /> }
		</>
	);
} );

export default PopupTabTirgger;
