import { isEmpty, omitBy } from 'lodash';

function getPostsPerPage() {
	const screenWidth = window.innerWidth;
	let $postsPerPage;

	switch ( true ) {
		case screenWidth > 1809 :
			$postsPerPage = 15;
			break;

		case screenWidth > 1509 && screenWidth <= 1809 :
			$postsPerPage = 12;
			break;

		case screenWidth >= 1140 && screenWidth <= 1509 :
			$postsPerPage = 9;
			break;

		case screenWidth >= 680 && screenWidth <= 1139 :
			$postsPerPage = 8;
			break;

		default :
			$postsPerPage = 6;
			break;
	}

	return $postsPerPage;
}

export const initialState = {
	isLoading: true,
	isPro: false,
	error: null,
	data: [],
	foundPosts: 0,
	simplicityMode: false,
	page: 1,
	hasNextPage: true,
	productId: 25348,
	postsPerPage: getPostsPerPage(),
	templateImport: false,
	filters: {},
};

export const actions = {
	FETCH: 'FETCH',
	LOADING: 'LOADING',
	IMPORT: 'IMPORT',
	FILTERS: 'FILTERS',
};

export const reducer = ( state, { type, payload } ) => {
	switch ( type ) {
		case actions.FETCH:
			const posts = Array.isArray( payload.posts )
				? [ ...state.data, ...payload.posts ]
				: [ ...state.data ];

			return {
				...state,
				isLoading: false,
				isPro: payload.is_pro,
				data: [ ...posts ],
				page: state.page + 1,
				hasNextPage: posts.length < parseInt( payload.found_posts ),
				foundPosts: payload.found_posts,
				simplicityMode: payload.simplicity_mode,
			};
		case actions.LOADING:
			return {
				...state,
				isLoading: payload,
			};
		case actions.IMPORT:
			return {
				...state,
				templateImport: payload,
			};
		case actions.FILTERS:
			return {
				...initialState,
				// Clear empty filters.
				filters: omitBy( payload, isEmpty ),
			};
		default:
			return {
				...state,
			};
	}
};
