import React, { useState, useEffect } from 'react';
import { nonce } from '@jupiterx/control-panel';
import Spinner from './../../../components/spinner';
import Header from './header';
import ContentView from './content-view';

const Templates = ( props ) => {
	const [ paged, setPaged ] = useState( 1 );
	const [ posts, setPosts ] = useState( [] );
	const [ loading, setLoading ] = useState( false ); // show or hide spinner
	const [ hasNextPage, setHasNextPage ] = useState( true );
	const [ content, setContent ] = useState( '' ); // Contents to show! posts or conditions
	const [ filter, setFilter ] = useState( 'all' );
	const [ filterType, setFilterType ] = useState( 'all' );
	const [ allConditions, setAllConditions ] = useState( [] );
	const [ newPost, setNewPost ] = useState( false );
	const [ preventFetch, setPreventFetch ] = useState( false );

	useEffect( () => {
		fetchPosts( 'new' );
	}, [ props.type, filter, filterType ] );

	useEffect( () => {
		setContent( props.content );
	}, [ props.navigation ] );

	useEffect( () => {
		if ( ! newPost ) {
			return;
		}

		fetchPosts( 'new' );
	}, [ newPost ] );

	const fetchPosts = ( type = 'default' ) => {
		if ( preventFetch ) {
			return;
		}

		setLoading( true );

		if ( type === 'new' ) {
			setPosts( [] );
		}

		wp.ajax.post( {
			action: 'jupiterx_layout_builder',
			sub_action: 'get_posts',
			type: props.type,
			page: type !== 'new' ? paged : 1,
			filter_value: filter,
			filter_type: filterType,
			nonce,
		} )
			.done( ( data ) => {
				setLoading( false );

				if ( paged >= data.max ) {
					setHasNextPage( false );
				}

				if ( type !== 'new' ) {
					setPaged( paged + 1 );
				}

				const newPosts = data.posts.filter( ( post ) => ! posts.some( ( p ) => p.ID === post.ID ) );
				setPosts( ( currentPosts ) => currentPosts.concat( [ ...newPosts ] ) );

				gatherAllConditions( data.posts );
				setNewPost( false );
			} )
			.fail( () => {
				setLoading( false );
				setNewPost( false );
				setPosts( [] );
			} );
	};

	// This is required to solve conflicts between templates conditions as much as possible.
	const gatherAllConditions = ( postsArray ) => {
		const conditions = allConditions;

		postsArray.forEach( ( item ) => {
			const postItem = {};
			postItem.id = item.ID;
			postItem.title = item.post_title;
			postItem.conditions = item.conditions;
			postItem.condition_string = item.conditions_string;

			if ( _.isUndefined( postItem.id ) ) {
				postItem.id = item.id;
			}

			conditions.push( postItem );
		} );

		setAllConditions( conditions ); // will be passed to each item.
	};

	const afterImportTemplate = ( type ) => {
		setContent( type );
	};

	const handleNewTemplate = () => {
		setNewPost( true );
	};

	const attachNewPostToPosts = ( post ) => {
		setPreventFetch( true );
		setPosts( ( currentPosts ) => currentPosts.concat( [ post ] ) );

		// Scroll to the new attached post.
		setTimeout( () => {
			const element = document.querySelector( '.post-' + post.ID );
			if ( element ) {
				element.style.order = -( post.ID );
				element.scrollIntoView( {
					behavior: 'smooth',
					block: 'start',
					inline: 'nearest',
				} );
			}

			setPreventFetch( false );
		}, 1000 );
	};

	return (
		<>
			{
				'posts' === content &&
				<Header
					title={ props.title }
					type={ props.type }
					fetch={ handleNewTemplate }
					attach={ ( post ) => attachNewPostToPosts( post ) }
					import={ () => setContent( 'import' ) }
					goPosts={ () => setContent( 'posts' ) }
					filter={ ( value ) => setFilter( value ) }
					filterType={ ( value ) => setFilterType( value ) }
				/>
			}
			{
				( posts.length > 0 || content === 'import' ) && <ContentView
					loading={ loading }
					fetchPosts={ fetchPosts }
					posts={ posts }
					hasNextPage={ hasNextPage }
					content={ content }
					allConditions={ allConditions }
					type={ props.type }
					title={ props.title }
					afterImportTemplate={ afterImportTemplate }
					gatherAllConditions={ ( array ) => gatherAllConditions( array ) }
					simplicityMode={ props.simplicityMode }
				/>
			}
			{
				loading &&
				<Spinner
					as="span"
					animation="border"
					size="lg"
					role="status"
					aria-hidden="true"
				/>
			}
		</>
	);
};

export default Templates;
