import React, { useState } from 'react';
import Dialog from '../../components/dialog';
import Spinner from '../../components/spinner/index';
import { __ } from '@wordpress/i18n';
import { nonce } from '@jupiterx/control-panel';
import './style.scss';

const ThemeUpdateModal = () => {
	const [ showDialog, setShowDialog ] = useState( true );
	const [ isSaving, setSaving ] = useState( false );
	const [ dismissModal, setDismissModal ] = useState( false );
	const [ closeIconPrgress, setCloseIconPrgress ] = useState( false );

	const handleDismissModal = () => {
		setDismissModal( true );

		wp.ajax.post( {
			action: 'jupiterx_dismiss_theme_update_modal',
			nonce,
		} )
			.done( () => {
				setDismissModal( false );
				setShowDialog( false );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const handleCloseIcon = () => {
		setCloseIconPrgress( true );

		wp.ajax.post( {
			action: 'jupiterx_dismiss_theme_update_modal',
			nonce,
		} )
			.done( () => {
				setCloseIconPrgress( false );
				setShowDialog( false );
			} )
			.fail( ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			} );
	};

	const handleUpdateTheme = () => {
		setSaving( true );

		wp.ajax.send( 'jupiterx_theme_update_modal', {
			data: {
				nonce,
			},
			success: () => {
				wp.updates.ajax( 'update-theme', {
					slug: 'jupiterx',
					success: () => {
						setShowDialog( false );
						setSaving( false );

						setTimeout( () => window.location.reload() );
					},
					error: () => {
						setSaving( false );
						setShowDialog( false );
					},
				} );
			},
			error: ( response ) => {
				setSaving( false );
				setShowDialog( false );
			},
		} );
	};

	const getTitlte = () => {
		return (
			<>
				<h3 className="d-flex align-items-center h3">
					<svg aria-hidden="true" focusable="false" data-prefix="fas" data-icon="exclamation-circle" className="svg-inline--fa fa-exclamation-circle fa-w-16 h4 m-0 me-2 text-warning" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="currentColor" d="M504 256c0 136.997-111.043 248-248 248S8 392.997 8 256C8 119.083 119.043 8 256 8s248 111.083 248 248zm-248 50c-25.405 0-46 20.595-46 46s20.595 46 46 46 46-20.595 46-46-20.595-46-46-46zm-43.673-165.346l7.418 136c.347 6.364 5.609 11.346 11.982 11.346h48.546c6.373 0 11.635-4.982 11.982-11.346l7.418-136c.375-6.874-5.098-12.654-11.982-12.654h-63.383c-6.884 0-12.356 5.78-11.981 12.654z"></path></svg>
					{ __( 'New Update Ready for JupiterX!', 'jupiterx-core' ) }
				</h3>
				<button type="button" className="close" onClick={ handleCloseIcon }>
					{ closeIconPrgress ? <Spinner /> : <span aria-hidden="true">×</span> }
					<span className="sr-only">Close</span>
				</button>
			</>
		);
	};

	return (
		showDialog && <Dialog
			className="jupiterx-theme-update-modal"
			show={ showDialog }
			title={ getTitlte() }
			isLoading={ false }
			okText={ isSaving ? <Spinner /> : __( 'Update JupiterX Theme Now', 'jupiterx-core' ) }
			okProps={ { variant: 'primary' } }
			onOk={ handleUpdateTheme }
			cancelText={ dismissModal ? <Spinner /> : __( 'Discard', 'jupiterx-core' ) }
			cancelProps={ { variant: 'secondary' } }
			onCancel={ handleDismissModal }
			closeButton={ false }
			showCancel={ true }
		>
			{ __( 'We noticed you\'ve updated the JupiterX Core Plugin – great job staying up-to-date! But wait, your JupiterX theme version seems to be a step behind. To ensure your site runs smoothly and to avoid any hiccups, it\'s important to update your theme as well. It\'s just a click away!', 'jupiterx-core' ) }
		</Dialog>
	);
};

export default ThemeUpdateModal;
