import './style.scss';
import React, { useReducer, useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import {
	HashRouter as Router,
	Routes,
	Route,
	Navigate,
} from 'react-router-dom';
import { appInitialState, appReducer } from './reducer';
import { isPremium, SimplicityVersion } from '@jupiterx/control-panel';
import Header from './components/header';
import Dashboard from './views/dashboard';
import LayoutBuilder from './views/layout-builder';
import CustomSnippets from './views/custom-snippets';
import CustomFonts from './views/custom-fonts';
import CustomIcons from './views/custom-icons';
import Elementor from './views/elementor';
import Settings from './views/settings';
import Tools from './views/tools';
import Updates from './views/tools/updates';
import VersionControl from './views/tools/version-control';
import Logs from './views/tools/logs';
import ExportCard from './views/tools/export';
import Templates from './views/tools/templates';
import FreeVsPro from './views/free-vs-pro';
import IconLibrary from './views/icon-library';
import PopupHeader from './views/popup/header';
import PopupCondition from './views/popup/condition';
import { TemplatesProvider } from './store/templates';
import { SettingsProvider } from './store/settings';
import { fetchUpdates } from './views/tools/updates/util';
import WidgetsModal from './views/enable-widgets-modal';
import SetupWizard from './views/setup-wizard';
import ThemeUpdateModal from './views/theme-update-modal';

export const AppContext = React.createContext( null );

const controlPanel = document.getElementById( 'jx-cp-root' );
const popups = document.getElementById( 'jx-popup-root' );
const popupEditor = document.getElementById( 'jupiterx-conditons-root' );
const enableWidget = document.getElementById( 'jx-enable-widget-root' );
const themeUpdate = document.getElementById( 'jx-theme-update-root' );
const setupWizard = document.getElementById( 'jx-setup-wizard-root' );

const App = () => {
	const [ appState, appDispatch ] = useReducer( appReducer, appInitialState );
	const [ simplicityMode, setSimplicityMode ] = useState( false );

	useEffect( () => {
		fetchUpdates( { appDispatch } );
	}, [] );

	const handleSetSimplicityMode = ( value ) => {
		if ( ! SimplicityVersion ) {
			setSimplicityMode( '0' );

			return;
		}

		setSimplicityMode( value );
	};

	return (
		<AppContext.Provider value={ { appState, appDispatch } }>
			<TemplatesProvider>
				<SettingsProvider>
					<Router>
						<Header handleSetSimplicityMode={ handleSetSimplicityMode } simplicityMode={ simplicityMode } />
						<Routes>
							<Route exact path="/" element={ <Dashboard /> } />
							<Route path="/icon-library" component={ <IconLibrary /> } />
							<Route path="/custom-fonts" element={ <CustomFonts /> } />
							<Route path="/custom-icons" element={ <CustomIcons /> } />
							<Route path="/layout-builder">
								<Route index element={ <Navigate to="/layout-builder/header" replace /> } />
								<Route path=":templateKey" element={ <LayoutBuilder simplicityMode={ simplicityMode } /> } />
							</Route>
							<Route path="/custom-snippets" element={ <CustomSnippets /> } />
							<Route path="/elementor" element={ <Elementor /> } />
							<Route
								path="/settings"
								element={
									<Settings
										handleSetSimplicityMode={ handleSetSimplicityMode }
										simplicityMode={ simplicityMode }
									/>
								} />

							<Route path="/maintenance" element={ <Tools /> } />
							<Route path="/updates" element={ <Updates /> } />
							<Route
								path="/ready-made-websites"
								element={ <Templates handleSetSimplicityMode={ handleSetSimplicityMode } /> }
							/>
							<Route path="/version-rollback" element={ <VersionControl /> } />
							<Route path="/logs" element={ <Logs /> } />
							<Route path="/export" element={ <ExportCard /> } />
							{ ! isPremium && <Route path="/free-vs-pro" element={ <FreeVsPro /> } /> }
						</Routes>
					</Router>
				</SettingsProvider>
			</TemplatesProvider>
		</AppContext.Provider>
	);
};

const Popup = () => {
	return <PopupHeader />;
};

const PopupConditionRender = () => {
	return <PopupCondition />;
};

if ( controlPanel ) {
	const root = createRoot( controlPanel );
	root.render( <App /> );
}

if ( popups ) {
	const root = createRoot( popups );
	root.render( <Popup /> );
}

if ( popupEditor ) {
	const root = createRoot( popupEditor );
	root.render( <PopupConditionRender /> );
}

const WidgetsModalApp = () => {
	return (
		<SettingsProvider>
			<WidgetsModal />
		</SettingsProvider>
	);
};

const ThemeUpdataModalApp = () => {
	return (
		<SettingsProvider>
			<ThemeUpdateModal />
		</SettingsProvider>
	);
};

const SetupWizardApp = () => {
	return (
		<SettingsProvider>
			<SetupWizard />
		</SettingsProvider>
	);
};

if ( enableWidget ) {
	const root = createRoot( enableWidget );
	root.render( <WidgetsModalApp /> );
}

if ( themeUpdate ) {
	const root = createRoot( themeUpdate );
	root.render( <ThemeUpdataModalApp /> );
}

if ( setupWizard ) {
	const root = createRoot( setupWizard );
	root.render( <SetupWizardApp /> );
}

