import React from 'react';
import { nonce, adminAjaxURL } from '@jupiterx/control-panel';
import { __ } from '@wordpress/i18n';
import { Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faChevronLeft, faUpload } from '@fortawesome/free-solid-svg-icons';
import { useForm } from 'react-hook-form';

const ImportForm = ( props ) => {
	const { register, handleSubmit, formState: { } } = useForm();
	// eslint-disable-next-line
	const dragFiles = new DataTransfer();

	const setMessage = ( color, text ) => {
		const message = document.getElementById( 'jx-layout-builder-import-error-area' );
		message.innerText = text;
		message.style.color = color;
	};

	const processFile = ( file ) => {
		if ( ! file ) {
			setMessage( 'red', __( 'Please select a file', 'jupiterx-core' ) );
			return;
		}

		const allowedTypes = [ 'application/json', 'application/zip', 'application/x-zip-compressed' ];

		if ( _.isEmpty( file.type ) || ! allowedTypes.includes( file.type ) ) {
			document.getElementById( 'jx-layout-import-file-upload-btn' ).value = null;
			setMessage( 'red', __( 'Only .JSON or .ZIP files are allowed.', 'jupiterx-core' ) );
			return;
		}

		const form = new FormData();
		form.append( 'action', 'jupiterx_layout_builder' );
		form.append( 'sub_action', 'import' );
		form.append( 'nonce', nonce );
		form.append( 'file', file, 'json' );
		form.append( 'type', props.type );
		form.append( 'ext', file.type === 'application/json' ? 'json' : 'zip' );

		dragFiles.clearData();

		jQuery.ajax( {
			url: adminAjaxURL,
			type: 'post',
			processData: false,
			contentType: false,
			cache: false,
			dataType: 'json',
			data: form,
			beforeSend: () => {
				setMessage( 'blue', __( 'Importing...' ) );
				setTimeout( () => {
					// Empty. let user find out status of uploading.
				}, 1500 );
			},
			success: ( response ) => {
				document.getElementById( 'jx-layout-import-file-upload-btn' ).value = null;
				document.getElementById( 'jx-layout-import-file-upload-btn' ).value = '';

				if ( true === response.success ) {
					setMessage( 'green', response.data );

					setTimeout( () => {
						props.afterImportTemplateView( 'posts' );
						props.fetchPosts( 'new' );
					}, 1000 );
				}

				if ( false === response.success ) {
					setMessage( 'red', response.data );
				}
			},
		} );
	};

	const onSubmit = () => {
		const fileInput = document.getElementById( 'jx-layout-import-file-upload-btn' );
		const file = fileInput.files[ 0 ];
		processFile( file );
	};

	return (
		<div className="layout-builder-import-form">
			<div className="d-flex import-form-header">
				<Button
					variant="outline-secondary"
					onClick={ () => {
						props.afterImportTemplateView( 'posts' );
						props.fetchPosts( 'new' );
					} }
					className="condition-header-back"
					style={ { textAlign: 'start' } }
				>
					<FontAwesomeIcon icon={ faChevronLeft } className="me-2 mb-1" size="sm" />
					<span>{ __( 'Back', 'jupiterx-core' ) }</span>
				</Button>
			</div>
			<div
				className="import-file-handler"
				onDragOver={ ( e ) => e.preventDefault() }
				onDragEnter={ ( e ) => e.preventDefault() }
				onDrop={ ( e ) => {
					e.preventDefault();
					const file = e.dataTransfer.files[ 0 ];
					processFile( file );
				} }
			>
				<form
					className="jx-layout-builder-import-form"
					onSubmit={ handleSubmit( onSubmit ) }
					id="jx-layout-builder-import"
					method="post"
					encType="multipart/form-data"
				>
					<div className="jx-drop-area">
						<FontAwesomeIcon
							className="layout-builder-upload-import"
							icon={ faUpload }
							title={ __( 'Upload', 'jupiterx-core' ) }
						/>
						<span className="jx-drop-import-text">{ __( 'Import Template', 'jupiterx-core' ) }</span>
						<span className="jx-drop-drag-text">{ __( 'Drag & drop .JSON or .ZIP file', 'jupiterx-core' ) }</span>
						<span className="jx-drop-drag-or">{ __( 'or', 'jupiterx-core' ) }</span>
						<span className="jx-layout-builder-import-hidden-wrappers">
							<label htmlFor="jx-layout-import-file-upload-btn" className="jx-upload-file-wrapper">
								{ __( 'Select File', 'jupiterx-core' ) }
							</label>
							<input
								className="jx-layout-import-file-upload-btn"
								id="jx-layout-import-file-upload-btn"
								type="file"
								accept=".json,.zip"
								{ ...register( 'json', {
									required: true,
									onChange: ( e ) => {
										if ( e.target.files?.length ) {
											processFile( e.target.files[ 0 ] );
										}
									},
								} ) }
							/>
						</span>
						<button
							type="submit"
							className="jx-layout-import-submit-btn"
							id="jx-layout-import-submit-btn"
						>
							{ __( 'Submit', 'jupiterx-core' ) }
						</button>
						<span id="jx-layout-builder-import-error-area"></span>
					</div>
				</form>
			</div>
		</div>
	);
};

export default ImportForm;
