import React, { useState, useContext } from 'react';
import StepButton from '../compenents/step-button';
import { __ } from '@wordpress/i18n';
import ColorPalette from '../compenents/color-palette';
import ChooseColors from '../compenents/choose-colors';
import SkipWizardButton from '../compenents/skip-wizard-button';
import { SetupWizardContext } from '..';

const ColorsControl = ( props ) => {
	const context = useContext( SetupWizardContext );
	const [ selectedColors, setSelectedColors ] = useState( context.getLocalStorage( 'selected_color' ) );

	const handleColorPaletteClick = ( colors ) => {
		setSelectedColors( colors );
		context.setLocalStorage( 'selected_color', colors );
		context.setLocalStorage( 'custom2_color', colors[ 0 ] );
		context.setLocalStorage( 'custom1_color', colors[ 1 ] );
		context.setLocalStorage( 'accent_color', colors[ 2 ] );
		context.setLocalStorage( 'primary_color', colors[ 3 ] );
		context.setLocalStorage( 'body_text_color', colors[ 4 ] );
		context.setLocalStorage( 'secondary_color', colors[ 5 ] );
	};

	const updateStateByStorage = () => {
		handleColorPaletteClick( [
			context.getLocalStorage( 'custom2_color' ),
			context.getLocalStorage( 'custom1_color' ),
			context.getLocalStorage( 'accent_color' ),
			context.getLocalStorage( 'primary_color' ),
			context.getLocalStorage( 'body_text_color' ),
			context.getLocalStorage( 'secondary_color' ),
		] );
	};

	const handleBackClick = () => {
		setSelectedColors( null );
	};

	const colors = [
		[ '#FFFFFF', '#F5F7FF', '#EA4C89', '#4C63ED', '#484F5F', '#1E232E' ],
		[ '#FFFFFF', '#EEF4F6', '#23D26B', '#036675', '#25393C', '#00292F' ],
		[ '#FFFFFF', '#F1F6FF', '#17CBCB', '#1967FF', '#5D6983', '#1A1A1A' ],
		[ '#FFFFFF', '#F6EADE', '#E76F50', '#32695B', '#666666', '#150844' ],
		[ '#FFFFFF', '#F5F5F5', '#EF8E67', '#542D57', '#645757', '#242424' ],
		[ '#FFFFFF', '#F0F2F6', '#F6C65D', '#3B51F5', '#252830', '#000000' ],
		[ '#FFFFFF', '#E6ECE8', '#077A2F', '#7A7AE7', '#4F545A', '#151D2A' ],
		[ '#FFFFFF', '#FDF2F5', '#EE81A2', '#923954', '#675E5E', '#303133' ],
		[ '#FFFFFF', '#F5F5F5', '#7414F3', '#3970FB', '#2C3445', '#292B2E' ],
		[ '#FFFFFF', '#F9F9FA', '#D5378E', '#2A459F', '#5B5E8D', '#212C49' ],
		[ '#FFFFFF', '#F5F7FA', '#A1E13F', '#3C9F8D', '#89849F', '#121213' ],
	];

	return (
		<>
			<div className="step-colors-header">
				<h2>
					{ __( 'Splash Some Color!', 'jupiterx-core' ) }
				</h2>
				<p>
					{ __( 'Time to add your personal touch. Choose from a vibrant', 'jupiterx-core' ) + ' ' }
					<br />
					{ __( 'color palette to make your website shine.', 'jupiterx-core' ) }
				</p>
			</div>

			{ selectedColors ? (
				<ChooseColors
					colors={ selectedColors }
					onBackClick={ handleBackClick }
					updateState={ updateStateByStorage }
					stepRef={ props.stepRef }
				/>
			) : (
				<div className="step-color-body">
					<div className="row">
						{ colors.map( ( colColors, colIndex ) => {
							return (
								<div className="color-col" key={ colIndex }>
									<button
										className="row jx-setup-wizard-color-palettes"
										onClick={ () => handleColorPaletteClick( colColors ) }
									>
										<ColorPalette colors={ colColors } />
									</button>
								</div>
							);
						} ) }
					</div>
				</div>
			) }

			{ selectedColors &&
				<StepButton nextStep={ 'typography' } { ...props } />
			}

			{ ! selectedColors &&
				<SkipWizardButton />
			}
		</>
	);
};

export default ColorsControl;
