import React, { useState, forwardRef, useEffect } from 'react';
import { Button } from 'react-bootstrap';
import ConditionRow from './row';
import { __ } from '@wordpress/i18n';

export const ConditionsContext = React.createContext();

const Conditions = forwardRef( ( props, ref ) => {
	const [ rowNumber, setRowNumber ] = useState( 1 );
	const [ renderingRows, setRenderingRows ] = useState( [] );

	useEffect( () => {
		const rows = [];

		if ( props.data ) {
			// eslint-disable-next-line
			Object.keys( props.data ).map( function( key, index ) {
				rows.push( <ConditionRow
					key={ rowNumber + index }
					row_number={ rowNumber + index }
					ref={ ref }
					conditionControl={ props.conditionControl }
					data={ props.data[ key ] }
				/> );

				setRowNumber( rowNumber + index );
			} );
		}

		setRenderingRows( rows );
	}, [] );

	const addNewCondtion = () => {
		const newRow = [
			...renderingRows,
			<ConditionRow
				key={ rowNumber + 1 }
				row_number={ rowNumber + 1 }
				ref={ ref }
				conditionControl={ props.conditionControl }
			/>,
		];

		setRowNumber( rowNumber + 1 );
		setRenderingRows( newRow );
	};

	return (
		<ConditionsContext.Provider value={ { renderingRows, setRenderingRows } } >
			<div className="popup-conditions-wrapper">
				<div className="popup-conditions-content">
					{ renderingRows }
					<Button
						className="d-flex justify-content-center popup-add-new-conditions"
						variant="primary"
						onClick={ addNewCondtion }
					>
						{ __( 'Add Condition', 'jupiterx-core' ) }
					</Button>
				</div>
			</div>
		</ConditionsContext.Provider>
	);
} );

export default Conditions;
