import React, { forwardRef } from 'react';
import { getStringDefault } from '../utils';
import { Form } from 'react-bootstrap';

const TextControl = forwardRef( ( props, ref ) => {
	const getDefaultValue = () => {
		return getStringDefault( props.triggerControl?.defaultValue );
	};

	return (
		<Form.Group className={ `d-flex align-items-center popup-trigger-type-${ props.triggerControl.type }` }>
			{ ! _.isEmpty( props.triggerControl.label ) && <Form.Label htmlFor={ props.rowName + '_control' }>
				{ props.triggerControl.label }
			</Form.Label> }
			<Form.Control
				id={ props.rowName + '_control' }
				className="popup-trigger-control"
				type="text"
				name={ props.rowName + '[control]' }
				placeholder={ props.triggerControl?.placeholder }
				defaultValue={ getDefaultValue() }
				{ ...ref( props.rowName + '[control]' ) }
			/>
		</Form.Group>
	);
} );

export default TextControl;
