import React, { useState, useEffect, useRef, useContext } from 'react';
import './style.scss';
import ColorPalette from './color-palette';
import NavButton from './nav-button';
import { SketchPicker } from 'react-color';
import { Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import { urls } from '@jupiterx/control-panel';
import { SetupWizardContext } from '..';
import RocketIcon from '../../../../img/setup-wizard/rocket';

const ChooseColors = ( props ) => {
	const context = useContext( SetupWizardContext );
	const [ showCustomizeSection, setShowCustomizeSection ] = useState( false );
	const [ customizeActive, setCustomizeActive ] = useState( false );

	const [ showSecondaryPicker, setShowSecondaryPicker ] = useState( false );
	const [ showPrimaryPicker, setShowPrimaryPicker ] = useState( false );
	const [ showBodyTextPicker, setShowBodyTextPicker ] = useState( false );
	const [ showAccentPicker, setShowAccentPicker ] = useState( false );
	const [ showCustom1Picker, setShowCustom1Picker ] = useState( false );
	const [ showCustom2Picker, setShowCustom2Picker ] = useState( false );

	const [ custom2Color, setCustom2Color ] = useState( context.getLocalStorage( 'custom2_color' ) );
	const [ custom1Color, setCustom1Color ] = useState( context.getLocalStorage( 'custom1_color' ) );
	const [ accentColor, setAccentColor ] = useState( context.getLocalStorage( 'accent_color' ) );
	const [ primaryColor, setPrimaryColor ] = useState( context.getLocalStorage( 'primary_color' ) );
	const [ secondaryColor, setSecondaryColor ] = useState( context.getLocalStorage( 'secondary_color' ) );
	const [ bodyTextColor, setBodyTextColor ] = useState( context.getLocalStorage( 'body_text_color' ) );

	const angleLeftIcon = urls.controlPanel + 'img/setup-wizard/angle-left.svg';
	const sliderIcon = urls.controlPanel + 'img/setup-wizard/slider.svg';

	const colorPickers = {
		custom2: {
			ref: useRef( null ),
			state: showCustom2Picker,
			setState: setShowCustom2Picker,
			color: custom2Color,
			setColor: setCustom2Color,
			setStorageValue: ( value ) => context.setLocalStorage( 'custom2_color', value ),
			label: __( 'Custom 2', 'jupiterx-core' ),
		},
		custom1: {
			ref: useRef( null ),
			state: showCustom1Picker,
			setState: setShowCustom1Picker,
			color: custom1Color,
			setColor: setCustom1Color,
			setStorageValue: ( value ) => context.setLocalStorage( 'custom1_color', value ),
			label: __( 'Custom 1', 'jupiterx-core' ),
		},
		accent: {
			ref: useRef( null ),
			state: showAccentPicker,
			setState: setShowAccentPicker,
			color: accentColor,
			setColor: setAccentColor,
			setStorageValue: ( value ) => context.setLocalStorage( 'accent_color', value ),
			label: __( 'Accent', 'jupiterx-core' ),
		},
		primary: {
			ref: useRef( null ),
			state: showPrimaryPicker,
			setState: setShowPrimaryPicker,
			color: primaryColor,
			setColor: setPrimaryColor,
			setStorageValue: ( value ) => context.setLocalStorage( 'primary_color', value ),
			label: __( 'Primary', 'jupiterx-core' ),
		},
		bodyText: {
			ref: useRef( null ),
			state: showBodyTextPicker,
			setState: setShowBodyTextPicker,
			color: bodyTextColor,
			setColor: setBodyTextColor,
			setStorageValue: ( value ) => context.setLocalStorage( 'body_text_color', value ),
			label: __( 'Body Text', 'jupiterx-core' ),
		},
		secondary: {
			ref: useRef( null ),
			state: showSecondaryPicker,
			setState: setShowSecondaryPicker,
			color: secondaryColor,
			setColor: setSecondaryColor,
			setStorageValue: ( value ) => context.setLocalStorage( 'secondary_color', value ),
			label: __( 'Secondary', 'jupiterx-core' ),
		},
	};

	useEffect( () => {
		const handleClickOutside = ( event ) => {
			for ( const picker of Object.values( colorPickers ) ) {
				if ( picker.ref.current && ! picker.ref.current.contains( event.target ) ) {
					picker.setState( false );
				}
			}
		};

		document.addEventListener( 'click', handleClickOutside );

		return () => {
			document.removeEventListener( 'click', handleClickOutside );
		};
	}, [ colorPickers ] );

	const handleBackClick = () => {
		if ( props.onBackClick ) {
			props.onBackClick();
		}
	};

	const handleCustomizeClick = () => {
		setShowCustomizeSection( ! showCustomizeSection );
		setCustomizeActive( ! customizeActive );
	};

	const decimalToHex = ( alpha ) => alpha === 0 ? '00' : ( Math.round( 255 * alpha ) ).toString( 16 ).padStart( 2, '0' );

	return (
		<>
			<div className="jx-choose-colors">
				<div className="jx-choose-colors__nav-bar">
					<div className="row">
						<div className="col-md-4">
							<NavButton
								className="back-button"
								buttonText={ __( 'Back', 'jupiterx-core' ) }
								handleNavButtonClick={ handleBackClick }
								buttonIcon={ angleLeftIcon }
							/>
						</div>
						<div className="col-md-4 d-flex justify-content-center align-items-center">
						</div>
						<div className="col-md-4">
							<NavButton
								className={ 'customize-button ' + ( customizeActive ? ' active-button' : '' ) }
								buttonText={ __( 'Customize', 'jupiterx-core' ) }
								handleNavButtonClick={ handleCustomizeClick }
								buttonIcon={ sliderIcon } />
						</div>
					</div>
				</div>

				<div className={ `jx-choose-colors__choose ${ showCustomizeSection ? 'show-section' : '' }` }>
					<div className="row">
						{ /* eslint-disable-next-line no-unused-vars */ }
						{ Object.entries( colorPickers ).map( ( [ key, picker ], index ) => (
							<div className="color-picker-col" key={ index }>
								<button
									className={ `choose-color-wrapper ${ picker.state ? 'active' : '' }` }
									onClick={ () => picker.setState( ! picker.state ) }
									ref={ picker.ref }
									type="button"
								>
									<div
										className="color"
										style={ { backgroundColor: picker.color } }
									></div>
									<div className="text">{ picker.label }</div>
									{ picker.state && (
										<div
											onClick={ ( e ) => e.stopPropagation() }
										>
											<SketchPicker
												color={ picker.color }
												onChange={ ( color ) => {
													const hexCode = color.hex;
													const alphaHex = decimalToHex( color.rgb.a );
													const updatedAlphaHex = alphaHex === 'ff' ? '' : alphaHex;
													const updatedColor = `${ hexCode }${ updatedAlphaHex }`;

													picker.setColor( updatedColor );
													picker.setStorageValue( updatedColor );
													props.updateState();
												} }
											/>
										</div>
									) }
								</button>
							</div>
						) ) }
					</div>
				</div>

				<div className="jx-choose-colors__sample">
					<div
						className="jx-choose-colors__icon"
						style={ { backgroundColor: primaryColor } }
					>
						<RocketIcon />
					</div>
					<div className="jx-choose-colors__heading mt-4">
						<h1 style={ { color: primaryColor } }>Heading</h1>
					</div>

					<div className="jx-choose-colors__divider">
						<hr />
					</div>

					<div className="jx-choose-colors__text">
						<p style={ { color: bodyTextColor } }>
							{ __( 'Lorem ipsum dolor sit amet consectetur. Pellentesque ullamcorper nulla urna pellentesque leo integer nulla porttitor. In massa non risus turpis sapien nulla.', 'jupiterx-core' ) }
							{ /* eslint-disable-next-line jsx-a11y/anchor-is-valid */ }
							<a href="#" style={ { color: primaryColor } }>
								{ ' ' + __( 'This is a link.', 'jupiterx-core' ) }
							</a>
						</p>
					</div>
					<div className="jx-choose-colors__button mt-4">
						{ /* eslint-disable-next-line jsx-a11y/anchor-is-valid */ }
						<a href="#" style={ { backgroundColor: accentColor } }>
							<div className="jx-choose-colors__button-text">
								{ __( 'Button text', 'jupiterx-core' ) }
							</div>
						</a>
					</div>
				</div>

				<div className="jx-setup-wizard-color-palettes row mb-5">
					<ColorPalette colors={ [ custom2Color, custom1Color, accentColor, primaryColor, bodyTextColor, secondaryColor ] } />
					<Form.Control
						name={ `colors[custom2_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[custom2_color]' ) }
						value={ custom2Color || '' }
					/>
					<Form.Control
						name={ `colors[custom1_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[custom1_color]' ) }
						value={ custom1Color || '' }
					/>
					<Form.Control
						name={ `colors[accent_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[accent_color]' ) }
						value={ accentColor || '' }
					/>
					<Form.Control
						name={ `colors[primary_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[primary_color]' ) }
						value={ primaryColor || '' }
					/>
					<Form.Control
						name={ `colors[body_text_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[body_text_color]' ) }
						value={ bodyTextColor || '' }
					/>
					<Form.Control
						name={ `colors[secondary_color]` }
						type="hidden"
						{ ...props.stepRef( 'colors[secondary_color]' ) }
						value={ secondaryColor || '' }
					/>
				</div>
			</div>
		</>
	);
};

export default ChooseColors;
