import _ from 'lodash';

export const actionTypes = {
	UPDATE_IMAGE_SIZES: 'UPDATE_IMAGE_SIZES',
	UPDATE_IMAGE_SIZE: 'UPDATE_IMAGE_SIZE',
	REMOVE_IMAGE_SIZE: 'REMOVE_IMAGE_SIZE',
	REMOVE_IMAGE_SIZE_STATUS: 'SAVE_IMAGE_SIZE_STATUS',
	SAVE_IMAGE_SIZES_STATUS: 'SAVE_IMAGE_SIZES_STATUS',
	ADD_IMAGE_SIZE_STATUS: 'ADD_IMAGE_SIZE_STATUS',
	TOGGLE_ADD_IMAGE_SIZE_DIALOG: 'TOGGLE_ADD_IMAGE_SIZE_DIALOG',
	FETCH_IMAGE_SIZES_STATUS: 'FETCH_IMAGE_SIZES_STATUS',
	EDIT_IMAGE_SIZE: 'EDIT_IMAGE_SIZE',
	DELETE_IMAGE_SIZE: 'DELETE_IMAGE_SIZE',
};

export const initialState = {
	sizes: [],
	fetchStatus: 'fetching',
	saveStatus: '',
	removeStatus: 'warning',
	addStatus: '',
	adding: false,
	removeSelected: null,
	selected: null,
};

export const reducer = ( state, action ) => {
	switch ( action.type ) {
		case actionTypes.UPDATE_IMAGE_SIZES:
			return {
				...state,
				sizes: action.payload,
			};
		case actionTypes.UPDATE_IMAGE_SIZE:
			state.sizes[ _.findIndex( state.sizes, { size_n: state.selected.size_n } ) ] = action.payload;

			return {
				...state,
				sizes: state.sizes,
			};
		case actionTypes.REMOVE_IMAGE_SIZE:
			return {
				...state,
				removeSelected: action.payload,
			};
		case actionTypes.TOGGLE_ADD_IMAGE_SIZE_DIALOG:
			return {
				...state,
				adding: action.payload,
			};
		case actionTypes.REMOVE_IMAGE_SIZE_STATUS:
			return {
				...state,
				removeStatus: action.payload,
			};
		case actionTypes.FETCH_IMAGE_SIZES_STATUS:
			return {
				...state,
				fetchStatus: action.payload,
			};
		case actionTypes.SAVE_IMAGE_SIZES_STATUS:
			return {
				...state,
				saveStatus: action.payload,
			};
		case actionTypes.ADD_IMAGE_SIZE_STATUS:
			return {
				...state,
				addStatus: action.payload,
			};
		case actionTypes.EDIT_IMAGE_SIZE:
			return {
				...state,
				selected: action.payload,
			};
		default:
			return state;
	}
};
