import React, { useEffect, useState } from 'react';
import { elements, isPremium } from '@jupiterx/control-panel';
import { Form } from 'react-bootstrap';
import { __ } from '@wordpress/i18n';
import './style.scss';

const ElementorWidgets = ( { options, register, type } ) => {
	const [ optionElements, setOptionElements ] = useState( [] );
	const [ freshInstall, isFreshInstall ] = useState( false );

	useEffect( () => {
		if ( typeof options.elements === 'undefined' ) {
			setOptionElements( [] );
			isFreshInstall( true );

			return;
		}

		if ( typeof options.elements === 'object' ) {
			setOptionElements( Object.values( options.elements ) );
			return;
		}

		setOptionElements( options.elements );
	}, [ options ] );

	const elementGroups = [
		{
			name: __( 'Global Features', 'jupiterx-core' ),
			validElements: [
				'animated-gradient',
				'global-widget',
				'motion_effects',
				'preview-settings',
				'role-manager',
				'tooltip',
				'custom-attributes',
				'custom-css',
				'wrapper-link',
			],
		},
		{
			name: __( 'Layout Building Blocks', 'jupiterx-core' ),
			validElements: [
				'nav-menu',
				'advanced-nav-menu',
				'advanced-accordion',
				'search-form',
				'site-logo',
				'site-title',
				'archive-description',
				'archive-title',
				'author-box',
				'post-comments',
				'post-content',
				'post-meta',
				'post-terms',
				'post-title',
				'post-navigation',
			],
		},
		{
			name: __( 'General Widgets', 'jupiterx-core' ),
			validElements: [
				'alert',
				'animated-heading',
				'breadcrumbs',
				'business-hours',
				'button',
				'call-to-action',
				'carousel',
				'categories',
				'code-highlight',
				'content-switch',
				'countdown',
				'counter',
				'sticky-media-scroller',
				'divider',
				'flex-spacer',
				'forms',
				'heading',
				'hotspot',
				'progress-tracker',
				'icon',
				'content-marquee',
				'text-marquee',
				'testimonial-marquee',
				'image',
				'image-accordion',
				'image-comparison',
				'image-gallery',
				'inline-svg',
				'lottie',
				'media-gallery',
				'photo-album',
				'photo-roller',
				'posts',
				'advanced-posts',
				'price-list',
				'pricing-table',
				'table-of-contents',
				'slider',
				'social-share',
				'tabs',
				'team-members',
				'video',
				'video-playlist',
				'flip-box',
				'paypal',
				'stripe',
				'circle-progress',
			],
		},
		{
			name: __( 'WooCommerce Widgets', 'jupiterx-core' ),
			validElements: [
				'woocommerce-breadcrumbs',
				'cart',
				'add-to-cart',
				'my-account',
				'products',
				'products-carousel',
				'shopping-cart',
				'product-additional-info',
				'product-content',
				'product-data-tabs',
				'product-gallery',
				'product-meta',
				'product-price',
				'product-rating',
				'product-reviews',
				'product-short-description',
				'product-title',
				'woocommerce-settings',
				'woocommerce-notices',
			],
		},
	];

	return (
		<>
			{ ( optionElements.length > 0 || freshInstall ) && elementGroups.map( ( group, groupId ) => (
				<div className={ `jx-cp-element-group col-sm-12 jx-cp-element-group-${ groupId } ${ group.validElements.length > 12 ? 'jx-cp-element-group-large' : '' }` } key={ groupId }>
					<Form.Label className="mb-3 mt-4">{ group.name }</Form.Label>
					<div className="jx-cp-checkbox-wrap">
						{ Object.keys( elements ).sort().map( ( element, index ) => (
							group.validElements.includes( element ) && <Form.Check
								className={ type === 'modal' ? 'jupiterx-enable-widget-item' : '' }
								key={ index }
								type="checkbox"
								id={ `jupiterx-elements-${ element }` }
								name={ 'elements' }
								value={ element }
								label={ elements[ element ] }
								defaultChecked={ optionElements.length > 0 ? optionElements.includes( element ) : true }
								{ ...register( 'elements' ) }
								disabled={ ! isPremium }
							/>
						) ) }
					</div>
				</div>
			) ) }
		</>

	);
};

export default ElementorWidgets;
