import React, { useState } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { Card, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faAward } from '@fortawesome/free-solid-svg-icons';
import { themeLicense } from '@jupiterx/control-panel';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
import Revoke from './revoke';
import Register from './register';
import Alert from '../../../components/alert';

const License = () => {
	const [ showRegisterModal, setShowRegisterModal ] = useState( false );
	const [ showRevokeModal, setShowRevokeModal ] = useState( false );

	const handleToggleRegisterModal = () => {
		setShowRegisterModal( ! showRegisterModal );
	};

	const handleToggleRevokeModal = () => {
		setShowRevokeModal( ! showRevokeModal );
	};

	const isExpired = dayjs().isAfter( dayjs( themeLicense.expiry ) );

	return (
		<Card className="jx-cp-license">
			<Card.Header>
				<FontAwesomeIcon icon={ faAward } />{ ' ' }
				<span>{ __( 'License Settings', 'jupiterx-core' ) }</span>
			</Card.Header>
			{ themeLicense.is_registered ? (
				<Card.Body>
					{ themeLicense.is_registered_on_another_domain ? (
						<Alert variant="warning">
							<span dangerouslySetInnerHTML={ { __html: __( 'Warning: <strong>Another domain</strong> is registered with this license and your license may be <strong>deactivated</strong> in future releases. If you have your api_key or purchase key, please revoke and reactivate your license. Otherwise, please contact <a href="https://my.artbees.net/create-ticket/" target="_blank">Artbees support</a>', 'jupiterx-core' ) } } />
						</Alert>
					) : (
						<Alert variant="success">
							<span dangerouslySetInnerHTML={ { __html: __( 'Status: <strong>Active</strong>', 'jupiterx-core' ) } } />
						</Alert>
					) }
					<div className="mb-3">
						<p className="mb-2">
							{ themeLicense.email ? (
								<span
									dangerouslySetInnerHTML={ {
										__html: sprintf(
											// translators: %s License registered email
											__(
												'License is registered to <strong>%s.</strong>',
												'jupiterx-core'
											),
											themeLicense.email
										),
									} }
								/>
							) : (
								<span>{ __( 'License is registered.', 'jupiterx-core' ) }</span>
							) }
							<span className="ms-2">
								<a href="https://themes.artbees.net/dashboard/register-product/" target="_blank">
									{ __( 'View license', 'jupiterx-core' ) }
								</a>
								<span className="ms-2 me-2 text-secondary">|</span>
								{ /* eslint-disable-next-line jsx-a11y/anchor-is-valid */ }
								<Button
									onClick={ handleToggleRevokeModal }
									className="p-0 pb-1"
									size="sm"
									variant="link"
								>
									{ __( 'Revoke license', 'jupiterx-core' ) }
								</Button>
							</span>
						</p>
						{ themeLicense.expiry ? (
							<p className="mb-0">
								<span
									dangerouslySetInnerHTML={ {
										__html: isExpired ? sprintf(
											// translators: %s License expiry date
											__(
												'Premium support has expired on <strong>%s.</strong>',
												'jupiterx-core'
											),
											dayjs( themeLicense.expiry ).format( 'MMM D, YYYY' )
										) : sprintf(
											// translators: %s License expiry date
											__(
												'Premium support expires in <strong>%s.</strong>',
												'jupiterx-core'
											),
											dayjs.extend( relativeTime )().to( themeLicense.expiry, true )
										),
									} }
								/>
								<span className="ms-2">
									<a href="https://themeforest.net/item/jupiter-multipurpose-responsive-theme/5177775" target="_blank">
										{ isExpired ? __( 'Renew support', 'jupiterx-core' ) : __( 'Extend support', 'jupiterx-core' ) }
									</a>
								</span>
							</p>
						) : ( '' ) }
					</div>
					<Button size="sm" variant="outline-secondary" href="https://themes.artbees.net/dashboard/" target="_blank">
						{ __( 'My account', 'jupiterx-core' ) }
					</Button>
					<div className="mt-3 p-0">
						<span className="jx-cp-dashbord-license-bulk-note" dangerouslySetInnerHTML={ { __html: __( 'Managing multiple licenses? Save up to 70% with our new <strong> Bulk plans.', 'jupiterx-core' ) } } />
						<a href="https://jupiterx.com/bulk-license?utm_source=JXControlPanelLicenseSection" target="_blank" className="jx-cp-dashbord-license-bulk-note-link ms-2">
							{ __( 'Learn More', 'jupiterx-core' ) }
						</a>
					</div>
					<Revoke
						show={ showRevokeModal }
						onHide={ handleToggleRevokeModal }
					/>
				</Card.Body>
			) : (
				<Card.Body>
					{ ( themeLicense.has_api_key && ! themeLicense.is_registered ) ? (
						<Alert className="m-0" variant="danger">
							{
								// translators: %s Artbees support link
								sprintf( __( 'An error occured while validating your license. Please try reloading the page. If the problem still persists, contact <a href="%s" target="_blank">Artbees support</a>.', 'jupiterx-core' ), 'https://themes.artbees.net/dashboard/new-topic/' )
							}
						</Alert>
					) : (
						<>
							<Alert variant="danger">
								{ __( 'Status: Not active', 'jupiterx-core' ) }
							</Alert>
							<p>
								{ __(
									'You need to register your license to be able to take advantage of lifetime auto-updates, install extensions and import hundreds of ready-made demo content.',
									'jupiterx-core'
								) + ' ' }
								<Button className="mb-1 p-0" size="sm" variant="link" onClick={ handleToggleRegisterModal }>Register your license now.</Button>
							</p>
							<Button size="sm" onClick={ handleToggleRegisterModal }>
								{ __( 'Register license', 'jupiterx-core' ) }
							</Button>
							<Register
								show={ showRegisterModal }
								onHide={ handleToggleRegisterModal }
							/>
							<div className="mt-3 p-0">
								<span className="jx-cp-dashbord-license-bulk-note" dangerouslySetInnerHTML={ { __html: __( 'Managing multiple licenses? Save up to 70% with our new <strong> Bulk plans.', 'jupiterx-core' ) } } />
								<a href="https://jupiterx.com/bulk-license?utm_source=JXControlPanelLicenseSection" target="_blank" className="jx-cp-dashbord-license-bulk-note-link ms-2">
									{ __( 'Learn More', 'jupiterx-core' ) }
								</a>
							</div>
						</>
					) }
				</Card.Body>
			) }
		</Card>
	);
};

export default License;
