import React, { useEffect, useState } from 'react';
import { Form } from 'react-bootstrap';
import AsyncSelect from 'react-select/async';
import { __ } from '@wordpress/i18n';
import { Controller } from 'react-hook-form';
import { nonce } from '@jupiterx/control-panel';

const SubIdCondition = ( props ) => {
	const [ theme, setTheme ] = useState( 'light' );

	let fetchingTimeoutId = '';

	useEffect( () => {
		handleDarkMode();
	}, [] );

	const fetchOptions = ( resolve, inputValue ) => {
		if ( inputValue.length < 3 ) {
			return;
		}

		wp.ajax.send( 'jupiterx_popup_get_options', {
			type: 'GET',
			data: {
				nonce,
				type: 'condition',
				//eslint-disable-next-line
				condition_name: props?.name,
				search_value: inputValue,
			},
			dataType: 'json',
			success: ( data ) => {
				const options = [];

				// eslint-disable-next-line
				data.map( ( value, key ) => {
					options.push( {
						value: value.id,
						label: value.name,
					} );
				} );

				resolve( options );
			},
			error: ( data ) => {
				// eslint-disable-next-line no-console
				console.error( data );
			},
		} );
	};

	const loadOptions = ( inputValue ) => {
		if ( _.isNumber( fetchingTimeoutId ) ) {
			clearTimeout( fetchingTimeoutId );
		}

		return new Promise( ( resolve ) => {
			fetchingTimeoutId = setTimeout( () => {
				fetchOptions( resolve, inputValue );
			}, 500 );
		} );
	};

	const handleDarkMode = () => {
		const uiTheme = window.elementor?.getPreferences?.( 'ui_theme' );

		if ( uiTheme === 'dark' ) {
			setTheme( 'dark' );

			return;
		}

		if ( uiTheme === 'light' ) {
			setTheme( 'light' );

			return;
		}

		if ( uiTheme === 'auto' && window.matchMedia && window.matchMedia( `(prefers-color-scheme: dark)` ).matches ) {
			setTheme( 'dark' );

			return;
		}

		setTheme( 'light' );
	};

	return <Form.Group className="popup-condition-sub-id-group">
		<Controller
			control={ props.conditionControl }
			name={ props.rowName + '[sub_id]' }
			// eslint-disable-next-line
			defaultValue={ ! _.isEmpty( props.data ) ? props.data?.sub_id : 'all' }
			render={ ( childProp ) => {
				return <AsyncSelect
					isMulti={ false }
					cacheOptions={ true }
					name={ props.rowName + '[sub_id]' }
					className="popup-condition-sub-id"
					placeholder={ __( 'All', 'jupiterx-core' ) }
					autoComplete="off"
					loadOptions={ loadOptions }
					openMenuOnClick={ false }
					// eslint-disable-next-line
					defaultValue={ ! _.isEmpty( props.data ) ? props.data?.sub_id : 'all' }
					isClearable={ true }
					loadingMessage={ () => __( 'Searching...', 'jupiterx-core' ) }
					onChange={ ( event ) => {
						childProp.onChange( event );
					} }
					components={ {
						DropdownIndicator: () => null,
						IndicatorSeparator: () => null,
						ClearIndicator: ( { innerProps } ) => <div className="popup-condition-sub-id-cross-icon" { ...innerProps }>×</div>,
					} }
					styles={ {
						control: ( provided ) => ( {
							...provided,
							boxShadow: 'none',
						} ),
						valueContainer: ( provided ) => ( {
							...provided,
							padding: 0,
						} ),
						option: ( provided, state ) => ( {
							...provided,
							color: state.isSelected ? '#515962' : '#515962',
							backgroundColor: ( state.isSelected || state.isFocused ) ? '#F1F2F3' : 'transparent',
							fontSize: '12px',
							width: '100%',
							padding: 0,
							margin: 0,
						} ),
						singleValue: ( provided ) => ( {
							...provided,
							color: theme === 'light' ? '#515962' : '',
						} ),
						menuList: ( provided ) => ( {
							...provided,
							padding: 0,
							margin: 0,
							width: '100%',
							textAlign: 'left',
							borderRadius: '3px',
							border: '1px solid #D5D8DC',
							borderColor: theme === 'light' ? '#D5D8DC' : '#3f444b',
						} ),
						noOptionsMessage: ( provided ) => ( {
							...provided,
							padding: '0 0 0 10px',
							textAlign: 'left',
						} ),
						loadingMessage: ( ...provided ) => ( {
							...provided,
							fontSize: '12px',
							textAlign: 'left',
							padding: '0 0 0 10px',
							border: '1px solid #D5D8DC',
							borderColor: theme === 'light' ? '#D5D8DC' : '#3f444b',
						} ),
						placeholder: ( ...provided ) => ( {
							...provided,
							fontSize: '12px',
							color: theme === 'light' ? '#515962' : '',
						} ),
					} }
				/>;
			} }
		/>
	</Form.Group>;
};

export default SubIdCondition;
