import React, { useState, useContext } from 'react';
import { __ } from '@wordpress/i18n';
import NavButton from './nav-button';
import { urls } from '@jupiterx/control-panel';
import { Form } from 'react-bootstrap';
import './style.scss';
import Select from 'react-select';
import { SetupWizardContext } from '..';

const TypographyCustomize = ( props ) => {
	const context = useContext( SetupWizardContext );

	const defaultRatio = [
		{ value: '1.067', label: '1.067 - Minor Second' },
		{ value: '1.125', label: '1.125 - Major Second' },
		{ value: '1.2', label: '1.200 - Minor Third' },
		{ value: '1.25', label: '1.250 - Major Third' },
		{ value: '1.333', label: '1.333 - Perfect Fourth' },
		{ value: '1.414', label: '1.414 - Augmented Fourth' },
		{ value: '1.500', label: '1.500 - Perfect Fifth' },
		{ value: '1.618', label: '1.618 - Golden Ratio' },
	];

	let defaultRatioValue = context.getLocalStorage( 'default_ratio' );
	let defaultBodyFontSize = context.getLocalStorage( 'body_font_size' );

	if ( _.isEmpty( defaultRatioValue ) ) {
		defaultRatioValue = defaultRatio[ 2 ];
	}

	if ( _.isEmpty( defaultBodyFontSize ) ) {
		defaultBodyFontSize = 16;
	}

	const [ showCustomizeSection, setShowCustomizeSection ] = useState( false );
	const [ headingRatio, setHeadingRatio ] = useState( defaultRatioValue.value );
	const [ bodyFontSize, setbodyFontSize ] = useState( defaultBodyFontSize );

	const bodyTypography = { fontFamily: `${ props.typographyStyles.body.fontFamily }`, fontSize: `${ bodyFontSize }px` };

	const angleLeftIcon = urls.controlPanel + 'img/setup-wizard/angle-left.svg';
	const sliderIcon = urls.controlPanel + 'img/setup-wizard/slider.svg';

	const handleBackClick = () => {
		if ( props.onBackClick ) {
			props.onBackClick();
		}
	};

	const handleCustomizeClick = () => {
		setShowCustomizeSection( ! showCustomizeSection );
	};

	const calculateHeadingSize = ( baseSize, ratio, index ) => {
		// For H6, font size is baseSize * ratio.
		if ( index === 6 ) {
			return baseSize * ratio;
		}

		// For other headings, font size is the previous heading's size * ratio.
		const unroundedSize = calculateHeadingSize( baseSize, ratio, index + 1 ) * ratio;

		return index === 1 ? unroundedSize : unroundedSize;
	};

	return (
		<>
			<div className="jx-typography-customize">
				<div className="jx-typography-customize__nav-bar">
					<div className="row">
						<div className="col-6">
							<NavButton
								className="back-button"
								buttonText={ __( 'Back', 'jupiterx-core' ) }
								handleNavButtonClick={ handleBackClick }
								buttonIcon={ angleLeftIcon }
							/>
						</div>
						<div className="col-6">
							<NavButton
								className={ 'customize-button ' + ( showCustomizeSection ? ' active-button' : '' ) }
								buttonText={ __( 'Customize', 'jupiterx-core' ) }
								handleNavButtonClick={ handleCustomizeClick }
								buttonIcon={ sliderIcon }
							/>
						</div>
					</div>
				</div>

				<div className={ `jx-choose-typography ${ showCustomizeSection ? 'show-section' : '' }` }>
					<div className="row">
						<div className="col-6">
							<div className="body">
								<label htmlFor="jx-body-font-size">
									{ __( 'Body Font Size', 'jupiterx-core' ) }
								</label>
								<input
									id="jx-body-font-size"
									value={ bodyFontSize }
									type="number"
									min="0"
									// ref={ ref }
									onChange={ ( e ) => {
										setbodyFontSize( parseFloat( e.target.value ) );
										context.setLocalStorage( 'body_font_size', e.target.value );
									} }
								/>
							</div>
						</div>
						<div className="col-6">
							<div className="ratio">
								<label htmlFor="jx-heading-ratio">
									{ __( 'Heading Ratio', 'jupiterx-core' ) }
								</label>
								{ /* eslint-disable-next-line jsx-a11y/no-onchange */ }
								<Select
									className="jx-heading-ratio-select"
									defaultValue={ defaultRatioValue }
									options={ defaultRatio }
									isSearchable={ false }
									onChange={ ( selected ) => {
										setHeadingRatio( selected.value );
										context.setLocalStorage( 'default_ratio', selected );
									} }
								/>
							</div>
						</div>
					</div>
				</div>

				<div className="jx-typography-customize__sample my-4">
					<div className="row">
						<div className="col-6">
							<div className="body-button-wrapper">
								<div className="title">
									{ __( 'Body and Button', 'jupiterx-core' ) }
								</div>

								<div className="text">
									<p style={ bodyTypography } >
										{ __( 'Lorem ipsum dolor sit amet consectetur. Orci auctor magnis lobortis in ut nunc lectus. Vitae quisque tortor et amet libero ac integer in. Volutpat lectus sed phasellus.', 'jupiterx-core' ) }
									</p>
									<p style={ bodyTypography } >
										{ __( 'Scelerisque diam aliquam praesent vitae elementum risus. Lorem ipsum dolor sit amet consectetur. Orci auctor magnis lobortis in ut nunc lectus. Vitae quisque tortor et amet libero ac integer in. Volutpat lectus sed phasellus nisi purus. Scelerisque diam aliquam praesent.', 'jupiterx-core' ) }
									</p>
									<p style={ bodyTypography } >
										{ __( 'Lorem ipsum dolor sit amet consectetur. Orci auctor magnis lobortis in ut nunc lectus. Vitae quisque tortor et amet libero ac integer in. Volutpat lectus sed phasellus.', 'jupiterx-core' ) }
									</p>
								</div>

								<div className="typography-customize-button mt-4">
									{ /* eslint-disable-next-line jsx-a11y/anchor-is-valid */ }
									<a href="#">
										<div className="typography-customize-button-text" style={ bodyTypography }>
											{ __( 'Button text', 'jupiterx-core' ) }
										</div>
									</a>
								</div>
							</div>
						</div>
						<div className="col-6">
							<div className="headings-wrapper">
								{ [ 1, 2, 3, 4, 5, 6 ].map( ( index ) => {
									const HeadingTag = `h${ index }`;
									const fontSize = Math.round( calculateHeadingSize( bodyFontSize, headingRatio, index ) );

									return (
										<React.Fragment key={ index }>
											<div className="title">Heading H{ index }</div>
											<HeadingTag className="heading" style={ { fontFamily: `${ props.typographyStyles.heading.fontFamily }`, fontSize: `${ fontSize }px`, fontWeight: `${ props.typographyStyles.heading?.fontWeight }` } }>
												Playful and quirky lettering
											</HeadingTag>
											{ index !== 6 &&
												<hr />
											}

											<Form.Control
												name={ `typography[headings_font_size[h${ index }]]` }
												type="hidden"
												{ ...props.stepRef( `typography[headings_font_size][h${ index }]` ) }
												value={ fontSize }
											/>
										</React.Fragment>
									);
								} ) }
							</div>
						</div>
					</div>
				</div>

				<Form.Control
					name="typography[headings_font_family]"
					type="hidden"
					{ ...props.stepRef( 'typography[headings_font_family]' ) }
					value={ props.typographyStyles.heading.fontFamily }
				/>

				<Form.Control
					name="typography[body_font_family]"
					type="hidden"
					{ ...props.stepRef( 'typography[body_font_family]' ) }
					value={ props.typographyStyles.body.fontFamily }
				/>

				<Form.Control
					name="typography[body_font_size]"
					type="hidden"
					{ ...props.stepRef( 'typography[body_font_size]' ) }
					value={ bodyFontSize }
				/>
			</div>
		</>
	);
};

export default TypographyCustomize;
